# ── 網路環境偵測（TAIS 內網 vs 外部網路）────────────────────────────
def _tais_net_probe(host="ac.tais.cht.com.tw", timeout=2):
    """
    偵測目前是否在公司內網：
      可解析 TAIS 主機名稱 → 'intranet'（公司內網）
      無法解析              → 'internet'（外部網路/家中）
    ⚠ 僅影響錯誤提示文字，不影響連線邏輯。
    兩種連線完全獨立：
      • TAIS API  → 永遠直連（內網服務，不需 Proxy）
      • JSONBin.io → PWASyncBridge._get_proxies() 自動決定
    """
    import socket
    try:
        socket.setdefaulttimeout(timeout)
        socket.gethostbyname(host)
        return "intranet"
    except Exception:
        return "internet"
    finally:
        socket.setdefaulttimeout(None)

def strip_schema(sql):
    """
    移除 SQL 中 FROM / JOIN 後面的 schema 前綴
    將 SCHEMA.TABLE 或 SCHEMA/TABLE 轉為 TABLE
    """
    processed = re.sub(
        r'(?i)((?:FROM|JOIN|INTO|UPDATE)\s+)([A-Za-z_]\w*)[./]([A-Za-z_]\w*)',
        r'\1\3',
        sql
    )
    if processed != sql:
        print(f"[INFO] SQL schema 前綴已自動移除")
    return processed


# ==================== API Token 查詢函數 ====================
def execute_query(sql, api_url, api_token, org_code=""):
    """
    透過 API Token 執行SQL查詢並返回 pandas DataFrame
    
    參數說明:
        sql       : 要執行的SQL語句（IBM DB2格式）
        api_url   : API 完整端點 URL（直接使用，不會附加額外路徑）
                    例如 "https://ac.tais.cht.com.tw:8181/TAIS/rest/TAIS/only_query"
        api_token : 您的服務權杖（API Token）
        org_code  : 機構代號（目前 3 參數模式為必填）
    
    回傳:
        pandas DataFrame — 查詢結果
    """
    try:
        # 前處理：移除 SQL 中的 schema 前綴（API 不支援 schema.table 格式）
        sql = strip_schema(sql)

        # 根據模式建立參數列表
        if USE_ORG_CODE and org_code:
            parameters = [org_code, api_token, sql]
        else:
            parameters = [api_token, sql]

        payload = {"parameters": parameters}

        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Accept-Language': 'zh-TW,zh;q=0.9,en-US;q=0.8,en;q=0.7',
            'Accept-Encoding': 'gzip, deflate, br',
            'Connection': 'keep-alive'
        }

        # 直接使用登入畫面填入的 URL（不再附加額外路徑）
        full_url = api_url.rstrip('/')
        print(f"[DEBUG] API 請求 URL: {full_url}")
        print(f"[DEBUG] 參數數量: {len(parameters)} 個 ({'3參數模式' if USE_ORG_CODE else '2參數模式'})")

        # Proxy 設定
        proxies = None
        if USE_PROXY:
            proxies = {
                'http': os.environ.get('HTTP_PROXY', ''),
                'https': os.environ.get('HTTPS_PROXY', '')
            }
            print(f"[DEBUG] 使用 Proxy: {proxies}")

        response = requests.post(
            full_url,
            json=payload,
            headers=headers,
            timeout=900,
            verify=False,
            proxies=proxies
        )

        # 檢查 HTTP 回應狀態
        if response.status_code != 200:
            # 偵測伺服器是否回傳 HTML 錯誤頁面（而非 JSON）
            resp_text = response.text.strip() if response.text else ""
            is_html = ('text/html' in response.headers.get('Content-Type', '') 
                      or resp_text.startswith('<!DOCTYPE') 
                      or resp_text.startswith('<html')
                      or resp_text.startswith('<HTML'))

            if is_html:
                error_hint = ""
                if response.status_code == 404:
                    error_hint = (
                        f"\n\n【可能原因】\n"
                        f"1. API 端點路徑不正確\n"
                        f"2. 目前使用的 URL: {full_url}\n"
                        f"3. 請確認 API 伺服器是否正在運行"
                    )
                elif response.status_code == 403:
                    error_hint = "\n\n【可能原因】服務權杖無效或已過期，請從 4B 系統重新取得"
                elif response.status_code == 401:
                    error_hint = "\n\n【可能原因】未經授權，請確認服務權杖是否有效"
                elif response.status_code == 503:
                    error_hint = (
                        f"\n\n【可能原因】\n"
                        f"1. API 伺服器暫時無法使用\n"
                        f"2. 若使用 Proxy，請確認 USE_PROXY 設定是否正確（目前為 {USE_PROXY}）"
                    )
                
                raise Exception(
                    f"HTTP {response.status_code} 錯誤: 伺服器回傳了 HTML 頁面而非 JSON 資料。"
                    f"{error_hint}"
                )
            else:
                raise Exception(f"HTTP {response.status_code}: {resp_text[:500]}")

        # 確認回應內容是 JSON 格式
        resp_text = response.text.strip() if response.text else ""
        if resp_text.startswith('<!DOCTYPE') or resp_text.startswith('<html') or resp_text.startswith('<HTML'):
            raise Exception(
                f"伺服器回傳 HTML 頁面而非 JSON 資料。\n"
                f"請確認 API 端點 URL 是否正確: {full_url}"
            )

        # 解析 JSON 回應
        try:
            data = response.json()
            print(f"[DEBUG] API 回應格式: {list(data.keys())}")
            print(f"[DEBUG] API 回應前200字: {str(data)[:200]}")
        except Exception:
            raise Exception(
                f"無法解析伺服器回應為 JSON 格式。\n"
                f"回應內容前200字: {resp_text[:200]}\n"
                f"請確認 API 端點 URL 是否正確: {full_url}"
            )

        # 檢查回應格式：支援兩種API格式
        # 1. 原始API格式: {"status": "success", "result": {"columnNames": [...], "data": [...]}}
        # 2. Flask API格式: {"success": true, "data": {"rows": [...], "columns": [...]}}
        
        # 檢查是原始API還是Flask API
        if 'status' in data:
            # 原始API格式
            if data.get('status') != 'success':
                raise Exception(f"查詢失敗: {data.get('message', '未知錯誤')}")
            
            result = data.get('result', {})
            column_names = result.get('columnNames', [])
            data_rows = result.get('data', [])
            
            if data_rows and column_names:
                df = pd.DataFrame(data_rows, columns=column_names)
            elif data_rows:
                df = pd.DataFrame(data_rows)
            else:
                df = pd.DataFrame()
                
        elif 'success' in data:
            # Flask API格式
            if not data.get('success'):
                raise Exception(f"查詢失敗: {data.get('message', '未知錯誤')}")

            result_data = data.get('data', {})
            
            # 處理兩種可能的返回格式
            if isinstance(result_data, dict):
                # 新格式：包含 rows 和 columns 的字典
                rows = result_data.get('rows', [])
                columns = result_data.get('columns', [])
                
                if rows and columns:
                    df = pd.DataFrame(rows, columns=columns)
                elif rows:
                    df = pd.DataFrame(rows)
                else:
                    df = pd.DataFrame()
            elif isinstance(result_data, list):
                # 舊格式：直接是 list of dicts
                if result_data:
                    df = pd.DataFrame(result_data)
                else:
                    df = pd.DataFrame()
            else:
                df = pd.DataFrame()
        else:
            raise Exception("無法識別的API回應格式")

        return df

    except requests.exceptions.Timeout:
        raise Exception("API 請求超時(900秒)，請檢查網路連線或SQL語句是否過於複雜")
    except requests.exceptions.ConnectionError:
        raise Exception("無法連線到 API 伺服器，請確認伺服器位址是否正確且伺服器正在運行")
    except Exception as e:
        raise Exception(f"執行查詢時發生錯誤: {str(e)}")
# ==================== 結束 API Token 連線設定 ====================


