class AdvancedStatisticsGenerator:
    """進階統計資訊產生器"""
    
    def __init__(self):
        self.report_timestamp = datetime.now()
        
    def generate_comprehensive_statistics(self, dept_data, dept_name, year_col='年'):
        """產生全面的統計資訊"""
        try:
            stats_info = {
                'basic_info': self._get_basic_info(dept_data, dept_name),
                'amount_analysis': self._analyze_amounts(dept_data),
                'yearly_analysis': self._analyze_by_year(dept_data, year_col),
                'budget_performance': self._analyze_budget_performance(dept_data),
                'trend_analysis': self._analyze_trends(dept_data, year_col),
                'ranking_analysis': self._analyze_rankings(dept_data)
            }
            
            return stats_info
            
        except Exception as e:
            print(f"統計分析錯誤: {e}")
            return None
    
    def _get_basic_info(self, dept_data, dept_name):
        """基本資訊統計"""
        return {
            'dept_name': dept_name,
            'total_records': len(dept_data),
            'date_range': self._get_date_range(dept_data),
            'report_time': self.report_timestamp.strftime("%Y/%m/%d %H:%M:%S")
        }
    
    def _analyze_amounts(self, dept_data):
        """金額分析"""
        amount_cols = ['截至本月已動支金額', '累計動支數', 'AMTTM']
        budget_cols = ['至本月累計預算數', '本年度預算', 'BGTTTM', 'BGTTY']
        
        amount_col = None
        budget_col = None
        
        for col in amount_cols:
            if col in dept_data.columns:
                amount_col = col
                break
                
        for col in budget_cols:
            if col in dept_data.columns:
                budget_col = col
                break
        
        if amount_col is None:
            return None
            
        amounts = pd.to_numeric(dept_data[amount_col], errors='coerce').fillna(0)
        
        analysis = {
            'amount_column': amount_col,
            'total_amount': amounts.sum(),
            'average_amount': amounts.mean(),
            'median_amount': amounts.median(),
            'max_amount': amounts.max(),
            'min_amount': amounts.min(),
            'std_amount': amounts.std(),
            'positive_records': (amounts > 0).sum(),
            'zero_records': (amounts == 0).sum(),
            'negative_records': (amounts < 0).sum()
        }
        
        if budget_col and budget_col in dept_data.columns:
            budgets = pd.to_numeric(dept_data[budget_col], errors='coerce').fillna(0)
            analysis.update({
                'budget_column': budget_col,
                'total_budget': budgets.sum(),
                'average_budget': budgets.mean(),
                'overall_execution_rate': (amounts.sum() / budgets.sum() * 100) if budgets.sum() > 0 else 0
            })
        
        return analysis
    
    def _analyze_by_year(self, dept_data, year_col):
        """年度分析"""
        if year_col not in dept_data.columns:
            return None
            
        amount_cols = ['截至本月已動支金額', '累計動支數', 'AMTTM']
        amount_col = None
        
        for col in amount_cols:
            if col in dept_data.columns:
                amount_col = col
                break
                
        if amount_col is None:
            return None
            
        # 確保年度為字串格式
        dept_data_copy = dept_data.copy()
        dept_data_copy[year_col] = dept_data_copy[year_col].apply(
            lambda x: str(int(float(x))) if pd.notna(x) and str(x).replace('.', '').replace('-', '').isdigit() 
            else str(x) if pd.notna(x) else ""
        )
        
        yearly_stats = dept_data_copy.groupby(year_col).agg({
            amount_col: ['sum', 'mean', 'count', 'std']
        }).round(2)
        
        yearly_stats.columns = ['總動支金額', '平均動支金額', '記錄數', '標準差']
        yearly_stats = yearly_stats.reset_index()
        yearly_stats = yearly_stats.sort_values(year_col, ascending=False)
        
        return yearly_stats
    
    def _analyze_budget_performance(self, dept_data):
        """預算執行績效分析 - 修正版，避免特殊符號"""
        amount_cols = ['截至本月已動支金額', '累計動支數', 'AMTTM']
        budget_cols = ['至本月累計預算數', '本年度預算', 'BGTTTM', 'BGTTY']
        
        amount_col = None
        budget_col = None
        
        for col in amount_cols:
            if col in dept_data.columns:
                amount_col = col
                break
                
        for col in budget_cols:
            if col in dept_data.columns:
                budget_col = col
                break
        
        if amount_col is None or budget_col is None:
            return None
            
        amounts = pd.to_numeric(dept_data[amount_col], errors='coerce').fillna(0)
        budgets = pd.to_numeric(dept_data[budget_col], errors='coerce').fillna(0)
        
        # 計算執行率
        execution_rates = []
        for amt, bgt in zip(amounts, budgets):
            if bgt > 0:
                execution_rates.append(amt / bgt * 100)
            else:
                execution_rates.append(0)
        
        execution_rates = pd.Series(execution_rates)
        
        performance = {
            'avg_execution_rate': execution_rates.mean(),
            'high_performers': (execution_rates >= 80).sum(),      # 執行率>=80%
            'medium_performers': ((execution_rates >= 60) & (execution_rates < 80)).sum(),  # 60-80%
            'low_performers': (execution_rates < 60).sum(),        # <60%
            'over_budget': (execution_rates > 100).sum(),          # 超預算
            'best_execution_rate': execution_rates.max(),
            'worst_execution_rate': execution_rates.min()
        }
        
        return performance
    
    def verify_excel_file(file_path):
        """驗證Excel檔案完整性"""
        try:
            import openpyxl
            
            # 嘗試開啟檔案
            workbook = openpyxl.load_workbook(file_path)
            
            # 檢查工作表
            print(f"[DEBUG] Excel檔案驗證成功")
            print(f"[DEBUG] 工作表清單: {workbook.sheetnames}")
            
            # 檢查是否有圖表
            for sheet_name in workbook.sheetnames:
                worksheet = workbook[sheet_name]
                chart_count = len(worksheet._charts)
                if chart_count > 0:
                    print(f"[DEBUG] 工作表 '{sheet_name}' 包含 {chart_count} 個圖表")
            
            workbook.close()
            return True
            
        except Exception as e:
            print(f"[ERROR] Excel檔案驗證失敗: {e}")
            return False
    
    def _analyze_trends(self, dept_data, year_col):
        """趨勢分析"""
        if year_col not in dept_data.columns:
            return None
            
        amount_cols = ['截至本月已動支金額', '累計動支數', 'AMTTM']
        amount_col = None
        
        for col in amount_cols:
            if col in dept_data.columns:
                amount_col = col
                break
                
        if amount_col is None:
            return None
            
        # 年度趨勢
        dept_data_copy = dept_data.copy()
        dept_data_copy[year_col] = dept_data_copy[year_col].apply(
            lambda x: str(int(float(x))) if pd.notna(x) and str(x).replace('.', '').replace('-', '').isdigit() 
            else str(x) if pd.notna(x) else ""
        )
        
        yearly_amounts = dept_data_copy.groupby(year_col)[amount_col].sum().sort_index()
        
        if len(yearly_amounts) < 2:
            return None
            
        # 計算年成長率
        growth_rates = []
        years = list(yearly_amounts.index)
        amounts = list(yearly_amounts.values)
        
        for i in range(1, len(amounts)):
            if amounts[i-1] > 0:
                growth_rate = ((amounts[i] - amounts[i-1]) / amounts[i-1]) * 100
                growth_rates.append({
                    'year': years[i],
                    'growth_rate': growth_rate,
                    'amount': amounts[i],
                    'previous_amount': amounts[i-1]
                })
        
        trend_analysis = {
            'yearly_amounts': yearly_amounts.to_dict(),
            'growth_rates': growth_rates,
            'trend_direction': self._determine_trend_direction(growth_rates)
        }
        
        return trend_analysis
    
    def _determine_trend_direction(self, growth_rates):
        """判斷趨勢方向"""
        if not growth_rates:
            return "資料不足"
            
        recent_rates = [gr['growth_rate'] for gr in growth_rates[-3:]]  # 最近3年
        avg_growth = sum(recent_rates) / len(recent_rates)
        
        if avg_growth > 5:
            return "上升趨勢"
        elif avg_growth < -5:
            return "下降趨勢"
        else:
            return "平穩趨勢"
    
    def _analyze_rankings(self, dept_data):
        """項目排名分析"""
        amount_cols = ['截至本月已動支金額', '累計動支數', 'AMTTM']
        name_cols = ['會計名稱', '會計項目', 'FULNAM']
        
        amount_col = None
        name_col = None
        
        for col in amount_cols:
            if col in dept_data.columns:
                amount_col = col
                break
                
        for col in name_cols:
            if col in dept_data.columns:
                name_col = col
                break
        
        if amount_col is None or name_col is None:
            return None
            
        # 按項目排序
        item_amounts = dept_data.groupby(name_col)[amount_col].sum().sort_values(ascending=False)
        
        top_10 = item_amounts.head(10)
        bottom_10 = item_amounts.tail(10)
        
        ranking = {
            'total_items': len(item_amounts),
            'top_10': top_10.to_dict(),
            'bottom_10': bottom_10.to_dict(),
            'concentration_ratio': (top_10.sum() / item_amounts.sum() * 100) if item_amounts.sum() > 0 else 0
        }
        
        return ranking
    
    def _get_date_range(self, dept_data):
        """取得資料日期範圍 - 修正版本，正確計算年月組合的範圍"""
        year_cols = ['年', 'YEAR']
        month_cols = ['月', 'MONTH']
        
        year_col = None
        month_col = None
        
        for col in year_cols:
            if col in dept_data.columns:
                year_col = col
                break
                
        for col in month_cols:
            if col in dept_data.columns:
                month_col = col
                break
        
        if year_col is None:
            return "無法確定日期範圍"
        
        # 清理並過濾有效的年度資料
        dept_data_clean = dept_data.copy()
        dept_data_clean = dept_data_clean[dept_data_clean[year_col].notna()]
        
        if dept_data_clean.empty:
            return "無有效日期資料"
        
        if month_col and month_col in dept_data_clean.columns:
            # 如果有月份資料，建立年月組合進行排序
            dept_data_clean = dept_data_clean[dept_data_clean[month_col].notna()]
            
            if dept_data_clean.empty:
                years = dept_data[year_col].dropna().unique()
                return f"{min(years):.0f}年 - {max(years):.0f}年"
            
            # 建立年月組合列表
            year_month_combinations = []
            for _, row in dept_data_clean.iterrows():
                try:
                    year = int(float(row[year_col]))
                    month = int(float(row[month_col]))
                    # 建立排序用的數值 (例如：114年06月 = 114.06)
                    year_month_value = year + month / 100.0
                    year_month_combinations.append((year_month_value, year, month))
                except (ValueError, TypeError):
                    continue
            
            if not year_month_combinations:
                years = dept_data[year_col].dropna().unique()
                return f"{min(years):.0f}年 - {max(years):.0f}年"
            
            # 按年月組合排序
            year_month_combinations.sort()
            
            # 取得最早和最晚的年月
            earliest = year_month_combinations[0]
            latest = year_month_combinations[-1]
            
            earliest_year, earliest_month = earliest[1], earliest[2]
            latest_year, latest_month = latest[1], latest[2]
            
            return f"{earliest_year:.0f}年{earliest_month:02.0f}月 - {latest_year:.0f}年{latest_month:02.0f}月"
        else:
            # 如果沒有月份資料，只顯示年度範圍
            years = dept_data_clean[year_col].dropna().unique()
            years = [float(year) for year in years if pd.notna(year)]
            
            if not years:
                return "無有效年度資料"
                
            return f"{min(years):.0f}年 - {max(years):.0f}年"

class EnhancedChartGenerator:
    """增強圖表產生器"""
    
    def __init__(self):
        set_chinese_font()
        
    def create_enhanced_bar_chart(self, dept_data, dept_name, stats_info):
        """建立增強的長條圖 - 加大尺寸並改善執行率分析"""
        try:
            # 取得年度分析資料
            yearly_analysis = stats_info.get('yearly_analysis')
            if yearly_analysis is None:
                return None
                
            # 建立圖表 - 加大尺寸
            fig, axes = plt.subplots(2, 2, figsize=(20, 14))  # 從(16, 12)增加到(20, 14)
            fig.suptitle(f'{dept_name} - 預算動支分析報告', fontsize=18, fontweight='bold', y=0.96)
            
            # 第一個子圖：年度動支金額
            years = yearly_analysis['年'].values
            amounts = yearly_analysis['總動支金額'].values
            
            bars1 = axes[0, 0].bar(years, amounts, color='#2E86AB', alpha=0.8, edgecolor='white', linewidth=1.5)
            axes[0, 0].set_title('年度總動支金額', fontsize=16, fontweight='bold', pad=20)
            axes[0, 0].set_xlabel('年度', fontsize=14)
            axes[0, 0].set_ylabel('動支金額 (元)', fontsize=14)
            
            # 格式化Y軸
            axes[0, 0].yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'{x:,.0f}'))
            
            # 在長條上顯示數值
            for bar, amount in zip(bars1, amounts):
                height = bar.get_height()
                axes[0, 0].text(bar.get_x() + bar.get_width()/2., height,
                            f'{amount:,.0f}',
                            ha='center', va='bottom', fontsize=12, fontweight='bold')
            
            # 添加網格
            axes[0, 0].grid(True, alpha=0.3, linestyle='--')
            axes[0, 0].set_axisbelow(True)
            
            # 第二個子圖：預算執行狀況分析
            self._add_budget_performance_chart(axes[0, 1], dept_data, stats_info)
            
            # 第三個子圖：年度趨勢分析
            self._add_trend_analysis_chart(axes[1, 0], dept_data, stats_info)
            
            # 第四個子圖：執行率比較 - 改善版本
            self._add_enhanced_execution_rate_chart(axes[1, 1], dept_data, stats_info)
            
            plt.tight_layout(rect=[0, 0.02, 1, 0.96])
            
            return fig
            
        except Exception as e:
            print(f"圖表建立錯誤: {e}")
            return None
        
    def _add_budget_performance_chart(self, ax, dept_data, stats_info):
        """添加預算執行狀況圖表"""
        try:
            performance = stats_info.get('budget_performance')
            if performance:
                categories = ['高執行率\n(80%以上)', '中執行率\n(60-80%)', '低執行率\n(60%以下)', '超預算\n(100%以上)']
                values = [
                    performance.get('high_performers', 0),
                    performance.get('medium_performers', 0),
                    performance.get('low_performers', 0),
                    performance.get('over_budget', 0)
                ]
                colors = ['#28A745', '#FFC107', '#DC3545', '#6F42C1']
                
                bars2 = ax.bar(categories, values, color=colors, alpha=0.8, edgecolor='white', linewidth=1.5)
                ax.set_title('預算執行狀況分佈', fontsize=14, fontweight='bold', pad=20)
                ax.set_ylabel('項目數量', fontsize=12)
                
                # 在長條上顯示數值
                for bar, value in zip(bars2, values):
                    if value > 0:
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., height,
                            f'{int(value)}',
                            ha='center', va='bottom', fontsize=10, fontweight='bold')
            else:
                ax.text(0.5, 0.5, '預算執行分析\n(資料準備中)', 
                    ha='center', va='center', transform=ax.transAxes, fontsize=12)
            
            ax.grid(True, alpha=0.3, linestyle='--')
            ax.set_axisbelow(True)
            
        except Exception as e:
            print(f"預算執行圖表建立錯誤: {e}")
            ax.text(0.5, 0.5, f'圖表建立錯誤', 
                ha='center', va='center', transform=ax.transAxes, fontsize=10)

    def _add_trend_analysis_chart(self, ax, dept_data, stats_info):
        """添加趨勢分析圖表"""
        try:
            trend_analysis = stats_info.get('trend_analysis')
            if trend_analysis and 'growth_rates' in trend_analysis:
                growth_rates = trend_analysis['growth_rates']
                if growth_rates:
                    years = [gr['year'] for gr in growth_rates]
                    rates = [gr['growth_rate'] for gr in growth_rates]
                    
                    bars = ax.bar(years, rates, color=['#28A745' if r >= 0 else '#DC3545' for r in rates], 
                                alpha=0.8, edgecolor='white', linewidth=1.5)
                    ax.set_title('年度成長率', fontsize=14, fontweight='bold', pad=20)
                    ax.set_xlabel('年度', fontsize=12)
                    ax.set_ylabel('成長率 (%)', fontsize=12)
                    
                    # 添加0%參考線
                    ax.axhline(y=0, color='black', linestyle='-', alpha=0.5, linewidth=1)
                    
                    # 在長條上顯示數值
                    for bar, rate in zip(bars, rates):
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., 
                            height + (1 if height >= 0 else -3),
                            f'{rate:.1f}%',
                            ha='center', va='bottom' if height >= 0 else 'top', 
                            fontsize=10, fontweight='bold')
                else:
                    ax.text(0.5, 0.5, '趨勢分析\n(需要多年度資料)', 
                        ha='center', va='center', transform=ax.transAxes, fontsize=12)
            else:
                ax.text(0.5, 0.5, '趨勢分析\n(資料不足)', 
                    ha='center', va='center', transform=ax.transAxes, fontsize=12)
            
            ax.grid(True, alpha=0.3, linestyle='--')
            ax.set_axisbelow(True)
            
        except Exception as e:
            print(f"趨勢分析圖表建立錯誤: {e}")
            ax.text(0.5, 0.5, f'圖表建立錯誤', 
                ha='center', va='center', transform=ax.transAxes, fontsize=10)

    def _add_execution_rate_chart(self, ax, dept_data, stats_info):
        """添加執行率比較圖表"""
        try:
            yearly_analysis = stats_info.get('yearly_analysis')
            if yearly_analysis is not None and not yearly_analysis.empty:
                years = yearly_analysis['年'].values
                amounts = yearly_analysis['總動支金額'].values
                
                # 嘗試計算執行率（需要預算資料）
                execution_rates = []
                for year in years:
                    year_str = str(int(float(year))) if pd.notna(year) else "未知"
                    year_data = dept_data[dept_data['年'].astype(str).str.strip() == year_str]
                    
                    if not year_data.empty:
                        # 尋找預算欄位
                        budget_cols = ['至本月累計預算數', 'BGTTTM', '本年度預算', 'BGTTY']
                        budget_col = None
                        for col in budget_cols:
                            if col in year_data.columns:
                                budget_col = col
                                break
                        
                        if budget_col:
                            total_budget = year_data[budget_col].sum()
                            year_amount = amounts[list(years).index(year)]
                            if total_budget > 0:
                                rate = (year_amount / total_budget) * 100
                                execution_rates.append(rate)
                            else:
                                execution_rates.append(0)
                        else:
                            execution_rates.append(0)
                    else:
                        execution_rates.append(0)
                
                if any(rate > 0 for rate in execution_rates):
                    bars = ax.bar(years, execution_rates, 
                                color=['#28A745' if r >= 80 else '#FFC107' if r >= 60 else '#DC3545' for r in execution_rates],
                                alpha=0.8, edgecolor='white', linewidth=1.5)
                    ax.set_title('年度預算執行率', fontsize=14, fontweight='bold', pad=20)
                    ax.set_xlabel('年度', fontsize=12)
                    ax.set_ylabel('執行率 (%)', fontsize=12)
                    
                    # 添加目標線
                    ax.axhline(y=100, color='red', linestyle='--', alpha=0.7, linewidth=2)
                    ax.text(years[-1], 102, '100%目標', fontsize=10, color='red')
                    
                    # 在長條上顯示數值
                    for bar, rate in zip(bars, execution_rates):
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., height,
                            f'{rate:.1f}%',
                            ha='center', va='bottom', fontsize=10, fontweight='bold')
                else:
                    ax.text(0.5, 0.5, '執行率分析\n(缺少預算資料)', 
                        ha='center', va='center', transform=ax.transAxes, fontsize=12)
            else:
                ax.text(0.5, 0.5, '執行率分析\n(資料不足)', 
                    ha='center', va='center', transform=ax.transAxes, fontsize=12)
            
            ax.grid(True, alpha=0.3, linestyle='--')
            ax.set_axisbelow(True)
            
        except Exception as e:
            print(f"執行率圖表建立錯誤: {e}")
            ax.text(0.5, 0.5, f'圖表建立錯誤', 
                ha='center', va='center', transform=ax.transAxes, fontsize=10)
            
    def _add_secondary_chart(self, ax, dept_data, stats_info):
        """添加第二個圖表 - 修正版，避免特殊符號問題"""
        try:
            amount_analysis = stats_info.get('amount_analysis')
            if amount_analysis is None:
                ax.text(0.5, 0.5, '無足夠資料產生第二圖表', 
                    ha='center', va='center', transform=ax.transAxes, fontsize=12)
                return
            
            # 建立執行狀況分析圖
            performance = stats_info.get('budget_performance')
            if performance:
                # 修正：避免使用≥符號，改用文字
                categories = ['高執行率\n(80%以上)', '中執行率\n(60-80%)', '低執行率\n(60%以下)', '超預算\n(100%以上)']
                values = [
                    performance.get('high_performers', 0),
                    performance.get('medium_performers', 0),
                    performance.get('low_performers', 0),
                    performance.get('over_budget', 0)
                ]
                colors = ['#28A745', '#FFC107', '#DC3545', '#6F42C1']
                
                bars2 = ax.bar(categories, values, color=colors, alpha=0.8, edgecolor='white', linewidth=1.5)
                ax.set_title('預算執行狀況分佈', fontsize=14, fontweight='bold', pad=20)
                ax.set_ylabel('項目數量', fontsize=12)
                
                # 在長條上顯示數值
                for bar, value in zip(bars2, values):
                    if value > 0:
                        height = bar.get_height()
                        ax.text(bar.get_x() + bar.get_width()/2., height,
                            f'{int(value)}',
                            ha='center', va='bottom', fontsize=10, fontweight='bold')
            else:
                # 如果沒有預算資料，顯示金額分佈
                ax.text(0.5, 0.5, '預算執行分析\n(資料準備中)', 
                    ha='center', va='center', transform=ax.transAxes, fontsize=12)
            
            ax.grid(True, alpha=0.3, linestyle='--')
            ax.set_axisbelow(True)
            
        except Exception as e:
            print(f"第二圖表建立錯誤: {e}")
            ax.text(0.5, 0.5, f'圖表建立錯誤', 
                ha='center', va='center', transform=ax.transAxes, fontsize=10)
            
