class DateCircleWidget(QWidget):
    """日期圓環顯示Widget - 縮小版本"""
    
    def __init__(self):
        super().__init__()
        self.setFixedSize(162, 162)  # 從220縮小到180
        self.current_month = pd.Timestamp.now().month
        self.current_day = pd.Timestamp.now().day
        # 初始化天氣服務
        self.weather_service = WeatherService()
        self.column_rename_mapping = {}  # 確保這個變數被初始化

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        
        # 設定字型
        font = QFont()
        font.setFamily("Microsoft JhengHei")
        painter.setFont(font)
        
        center_x = self.width() // 2
        center_y = self.height() // 2
        
        # 繪製外圈月份 (1-12月)
        self.draw_month_circle(painter, center_x, center_y)
        
        # 繪製內圈日期 (1-31日)
        self.draw_day_circle(painter, center_x, center_y)
        
        # 繪製中心當前日期
        self.draw_center_date(painter, center_x, center_y)
    
    def draw_month_circle(self, painter, center_x, center_y):
        """繪製外圈月份 - 調整半徑"""
        radius = 63  # 從85調整到70→63 (v5_13b)
        
        for month in range(1, 13):
            angle = (month - 1) * 30 - 90  # 從12點方向開始，每月30度
            angle_rad = math.radians(angle)
            
            x = center_x + radius * math.cos(angle_rad)
            y = center_y + radius * math.sin(angle_rad)
            
            # 設定顏色和字型
            if month == self.current_month:
                painter.setPen(QPen(QColor("#e74c3c"), 3))
                font = painter.font()
                font.setBold(True)
                font.setPointSize(9)  # 從12調整到10
                painter.setFont(font)
            else:
                painter.setPen(QPen(QColor("#34495e"), 2))
                font = painter.font()
                font.setBold(False)
                font.setPointSize(7)  # 從10調整到8
                painter.setFont(font)
            
            # 計算文字尺寸並完全置中
            text = str(month)
            font_metrics = painter.fontMetrics()
            text_rect = font_metrics.boundingRect(text)
            text_width = text_rect.width()
            text_height = text_rect.height()
            
            # 完全置中繪製月份數字
            text_x = int(x - text_width / 2)
            text_y = int(y + text_height / 2 - font_metrics.descent())
            painter.drawText(text_x, text_y, text)
        
    def draw_day_circle(self, painter, center_x, center_y):
        """繪製內圈日期 - 調整半徑"""
        radius = 36  # 從50調整到40→36 (v5_13b)
        
        # 顯示重要日期以避免過於擁擠
        days_to_show = [1, 5, 10, 15, 20, 25, 31]
        
        for i, day in enumerate(days_to_show):
            angle = i * (360 / len(days_to_show)) - 90
            angle_rad = math.radians(angle)
            
            x = center_x + radius * math.cos(angle_rad)
            y = center_y + radius * math.sin(angle_rad)
            
            # 設定顏色和字型
            if day == self.current_day:
                painter.setPen(QPen(QColor("#27ae60"), 3))
                font = painter.font()
                font.setBold(True)
                font.setPointSize(7)  # 從10調整到8
                painter.setFont(font)
            else:
                painter.setPen(QPen(QColor("#7f8c8d"), 2))
                font = painter.font()
                font.setBold(False)
                font.setPointSize(6)  # 從8調整到7
                painter.setFont(font)
            
            # 計算文字尺寸並完全置中
            text = str(day)
            font_metrics = painter.fontMetrics()
            text_rect = font_metrics.boundingRect(text)
            text_width = text_rect.width()
            text_height = text_rect.height()
            
            # 完全置中繪製日期數字
            text_x = int(x - text_width / 2)
            text_y = int(y + text_height / 2 - font_metrics.descent())
            painter.drawText(text_x, text_y, text)
        
    def draw_center_date(self, painter, center_x, center_y):
        """繪製中心當前日期 - 調整字體大小"""
        painter.setPen(QPen(QColor("#2c3e50"), 2))
        font = painter.font()
        font.setBold(True)
        font.setPointSize(13)  # 從16調整到14
        painter.setFont(font)
        
        current_date = f"{self.current_month}/{self.current_day}"
        
        # 計算文字尺寸並完全置中
        font_metrics = painter.fontMetrics()
        text_rect = font_metrics.boundingRect(current_date)
        text_width = text_rect.width()
        text_height = text_rect.height()
        
        # 完全置中繪製當前日期
        text_x = int(center_x - text_width / 2)
        text_y = int(center_y + text_height / 2 - font_metrics.descent())
        painter.drawText(text_x, text_y, current_date)
    
    def update_date(self):
        """更新當前日期"""
        now = pd.Timestamp.now()
        self.current_month = now.month
        self.current_day = now.day
        self.update()

