    def on_login(self):
        api_url = self.system_name.text().strip()
        api_token = self.username.text().strip()
        institution_code = self.institution_code.text().strip()
        year = self.year_input.text()
        month = self.month_input.text()

        if not api_token:
            QMessageBox.warning(self, "警告", "請輸入服務權杖！\n\n請從 4B 系統取得服務權杖。")
            return

        # 驗證機構代號、年度、月份
        if not institution_code or not year or not month:
            QMessageBox.warning(self, "警告", "請填寫機構代號、年度和月份！")
            return

        if not api_url:
            QMessageBox.warning(self, "警告", "請填寫 API 位址！")
            return

        try:
            print(f"[INFO] 測試 API 連線: {api_url}")
            print(f"[INFO] 機構代號: {institution_code}")
            print(f"[INFO] 連線模式: {'3參數模式' if USE_ORG_CODE else '2參數模式'}")

            # 使用簡單的測試SQL驗證API連線（不使用 schema 前綴）
            test_sql = f"SELECT * FROM VOUD{institution_code} FETCH FIRST 1 ROWS ONLY"
            execute_query(test_sql, api_url, api_token, institution_code)

            # 登入成功後，將參數儲存到主視窗的全域變數
            self.main_window.global_institution_code = institution_code
            self.main_window.global_year = year
            self.main_window.global_month = month

            # 同步參數到 SQLPanel
            self.main_window.sync_budget_params()

            QMessageBox.information(self, "成功", f"✅ 已成功連接到 API 伺服器！\n\nAPI 位址：{api_url}\n機構代號：{institution_code}\n年度：{year}\n月份：{month}")
            self.main_window.budget_tab_widget.setCurrentIndex(0)  # 切換到預算SQL頁
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"❌ API 連接失敗:\n{str(e)}")

