            self.start_year = QLineEdit()
            self.start_year.setPlaceholderText("起始年(例如：112)")
            self.start_year.setFont(QFont("Microsoft JhengHei", 12))  # 減小字體大小
            self.start_year.setStyleSheet(self.get_input_style_compact())
            
            period_layout.addWidget(QLabel("起始年："))
            period_layout.addWidget(self.start_year)
