            self.end_year = QLineEdit()
            self.end_year.setPlaceholderText("結束年(例如：115)")
            self.end_year.setFont(QFont("Microsoft JhengHei", 12))  # 減小字體大小
            self.end_year.setStyleSheet(self.get_input_style_compact())
            
