    def validate_inputs(self):
        """驗證輸入值是否有效"""
        # 檢查是否至少有一個查詢條件
        has_condition = any([
            self.year_month.text().strip(),
            self.start_year.text().strip(),
            self.end_year.text().strip(),
            self.general_account.text().strip(),
            self.detail_account.text().strip(),
            self.account_name.text().strip(),
            self.trade_org.text().strip(),
            self.account_org.text().strip(),
            self.budget_unit.text().strip(),
            self.report_type.text().strip(),      # 新增報表類別驗證
            self.item_code.text().strip()         # 新增項目代號驗證
        ])
        
        if not has_condition:
            QMessageBox.warning(self, "警告", "請至少輸入一個查詢條件！")
            return False
            
        return True
    
    def get_query_conditions(self):
        """取得查詢條件字典"""
        return {
            'year_month': self.year_month.text().strip(),
            'start_year': self.start_year.text().strip(),
            'end_year': self.end_year.text().strip(),
            'general_account': self.general_account.text().strip(),
            'detail_account': self.detail_account.text().strip(),
            'account_name': self.account_name.text().strip(),
            'trade_org': self.trade_org.text().strip(),
            'account_org': self.account_org.text().strip(),
            'budget_unit': self.budget_unit.text().strip(),
            'report_type': self.report_type.text().strip(),    # 新增報表類別
            'item_code': self.item_code.text().strip()         # 新增項目代號
        }
    
    # ... (其他方法保持不變，因為它們主要是邏輯處理，不涉及界面大小)
    def build_performance_sql(self):
        """建立預算與營收績效查詢SQL語句"""
        conditions = self.get_query_conditions()
        
        # 取得參數值，提供預設值
        trade_org = conditions['trade_org'] if conditions['trade_org'] else '3047'
        account_org = conditions['account_org'] if conditions['account_org'] else ''
        general_account = conditions['general_account'] if conditions['general_account'] else '5'
        detail_account = conditions['detail_account'] if conditions['detail_account'] else '%'
        report_type = conditions['report_type'] if conditions['report_type'] else '%'
        item_code = conditions['item_code'] if conditions['item_code'] else '%'
        account_name = conditions['account_name'] if conditions['account_name'] else '%'
        budget_unit = conditions['budget_unit'] if conditions['budget_unit'] else '%'
        
        # 處理年月條件
        if conditions['year_month']:
            year = conditions['year_month'][:3]  # 前3位是年
            month = conditions['year_month'][3:]  # 後面是月
        else:
            # 預設為登入頁面輸入的年度月份
            year = self.main_window.global_year if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else '115'
            month = self.main_window.global_month if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_month') else '01'
        
        # 判斷是否有輸入具體的查詢條件
        has_specific_detail_account = (detail_account and detail_account != '%')
        has_specific_account_name = (account_name and account_name != '%')
        has_specific_item_code = (item_code and item_code != '%')
        has_specific_report_type = (report_type and report_type != '%')
        
        # 根據參數決定JOIN限制條件，但保持general_account的原始值
        if general_account == '5' and report_type == '55':
            join_condition_restriction = "AND (a.GENACC LIKE '5%' OR d.ACCTYP like '55%')"
        elif general_account == '5':
            join_condition_restriction = "AND a.GENACC LIKE '5%'"
        elif report_type == '55':
            join_condition_restriction = "AND d.ACCTYP like '55%'"
        else:
            join_condition_restriction = ""
        
        # 建立SQL語句 (移除了 JOIN LPB3047WP.U3047107, DEPT欄位將在記憶體JOIN後加入)
        sql = f"""
        SELECT DISTINCT
            a.BKGOFN,
            a.TRNOFN,
            a.YEAR,
            "MONTH",
            a.GENACC,
            a.SUBACC,
            RTRIM(a.FULNAM) AS FULNAM,
            AMTLY,
            AMTLM,
            DAMTTM,
            CAMTTM,
            (AMTTM - AMTLM) AS AMT_DIFF,
            AMTTM,
            BGTTM,
            BGTTTM,
            DECIMAL(ROUND((AMTTM / NULLIF(BGTTTM, 0)) * 100, 2), 10, 2) AS PCT_OF_MBUDGET,
            BGTTY,
            DECIMAL(ROUND((AMTTM / NULLIF(BGTTY, 0)) * 100, 2), 10, 2) AS PCT_OF_BUDGET,
            BGTTY - AMTTM AS BUDGET_REMAINING,
            trim(d.itmcod) as ITMCOD
        FROM VQRY6{trade_org} a
        LEFT OUTER JOIN acpgacod d ON a.genacc = d.genacc and a.subacc = d.subacc AND a.year = d.year
        WHERE a.bkgofn like '%{account_org}%'
            AND a.trnofn = '{trade_org}'
            AND (a.YEAR = {year} AND MONTH = {month})
            AND a.GENACC LIKE '{general_account}%'
            AND a.SUBACC LIKE '{detail_account}%'
            AND d.ACCTYP like '{report_type}%'
            AND d.itmcod LIKE '{item_code}%'
            AND a.FULNAM LIKE '%{account_name}%'
        ORDER BY YEAR, "MONTH", GENACC, SUBACC, BKGOFN, TRNOFN
        """
        
        return sql

    def build_voucher_sql(self):
        """建立年度預算查詢SQL語句 - 含跨年度比較欄位 (SBGTTTM/SBGTTY/BGTTTM_DIFF/BGTTY_DIFF/REMAINING)"""
        conditions = self.get_query_conditions()

        # ── 步驟1：先決定查詢年月（供前一年 LEFT JOIN 使用）──────────────────
        if conditions['year_month']:
            year  = conditions['year_month'][:3]
            month = conditions['year_month'][3:]
        elif conditions['start_year']:
            year  = conditions['start_year']
            month = self.main_window.global_month if hasattr(self.main_window, 'global_month') else '06'
        else:
            year  = self.main_window.global_year  if hasattr(self.main_window, 'global_year')  else '115'
            month = self.main_window.global_month if hasattr(self.main_window, 'global_month') else '06'

        prev_year = int(year) - 1

        # ── 步驟2：建立 SELECT（含前一年比較欄位，欄位順序同績效查詢）────────
        base_sql = f"""
        SELECT DISTINCT
            a.BKGOFN,
            a.TRNOFN,
            a.YEAR,
            a."MONTH",
            a.GENACC,
            a.SUBACC,
            RTRIM(a.FULNAM) AS FULNAM,
            a.AMTLY,
            a.AMTLM,
            a.DAMTTM,
            a.CAMTTM,
            (a.AMTTM - a.AMTLM) AS AMT_DIFF,
            a.AMTTM,
            a.BGTTM,
            a.BGTTTM,
            DECIMAL(ROUND((a.AMTTM / NULLIF(a.BGTTTM, 0)) * 100, 2), 10, 2) AS PCT_OF_MBUDGET,
            COALESCE(p.BGTTTM, 0) AS SBGTTTM,
            (a.BGTTTM - COALESCE(p.BGTTTM, 0)) AS BGTTTM_DIFF,
            a.BGTTY,
            DECIMAL(ROUND((a.AMTTM / NULLIF(a.BGTTY, 0)) * 100, 2), 10, 2) AS PCT_OF_BUDGET,
            a.BGTTY - a.AMTTM AS REMAINING,
            COALESCE(p.BGTTY, 0) AS SBGTTY,
            (a.BGTTY - COALESCE(p.BGTTY, 0)) AS BGTTY_DIFF,
            CASE
                WHEN (  substr(a.subacc,1,1) in ('6','R')  or SUBSTR(a.subacc, 1, 3) IN ('153','157','164','185','251','817')
                OR SUBSTR(a.subacc, 1, 4) IN ( '1613','2312','2313','2314','2522','3319','3320' )
                OR SUBSTR(a.subacc, 1, 5) IN ('25211','25213','25410','32922','BB1ZZ','BB2ZZ','33111','33130') )
                THEN 'XXX'
                WHEN SUBSTR(d.ITMCOD, 1, 1) = 'D'
                THEN 'XXX企客'
                ELSE ''
            END AS CATEGORY,
            case when substr(d.ITMCOD,1,4) in 'A.01' then 'CO2' else d.ITMCOD end AS ITMCOD
        FROM VQRY63047 a
        LEFT OUTER JOIN acpgacod d ON a.subacc = d.subacc AND a.year = d.year
        LEFT OUTER JOIN VQRY63047 p ON
            a.GENACC  = p.GENACC  AND
            a.SUBACC  = p.SUBACC  AND
            a.BKGOFN  = p.BKGOFN  AND
            a.TRNOFN  = p.TRNOFN  AND
            p.YEAR    = {prev_year} AND
            p."MONTH" = {month}
        WHERE 1=1
        """

        # ── 步驟3：建立 WHERE 條件 ─────────────────────────────────────────
        where_conditions = []

        # 時間條件（year/month 已於上方解析，直接套用）
        if conditions['year_month'] or not (conditions['start_year'] or conditions['end_year']):
            where_conditions.append(f"(a.YEAR = {year} AND a.\"MONTH\" = {month})")
        else:
            if conditions['start_year'] and conditions['end_year']:
                where_conditions.append(f"a.YEAR BETWEEN {conditions['start_year']} AND {conditions['end_year']}")
            elif conditions['start_year']:
                where_conditions.append(f"a.YEAR >= {conditions['start_year']}")
            else:
                where_conditions.append(f"a.YEAR <= {conditions['end_year']}")

        # 科目條件
        if conditions['general_account']:
            if '%' in conditions['general_account']:
                where_conditions.append(f"(a.GENACC LIKE '{conditions['general_account']}' and substr(a.genacc,1,2) not in ('59') ) or a.GENACC = '570B'")
            else:
                where_conditions.append(f"a.GENACC = '{conditions['general_account']}' ")
        else:
            where_conditions.append("((a.GENACC LIKE '5%' and a.SUBACC LIKE '%' and d.ACCTYP='55') or (a.GENACC = '570B' and a.subacc in ('AA1ZZ','AA2ZZ') and d.ACCTYP='CO2' and d.itmcod like 'A.01%'))")

        if conditions['detail_account']:
            where_conditions.append(f"a.SUBACC LIKE '%{conditions['detail_account']}%'")

        if conditions['account_name']:
            where_conditions.append(f"a.FULNAM LIKE '%{conditions['account_name']}%'")
        else:
            where_conditions.append("a.FULNAM LIKE '%%'")

        if conditions['trade_org']:
            where_conditions.append(f"a.trnofn = '{conditions['trade_org']}'")
        else:
            where_conditions.append("a.trnofn = '3047'")

        if conditions['account_org']:
            where_conditions.append(f"a.bkgofn like '%{conditions['account_org']}%'")
        else:
            where_conditions.append("a.bkgofn like '%%'")

        # ── 步驟4：組合完整 SQL ──────────────────────────────────────────────
        sql = base_sql + " AND " + " AND ".join(where_conditions)
        sql += "\nORDER BY a.YEAR, a.\"MONTH\", a.GENACC, a.SUBACC, a.BKGOFN, a.TRNOFN"

        return sql
    
    def build_budget_sql(self):
        """建立跨年度預算查詢SQL語句 - 支援多年月查詢"""
        try:
            conditions = self.get_query_conditions()
            print(f"[DEBUG] 取得的查詢條件: {conditions}")
            
            # 基礎SQL語句的主要部分 (移除了 DEPT 欄位,將在記憶體JOIN後加入)
            base_select = """
            SELECT DISTINCT
                a.BKGOFN,
                a.TRNOFN,
                a.YEAR,
                "MONTH",
                a.GENACC,
                a.SUBACC,
                RTRIM(a.FULNAM) AS FULNAM,
                AMTLY,
                AMTLM,
                DAMTTM,
                CAMTTM,
                (AMTTM - AMTLM) AS AMT_DIFF,
                AMTTM,
                BGTTM,
                BGTTTM,
                DECIMAL(ROUND((AMTTM / NULLIF(BGTTTM, 0)) * 100, 2), 10, 2) AS PCT_OF_MBUDGET,
                BGTTY,
                DECIMAL(ROUND((AMTTM / NULLIF(BGTTY, 0)) * 100, 2), 10, 2) AS PCT_OF_BUDGET,
                BGTTY - AMTTM AS BUDGET_REMAINING,
                CASE
                    WHEN substr(a.subacc,1,1) in ('6','R') or SUBSTR(a.subacc, 1, 3) IN ('153','157','164','185','251','817')
                    OR SUBSTR(a.subacc, 1, 4) IN ( '1613','2312','2313','2314','2522','3319','3320' )
                    OR SUBSTR(a.subacc, 1, 5) IN ('25211','25213','25410','32922','BB1ZZ','BB2ZZ','33111','33130')
                    THEN 'XXX'
                    WHEN SUBSTR(d.ITMCOD, 1, 1) = 'D'
                    THEN 'XXX企客'
                    ELSE ''
                END AS CATEGORY, case when substr(d.ITMCOD,1,4) in 'A.01' then 'CO2' else d.ITMCOD end  AS ITMCOD
            """
            
            # 分析時間查詢需求
            time_queries = self.analyze_time_requirements(conditions)
            print(f"[DEBUG] 時間查詢需求分析: {time_queries}")
            
            # 確定科目條件
            subject_condition = self.get_subject_condition(conditions)
            print(f"[DEBUG] 科目條件: {subject_condition}")
            
            # 確定機構條件（不包含時間相關的條件）
            org_condition = self.get_org_condition_base(conditions)
            print(f"[DEBUG] 機構條件: {org_condition}")
            
            # 取得動態機構參數
            account_org = conditions['account_org'] if conditions['account_org'] else '%%'
            trade_org = conditions['trade_org'] if conditions['trade_org'] else '3047'
            
            print(f"[DEBUG] 使用機構參數 - 列帳機構:{account_org}, 交易機構:{trade_org}")
            
            # 建立查詢部分列表
            sql_parts = []
            
            # 根據時間需求建立對應的查詢
            # 1. 當前年度查詢 (112年以後) - 移除了 JOIN LPB3047WP.U3047107
            if time_queries['current_conditions']:
                try:
                    current_time_condition = ' OR '.join(time_queries['current_conditions'])
                    sql_part1 = f"""
                    {base_select}
                    FROM VQRY63047 a
                    LEFT OUTER JOIN acpgacod d ON a.subacc = d.subacc AND a.year = d.year
                    WHERE a.bkgofn like '%{account_org}%'
                    AND a.trnofn = '{trade_org}'
                    AND ({current_time_condition})
                    AND {subject_condition}
                    """
                    sql_parts.append(sql_part1)
                    print(f"[DEBUG] 添加當前年度查詢部分: {len(time_queries['current_conditions'])} 個時間條件")
                except Exception as e:
                    print(f"[ERROR] 建立當前年度SQL時發生錯誤: {e}")
            
            # 2. 歷史年度查詢 (111年) - 移除了 JOIN LPB3047WP.U3047107
            if time_queries['historical_conditions']:
                try:
                    historical_time_condition = ' OR '.join(time_queries['historical_conditions'])
                    sql_part2 = f"""
                    {base_select.replace('a.', 'c.')}
                    FROM VQRY2H0000 c
                    LEFT OUTER JOIN acpgacod d ON c.subacc = d.subacc AND c.year = d.year
                    WHERE c.bkgofn like '%{account_org}%'
                    AND c.trnofn = '{trade_org}'
                    AND ({historical_time_condition})
                    AND {subject_condition.replace('a.', 'c.')}
                    """
                    sql_parts.append(sql_part2)
                    print(f"[DEBUG] 添加歷史年度查詢部分: {len(time_queries['historical_conditions'])} 個時間條件")
                except Exception as e:
                    print(f"[ERROR] 建立歷史年度SQL時發生錯誤: {e}")
            
            # 3. 更早年度查詢 (110年以前) - 移除了 JOIN LPB3047WP.U3047107
            if time_queries['older_conditions']:
                try:
                    older_time_condition = ' OR '.join(time_queries['older_conditions'])
                    sql_part3 = f"""
                    {base_select.replace('a.TRNOFN', 'a.BKGOFN AS TRNOFN')}
                    FROM VQRYH0000 a
                    LEFT OUTER JOIN acpgacod d ON a.subacc = d.subacc AND a.year = d.year
                    WHERE a.bkgofn = '{trade_org}'
                    AND ({older_time_condition})
                    AND {subject_condition}
                    """
                    sql_parts.append(sql_part3)
                    print(f"[DEBUG] 添加更早年度查詢部分: {len(time_queries['older_conditions'])} 個時間條件")
                except Exception as e:
                    print(f"[ERROR] 建立更早年度SQL時發生錯誤: {e}")
            
            # 檢查是否有任何有效的SQL部分
            if not sql_parts:
                print("[DEBUG] 沒有有效的時間條件，使用預設查詢")
                sql_part_default = f"""
                {base_select}
                FROM VQRY63047 a
                LEFT OUTER JOIN acpgacod d ON a.subacc = d.subacc AND a.year = d.year
                WHERE a.bkgofn like '%{account_org}%'
                AND a.trnofn = '{trade_org}'
                AND ((a.YEAR BETWEEN 112 AND 113 AND MONTH = 12) OR (a.YEAR = 115 AND MONTH = 01))
                AND {subject_condition}
                """
                sql_parts.append(sql_part_default)
            
            # 組合完整SQL
            if len(sql_parts) == 1:
                # 只有一個查詢部分，不需要UNION
                full_sql = f"""
                {sql_parts[0]}
                ORDER BY YEAR desc, MONTH desc, GENACC, SUBACC, BKGOFN, TRNOFN
                """
            else:
                # 多個查詢部分，使用UNION ALL
                full_sql = f"""
                {' UNION ALL '.join(sql_parts)}
                ORDER BY YEAR desc, MONTH desc, GENACC, SUBACC, BKGOFN, TRNOFN
                """
            
            print(f"[DEBUG] 最終生成的SQL有 {len(sql_parts)} 個部分")
            print(f"[DEBUG] SQL長度: {len(full_sql)} 字元")
            
            return full_sql
            
        except Exception as e:
            print(f"[ERROR] build_budget_sql發生錯誤: {e}")
            print(f"[ERROR] 錯誤類型: {type(e).__name__}")
            import traceback
            print(f"[ERROR] 詳細錯誤: {traceback.format_exc()}")
            
            # 返回一個簡單的預設查詢，避免完全失敗 (移除了 JOIN LPB3047WP.U3047107)
            return """
            SELECT DISTINCT
                a.BKGOFN, a.TRNOFN, a.YEAR, "MONTH",
                a.GENACC, a.SUBACC, RTRIM(a.FULNAM) AS FULNAM,
                AMTTM, BGTTTM, BGTTY
            FROM VQRY63047 a
            WHERE a.bkgofn like '%0000%'
            AND a.trnofn = '3047'
            AND a.YEAR = 115 AND MONTH = 06
            AND a.GENACC LIKE '5%'
            ORDER BY YEAR desc, MONTH desc, GENACC, SUBACC
            """

    def analyze_time_requirements(self, conditions):
        """
        分析時間查詢需求，支援跨年度查詢
        返回：各個資料表需要的時間條件列表
        """
        result = {
            'current_conditions': [],      # 當前年度表格條件 (112年以後)
            'historical_conditions': [],   # 歷史年度表格條件 (111年)
            'older_conditions': []         # 更早年度表格條件 (110年以前)
        }
        
        try:
            print(f"[DEBUG] 分析時間需求，輸入條件: {conditions}")
            
            # 優先處理年月查詢
            if conditions.get('year_month'):
                year_month = conditions['year_month'].strip()
                # 支援多個年月查詢，以逗號分隔
                year_month_list = [ym.strip() for ym in year_month.split(',') if ym.strip()]
                
                for ym in year_month_list:
                    if len(ym) >= 4:
                        try:
                            # 處理不同格式的年月輸入
                            if len(ym) == 5:  # 11406 格式
                                year = ym[:3]
                                month = ym[3:]
                            elif len(ym) == 6:  # 111012 格式
                                year = ym[:3]
                                month = ym[3:]
                            elif len(ym) == 4:  # 1140 格式（年份+月份，月份可能是單位數）
                                year = ym[:3]
                                month = ym[3:]
                            else:
                                print(f"[WARNING] 無法解析的年月格式: {ym}")
                                continue
                            
                            year_int = int(year)
                            month_int = int(month)
                            
                            # 驗證月份範圍
                            if month_int < 1 or month_int > 12:
                                print(f"[WARNING] 無效的月份: {month_int}")
                                continue
                            
                            print(f"[DEBUG] 解析年月: {ym} -> 年:{year}({year_int}), 月:{month}({month_int})")
                            
                            # 根據年份分配到不同的資料表
                            if year_int >= 112:  # 112年以後使用當前表格
                                result['current_conditions'].append(f"(a.YEAR = {year} AND MONTH = {month})")
                            elif year_int == 111:  # 111年使用歷史表格
                                result['historical_conditions'].append(f"(c.YEAR = {year} AND MONTH = {month})")
                            elif year_int <= 110:  # 110年以前使用更早表格
                                result['older_conditions'].append(f"(a.YEAR = {year} AND MONTH = {month})")
                                
                        except ValueError as e:
                            print(f"[WARNING] 年月轉換錯誤: {ym}, 錯誤: {e}")
                            continue
                    else:
                        print(f"[WARNING] 年月格式太短: {ym}")
                
                # 如果成功解析了年月查詢，就不再處理區間查詢
                if any([result['current_conditions'], result['historical_conditions'], result['older_conditions']]):
                    print(f"[DEBUG] 年月查詢解析完成")
                    return result
            
            # 如果沒有年月查詢，或年月查詢解析失敗，處理區間查詢
            if conditions.get('start_year') or conditions.get('end_year'):
                start_year_str = conditions.get('start_year', '').strip()
                end_year_str = conditions.get('end_year', '').strip()

                # 取得登入頁面的年度參數作為預設值
                default_login_year = int(self.main_window.global_year) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else 115

                start_year = int(start_year_str) if start_year_str else 110
                end_year = int(end_year_str) if end_year_str else default_login_year

                print(f"[DEBUG] 區間查詢: 起始年:{start_year}, 結束年:{end_year}")

                # 當前年度表格條件 (112年以後)
                current_start = max(start_year, 112)
                current_end = min(end_year, default_login_year)
                if current_start <= current_end:
                    # 取得登入頁面的年度和月份參數
                    login_year = int(self.main_window.global_year) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else 115
                    login_month = int(self.main_window.global_month) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_month') else 6

                    for year in range(current_start, current_end + 1):
                        if year == login_year:
                            # 登入年度使用登入月份
                            result['current_conditions'].append(f"(a.YEAR = {year} AND MONTH = {login_month:02d})")
                        else:
                            # 其他年份使用12月
                            result['current_conditions'].append(f"(a.YEAR = {year} AND MONTH = 12)")
                
                # 歷史年度表格條件 (111年)
                if start_year <= 111 <= end_year:
                    result['historical_conditions'].append("(c.YEAR = 111 AND MONTH = 12)")
                
                # 更早年度表格條件 (110年以前)
                if start_year <= 110:
                    older_end = min(end_year, 110)
                    for year in range(start_year, older_end + 1):
                        result['older_conditions'].append(f"(a.YEAR = {year} AND MONTH = 12)")
            
            else:
                # 預設條件：使用登入頁面的年度月份和前幾年12月
                print("[DEBUG] 使用預設時間條件")
                # 取得登入頁面的年度和月份參數
                default_login_year = int(self.main_window.global_year) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else 115
                default_login_month = int(self.main_window.global_month) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_month') else 6

                result['current_conditions'].extend([
                    f"(a.YEAR = {default_login_year} AND MONTH = {default_login_month:02d})",
                    f"(a.YEAR = {default_login_year - 1} AND MONTH = 12)",
                    f"(a.YEAR = {default_login_year - 2} AND MONTH = 12)"
                ])
                result['historical_conditions'].append("(c.YEAR = 111 AND MONTH = 12)")
                result['older_conditions'].append("(a.YEAR = 110 AND MONTH = 12)")
            
            print(f"[DEBUG] 最終時間需求分析結果: {result}")
            return result
            
        except Exception as e:
            print(f"[ERROR] analyze_time_requirements發生錯誤: {e}")
            # 返回預設條件
            return {
                'current_conditions': ["(a.YEAR = 115 AND MONTH = 06)"],
                'historical_conditions': [],
                'older_conditions': []
            }

    def auto_adjust_column_width(self, writer, sheet_name, df):
        """自動調整Excel工作表的欄寬"""
        try:
            if not hasattr(writer, 'book') or sheet_name not in writer.book.sheetnames:
                return
                
            workbook = writer.book
            worksheet = workbook[sheet_name]
            
            # 計算每個欄位的適當寬度
            for column_cells in worksheet.columns:
                # 取得欄位字母（如A, B, C等）
                column_letter = column_cells[0].column_letter
                
                # 計算該欄位的最大內容長度
                max_length = 0
                
                for cell in column_cells:
                    try:
                        # 處理欄位標題和內容
                        if cell.value:
                            # 將內容轉換為字串並計算長度
                            cell_value = str(cell.value)
                            
                            # 中文字符計算為1.5倍寬度，英文數字為1倍
                            cell_length = 0
                            for char in cell_value:
                                if '\u4e00' <= char <= '\u9fff':  # 中文字符範圍
                                    cell_length += 1.5
                                else:
                                    cell_length += 1
                            
                            max_length = max(max_length, cell_length)
                    except:
                        continue
                
                # 設定欄寬，最小8，最大50
                adjusted_width = min(max(max_length + 2, 8), 50)
                worksheet.column_dimensions[column_letter].width = adjusted_width
                
            print(f"[DEBUG] 已自動調整工作表 '{sheet_name}' 的欄寬")
            
        except Exception as e:
            print(f"[DEBUG] 自動調整欄寬時發生錯誤: {e}")

    def get_org_condition_base(self, conditions):
        """產生機構相關的WHERE條件（預算單位條件將在記憶體JOIN後套用）"""
        try:
            # 預算單位條件已移除,將在記憶體JOIN後進行篩選
            # 這裡不再產生任何條件
            return "1=1"

        except Exception as e:
            print(f"[ERROR] get_org_condition_base發生錯誤: {e}")
            return "1=1"

    def get_subject_condition(self, conditions):
        """安全版本的科目條件產生方法"""
        try:
            subject_conditions = []
            
            # 總帳科目條件
            if conditions.get('general_account'):
                general_account = conditions['general_account'].strip()
                if '%' in general_account:
                    subject_conditions.append(f"(a.GENACC LIKE '{conditions['general_account']}' and substr(a.genacc,1,2) not in ('59')) or a.GENACC = '570B'")
                else:
                    subject_conditions.append(f"a.GENACC = '{general_account}' ")
            else:
                # 預設條件
                subject_conditions.append("((a.GENACC LIKE '5%' and a.SUBACC LIKE '%' and d.ACCTYP='55') or (a.GENACC = '570B' and a.subacc in ('AA1ZZ','AA2ZZ') and  d.ACCTYP='CO2' and d.itmcod like 'A.01%'))")
            
            # 明細科目條件
            if conditions.get('detail_account'):
                detail_account = conditions['detail_account'].strip()
                subject_conditions.append(f"a.SUBACC like '%{detail_account}%' ")
                
            # 科目名稱條件
            if conditions.get('account_name'):
                account_name = conditions['account_name'].strip()
                subject_conditions.append(f"a.FULNAM LIKE '%{account_name}%'")
            else:
                subject_conditions.append("a.FULNAM LIKE '%%'")
            
            return " AND ".join(subject_conditions)
            
        except Exception as e:
            print(f"[ERROR] get_subject_condition發生錯誤: {e}")
            return "a.GENACC LIKE '5%' AND a.FULNAM LIKE '%%'"

    def on_query_voucher(self):
        """查詢應付憑單傳票資料 - 年度預算動支資料"""
        if not self.validate_inputs():
            return
            
        # 顯示進度條
        self.progress_bar.setVisible(True)
        self.progress_bar.setRange(0, 0)
        self.timer.start(100)
        
        # 建立SQL查詢
        sql = self.build_voucher_sql()
        
        # 在新線程中執行查詢
        self.query_thread = BudgetQueryThread(sql, self.main_window, "voucher")
        self.query_thread.finished.connect(self.query_finished)
        self.query_thread.error.connect(self.query_error)
        self.query_thread.start()
    
    def on_query_budget(self):
        """查詢預算動支資料 - 跨年度預算動支資料"""
