    def get_query_conditions(self):
        """取得查詢條件字典"""
        return {
            'year_month': self.year_month.text().strip(),
            'start_year': self.start_year.text().strip(),
            'end_year': self.end_year.text().strip(),
            'general_account': self.general_account.text().strip(),
            'detail_account': self.detail_account.text().strip(),
            'account_name': self.account_name.text().strip(),
            'institution_code': self.institution_code.text().strip(),
            'trade_org': self.trade_org.text().strip(),
            'account_org': self.account_org.text().strip(),
            'accounting_code': self.accounting_code.text().strip(),
            'prd_code': self.prd_code.text().strip(),
            'cost_account': self.cost_account.text().strip()                        
        }
    
    def get_query_parameters(self):
        """取得查詢參數字典 - 支援區間查詢功能"""
        conditions = self.get_query_conditions()
        
        # 設定預設值（從登入頁面參數讀取）
        year = self.main_window.global_year if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else '115'
        month = self.main_window.global_month if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_month') else '06' 
        trade_org = '3047'
        account_org = '0000'
        use_range_query = False
        start_year = None
        end_year = None
        end_month = None
        
        # 🔥 優先順序1：年月查詢
        if conditions['year_month']:
            if len(conditions['year_month']) >= 5:
                year = conditions['year_month'][:3]
                month = conditions['year_month'][3:].zfill(2)
            else:
                print(f"⚠️ 年月格式可能有誤: {conditions['year_month']}")
        
        # 🔥 優先順序2：區間查詢（起始年+結束年）
        elif conditions['start_year'] and conditions['end_year']:
            try:
                start_year_int = int(conditions['start_year'])
                end_year_int = int(conditions['end_year'])
                # 取得登入頁面的年度和月份參數
                current_year = int(self.main_window.global_year) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_year') else 115
                current_month = int(self.main_window.global_month) if hasattr(self, 'main_window') and hasattr(self.main_window, 'global_month') else 6

                # 驗證年份範圍
                if start_year_int > end_year_int:
                    print(f"⚠️ 起始年({start_year_int})不能大於結束年({end_year_int})")
                    start_year_int, end_year_int = end_year_int, start_year_int

                # 設定區間查詢參數
                use_range_query = True
                start_year = str(start_year_int)
                end_year = str(end_year_int)

                # 計算結束月份
                if end_year_int == current_year:
                    # 結束年是登入年度：查到登入月份
                    end_month = str(current_month).zfill(2)
                else:
                    # 結束年不是登入年度：查到12月
                    end_month = '12'
                
                # 建立年月組合列表用於顯示
                year_month_list = []
                for year in range(start_year_int, end_year_int):
                    year_month_list.append(f"{year}12")
                year_month_list.append(f"{end_year}{end_month}")
                
                print(f"📅 區間查詢年月組合: {', '.join(year_month_list)}")
                
            except ValueError as e:
                print(f"⚠️ 區間年份轉換錯誤: {e}")
                # 回到預設值
                pass
        
        # 🔥 優先順序：trade_org > institution_code > 預設值
        if conditions['trade_org']:
            trade_org = conditions['trade_org']
        elif conditions['institution_code']:
            trade_org = conditions['institution_code']
        
        if conditions['account_org']:
            account_org = conditions['account_org']
        
        # 計算衍生參數（單一年月查詢時使用）
        try:
            if not use_range_query:
                year_int = int(year)
                month_int = int(month)
                prev_year = str(year_int - 1)
                prev_month = str(month_int - 1).zfill(2) if month_int > 1 else '12'
            else:
                year_int = int(end_year)
                month_int = int(end_month)
                prev_year = str(year_int - 1)
                prev_month = str(month_int - 1).zfill(2) if month_int > 1 else '12'
        except ValueError as e:
            print(f"⚠️ 年月轉換錯誤: {e}")
            year_int = 115
            month_int = 6
            prev_year = '113'
            prev_month = '06'
        
        params = {
            'year': year,
            'month': month,
            'prev_year': prev_year,
            'prev_month': prev_month,
            'trade_org': trade_org,
            'account_org': account_org,
            'institution_code': trade_org,
            'year_int': year_int,
            'month_int': month_int,
            # 🆕 新增區間查詢參數
            'use_range_query': use_range_query,
            'start_year': start_year,
            'end_year': end_year,
            'end_month': end_month
        }
        
        print(f"📋 參數解析結果: {params}")
        return params

    def build_revenue_detail_sql(self):
        """建立營收科目明細SQL語句 - 支援區間查詢（修正版）"""
        params = self.get_query_parameters()
        conditions = self.get_query_conditions()
        
        # 🔥 步驟1：處理總帳科目條件
        if conditions.get('general_account') and conditions['general_account'].strip():
            genacc_value = conditions['general_account'].strip()
            if len(genacc_value) >= 4:
                genacc_condition = f"substr(d.genacc,1,4) like '{genacc_value}%'"
            else:
                genacc_condition = f"substr(d.genacc,1,{len(genacc_value)}) like '{genacc_value}%'"
        else:
            genacc_condition = "substr(d.genacc,1,1)='4'"
        
        # 🔥 步驟2：建立時間查詢條件（修正版）
        if params['use_range_query']:
            # 區間查詢：只取特定年月組合
            # 例：110~114 → 取11012、11112、11212、11312、11406
            
            start_year_int = int(params['start_year'])
            end_year_int = int(params['end_year'])
            end_month_int = int(params['end_month'])
            
            # 建立年月組合條件
            year_month_conditions = []
            
            # 起始年到結束年-1：只取12月
            for year in range(start_year_int, end_year_int):
                year_month_conditions.append(f"(c.YEAR = {year} AND c.MONTH = 12)")
            
            # 結束年：取指定月份
            year_month_conditions.append(f"(c.YEAR = {end_year_int} AND c.MONTH = {end_month_int})")
            
            time_condition = "(" + " OR ".join(year_month_conditions) + ")"
            
            # 為a表建立相同條件
            year_month_conditions_a = []
            for year in range(start_year_int, end_year_int):
                year_month_conditions_a.append(f"(a.YEAR = {year} AND a.MONTH = 12)")
            year_month_conditions_a.append(f"(a.YEAR = {end_year_int} AND a.MONTH = {end_month_int})")
            
            time_condition_a = "(" + " OR ".join(year_month_conditions_a) + ")"
            
            print(f"[DEBUG] 區間查詢年月組合: {[f'{y}12' for y in range(start_year_int, end_year_int)] + [f'{end_year_int}{end_month_int:02d}']}")
            
        else:
            # 單一年月查詢
            time_condition = f"c.YEAR={params['year']} and c.MONTH={params['month']}"
            time_condition_a = f"a.YEAR={params['year']} and a.MONTH={params['month']}"
        
        
        # 🔥 步驟3：建立額外查詢條件
        c_additional_conditions = []
        a_additional_conditions = []
        
        if conditions.get('detail_account') and conditions['detail_account'].strip():
            subacc_value = conditions['detail_account'].strip()
            c_additional_conditions.append(f"and c.subacc like '{subacc_value}%'")
            a_additional_conditions.append(f"and a.subacc like '{subacc_value}%'")
        
        if conditions.get('account_name') and conditions['account_name'].strip():
            fulnam_value = conditions['account_name'].strip()
            c_additional_conditions.append(f"and c.fulnam like '%{fulnam_value}%'")
            a_additional_conditions.append(f"and a.fulnam like '%{fulnam_value}%'")
        
        c_conditions_str = '\n    '.join(c_additional_conditions) if c_additional_conditions else ''
        a_conditions_str = '\n    '.join(a_additional_conditions) if a_additional_conditions else ''
        
        # 🔥 步驟4：建立完整SQL語句
        sql_query = f"""
        select distinct c.BKGOFN,c.TRNOFN,c.YEAR,c.MONTH,c.GENACC,c.SUBACC,c.DIGITS,c.FULNAM,
        c.AMTLY,c.AMTLM,c.DAMTTM,c.CAMTTM,c.AMTTM,c.UPDUSR,c.UPDDAT,c.UPDTIM,c.BGTTM,c.BGTTTM,c.BGTTY,c.BCOSDAT,c.BCOSTIM
        from VQRY6{params['trade_org']} c
        where c.bkgofn in ('{params['account_org']}') and c.TRNOFN='{params['trade_org']}' and {time_condition}
        and c.genacc||c.subacc in 
        (
        select d.genacc||d.subacc
        from acpgacod d
        where d.year={params['end_year'] if params['use_range_query'] else params['year']} and ({genacc_condition} and ACCTYP='4' and filtyp='GACCN' and substr(itmcod,1,1)='I')
        )
        {c_conditions_str}
        union
        select distinct a.BKGOFN,a.TRNOFN,a.YEAR,a.MONTH,a.GENACC,a.SUBACC,a.DIGITS,a.FULNAM,
        a.AMTLY,a.AMTLM,a.DAMTTM,a.CAMTTM,a.AMTTM,a.UPDUSR,a.UPDDAT,a.UPDTIM,a.BGTTM,a.BGTTTM,a.BGTTY,a.BCOSDAT,a.BCOSTIM
        FROM VQRY2H0000 a
        where a.bkgofn in ('{params['account_org']}') and a.TRNOFN='{params['trade_org']}' and {time_condition_a}
        and a.genacc||a.subacc in 
        (
        select d.genacc||d.subacc
        from acpgacod d
        where d.year={params['end_year'] if params['use_range_query'] else params['year']} and ({genacc_condition} and ACCTYP='4' and filtyp='GACCN' and substr(itmcod,1,1)='I')
        )
        {a_conditions_str}
        order by 3 desc,4,5,6 
        """
        
        query_type = "區間查詢" if params['use_range_query'] else "單一年月查詢"
        print(f"[DEBUG] 營收科目明細使用{query_type}")
        print(f"[DEBUG] 時間條件: {time_condition}")
        
        return sql_query

