    def build_profit_analysis_sql(self):
        """建立專標案獲利分析SQL語句 - 支援區間查詢"""
        params = self.get_query_parameters()
        conditions = self.get_query_conditions()
        
        print("=== 建立專標案獲利分析SQL ===")
        
        # 🔥 建立時間查詢條件
        if params['use_range_query']:
            # 區間查詢條件
            time_condition = f"""a.bkgyy >= {params['start_year']} AND 
                               ((a.bkgyy > {params['start_year']} AND a.bkgyy < {params['end_year']}) 
                               OR (a.bkgyy = {params['start_year']})
                               OR (a.bkgyy = {params['end_year']} AND a.bkgmm <= {params['end_month']}))"""
            year_for_vqry = params['end_year']
            month_for_vqry = params['end_month']
        else:
            # 單一年月查詢條件
            time_condition = f"bkgyy={params['year']} AND bkgmm<={params['month']}"
            year_for_vqry = params['year']
            month_for_vqry = params['month']
        
        # 建立額外查詢條件
        additional_conditions = []
        
        if conditions.get('detail_account') and conditions['detail_account'].strip():
            subacc_value = conditions['detail_account'].strip()
            additional_conditions.append(f"AND a.subacc like '{subacc_value}%'")
        
        if conditions.get('accounting_code') and conditions['accounting_code'].strip():
            vencod_value = conditions['accounting_code'].strip()
            additional_conditions.append(f"AND a.vencod like '{vencod_value}%'")
        
        if conditions.get('general_account') and conditions['general_account'].strip():
            genacc_value = conditions['general_account'].strip()
            if genacc_value.startswith('4'):
                additional_conditions.append(f"AND a.genacc like '{genacc_value}%'")
            elif genacc_value.startswith('5'):
                additional_conditions.append(f"AND a.genacc like '{genacc_value}%'")
        
        if conditions.get('account_org') and conditions['account_org'].strip():
            account_org_value = conditions['account_org'].strip()
            additional_conditions.append(f"AND a.bkgofn = '{account_org_value}'")
        
        if conditions.get('institution_code') and conditions['institution_code'].strip():
            institution_filter_value = conditions['institution_code'].strip()
            if institution_filter_value != params['trade_org']:
                additional_conditions.append(f"AND a.offnbr = '{institution_filter_value}'")
        
        additional_conditions_str = '\n            '.join(additional_conditions) if additional_conditions else ''
        
        # 🔥 建立完整SQL語句
        sql_template = f"""
        WITH temp AS (
            SELECT a.genacc, a.subacc, a.vencod, SUM(amtnet), ITMCOD, ITMDSC,
                SUM(CASE WHEN a.genacc LIKE '4%' THEN amtnet ELSE 0 END) AS amt1,
                SUM(CASE WHEN a.genacc LIKE '5%' THEN amtnet ELSE 0 END) AS amt2,
                SUM(CASE WHEN a.genacc LIKE '4%' THEN amtnet ELSE 0 END) -
                SUM(CASE WHEN a.genacc LIKE '5%' THEN amtnet ELSE 0 END) AS amt3
            from voud{params['institution_code']} a 
                LEFT JOIN VQRY6{params['institution_code']} b
                    ON a.genacc = b.genacc 
                    AND a.subacc = b.subacc
                    AND YEAR={year_for_vqry}
                    AND MONTH={month_for_vqry}
                    AND b.trnofn='{params['trade_org']}'
                    AND b.bkgofn='{params['account_org']}'
            WHERE a.trnofn='{params['trade_org']}' 
                AND {time_condition}
                AND (substr(a.genacc,1,1) IN ('4','5') 
                AND substr(a.genacc,1,2) NOT IN ('57','47'))
                AND (ITMCOD IN ('D.1','D.2') OR substr(ITMCOD,1,1) = 'I')
                {additional_conditions_str}
            GROUP BY a.genacc, a.subacc, a.vencod, ITMCOD, ITMDSC
        ) 
        SELECT  
            CASE 
                WHEN GROUPING(a.vencod) = 1 THEN '合計'
                ELSE bcnam 
            END AS bcnam,
            CASE 
                WHEN GROUPING(a.vencod) = 1 THEN ''
                ELSE a.vencod 
            END AS vencod, 
            SUM(amt1) AS revenue, 
            SUM(amt2) AS cost, 
            SUM(amt3) AS earnings,
            CASE 
                WHEN SUM(amt1) = 0 AND SUM(amt2) > 0 THEN -1
                WHEN SUM(amt1) = 0 AND SUM(amt2) <= 0 THEN 0
                ELSE DECIMAL(ROUND(DECIMAL(SUM(amt1) - SUM(amt2),20,4) / 
                    DECIMAL(SUM(amt1),20,4),4),10,4)  
            END AS rate
        FROM temp a
        LEFT JOIN vbcname b ON a.vencod = BCK2NO
        GROUP BY ROLLUP((a.vencod, bcnam))
        HAVING GROUPING(a.vencod) = 0 OR GROUPING(bcnam) = 1
        ORDER BY GROUPING(a.vencod),a.vencod
        """
        
        query_type = "區間查詢" if params['use_range_query'] else "單一年月查詢"
        print(f"✅ 使用{query_type}")
        print(f"✅ 時間條件: {time_condition}")
        
        return sql_template

    def build_product_profit_analysis_sql(self):
        """
        建立產品獲利分析SQL語句。
        
        重要說明：
        API 伺服器會掃描 SQL 文字中的所有識別碼，只要識別碼與資料庫檔案名稱相似
        就會進行授權檢查。因此 SQL 中不可出現任何 CTE（WITH ... AS）。
        
        解法：SQL 只查詢 voud 原始資料（genacc, subacc, amtnet）。
        所有 u1072 / u1073 的 JOIN 與計算，全部改到 Python pandas 完成。
        """
        params = self.get_query_parameters()
        conditions = self.get_query_conditions()

        print("=== 建立產品獲利分析SQL (純 voud 查詢，無 CTE) ===")

        # 檢查是否已上傳必要的檔案（此處只做檢查，實際 JOIN 在 Python 端）
        u1072 = get_u1072_data()
        u1073 = get_u1073_data()

        if u1072 is None or u1073 is None:
            raise Exception("請先上傳U1072和U1073檔案後再執行產品獲利分析")

        # 建立時間查詢條件
        if params['use_range_query']:
            time_condition = f"""a.bkgyy >= {params['start_year']} AND
                            ((a.bkgyy > {params['start_year']} AND a.bkgyy < {params['end_year']})
                            OR (a.bkgyy = {params['start_year']})
                            OR (a.bkgyy = {params['end_year']} AND a.bkgmm <= {params['end_month']}))"""
        else:
            time_condition = f"a.bkgyy = {params['year']} AND a.bkgmm <= {params['month']}"

        # 只加入「純 voud 欄位」的篩選條件（不含需要 u1072 的 prd_code）
        # prd_code 篩選改由 Python 端 JOIN 後處理
        additional_conditions = []

        if conditions.get('detail_account') and conditions['detail_account'].strip():
            subacc_value = conditions['detail_account'].strip()
            additional_conditions.append(f"AND a.subacc LIKE '{subacc_value}%'")

        if conditions.get('general_account') and conditions['general_account'].strip():
            genacc_value = conditions['general_account'].strip()
            if len(genacc_value) >= 4:
                genacc_filter = f"SUBSTR(a.genacc, 1, 4) LIKE '{genacc_value}%'"
            else:
                genacc_filter = f"SUBSTR(a.genacc, 1, {len(genacc_value)}) LIKE '{genacc_value}%'"
            additional_conditions.append(f"AND ({genacc_filter})")

        if conditions.get('account_org') and conditions['account_org'].strip():
            account_org_value = conditions['account_org'].strip()
            additional_conditions.append(f"AND a.bkgofn = '{account_org_value}'")

        # prd_code 不放入 SQL，儲存到 params 供 Python 端過濾
        prd_code_filter = conditions.get('prd_code', '').strip() if conditions.get('prd_code') else ''

        additional_conditions_str = '\n        '.join(additional_conditions) if additional_conditions else ''

        # 純粹的 voud 原始資料查詢（不含任何 CTE 或 JOIN）
        sql_template = f"""
        SELECT
            a.genacc,
            a.subacc,
            SUM(a.amtnet) AS amtnet
        FROM voud{params['institution_code']} a
        WHERE a.trnofn = '{params['trade_org']}'
            AND {time_condition}
            AND SUBSTR(a.genacc, 1, 1) IN ('4', '5')
            AND SUBSTR(a.genacc, 1, 2) NOT IN ('57', '47')
            {additional_conditions_str}
        GROUP BY a.genacc, a.subacc
        """

        query_type = "區間查詢" if params['use_range_query'] else "單一年月查詢"
        print(f"[INFO] 使用{query_type}")
        print(f"[INFO] 時間條件: {time_condition}")
        print(f"[INFO] U1072 記錄數: {len(u1072)}，U1073 記錄數: {len(u1073)}")
        if prd_code_filter:
            print(f"[INFO] 產品代號篩選 (Python端): '{prd_code_filter}'")

        return sql_template

    def _build_clean_u1072(self):
        """
        將 u1072 Excel 資料整理成乾淨的 pandas DataFrame，供後續 JOIN 使用。
        回傳欄位：genacc, subacc, genacc01, subacc01, prdcod, costcd
        """
        u1072 = get_u1072_data()
        if u1072 is None:
            return None

        def safe_int_str(val):
            if pd.isna(val):
                return ''
            try:
                return str(int(float(val))).strip()
            except Exception:
                return str(val).strip()

        rows = []
        for _, row in u1072.iterrows():
            genacc   = safe_int_str(row.get('GENACC',  ''))
            subacc   = str(row.get('SUBACC',  '') or '').strip()
            prdcod   = str(row.get('PRDCOD',  '') or '').strip()
            costcd   = str(row.get('COSTCD',  '') or '').strip()
            genacc01 = safe_int_str(row.get('GENACC01', '')) if 'GENACC01' in row.index else ''
            subacc01 = str(row.get('SUBACC01', '') or '').strip() if 'SUBACC01' in row.index else ''
            rows.append({
                'genacc':   genacc,
                'subacc':   subacc,
                'genacc01': genacc01,
                'subacc01': subacc01,
                'prdcod':   prdcod,
                'costcd':   costcd,
            })

        df_clean = pd.DataFrame(rows)

        # 診斷輸出
        print(f"[診斷] U1072 整理後記錄數: {len(df_clean)}")
        rev  = df_clean[df_clean['genacc'].str.startswith('4') & df_clean['prdcod'].ne('')]
        cost = df_clean[df_clean['genacc'].str.startswith('5') & df_clean['prdcod'].ne('')]
        print(f"[診斷] 4開頭(收入)含prdcod: {len(rev)} 筆, 5開頭(成本)含prdcod: {len(cost)} 筆")
        print(f"[診斷] 5開頭含costcd: {len(cost[cost['costcd'].ne('')])} 筆, 無costcd: {len(cost[cost['costcd'].eq('')])} 筆")
        print(f"[診斷] 前5筆樣本:\n{df_clean.head().to_string(index=False)}")
        return df_clean


    def on_product_profit_analysis(self):
        """查詢產品獲利分析"""
        if not self.validate_inputs_enhanced():
            return
            
        self.progress_bar.setVisible(True)
        self.progress_bar.setRange(0, 0)
        self.timer.start(100)
        
        sql = self.build_product_profit_analysis_sql()
        
        self.query_thread = ICTQueryThread(sql, self.main_window, "ict_product_profit")
        # 使用專用 handler，查詢完成後在 Python 端與 u1073 join 補上 PRDNAM
        self.query_thread.finished.connect(self.product_profit_query_finished)
        self.query_thread.error.connect(self.query_error)
        self.query_thread.start()

    def product_profit_query_finished(self, df, message, query_type):
        """
        產品獲利分析查詢完成。
        
        流程：
        1. 取得 voud 原始資料 (genacc, subacc, amtnet)
        2. 在 Python 端與 u1072 做 JOIN (兩組 key)
        3. 過濾 prdcod 非空 (等同原 SQL 的 b.prdcod IS NOT NULL)
        4. 若有 prd_code 篩選條件，在此過濾
        5. 計算 amt1(收入)、amt2(成本)、amt3(毛利)
        6. 依 prdcod 彙總
        7. 與 u1073 JOIN 取得 PRDNAM(產品名稱)
        8. 計算毛利率 rate
        9. 加入合計列
        """
        try:
            # ── 取得查詢條件（prd_code 篩選用）──────────────────────
            conditions = self.get_query_conditions()
            prd_code_filter = conditions.get('prd_code', '').strip() if conditions.get('prd_code') else ''

            # ── 1. 整理 voud 原始資料欄位名稱（統一小寫）──────────
            df.columns = [c.lower().strip() for c in df.columns]
            # 確保 amtnet 為數值
            df['amtnet'] = pd.to_numeric(df['amtnet'], errors='coerce').fillna(0)
            print(f"[INFO] voud 原始資料: {len(df)} 筆 (genacc/subacc 組合)")

            # ── 2. 整理 u1072 對照表 ────────────────────────────────
            u1072_clean = self._build_clean_u1072()
            if u1072_clean is None or u1072_clean.empty:
                raise Exception("U1072 資料為空，無法進行產品獲利分析")

            # ── 3. 做 JOIN（兩組 key 合併，模擬 SQL 的 OR 條件）────
            # 主 key: (genacc, subacc)
            u1072_key1 = u1072_clean[u1072_clean['genacc'].ne('')][
                ['genacc', 'subacc', 'prdcod', 'costcd']].copy()
            j1 = df.merge(u1072_key1, on=['genacc', 'subacc'], how='inner')
            print(f"[INFO] 主 key JOIN 結果: {len(j1)} 筆")

            # 次 key: (genacc01, subacc01) → 重新命名後 JOIN
            u1072_key2 = u1072_clean[u1072_clean['genacc01'].ne('')][
                ['genacc01', 'subacc01', 'prdcod', 'costcd']].copy()
            u1072_key2 = u1072_key2.rename(columns={'genacc01': 'genacc', 'subacc01': 'subacc'})
            j2 = df.merge(u1072_key2, on=['genacc', 'subacc'], how='inner')
            print(f"[INFO] 次 key JOIN 結果: {len(j2)} 筆")

            # 合併兩次 JOIN，以 (genacc, subacc) 去除重複（保留主 key 優先）
            joined = pd.concat([j1, j2]).drop_duplicates(subset=['genacc', 'subacc'])
            print(f"[INFO] 合併去重後: {len(joined)} 筆")

            # ── 4. 過濾 prdcod 非空 ──────────────────────────────────
            joined = joined[joined['prdcod'].notna() & joined['prdcod'].ne('')]
            print(f"[INFO] 過濾 prdcod 非空後: {len(joined)} 筆")

            if joined.empty:
                raise Exception("與 U1072 JOIN 後沒有符合條件的資料，請確認 U1072 中的 GENACC/SUBACC 是否與 voud 相符")

            # ── 5. prd_code 篩選（Python 端過濾，支援代號或名稱）────
            if prd_code_filter:
                # 優先以產品代號 (prdcod) 前綴比對（不分大小寫）
                mask_by_code = joined['prdcod'].str.upper().str.startswith(prd_code_filter.upper())
                if mask_by_code.any():
                    joined = joined[mask_by_code]
                    print(f"[INFO] 以產品代號篩選 '{prd_code_filter}' 後: {len(joined)} 筆")
                else:
                    # 代號無匹配 → 從 u1073 以產品名稱 (AUXAC4) 反查對應 prdcod 清單
                    u1073_tmp = get_u1073_data()
                    matched_prdcods = []
                    if u1073_tmp is not None:
                        u1073_cols_tmp = {c.upper(): c for c in u1073_tmp.columns}
                        prdcod_col_tmp = u1073_cols_tmp.get('PRDCOD')
                        auxac4_col_tmp = u1073_cols_tmp.get('AUXAC4')
                        if prdcod_col_tmp and auxac4_col_tmp:
                            name_mask = u1073_tmp[auxac4_col_tmp].astype(str).str.strip().str.contains(
                                prd_code_filter, na=False)
                            matched_prdcods = (u1073_tmp[name_mask][prdcod_col_tmp]
                                               .astype(str).str.strip().tolist())
                            print(f"[INFO] 產品名稱反查 '{prd_code_filter}' → 代號清單: {matched_prdcods}")
                    if matched_prdcods:
                        joined = joined[joined['prdcod'].isin(matched_prdcods)]
                        print(f"[INFO] 以產品名稱篩選後: {len(joined)} 筆")
                    else:
                        raise Exception(f"找不到符合產品代號或名稱 '{prd_code_filter}' 的資料")
                if joined.empty:
                    raise Exception(f"找不到符合產品代號或名稱 '{prd_code_filter}' 的資料")

            # ── 6. 計算 amt1 / amt2 / amt3 ──────────────────────────
            #   amt1 = 收入：genacc 以 4 開頭
            #   amt2 = 成本：genacc 以 5 開頭 且 costcd 非空
            #   amt3 = 毛利：amt1 - amt2
            joined['amt1'] = joined.apply(
                lambda r: r['amtnet'] if r['genacc'].startswith('4') else 0, axis=1)
            joined['amt2'] = joined.apply(
                lambda r: r['amtnet'] if r['genacc'].startswith('5') and r['costcd'] != '' else 0, axis=1)

            # ── 7. 依 prdcod 彙總 ────────────────────────────────────
            grouped = joined.groupby('prdcod', as_index=False).agg(
                revenue=('amt1', 'sum'),
                cost=('amt2', 'sum'),
            )
            grouped['earnings'] = grouped['revenue'] - grouped['cost']
            grouped['rate'] = grouped.apply(
                lambda r: (
                    -1 if r['revenue'] == 0 and r['cost'] > 0
                    else 0 if r['revenue'] == 0
                    else round((r['revenue'] - r['cost']) / r['revenue'], 4)
                ), axis=1
            )
            print(f"[INFO] 依 prdcod 彙總後: {len(grouped)} 筆")

            # ── 8. 與 u1073 JOIN 取得 PRDNAM ────────────────────────
            u1073 = get_u1073_data()
            if u1073 is not None:
                u1073_cols = {c.upper(): c for c in u1073.columns}
                prdcod_col = u1073_cols.get('PRDCOD')
                auxac4_col = u1073_cols.get('AUXAC4')
                if prdcod_col and auxac4_col:
                    prd_map = dict(zip(
                        u1073[prdcod_col].astype(str).str.strip(),
                        u1073[auxac4_col].astype(str).str.strip()
                    ))
                    grouped['PRDNAM'] = grouped['prdcod'].map(lambda x: prd_map.get(str(x).strip(), str(x).strip()))
                    print(f"[INFO] u1073 產品名稱 JOIN 完成")
                else:
                    grouped['PRDNAM'] = grouped['prdcod']
            else:
                grouped['PRDNAM'] = grouped['prdcod']

            # ── 9. 加入合計列 ────────────────────────────────────────
            total_revenue  = grouped['revenue'].sum()
            total_cost     = grouped['cost'].sum()
            total_earnings = grouped['earnings'].sum()
            total_rate     = (
                -1 if total_revenue == 0 and total_cost > 0
                else 0 if total_revenue == 0
                else round((total_revenue - total_cost) / total_revenue, 4)
            )
            total_row = pd.DataFrame([{
                'PRDNAM':   '合計',
                'prdcod':   '',
                'revenue':  total_revenue,
                'cost':     total_cost,
                'earnings': total_earnings,
                'rate':     total_rate,
            }])

            # ── 10. 組合最終結果：依 prdcod 排序 + 合計列在最後 ──
            grouped = grouped.sort_values('prdcod').reset_index(drop=True)
            result_df = pd.concat([grouped, total_row], ignore_index=True)

            # 欄位順序
            col_order = ['PRDNAM', 'prdcod', 'revenue', 'cost', 'earnings', 'rate']
            result_df = result_df[[c for c in col_order if c in result_df.columns]]

            new_message = f"產品獲利分析完成，共 {len(result_df) - 1} 項產品"
            print(f"[INFO] {new_message}")

            # 繼續走一般的 query_finished 流程
            self.query_finished(result_df, new_message, query_type)

        except Exception as e:
            print(f"[ERROR] product_profit_query_finished 失敗: {e}")
            self.timer.stop()
            self.progress_bar.setVisible(False)
            QMessageBox.critical(self, "查詢錯誤", f"❌ 產品獲利分析 Python JOIN 失敗:\n{str(e)}")

