    def format_number(self, value):
        """
        格式化數值函數 - 修正版，加強錯誤處理
        
        參數說明:
        value: 要格式化的數值
        
        返回:
        str - 格式化後的字串，如果不是數值則返回原值
        """
        # 🔥 修正1：加強空值和異常值檢查
        if value is None or pd.isna(value):
            return ""
        
        # 如果已經是字串且為空，直接返回
        if isinstance(value, str) and value.strip() == "":
            return ""
        
        try:
            # 嘗試轉換為浮點數
            num_value = float(value)
            
            # 🔥 修正2：檢查無窮大和NaN
            if not np.isfinite(num_value):
                return str(value) if value else ""
            
            # 如果是整數，格式化為千分位無小數位
            if abs(num_value - int(num_value)) < 1e-10:  # 使用小的容差值
                return f"{int(num_value):,}"
            else:
                # 如果是小數，格式化為千分位無小數位（修正格式）
                return f"{num_value:,.0f}"
                
        except (ValueError, TypeError, OverflowError) as e:
            # 🔥 修正3：記錄但不拋出異常
            print(f"[DEBUG] 格式化數值時遇到問題: {value}, 錯誤: {e}")
            return str(value) if value else ""

    def format_pct_budget(self, value):
        """
        格式化 N%年度預算 欄位：千分位整數（無小數）
        例：10218950.0 → "10,218,950"
        """
        import numpy as np
        import pandas as pd
        if value is None or (isinstance(value, float) and pd.isna(value)):
            return ""
        if isinstance(value, str):
            s = value.strip()
            if s in ('', 'nan', 'None', 'null'):
                return ""
            try:
                val = float(s)
            except (ValueError, TypeError):
                return s
        else:
            try:
                val = float(value)
            except (ValueError, TypeError):
                return str(value) if value is not None else ""
        try:
            if not np.isfinite(val):
                return str(value)
            return f"{int(round(val)):,}"
        except (TypeError, OverflowError):
            return str(value) if value is not None else ""

    def format_rate_value(self, value):
        """
        格式化動支率欄位：小數二位，保留「正影響」「負影響」特殊文字
        例：26.61 → "26.61"；"正影響" → "正影響"
        """
        import numpy as np
        import pandas as pd
        if value is None or (isinstance(value, float) and pd.isna(value)):
            return ""
        if isinstance(value, str):
            s = value.strip()
            if s in ('', 'nan', 'None', 'null'):
                return ""
            # 保留特殊影響文字
            if s in ('正影響', '負影響'):
                return s
            try:
                val = float(s)
            except (ValueError, TypeError):
                return s
        else:
            try:
                val = float(value)
            except (ValueError, TypeError):
                return str(value) if value is not None else ""
        try:
            if not np.isfinite(val):
                return str(value)
            return f"{val:.2f}"
        except (TypeError, OverflowError):
            return str(value) if value is not None else ""

    def format_percentage(self, value):
        """
        格式化百分比函數 - 新增方法

        參數說明:
        value: 要格式化的百分比數值（小數形式，如0.1515）

        返回:
        str - 格式化後的百分比字串（如"15.15%"）
        """
        if value is None or pd.isna(value):
            return ""
        
        if isinstance(value, str) and value.strip() == "":
            return ""
        
        try:
            # 嘗試轉換為浮點數
            num_value = float(value)
            
            # 檢查無窮大和NaN
            if not np.isfinite(num_value):
                return str(value) if value else ""
            
            # 轉換為百分比格式（乘以100並添加%符號）
            percentage = num_value * 100
            return f"{percentage:.2f}%"
            
        except (ValueError, TypeError, OverflowError) as e:
            print(f"[DEBUG] 格式化百分比時遇到問題: {value}, 錯誤: {e}")
            return str(value) if value else ""

    def is_numeric_column(self, column_name, series):
        """
        判斷欄位是否為數值欄位 - 修正版，加強安全檢查
        
        參數說明:
        column_name: str - 欄位名稱
        series: pandas Series - 要檢查的欄位資料
        
        返回:
        bool - True表示是數值欄位，False表示不是
        """
        # 🔥 修正1：檢查輸入參數有效性
        if series is None or len(series) == 0:
            return False
        
        if not isinstance(column_name, str):
            return False
        
        # 🔥 修正：擴充不需要格式化的欄位清單
        excluded_columns = [
            # 原有的排除欄位
            '年', '年度', 'YEAR', '月', '月份', 'MONTH',              # 日期相關
            '列帳機構', 'BKGOFN', '交易機構', 'TRNOFN', '機構代號', 'OFFNBR',  # 機構代碼
            '總帳', '總帳科目', 'GENACC', '明細帳', 'SUBACC', '會計科目代號位數',       # 會計科目代碼
            '項目代號', 'ITMCOD', 'DIGITS', '更新時間', '更新日期',
            '製票編號', 'REGNBR', '列帳編號', 'BKGNBR', '傳票種類', 'VOUID',
            
            # 🔥 修正：營收科目明細相關欄位（包含所有英文欄位名）
            'DIGITS',           # 會計科目代號位數
            'UPDDAT',           # 更新日期
            'UPDTIM',           # 更新時間  
            'BCOSDAT',          # 更新日期
            'BCOSTIM',          # 更新時間
            
            # 🔥 修正：營收傳票明細相關欄位（包含所有英文欄位名）
            'REGNBR',           # 製票編號
            'BKGNBR',           # 列帳編號
            
            # 🔥 新增：其他不需要格式化的欄位
            'VOUID',            # 傳票種類
            'VENCOD',           # 廠商號碼/專標案編號
            'AUXAC3',           # 輔助帳號三
            'AUXAC4',           # 科目說明            
            'DRCRID',           # 借貸別
            'REGDATE',          # 製票日期
            'BKGDATE',          # 列帳日期
            'OFFNBR',           # 機構代號
            'UPDUSR',           # 更新人員
            
            # 🔥 修正：中文欄位名（翻譯後的欄位名）
            '會計科目代號位數',  # DIGITS
            '更新日期',         # UPDDAT/BCOSDAT
            '更新時間',         # UPDTIM/BCOSTIM  
            '製票編號',         # REGNBR
            '列帳編號',         # BKGNBR
            '廠商號碼',         # VENCOD
            '輔助帳號三',       # AUXAC3
            '科目說明',         # AUXAC4            
            '傳票種類',         # VOUID
            '機構代號',         # OFFNBR
        ]
        
        # 檢查是否為排除的欄位
        if column_name in excluded_columns:
            return False
            
        # 檢查是否包含百分比符號的欄位
        if '%' in column_name or 'YOY' in column_name or '率' in column_name or 'RATE' in column_name:
            return False
            
        try:
            # 🔥 修正2：安全的數值轉換檢查
            # 移除空值和無效值
            clean_series = series.dropna()
            if len(clean_series) == 0:
                return False
            
            # 嘗試轉換為數值，如果超過50%的資料可以轉換就認為是數值欄位
            numeric_converted = pd.to_numeric(clean_series, errors='coerce')
            valid_numeric = numeric_converted.dropna()
            
            if len(clean_series) > 0:
                conversion_ratio = len(valid_numeric) / len(clean_series)
                return conversion_ratio >= 0.5
            
            return False
            
        except Exception as e:
            print(f"[DEBUG] 檢查數值欄位時發生錯誤: {column_name}, 錯誤: {e}")
            return False

    def update_table(self, df):
        """
        更新表格顯示 - 修正 Series 布林判斷錯誤
        
        修正重點：
        1. 避免直接對 pandas Series 進行 if 判斷
        2. 使用安全的布林檢查方法
        3. 加強錯誤處理和邊界條件檢查
        """
        try:
            import numpy as np
            import pandas as pd
            from PyQt6.QtCore import Qt
            from PyQt6.QtWidgets import QTableWidgetItem
            from PyQt6.QtGui import QFont, QColor
            
            # 🔥 修正1：檢查輸入資料有效性
            if df is None:
                print("[DEBUG] 輸入資料為 None")
                self.table.setRowCount(0)
                self.table.setColumnCount(0)
                return
            
            if df.empty:
                print("[DEBUG] 輸入資料為空")
                self.table.setRowCount(0)
                self.table.setColumnCount(0)
                return
            
            if len(df.columns) == 0:
                print("[DEBUG] 資料沒有欄位")
                self.table.setRowCount(0)
                self.table.setColumnCount(0)
                return
            
            print(f"[DEBUG] 處理資料: {len(df)} 行, {len(df.columns)} 欄")
            
            # 儲存本面板的原始資料，供清除篩選使用（避免與查詢結果混用 current_data）
            # 🔥 修正：只在尚未儲存時才存（防止套用篩選時的 update_table 呼叫覆蓋原始資料）
            if not hasattr(self, '_panel_original_data') or self._panel_original_data is None:
                self._panel_original_data = df.copy()
            
            # 處理特殊欄位的格式，避免顯示小數位
            df_display = df.copy()
            
            # 🔥 修正：整數欄位處理（不包含時間日期欄位）
            integer_columns = [
                # 英文欄位名
                'DIGITS',           # 會計科目代號位數
                'REGNBR',           # 製票編號
                'BKGNBR',           # 列帳編號
                'VENCOD',           # 廠商號碼/專標案編號
                'AUXAC3',           # 輔助帳號三
                'AUXAC4',           # 科目說明               
                'VOUID',            # 傳票種類
                'OFFNBR',           # 機構代號
                
                # 中文欄位名（翻譯後的）
                '會計科目代號位數',  # DIGITS
                '製票編號',         # REGNBR
                '列帳編號',         # BKGNBR
                '廠商號碼',         # VENCOD
                '輔助帳號三',       # AUXAC3
                '科目說明',         # AUXAC4                
                '傳票種類',         # VOUID
                '機構代號',         # OFFNBR
            ]
            
            # 🔥 修正：定義時間日期欄位（單獨處理）
            datetime_integer_columns = [
                'UPDDAT',           # 更新日期
                'UPDTIM',           # 更新時間  
                'BCOSDAT',          # 更新日期
                'BCOSTIM',          # 更新時間
                '更新日期',         # 中文欄位
                '更新時間',         # 中文欄位
            ]
            
            # 🔥 第一步：處理整數欄位
            for col in integer_columns:
                if col in df_display.columns:
                    try:
                        def format_integer_safe(x):
                            """安全的整數格式化函數"""
                            if pd.isna(x) or x is None:
                                return ""
                            try:
                                str_val = str(x).strip()
                                if str_val == "" or str_val.lower() in ['nan', 'none', 'null']:
                                    return ""
                                
                                # 確保移除小數點
                                if '.' in str_val:
                                    try:
                                        float_val = float(str_val)
                                        if np.isfinite(float_val):
                                            return str(int(float_val))
                                        else:
                                            return str_val.replace('.0', '')
                                    except (ValueError, OverflowError):
                                        return str_val.replace('.0', '')
                                else:
                                    return str_val
                            except Exception as e:
                                print(f"[DEBUG] 格式化整數 {x} 時發生錯誤: {e}")
                                return str(x).replace('.0', '') if x is not None else ""
                        
                        # 安全的 apply 操作
                        df_display[col] = df_display[col].apply(format_integer_safe)
                        print(f"[DEBUG] 已將欄位 {col} 格式化為整數格式")
                        
                        # 驗證處理結果
                        sample_values = df_display[col].head(3).tolist()
                        print(f"[DEBUG] 欄位 {col} 處理後範例值: {sample_values}")
                        
                    except Exception as e:
                        print(f"[DEBUG] 處理整數欄位 {col} 時發生錯誤: {e}")
                        continue
            
            # 🔥 第二步：修正時間日期欄位處理（避免 Series 布林判斷錯誤）
            for col in datetime_integer_columns:
                if col in df_display.columns:
                    try:
                        print(f"[DEBUG] 開始處理時間日期欄位: {col}")
                        
                        # 🔥 關鍵修正：安全的空值檢查
                        try:
                            # 檢查欄位是否全為空值 - 使用安全的方法
                            series_isna = df_display[col].isna()
                            if len(series_isna) == 0:
                                print(f"[DEBUG] 時間日期欄位 {col} 長度為0，跳過處理")
                                continue
                            
                            is_all_na = series_isna.all()  # 這會返回一個純粹的布林值
                            if is_all_na:
                                print(f"[DEBUG] 時間日期欄位 {col} 全為空值，跳過處理")
                                continue
                        except Exception as check_error:
                            print(f"[DEBUG] 檢查時間日期欄位 {col} 是否為空時發生錯誤: {check_error}")
                            continue
                        
                        # 檢查欄位是否為空
                        if len(df_display[col]) == 0:
                            print(f"[DEBUG] 時間日期欄位 {col} 長度為0，跳過處理")
                            continue
                        
                        def format_datetime_integer_safe(x):
                            """安全的時間日期整數格式化函數"""
                            # 基本空值檢查
                            if pd.isna(x) or x is None:
                                return ""
                            
                            try:
                                # 轉換為字串處理
                                str_val = str(x).strip()
                                if str_val == "" or str_val.lower() in ['nan', 'none', 'null']:
                                    return ""
                                
                                # 🔥 關鍵：去除小數位但不加千分位
                                if '.' in str_val:
                                    try:
                                        float_val = float(str_val)
                                        if np.isfinite(float_val):
                                            return str(int(float_val))  # 直接轉為整數字串
                                        else:
                                            return str_val.replace('.0', '')
                                    except (ValueError, OverflowError):
                                        return str_val.replace('.0', '')
                                else:
                                    return str_val
                                    
                            except Exception as inner_e:
                                print(f"[DEBUG] 格式化時間日期值 {x} 時發生內部錯誤: {inner_e}")
                                return str(x).replace('.0', '') if x is not None else ""
                        
                        # 🔥 修正：安全的 apply 操作
                        print(f"[DEBUG] 對欄位 {col} 套用格式化函數")
                        df_display[col] = df_display[col].apply(format_datetime_integer_safe)
                        
                        print(f"[DEBUG] 已將時間日期欄位 {col} 去除小數位")
                        
                        # 驗證處理結果
                        try:
                            sample_values = df_display[col].head(3).tolist()
                            print(f"[DEBUG] 時間日期欄位 {col} 處理後範例值: {sample_values}")
                        except Exception as sample_e:
                            print(f"[DEBUG] 無法顯示 {col} 的範例值: {sample_e}")
                            
                    except Exception as e:
                        print(f"[DEBUG] 處理時間日期欄位 {col} 時發生錯誤: {e}")
                        import traceback
                        print(f"[DEBUG] 詳細錯誤堆疊: {traceback.format_exc()}")
                        continue
            
            # 🔥 第三步：處理其他特殊欄位格式
            no_format_columns = [
                # 原有的不格式化欄位
                '年', '年度', 'YEAR', '月', '月份', 'MONTH',              # 日期相關
                '列帳機構', 'BKGOFN', '交易機構', 'TRNOFN', '機構代號', 'OFFNBR',  # 機構代碼
                '總帳', '總帳科目', 'GENACC', '明細帳', 'SUBACC', '會計科目代號位數',       # 會計科目代碼
                '項目代號', 'ITMCOD', 'DIGITS', '製票編號', 'REGNBR', '列帳編號', 'BKGNBR', 
                '傳票種類', 'VOUID',
                
                # 營收傳票明細相關欄位
                'VENCOD',           # 廠商號碼/專標案編號
                'AUXAC3',           # 輔助帳號三
                'AUXAC4',           # 科目說明                
                'DRCRID',           # 借貸別
                'REGDATE',          # 製票日期
                'BKGDATE',          # 列帳日期
                'UPDUSR',           # 更新人員
            ]
            
            # 定義需要保持前導零的機構代碼欄位
            institution_columns = ['列帳機構', 'BKGOFN', '交易機構', 'TRNOFN', '機構代號', 'OFFNBR']
            
            # 定義只需要去除小數位的日期欄位
            date_columns = ['年', '年度', 'YEAR', '月', '月份', 'MONTH']
            
            # 定義需要特殊處理的欄位
            percentage_columns = ['獲利率', 'RATE']  # 需要轉換為百分比的欄位
            
            # 🔥 修正：安全的欄位處理
            for col in no_format_columns:
                if col in df_display.columns:
                    try:
                        # 🔥 修正：檢查欄位是否為空
                        if len(df_display[col]) == 0:
                            print(f"[DEBUG] 欄位 {col} 長度為0，跳過處理")
                            continue
                            
                        if col in institution_columns:
                            # 機構代碼欄位：保持原始格式，不進行數值轉換（保留前導零）
                            df_display[col] = df_display[col].apply(
                                lambda x: str(x).strip() if pd.notna(x) else ""
                            )
                        elif col in date_columns:
                            # 日期欄位：只去除小數位，但保持數值
                            def safe_date_format(x):
                                if pd.isna(x):
                                    return ""
                                try:
                                    str_x = str(x)
                                    if str_x.replace('.', '').replace('-', '').isdigit():
                                        return str(int(float(str_x)))
                                    else:
                                        return str_x
                                except:
                                    return str(x) if x is not None else ""
                            
                            df_display[col] = df_display[col].apply(safe_date_format)
                        else:
                            # 其他欄位：一般字串處理
                            df_display[col] = df_display[col].apply(
                                lambda x: str(x).strip() if pd.notna(x) else ""
                            )
                    except Exception as e:
                        print(f"[DEBUG] 處理欄位 {col} 時發生錯誤: {e}")
                        continue
            
            # 🔥 第四步：處理百分比欄位
            for col in percentage_columns:
                if col in df_display.columns:
                    try:
                        # 🔥 修正：檢查欄位是否為空
                        if len(df_display[col]) == 0:
                            print(f"[DEBUG] 百分比欄位 {col} 長度為0，跳過處理")
                            continue
                            
                        df_display[col] = df_display[col].apply(
                            lambda x: self.format_percentage(x) if pd.notna(x) else ""
                        )
                        print(f"[DEBUG] 已將欄位 {col} 格式化為百分比")
                    except Exception as e:
                        print(f"[DEBUG] 處理百分比欄位 {col} 時發生錯誤: {e}")
                        continue
            
            # ── 新增：識別動支率欄位（含「率」或含 YoY → 小數二位、靠右）
            rate_display_columns = [
                c for c in df_display.columns
                if ('率' in c or 'YoY' in c or 'yoy' in c.lower())
                and c not in no_format_columns
            ]

            # ── 新增：識別 N%年度預算 欄位
            #   條件：同時含「%」且含「預算」且不含「率」→ 千分位整數、靠右
            #   ※ 避免誤判 YoY%、截至本月預算動支率% 等欄位
            pct_budget_display_columns = [
                c for c in df_display.columns
                if '%' in c and '預算' in c and '率' not in c
                and c not in no_format_columns
            ]

            # 🔥 第五步：識別數值欄位（排除已處理的整數、百分比和時間日期欄位）
            numeric_columns = []
            for col in df_display.columns:
                try:
                    if self.is_numeric_column_safe(col, df_display[col]):
                        # 確保不包含已經處理過的欄位
                        if (col not in integer_columns and
                            col not in percentage_columns and
                            col not in datetime_integer_columns):
                            numeric_columns.append(col)
                except Exception as e:
                    print(f"[DEBUG] 檢查欄位 {col} 時發生錯誤: {e}")
                    continue
            
            print(f"[DEBUG] 識別出數值欄位: {numeric_columns}")
            
            # 🔥 修正：安全的合計行計算
            total_row = {}
            if len(df_display.columns) > 0:  # 確保有欄位存在
                for col in df_display.columns:
                    try:
                        # 🔥 關鍵修正：明確排除明細科目和其他不應合計的欄位
                        non_summable_columns = [
                            # 原有的不合計欄位
                            '年', '年度', 'YEAR', '月', '月份', 'MONTH',
                            '列帳機構', 'BKGOFN', '交易機構', 'TRNOFN', '機構代號', 'OFFNBR',
                            '總帳', '總帳科目', 'GENACC', '明細帳', 'SUBACC', '會計科目代號位數',
                            '項目代號', 'ITMCOD', 'DIGITS', '製票編號', 'REGNBR', '列帳編號', 'BKGNBR',
                            '傳票種類', 'VOUID', '更新時間', '更新日期',
                            
                            # 🔥 新增：明細科目相關欄位（關鍵修正）
                            '明細科目', 'SUBACC', '科目名稱', '科目代碼', '會計科目',
                            '明細帳科目', '子科目', '細科目', '詳細科目',
                            
                            # 🔥 新增：其他代碼類欄位
                            '廠商代碼', 'VENCOD', '輔助帳號', 'AUXAC1', 'AUXAC2', 'AUXAC3', 'AUXAC4',
                            '借貸別', 'DRCRID', '憑證號碼', '單據編號',
                            
                            # 🔥 新增：日期時間欄位
                            '製票日期', 'REGDATE', '列帳日期', 'BKGDATE',
                            '更新日期', 'UPDDAT', '更新時間', 'UPDTIM',
                            '異動日期', 'BCOSDAT', '異動時間', 'BCOSTIM',
                            
                            # 🔥 新增：文字描述欄位
                            '摘要', '備註', '說明', '描述', 'REMARK', 'NOTE', 'DESC',
                            '人員', '更新人員', 'UPDUSR', '操作人員',
                            
                            # 🔥 新增：狀態和分類欄位
                            '狀態', 'STATUS', '類別', 'CATEGORY', '分類',
                            '控制項目', 'CONTROL', 'KPI排除項目', '排除考核項目',
                        ]
                        
                        # 檢查是否為不應合計的欄位
                        should_not_total = (
                            col in non_summable_columns or  # 在明確排除清單中
                            '%' in col or  # 包含百分比符號
                            'YOY' in col or  # 年成長率
                            '率' in col or  # 各種比率
                            'RATE' in col or  # 比率欄位英文
                            '代碼' in col or  # 各種代碼欄位
                            '編號' in col or  # 各種編號欄位
                            col.upper().endswith('ID') or  # 以ID結尾的識別欄位
                            col.upper().endswith('NO') or  # 以NO結尾的編號欄位
                            col.upper().endswith('CODE')   # 以CODE結尾的代碼欄位
                        )
                        
                        # 檢查是否為真正需要合計的數值欄位
                        should_total = (
                            not should_not_total and  # 不在排除清單中
                            self.is_numeric_column_safe(col, df_display[col])  # 是數值欄位
                        )
                        
                        if should_total:
                            total_value = self.calculate_column_total(df_display[col])
                            # 合計數格式化為千分位
                            if abs(total_value) >= 1:  # 大於等於1才顯示小數位
                                total_row[col] = f"{total_value:,.2f}"
                            else:
                                total_row[col] = f"{total_value:,.4f}" if total_value != 0 else "0"
                        else:
                            # 🔥 關鍵修正：非數值欄位的處理
                            if col == df_display.columns[0]:
                                total_row[col] = "📊 合計"
                            else:
                                total_row[col] = ""  # 其他非數值欄位顯示空白
                                
                    except Exception as e:
                        print(f"[DEBUG] 計算欄位 {col} 合計時發生錯誤: {e}")
                        total_row[col] = ""
            
            # 🔥 修正：安全的表格設定
            try:
                # 設定表格行數和列數（+1是為了合計行）
                self.table.setRowCount(len(df_display) + 1)
                self.table.setColumnCount(len(df_display.columns))
                self.table.setHorizontalHeaderLabels(df_display.columns.tolist())
                # 每次新查詢都更新完整欄位清單（欄位選擇器套用不會呼叫此處，故不影響灰色顯示）
                self._rcmAllColumns  = df_display.columns.tolist()
                # 同步更新原始 DataFrame 快照，供已刪除欄位重新勾選時還原資料
                self._csOriginalDf   = df
                self._csDisplayNames = df_display.columns.tolist()
            except Exception as e:
                print(f"[DEBUG] 設定表格大小時發生錯誤: {e}")
                return
            
            # 設定標題欄字體（與內容字體保持一致）
            try:
                header_font = QFont("Microsoft JhengHei", 11, QFont.Weight.Bold)
                self.table.horizontalHeader().setFont(header_font)
                self.table.verticalHeader().setFont(header_font)
            except Exception as e:
                print(f"[DEBUG] 設定標題字體時發生錯誤: {e}")
            
            # 設定一般資料行的字體
            normal_font = QFont("Microsoft JhengHei", 11)
            
            # 設定合計行的字體
            total_font = QFont("Microsoft JhengHei", 12, QFont.Weight.Bold)
            
            # 🔥 修正：安全的資料填入
            # 填入一般資料
            for i in range(len(df_display)):
                for j in range(len(df_display.columns)):
                    try:
                        col_name = df_display.columns[j]
                        value = df_display.iloc[i, j]
                        
                        # 判斷欄位格式化類型（優先序：率 > %預算 > 一般數值）
                        is_rate_col       = col_name in rate_display_columns
                        is_pct_budget_col = col_name in pct_budget_display_columns

                        should_format = (
                            not is_rate_col and
                            not is_pct_budget_col and
                            col_name in numeric_columns and
                            col_name not in no_format_columns and
                            col_name not in percentage_columns and
                            col_name not in integer_columns and
                            col_name not in datetime_integer_columns and
                            '%' not in col_name and
                            'YOY' not in col_name and
                            '率' not in col_name
                        )

                        if is_pct_budget_col:
                            # N%年度預算：千分位整數、靠右
                            display_value = self.format_pct_budget(value)
                            right_align = True
                        elif is_rate_col:
                            # 動支率：小數二位、靠右
                            display_value = self.format_rate_value(value)
                            right_align = True
                        elif should_format:
                            display_value = self.format_number(value)
                            right_align = True
                        else:
                            display_value = str(value) if pd.notna(value) else ""
                            right_align = False

                        item = QTableWidgetItem(display_value)
                        item.setFont(normal_font)

                        # 數值欄位右對齊，文字欄位左對齊
                        if right_align:
                            item.setTextAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                        else:
                            item.setTextAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)
                        
                        self.table.setItem(i, j, item)
                        
                    except Exception as e:
                        print(f"[DEBUG] 填入資料 ({i}, {j}) 時發生錯誤: {e}")
                        # 建立空白項目避免崩潰
                        item = QTableWidgetItem("")
                        item.setFont(normal_font)
                        self.table.setItem(i, j, item)
            
            # 🔥 修正：安全的合計行填入
            total_row_index = len(df_display)
            for j, col_name in enumerate(df_display.columns):
                try:
                    total_value = total_row.get(col_name, "")
                    
                    item = QTableWidgetItem(str(total_value))
                    item.setFont(total_font)
                    
                    # 設定合計行的背景顏色
                    item.setBackground(QColor(240, 248, 255))  # 淺藍色背景
                    
                    # 檢查是否為真正的數值欄位來決定對齊方式
                    should_total = (col_name in numeric_columns and 
                                col_name not in no_format_columns and 
                                col_name not in percentage_columns and
                                col_name not in integer_columns and
                                col_name not in datetime_integer_columns and
                                '%' not in col_name and 
                                'YOY' not in col_name and 
                                '率' not in col_name)
                    
                    if should_total:
                        item.setTextAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                    else:
                        item.setTextAlignment(Qt.AlignmentFlag.AlignCenter | Qt.AlignmentFlag.AlignVCenter)
                    
                    # 如果是第一個欄位（顯示"合計"），設定特殊顏色
                    if j == 0:
                        item.setForeground(QColor(0, 100, 200))  # 深藍色文字
                    
                    self.table.setItem(total_row_index, j, item)
                    
                except Exception as e:
                    print(f"[DEBUG] 填入合計行 ({total_row_index}, {j}) 時發生錯誤: {e}")
                    # 建立空白項目避免崩潰
                    item = QTableWidgetItem("")
                    item.setFont(total_font)
                    self.table.setItem(total_row_index, j, item)
            
            # 調整欄位寬度（依內容自動調整後，再強制最小 80px 確保水平捲軸出現）
            try:
                self.table.resizeColumnsToContents()
                MIN_COL_W = 80
                for _ci in range(self.table.columnCount()):
                    if self.table.columnWidth(_ci) < MIN_COL_W:
                        self.table.setColumnWidth(_ci, MIN_COL_W)
            except Exception as e:
                print(f"[DEBUG] 調整欄位寬度時發生錯誤: {e}")
            
            # 🔥 修正：安全的篩選欄位更新
            try:
                # 保存目前選擇的欄位名稱
                current_selections = []
                for combo in self.filter_columns:
                    current_text = combo.currentText()
                    current_selections.append(current_text)
                
                # 更新篩選欄位選項
                for i, combo in enumerate(self.filter_columns):
                    combo.clear()
                    combo.addItems(df.columns.tolist())
                    
                    # 恢復之前的選擇（如果該欄位仍存在）
                    if i < len(current_selections) and current_selections[i]:
                        if current_selections[i] in df.columns.tolist():
                            index = combo.findText(current_selections[i])
                            if index >= 0:
                                combo.setCurrentIndex(index)
            except Exception as e:
                print(f"[DEBUG] 更新篩選欄位時發生錯誤: {e}")
            
            print(f"[DEBUG] 表格更新完成 - Series 布林判斷錯誤已修正")
            
        except Exception as e:
            print(f"[ERROR] update_table 發生嚴重錯誤: {e}")
            import traceback
            print(f"[ERROR] 錯誤詳情: {traceback.format_exc()}")
            
            # 緊急措施：設定空表格避免崩潰
            try:
                self.table.setRowCount(0)
                self.table.setColumnCount(0)
            except:
                pass

    def is_numeric_column_safe(self, column_name, series):
        """
        判斷欄位是否為數值欄位 - 增強版，更精確地排除明細科目
        """
        try:
            if series is None or len(series) == 0:
                return False
            
            if not isinstance(column_name, str):
                return False
            
            # 🔥 擴充不需要格式化的欄位清單（包含明細科目）
            excluded_columns = [
                # 原有的排除欄位
                '年', '年度', 'YEAR', '月', '月份', 'MONTH',
                '列帳機構', 'BKGOFN', '交易機構', 'TRNOFN', '機構代號', 'OFFNBR',
                '總帳', '總帳科目', 'GENACC', '明細帳', 'SUBACC', '會計科目代號位數',
                '項目代號', 'ITMCOD', 'DIGITS', '更新時間', '更新日期',
                '製票編號', 'REGNBR', '列帳編號', 'BKGNBR', '傳票種類', 'VOUID',
                
                # 🔥 重點新增：明細科目相關（這是關鍵）
                '明細科目', '科目名稱', '科目代碼', '會計科目', '明細帳科目',
                '子科目', '細科目', '詳細科目', 'ACCOUNT_NAME', 'ACC_NAME',
                
                # 營收科目明細相關欄位
                'UPDDAT', 'UPDTIM', 'BCOSDAT', 'BCOSTIM',
                'VENCOD', 'AUXAC3', 'AUXAC4', 'DRCRID', 'REGDATE', 'BKGDATE', 'UPDUSR',
                
                # 中文欄位名
                '會計科目代號位數', '更新日期', '更新時間', '製票編號', '列帳編號',
                '廠商號碼', '輔助帳號三', '傳票種類', '機構代號',
            ]
            
            # 檢查是否為排除的欄位
            if column_name in excluded_columns:
                return False
                
            # 🔥 新增：模糊匹配排除包含特定關鍵字的欄位
            exclude_keywords = ['科目', '代碼', '編號', '名稱', '說明', '備註', '摘要']
            for keyword in exclude_keywords:
                if keyword in column_name:
                    return False
                
            # 檢查是否包含百分比符號的欄位
            if '%' in column_name or 'YOY' in column_name or '率' in column_name or 'RATE' in column_name:
                return False
                
            try:
                # 安全的數值轉換檢查
                clean_series = series.dropna()
                if len(clean_series) == 0:
                    return False
                
                # 嘗試轉換為數值
                numeric_converted = pd.to_numeric(clean_series, errors='coerce')
                valid_numeric = numeric_converted.dropna()
                
                if len(clean_series) > 0:
                    conversion_ratio = len(valid_numeric) / len(clean_series)
                    return conversion_ratio >= 0.5
                
                return False
                
            except Exception as e:
                print(f"[DEBUG] 檢查數值欄位時發生錯誤: {column_name}, 錯誤: {e}")
                return False
                
        except Exception as e:
            print(f"[DEBUG] is_numeric_column_safe 發生錯誤: {e}")
            return False

    def apply_filter_condition_safe(self, series, operator, value):
        """根據運算子和值對Series進行篩選 - 修正版"""
        try:
            # 🔥 修正：安全的 notna() 檢查
            non_null_mask = series.notna()
            
            if operator == '=':
                try:
                    numeric_value = pd.to_numeric(value, errors='raise')
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    exact_match = (numeric_series == numeric_value) & non_null_mask
                    # 🔥 修正：使用 .any() 檢查是否有匹配項
                    if exact_match.any():
                        return exact_match
                except:
                    pass
                str_match = series.astype(str).str.lower() == value.lower()
                return str_match & non_null_mask
                
            elif operator == '!=':
                try:
                    numeric_value = pd.to_numeric(value, errors='raise')
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    numeric_not_equal = (numeric_series != numeric_value) & numeric_series.notna()
                    non_numeric_mask = numeric_series.isna() & non_null_mask
                    str_not_equal = (series.astype(str).str.lower() != value.lower()) & non_numeric_mask
                    return numeric_not_equal | str_not_equal
                except:
                    str_not_equal = (series.astype(str).str.lower() != value.lower()) & non_null_mask
                    return str_not_equal
                    
            elif operator == 'contains':
                return series.astype(str).str.contains(value, case=False, na=False) & non_null_mask
                
            elif operator == 'not contains':
                str_series = series.astype(str)
                contains_mask = str_series.str.contains(value, case=False, na=False)
                is_blank_mask = (
                    series.isna() |
                    (str_series == 'nan') |
                    (str_series.str.strip() == '') |
                    (str_series.str.strip() == 'None')
                )
                return ~contains_mask | is_blank_mask

            elif operator == '開始於':
                str_series = series.astype(str)
                return str_series.str.lower().str.startswith(value.lower(), na=False) & non_null_mask

            elif operator == '不開始於':
                str_series = series.astype(str)
                starts_mask = str_series.str.lower().str.startswith(value.lower(), na=False)
                is_blank_mask = (
                    series.isna() |
                    (str_series == 'nan') |
                    (str_series.str.strip() == '') |
                    (str_series.str.strip() == 'None')
                )
                return ~starts_mask | is_blank_mask

            else:
                try:
                    numeric_value = float(value)
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    valid_numeric_mask = numeric_series.notna()
                    
                    if operator == '>':
                        return (numeric_series > numeric_value) & valid_numeric_mask
                    elif operator == '<':
                        return (numeric_series < numeric_value) & valid_numeric_mask
                    elif operator == '>=':
                        return (numeric_series >= numeric_value) & valid_numeric_mask
                    elif operator == '<=':
                        return (numeric_series <= numeric_value) & valid_numeric_mask
                    else:
                        return pd.Series([False] * len(series))
                        
                except (ValueError, TypeError):
                    if operator in ['>', '<', '>=', '<=']:
                        str_series = series.astype(str)
                        valid_str_mask = non_null_mask
                        
                        if operator == '>':
                            return (str_series > value) & valid_str_mask
                        elif operator == '<':
                            return (str_series < value) & valid_str_mask
                        elif operator == '>=':
                            return (str_series >= value) & valid_str_mask
                        elif operator == '<=':
                            return (str_series <= value) & valid_str_mask
                            
                    return pd.Series([False] * len(series))
                    
        except Exception as e:
            print(f"篩選條件應用錯誤: {e}")
            return pd.Series([False] * len(series))

    def on_filter_safe(self):
        """篩選功能 - 修正版"""
        if self.main_window.current_data is None or self.main_window.current_data.empty:
            QMessageBox.warning(self, "警告", "沒有可篩選的資料！")
            return
        
        filters = []
        for col_combo, op_combo, val_edit in zip(self.filter_columns, self.filter_operators, self.filter_values):
            col = col_combo.currentText()
            operator = op_combo.currentText()
            val = val_edit.text().strip()
            
            if col and operator and val:
                filters.append((col, operator, val))
        
        if not filters:
            QMessageBox.warning(self, "警告", "請至少設定一個篩選條件！")
            return
        
        try:
            df = self.main_window.current_data.copy()
            
            for col, operator, val in filters:
                if col not in df.columns:
                    QMessageBox.critical(self, "錯誤", f"欄位 '{col}' 不存在於資料中！")
                    return
                
                mask = self.apply_filter_condition_safe(df[col], operator, val)  # 🔥 使用修正版方法
                df = df[mask]
                
                if df.empty:
                    break
            
            if df.empty:
                QMessageBox.information(self, "提示", "沒有符合條件的資料！")
                self.main_window.filtered_data = self.main_window.current_data
                self.update_table(self.main_window.current_data)
                return
            
            self.main_window.filtered_data = df
            self.update_table(df)
            
            filter_summary = "\n".join([f"{col} {op} '{val}'" for col, op, val in filters])
            QMessageBox.information(self, "篩選完成", 
                                f"✅ 篩選完成，共 {len(df)} 筆資料\n\n篩選條件：\n{filter_summary}")
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"篩選錯誤: {str(e)}")
                               
    def calculate_column_total(self, series):
        """
        計算欄位合計 - 修正版，加強錯誤處理
        
        參數說明:
        series: pandas Series - 要計算合計的欄位資料
        
        返回:
        float - 合計值，如果無法計算則返回0
        """
        try:
            # 🔥 修正1：檢查輸入有效性
            if series is None or len(series) == 0:
                return 0.0
            
            # 🔥 修正2：安全的數值轉換
            numeric_series = pd.to_numeric(series, errors='coerce')
            
            # 移除無窮大和NaN值
            valid_values = numeric_series[np.isfinite(numeric_series)]
            
            if len(valid_values) == 0:
                return 0.0
            
            total = float(valid_values.sum())
            
            # 🔥 修正3：檢查結果是否有效
            if not np.isfinite(total):
                return 0.0
                
            return total
            
        except Exception as e:
            print(f"[DEBUG] 計算欄位合計時發生錯誤: {e}")
            return 0.0

    def on_clear(self):
        """清除篩選條件 - 使用本面板自身原始資料（避免被查詢結果 current_data 覆蓋）"""
        _orig = getattr(self, '_panel_original_data', None)
        panel_data = _orig if _orig is not None else self.main_window.current_data
        if panel_data is not None:
            self.main_window.filtered_data = panel_data
            self.update_table(panel_data)
            # 恢復全欄後同步更新圖表樞紐分析設定欄位
            try:
                self.main_window.revenue_chart_panel.update_combo_options()
            except Exception:
                pass
        
        # 只重設運算子和值，不重設欄位選擇
        for combo in self.filter_operators:
            combo.setCurrentIndex(0)
        for edit in self.filter_values:
            edit.clear()
        
        # 如果要完全清除包含欄位選擇，可以取消註解下面這段
        # for combo in self.filter_columns:
        #     combo.setCurrentIndex(0)

    # ─────────────────────────────────────────────
    # 動態篩選列：新增 / 刪除 / 重新編號
    # ─────────────────────────────────────────────
    def _add_filter_row(self):
        """動態新增一列篩選條件（含 ✕ 刪除按鈕）"""
        row_num = len(self.filter_columns) + 1

        row_widget = QWidget()
        row_layout = QHBoxLayout(row_widget)
        row_layout.setContentsMargins(0, 2, 0, 2)

        # 左側彈性空間
        row_layout.addStretch(1)

        # 欄位標籤
        lbl = QLabel(f"欄位{row_num}：")
        row_layout.addWidget(lbl)

        # 欄位下拉
        column_combo = QComboBox()
        column_combo.setFixedWidth(135)
        row_layout.addWidget(column_combo)
        self.filter_columns.append(column_combo)

        row_layout.addSpacing(9)

        # 運算子標籤 + 下拉
        row_layout.addWidget(QLabel("運算子："))
        operator_combo = QComboBox()
        operator_combo.addItems(['=', '!=', '>', '<', '>=', '<=', 'contains', 'not contains', '開始於', '不開始於'])
        operator_combo.setFixedWidth(135)
        row_layout.addWidget(operator_combo)
        self.filter_operators.append(operator_combo)

        row_layout.addSpacing(9)

        # 值標籤 + 輸入框
        row_layout.addWidget(QLabel("值："))
        value_edit = QLineEdit()
        value_edit.setFixedWidth(135)
        row_layout.addWidget(value_edit)
        self.filter_values.append(value_edit)

        row_layout.addSpacing(7)

        # ✕ 刪除按鈕
        del_btn = QPushButton("✕")
        del_btn.setFixedSize(25, 25)
        del_btn.setToolTip("刪除此列篩選條件")
        del_btn.setStyleSheet("""
            QPushButton {
                background-color: #dc3545;
                color: white;
                border: none;
                border-radius: 4px;
                font-weight: bold;
                font-size: 13px;
            }
            QPushButton:hover {
                background-color: #c82333;
            }
        """)
        del_btn.clicked.connect(
            lambda checked, rw=row_widget, cc=column_combo,
                   oc=operator_combo, ve=value_edit:
            self._remove_filter_row(rw, cc, oc, ve)
        )
        row_layout.addWidget(del_btn)

        # 右側彈性空間
        row_layout.addStretch(1)

        self.filter_row_widgets.append(row_widget)
        self.filter_rows_layout.addWidget(row_widget)

        # 若已有資料，立即填充欄位下拉
        try:
            if hasattr(self, 'main_window') and self.main_window.current_data is not None:
                cols = list(self.main_window.current_data.columns)
                column_combo.clear()
                column_combo.addItems(cols)
        except Exception:
            pass

        return row_widget

    def _remove_filter_row(self, row_widget, col_combo, op_combo, val_edit):
        """刪除指定的篩選列（至少保留 1 列）"""
        if len(self.filter_columns) <= 1:
            from PyQt6.QtWidgets import QMessageBox
            QMessageBox.information(self, "提示", "至少需要保留一列篩選條件！")
            return

        if col_combo in self.filter_columns:
            idx = self.filter_columns.index(col_combo)
            self.filter_columns.pop(idx)
            self.filter_operators.pop(idx)
            self.filter_values.pop(idx)
            self.filter_row_widgets.pop(idx)

        row_widget.setParent(None)
        row_widget.deleteLater()

        # 重新編號
        self._update_filter_row_labels()

    def _update_filter_row_labels(self):
        """重新編號所有篩選列的「欄位N：」標籤"""
        for i, rw in enumerate(self.filter_row_widgets):
            layout = rw.layout()
            if layout is None:
                continue
            for j in range(layout.count()):
                item = layout.itemAt(j)
                if item and item.widget() and isinstance(item.widget(), QLabel):
                    lbl = item.widget()
                    if lbl.text().startswith("欄位"):
                        lbl.setText(f"欄位{i+1}：")
                        break

    def apply_filter_condition(self, series, operator, value):
        """根據運算子和值對Series進行篩選"""
        try:
            non_null_mask = series.notna()
            
            if operator == '=':
                try:
                    numeric_value = pd.to_numeric(value, errors='raise')
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    exact_match = (numeric_series == numeric_value) & non_null_mask
                    if exact_match.any():
                        return exact_match
                except:
                    pass
                str_match = series.astype(str).str.lower() == value.lower()
                return str_match & non_null_mask
                
            elif operator == '!=':
                try:
                    numeric_value = pd.to_numeric(value, errors='raise')
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    numeric_not_equal = (numeric_series != numeric_value) & numeric_series.notna()
                    non_numeric_mask = numeric_series.isna() & non_null_mask
                    str_not_equal = (series.astype(str).str.lower() != value.lower()) & non_numeric_mask
                    return numeric_not_equal | str_not_equal
                except:
                    str_not_equal = (series.astype(str).str.lower() != value.lower()) & non_null_mask
                    return str_not_equal
                    
            elif operator == 'contains':
                return series.astype(str).str.contains(value, case=False, na=False) & non_null_mask
                
            elif operator == 'not contains':
                # 修正：對於 "not contains"，應該保留空白值
                # 因為空白值確實不包含任何指定的文字

                # 將所有值轉換為字串進行比較
                str_series = series.astype(str)

                # 檢查哪些值包含指定文字
                contains_mask = str_series.str.contains(value, case=False, na=False)

                # 處理空白值的情況
                # 對於空白、None、NaN 等值，我們認為它們不包含任何文字，所以應該保留
                is_blank_mask = (
                    series.isna() |  # None、NaN
                    (str_series == 'nan') |  # 轉換為字串後的 'nan'
                    (str_series.str.strip() == '') |  # 空字串或只有空格
                    (str_series.str.strip() == 'None')  # 字串形式的 'None'
                )

                # 返回：不包含指定文字的記錄 + 空白值記錄
                return ~contains_mask | is_blank_mask

            elif operator == '開始於':
                str_series = series.astype(str)
                return str_series.str.lower().str.startswith(value.lower(), na=False) & non_null_mask

            elif operator == '不開始於':
                str_series = series.astype(str)
                starts_mask = str_series.str.lower().str.startswith(value.lower(), na=False)
                is_blank_mask = (
                    series.isna() |
                    (str_series == 'nan') |
                    (str_series.str.strip() == '') |
                    (str_series.str.strip() == 'None')
                )
                return ~starts_mask | is_blank_mask

            else:
                try:
                    numeric_value = float(value)
                    numeric_series = pd.to_numeric(series, errors='coerce')
                    valid_numeric_mask = numeric_series.notna()
                    
                    if operator == '>':
                        return (numeric_series > numeric_value) & valid_numeric_mask
                    elif operator == '<':
                        return (numeric_series < numeric_value) & valid_numeric_mask
                    elif operator == '>=':
                        return (numeric_series >= numeric_value) & valid_numeric_mask
                    elif operator == '<=':
                        return (numeric_series <= numeric_value) & valid_numeric_mask
                    else:
                        return pd.Series([False] * len(series))
                        
                except (ValueError, TypeError):
                    if operator in ['>', '<', '>=', '<=']:
                        str_series = series.astype(str)
                        valid_str_mask = non_null_mask
                        
                        if operator == '>':
                            return (str_series > value) & valid_str_mask
                        elif operator == '<':
                            return (str_series < value) & valid_str_mask
                        elif operator == '>=':
                            return (str_series >= value) & valid_str_mask
                        elif operator == '<=':
                            return (str_series <= value) & valid_str_mask
                            
                    return pd.Series([False] * len(series))
                    
        except Exception as e:
            print(f"篩選條件應用錯誤: {e}")
            return pd.Series([False] * len(series))
    
