                    ['分析欄位', amount_analysis.get('amount_column', '')],
                    ['⭐ KPI篩選後總動支金額', float(amount_analysis.get('total_amount', 0))],
                    ['⭐ KPI篩選後平均動支金額', float(amount_analysis.get('average_amount', 0))],
