                        amount_val = year_data['amount']
                        budget_current_val = year_data['budget_current']
                        budget_yearly_val = year_data['budget_yearly']
                        execution_rate_current = year_data['execution_rate_current']
                        execution_rate_yearly = year_data['execution_rate_yearly']
                        
