                    chart_data.append([
                        year_data['year'], 
                        year_data['amount'], 
                        year_data['budget_current'], 
                        year_data['budget_yearly'], 
                        year_data['execution_rate_current'], 
                        year_data['execution_rate_yearly']
                    ])
            
