    def apply_kpi_filter_enhanced(self, dept_data):
        """增強版KPI篩選 - 修正變數名稱"""
        try:
            kpi_cols = ['CATEGORY', 'KPI排除項目', '排除考核項目', 'CONTROL']
            kpi_col = None  # 修正：kmp_col -> kpi_col
            
            for col in kpi_cols:
                if col in dept_data.columns:
                    kpi_col = col  # 修正：kmp_col -> kpi_col
                    break
            
            if kpi_col is None:  # 修正：kmp_col -> kpi_col
                return None
            
            original_count = len(dept_data)
            kpi_filtered = dept_data[  # 修正：kmp_filtered -> kpi_filtered
                ~dept_data[kpi_col].astype(str).str.contains('XXX', na=False, case=False)
            ]
            filtered_count = len(kpi_filtered)  # 修正：kmp_filtered -> kpi_filtered
            
            print(f"[DEBUG] KPI篩選結果: 原始 {original_count} 筆 -> 篩選後 {filtered_count} 筆")
            
            return kpi_filtered  # 修正：kmp_filtered -> kpi_filtered
            
        except Exception as e:
            print(f"[DEBUG] KPI篩選錯誤: {e}")
            return None

