    def on_tab_changed(self, index):
        """當切換到營收圖表面板時，更新下拉選單選項"""
        if (self.main_window.tab_widget.widget(index) == self and 
            self.main_window.filtered_data is not None and 
            not self.main_window.filtered_data.empty):
            self.update_combo_options()
    
    def update_combo_options(self):
        """更新下拉選單選項，基於當前查詢結果的欄位"""
        if self.main_window.filtered_data is None or self.main_window.filtered_data.empty:
            return
        
        # 獲取所有欄位名稱（優先讀取查詢結果表格當前可見欄位，含欄位選擇/篩選後狀態）
        columns = list(self.main_window.filtered_data.columns)
        try:
            rp = (getattr(self.main_window, 'result_panel', None) or
                  getattr(self.main_window, 'budget_result_panel', None))
            if rp is not None and hasattr(rp, 'table') and rp.table.columnCount() > 0:
                _tbl_cols = [rp.table.horizontalHeaderItem(c).text()
                             for c in range(rp.table.columnCount())
                             if rp.table.horizontalHeaderItem(c)]
                if _tbl_cols:
                    columns = _tbl_cols
        except Exception:
            pass
        
        # 保存當前的選擇 - 修正：防止reset
        current_index = self.index_combo.currentText()
        current_columns = self.columns_combo.currentText()
        current_values = self.values_combo.currentText()
        current_values2 = self.values2_combo.currentText()
        current_values3 = self.values3_combo.currentText()
        
        # 清空並重新填充下拉選單
        for combo in [self.index_combo, self.columns_combo, self.values_combo, self.values2_combo, self.values3_combo]:
            combo.clear()
            
        # 為欄位和值2、值3添加不選選項 - 修正：columns也可以不選
        self.columns_combo.addItem("(不選)")
        self.values2_combo.addItem("(不選)")
        self.values3_combo.addItem("(不選)")
        
        # 填充所有欄位選項
        for combo in [self.index_combo, self.columns_combo, self.values_combo, self.values2_combo, self.values3_combo]:
            combo.addItems(columns)
        
        # 恢復之前的選擇 - 修正：防止reset
        if current_index in columns:
            self.index_combo.setCurrentText(current_index)
        if current_columns and (current_columns in columns or current_columns == "(不選)"):
            self.columns_combo.setCurrentText(current_columns)
        if current_values in columns:
            self.values_combo.setCurrentText(current_values)
        if current_values2 and (current_values2 in columns or current_values2 == "(不選)"):
            self.values2_combo.setCurrentText(current_values2)
        if current_values3 and (current_values3 in columns or current_values3 == "(不選)"):
            self.values3_combo.setCurrentText(current_values3)
    
