    # 新增：格式化數值的方法
    def format_value(self, value):
        """根據設定格式化數值"""
        try:
            format_type = self.format_combo.currentText()
            currency = self.currency_input.text()
            
            if format_type == "thousands":
                # 顯示為千位單位，並加上千分位
                formatted = f"{value/1000:,.1f}K"
            elif format_type == "millions":
                # 顯示為百萬位單位，並加上千分位
                formatted = f"{value/1000000:,.1f}M"
            else:
                # 正常顯示
                formatted = f"{value:,.0f}"
            
            return f"{currency}{formatted}" if currency else formatted
        except:
            return str(value)
 
       
    def get_date_title_prefix(self):
        """獲取年度月份標題前綴"""
        if self.main_window.filtered_data is None or self.main_window.filtered_data.empty:
            return "營收資料"
        
        df = self.main_window.filtered_data
        
        # 嘗試從資料中找到年度和月份資訊
        year = None
        month = None
        
        # 可能的年度欄位名稱
        year_columns = ['年度', 'YEAR', '會計年度', '民國年', 'YR', '年']
        for col in year_columns:
            if col in df.columns and not df[col].isna().all():
                year_values = df[col].dropna()
                if len(year_values) > 0:
                    year = int(year_values.iloc[0])
                    break
        
        # 可能的月份欄位名稱
        month_columns = ['月份', 'MONTH', '會計月份', '月', 'MM', 'MON']
        for col in month_columns:
            if col in df.columns and not df[col].isna().all():
                month_values = df[col].dropna()
                if len(month_values) > 0:
                    month = int(month_values.iloc[0])
                    break
        
        # 如果找不到，使用當前年月
        if year is None or month is None:
            from datetime import datetime
            now = datetime.now()
            if year is None:
                year = now.year - 1911  # 轉換為民國年
            if month is None:
                month = now.month
        
        return f"{year}年{month}月"
    
