    def regenerate_current_chart(self):
        """重新生成當前圖表 - 不顯示對話窗，使用上次的設定"""
        if self.main_window.current_chart_type == 'bar':
            self.on_bar_chart()
        elif self.main_window.current_chart_type == 'pie':
            self.generate_pie_chart_direct()  # 直接生成，不顯示對話窗
        elif self.main_window.current_chart_type == 'donut':
            self.generate_donut_chart_direct()  # 直接生成，不顯示對話窗
    
    def add_color(self, color):
        """添加顏色"""
        if color in self.main_window.selected_colors:
            QMessageBox.information(self, "提示", f"顏色 {color} 已經在列表中！")
            return
        
        if len(self.main_window.selected_colors) >= 12:
            QMessageBox.warning(self, "警告", "最多只能選擇 12 個自定義顏色！")
            return
        
        self.main_window.selected_colors.append(color)
        self.update_selected_colors_display()
        
        if self.main_window.current_figure and self.main_window.current_chart_type:
            self.regenerate_current_chart()
    
    def remove_color(self, color):
        """移除顏色"""
        if color in self.main_window.selected_colors:
            self.main_window.selected_colors.remove(color)
            self.update_selected_colors_display()
            
            if self.main_window.current_figure and self.main_window.current_chart_type:
                self.regenerate_current_chart()
    
    def clear_all_colors(self):
        """清除所有自定義顏色"""
        if not self.main_window.selected_colors:
            QMessageBox.information(self, "提示", "目前沒有自定義顏色！")
            return
        
        reply = QMessageBox.question(self, "確認", 
                                   f"確定要清除所有 {len(self.main_window.selected_colors)} 個自定義顏色嗎？",
                                   QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        
        if reply == QMessageBox.StandardButton.Yes:
            self.main_window.selected_colors.clear()
            self.update_selected_colors_display()
            
            if self.main_window.current_figure and self.main_window.current_chart_type:
                self.regenerate_current_chart()
    
    def update_selected_colors_display(self):
        """更新已選顏色顯示"""
        for i in reversed(range(self.selected_colors_layout.count())):
            child = self.selected_colors_layout.itemAt(i).widget()
            if child:
                child.deleteLater()
        
        for i, color in enumerate(self.main_window.selected_colors):
            btn = QPushButton()
            btn.setFixedSize(20, 20)
            btn.setStyleSheet(f"""
                QPushButton {{
                    background-color: {color};
                    border: 2px solid #666;
                    border-radius: 4px;
                }}
                QPushButton:hover {{
                    border: 2px solid #333;
                }}
            """)
            btn.setToolTip(f"顏色: {color}\n點擊移除")
            btn.clicked.connect(lambda checked, c=color: self.remove_color(c))
            
            row = i // 8
            col = i % 8
            self.selected_colors_layout.addWidget(btn, row, col)
    
    def get_data_for_chart(self):
        """根據樞紐分析設定取得圖表資料"""
        if self.main_window.filtered_data is None or self.main_window.filtered_data.empty:
            return None
            
        df = self.main_window.filtered_data.copy()
        
        # 獲取使用者選擇的設定
        index_col = self.index_combo.currentText()
        columns_col = self.columns_combo.currentText() if self.columns_combo.currentText() != "(不選)" else None
        values_col = self.values_combo.currentText()
        values2_col = self.values2_combo.currentText() if self.values2_combo.currentText() != "(不選)" else None
        values3_col = self.values3_combo.currentText() if self.values3_combo.currentText() != "(不選)" else None
        aggfunc = self.aggfunc_combo.currentText()
        
        # 檢查必要欄位是否已選擇
        if not index_col or not values_col:
            return None
        
        # 檢查欄位是否存在於資料中
        required_cols = [index_col, values_col]
        if columns_col:
            required_cols.append(columns_col)
        if values2_col:
            required_cols.append(values2_col)
        if values3_col:
            required_cols.append(values3_col)
            
        for col in required_cols:
            if col not in df.columns:
                return None
        
        return df, index_col, columns_col, values_col, values2_col, values3_col, aggfunc

    # 修正1：增強對話窗，讓值欄位下拉選單可以正常使用
    def show_enhanced_column_value_dialog(self, index_col, columns_col, values_col, values2_col, values3_col, df, chart_type="圓餅圖"):
        """顯示增強的欄位值選擇對話窗"""
        from PyQt6.QtWidgets import (
            QDialog, QVBoxLayout, QLabel, QComboBox, QPushButton, QHBoxLayout,
            QGridLayout, QFrame
        )
        from PyQt6.QtGui import QFont, QIcon
        from PyQt6.QtCore import Qt
        
        # 根據圖表類型設定圖標和顏色
        if chart_type == "圓餅圖":
            icon = "🥧"
            color = "#fd7e14"
        else:  # 環圈圖
            icon = "🍩"
            color = "#e83e8c"
        
        dialog = QDialog(self)
        dialog.setWindowTitle(f"{chart_type}設定選擇")
        dialog.setModal(True)
        dialog.resize(450, 320)
        
        # 主布局
        main_layout = QVBoxLayout()
        main_layout.setSpacing(14)
        main_layout.setContentsMargins(18, 18, 18, 18)
        
        # 標題框架
        title_frame = QFrame()
        title_frame.setStyleSheet(f"""
            QFrame {{
                background-color: #f8f9fa;
                border: 2px solid {color};
                border-radius: 7px;
                padding: 7px;
            }}
        """)
        title_layout = QHBoxLayout(title_frame)
        
        # 圖表圖標和標題
        title_label = QLabel(f"{icon} {chart_type}設定選擇")
        title_label.setFont(QFont("Microsoft JhengHei", 14, QFont.Weight.Bold))
        title_label.setStyleSheet(f"color: {color}; border: none;")
        title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        title_layout.addWidget(title_label)
        
        main_layout.addWidget(title_frame)
        
        # 說明標籤
        desc_label = QLabel("請選擇要顯示的內容")
        desc_label.setFont(QFont("Microsoft JhengHei", 11))
        desc_label.setStyleSheet("color: #333; margin: 9px 0;")
        main_layout.addWidget(desc_label)
        
        # 選擇區域
        selection_layout = QGridLayout()
        selection_layout.setSpacing(11)
        
        # 修正1：選擇值欄位 - 現在可以讓用戶選擇要顯示的值欄位
        values_label = QLabel("選擇值欄位:")
        values_label.setFont(QFont("Microsoft JhengHei", 11))
        selection_layout.addWidget(values_label, 0, 0)
        
        values_combo = QComboBox()
        values_combo.setFont(QFont("Microsoft JhengHei", 10))
        values_combo.setMinimumHeight(27)
        
        # 加入所有可用的值欄位
        available_values = [values_col]
        if values2_col:
            available_values.append(values2_col)
        if values3_col:
            available_values.append(values3_col)
        
        values_combo.addItems(available_values)
        values_combo.setCurrentText(values_col)  # 預設選擇第一個值欄位
        # 修正1：啟用值欄位選擇功能
        values_combo.setEnabled(True)
        selection_layout.addWidget(values_combo, 0, 1)
        
        # 選擇欄位值（原本的columns選擇）
        column_label = QLabel(f"選擇{columns_col}:")
        column_label.setFont(QFont("Microsoft JhengHei", 11))
        selection_layout.addWidget(column_label, 1, 0)
        
        column_combo = QComboBox()
        column_combo.setFont(QFont("Microsoft JhengHei", 10))
        column_combo.setMinimumHeight(27)
        unique_values = df[columns_col].unique()
        column_combo.addItems([str(val) for val in sorted(unique_values)])
        selection_layout.addWidget(column_combo, 1, 1)
        
        main_layout.addLayout(selection_layout)
        
        # 提示信息
        hint_label = QLabel("💡 將依據您的選擇動態產生圖表")
        hint_label.setFont(QFont("Microsoft JhengHei", 10))
        hint_label.setStyleSheet("color: #6c757d; font-style: italic; margin: 9px 0;")
        main_layout.addWidget(hint_label)
        
        # 按鈕區域
        button_layout = QHBoxLayout()
        button_layout.setSpacing(9)
        
        # 確定按鈕
        ok_button = QPushButton("✓ 確定")
        ok_button.setFont(QFont("Microsoft JhengHei", 11, QFont.Weight.Bold))
        ok_button.setMinimumHeight(36)
        ok_button.setStyleSheet("""
            QPushButton {
                background-color: #28a745;
                color: white;
                border: none;
                border-radius: 6px;
                padding: 6px 18px;
            }
            QPushButton:hover {
                background-color: #218838;
            }
        """)
        ok_button.clicked.connect(dialog.accept)
        
        # 取消按鈕
        cancel_button = QPushButton("✗ 取消")
        cancel_button.setFont(QFont("Microsoft JhengHei", 11, QFont.Weight.Bold))
        cancel_button.setMinimumHeight(36)
        cancel_button.setStyleSheet("""
            QPushButton {
                background-color: #6c757d;
                color: white;
                border: none;
                border-radius: 6px;
                padding: 6px 18px;
            }
            QPushButton:hover {
                background-color: #5a6268;
            }
        """)
        cancel_button.clicked.connect(dialog.reject)
        
        button_layout.addWidget(ok_button)
        button_layout.addWidget(cancel_button)
        main_layout.addLayout(button_layout)
        
        dialog.setLayout(main_layout)
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            return {
                'values_col': values_combo.currentText(),
                'column_value': column_combo.currentText()
            }
        return None

    # 修正2：修正長條圖處理多值的邏輯
    def on_bar_chart(self):
        """生成長條圖"""
        set_chinese_font()
        import numpy as np
        
        chart_data = self.get_data_for_chart()
        if chart_data is None:
            QMessageBox.warning(self, "警告", "請先選擇樞紐分析設定，並確保資料欄位存在！")
            return
            
        df, index_col, columns_col, values_col, values2_col, values3_col, aggfunc = chart_data
        
        try:
            # 修正2：改進多值處理邏輯
            # 收集所有要處理的值欄位
            value_cols = [values_col]
            if values2_col:
                value_cols.append(values2_col)
            if values3_col:
                value_cols.append(values3_col)
            
            # 建立樞紐表
            pivot_kwargs = {
                'index': index_col,
                'values': value_cols,
                'aggfunc': aggfunc
            }
            
            if columns_col:
                pivot_kwargs['columns'] = columns_col
            
            pivot_table = pd.pivot_table(df, **pivot_kwargs)
            
            if pivot_table.empty:
                QMessageBox.warning(self, "警告", "樞紐分析結果為空，請檢查設定！")
                return
            
            # 修正2：改善多層欄位處理
            if isinstance(pivot_table.columns, pd.MultiIndex):
                if columns_col:
                    # 有columns時，重新命名欄位為更清楚的格式
                    new_columns = []
                    for col in pivot_table.columns:
                        if len(col) > 1:
                            # 格式：值欄位_欄位值
                            new_columns.append(f"{col[0]}_{col[1]}")
                        else:
                            new_columns.append(str(col[0]))
                    pivot_table.columns = new_columns
                else:
                    # 沒有columns時，直接使用值欄位名稱
                    pivot_table.columns = [str(col[0]) if isinstance(col, tuple) else str(col) for col in pivot_table.columns]
            
            # 修正2：確保資料型態正確
            # 將所有數值欄位轉換為數值型態，處理可能的型態不匹配問題
            for col in pivot_table.columns:
                try:
                    pivot_table[col] = pd.to_numeric(pivot_table[col], errors='coerce')
                except:
                    pass
            
            # 移除包含NaN的行
            pivot_table = pivot_table.dropna()
            
            if pivot_table.empty:
                QMessageBox.warning(self, "警告", "處理後的資料為空，請檢查數值欄位！")
                return
            
            plt.close('all')
            fig, ax = plt.subplots(figsize=(12, 8))
            
            colors = self.main_window.selected_colors if self.main_window.selected_colors else self.main_window.default_colors
            show_labels = self.show_index_checkbox.isChecked()
            
            # 繪製長條圖
            if len(pivot_table.columns) == 1:
                # 單一數值欄位
                bars = ax.bar(range(len(pivot_table)), pivot_table.iloc[:, 0], 
                            color=colors[0] if colors else '#4472C4', alpha=0.8, edgecolor='white', linewidth=1.2)
                
                # 添加數值標籤
                if show_labels:
                    for i, bar in enumerate(bars):
                        height = bar.get_height()
                        if pd.notna(height) and height != 0:
                            ax.text(bar.get_x() + bar.get_width()/2., height,
                                self.format_value(height),
                                ha='center', va='bottom', fontsize=10, fontweight='bold')
            else:
                # 多個數值欄位或有columns分組
                x_pos = np.arange(len(pivot_table))
                width = 0.8 / len(pivot_table.columns)
                
                # 修正2：改善圖例標籤處理
                legend_labels = []
                for col in pivot_table.columns:
                    # 如果欄位名稱包含底線，表示是"值欄位_欄位值"的格式
                    if '_' in str(col) and columns_col:
                        parts = str(col).split('_', 1)
                        if len(parts) >= 2:
                            legend_labels.append(parts[1])  # 只顯示欄位值部分
                        else:
                            legend_labels.append(str(col))
                    else:
                        legend_labels.append(str(col))
                
                for i, col in enumerate(pivot_table.columns):
                    color = colors[i % len(colors)] if colors else plt.cm.Set3(i / len(pivot_table.columns))
                    try:
                        bars = ax.bar(x_pos + i * width, pivot_table[col], width, 
                                    label=legend_labels[i] if i < len(legend_labels) else str(col), 
                                    color=color, alpha=0.8, edgecolor='white', linewidth=1.2)
                        
                        # 添加數值標籤
                        if show_labels:
                            for bar, value in zip(bars, pivot_table[col]):
                                if pd.notna(value) and value != 0:
                                    height = bar.get_height()
                                    ax.text(bar.get_x() + bar.get_width()/2., height,
                                        self.format_value(value),
                                        ha='center', va='bottom', fontsize=9, fontweight='bold')
                    except Exception as e:
                        print(f"繪製欄位 {col} 時發生錯誤: {e}")
                        continue
                
                ax.legend(fontsize=10, loc='upper right')
            
            # 設定圖表標題
            if len(value_cols) > 1:
                value_names = ' + '.join(value_cols)
                title_text = f'長條圖 - {index_col} vs {value_names} ({aggfunc})'
            else:
                title_text = f'長條圖 - {index_col} vs {values_col} ({aggfunc})'
            
            ax.set_title(title_text, fontsize=14, fontweight='bold', pad=20)
            ax.set_xlabel(index_col, fontsize=12)
            ax.set_ylabel(f'{values_col} ({aggfunc})', fontsize=12)
            ax.set_xticks(range(len(pivot_table)))
            
            # X軸標籤處理
            x_labels = []
            for idx in pivot_table.index:
                if columns_col and columns_col in ['年度', 'YEAR', '年', '會計年度']:
                    if str(idx).isdigit():
                        x_labels.append(f"{idx}年")
                    else:
                        x_labels.append(str(idx))
                else:
                    x_labels.append(str(idx))
            
            ax.set_xticklabels(x_labels, rotation=45, ha='right')
            
            # 根據數值格式設定Y軸格式
            format_type = self.format_combo.currentText()
            if format_type == "thousands":
                ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'{x/1000:.0f}K'))
            elif format_type == "millions":
                ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'{x/1000000:.1f}M'))
            else:
                ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, p: f'{x:,.0f}'))
            
            ax.grid(True, alpha=0.3, linestyle='--')
            ax.set_axisbelow(True)
            
            plt.tight_layout()
            
            self.main_window.current_chart_type = 'bar'
            self.main_window.current_figure = fig
            self.display_chart(fig)
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"生成長條圖時發生錯誤：{str(e)}\n\n請檢查資料型態和樞紐分析設定")

    def on_pie_chart(self):
        """生成圓餅圖 - 會顯示對話窗"""
        set_chinese_font()
        
        chart_data = self.get_data_for_chart()
        if chart_data is None:
            QMessageBox.warning(self, "警告", "請先選擇樞紐分析設定，並確保資料欄位存在！")
            return
            
        df, index_col, columns_col, values_col, values2_col, values3_col, aggfunc = chart_data
        
        try:
            # 如果有選擇columns，顯示對話窗讓用戶選擇特定值
            if columns_col:
                result = self.show_enhanced_column_value_dialog(
                    index_col, columns_col, values_col, values2_col, values3_col, df, "圓餅圖")
                
                if result is None:
                    return  # 用戶取消
                
                # 儲存選擇結果供後續重新生成使用
                self.last_pie_selection = result
                
                selected_column_value = result['column_value']
                selected_values_col = result['values_col']
                
                # 根據選擇的值篩選資料
                filtered_df = df[df[columns_col].astype(str) == selected_column_value]
                title_suffix = f"【{columns_col}: {selected_column_value}】"
            else:
                # 沒有columns時，清除之前的選擇記錄
                self.last_pie_selection = None
                filtered_df = df
                selected_values_col = values_col
                title_suffix = ""
            
            # 生成圖表
            self._generate_pie_chart_core(filtered_df, index_col, selected_values_col, aggfunc, title_suffix)
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"生成圓餅圖時發生錯誤：{str(e)}")

    def generate_pie_chart_direct(self):
        """直接生成圓餅圖 - 不顯示對話窗，使用上次的設定"""
        set_chinese_font()
        
        chart_data = self.get_data_for_chart()
        if chart_data is None:
            return
            
        df, index_col, columns_col, values_col, values2_col, values3_col, aggfunc = chart_data
        
        try:
            # 如果有columns且有上次的選擇記錄，使用上次的設定
            if columns_col and self.last_pie_selection:
                selected_column_value = self.last_pie_selection['column_value']
                selected_values_col = self.last_pie_selection['values_col']
                
                # 根據上次的選擇篩選資料
                filtered_df = df[df[columns_col].astype(str) == selected_column_value]
                title_suffix = f"【{columns_col}: {selected_column_value}】"
            else:
                # 沒有columns或沒有上次選擇記錄，使用預設設定
                filtered_df = df
                selected_values_col = values_col
                title_suffix = ""
            
            # 生成圖表
            self._generate_pie_chart_core(filtered_df, index_col, selected_values_col, aggfunc, title_suffix)
            
        except Exception as e:
            # 靜默處理錯誤，避免在樣式變更時出現錯誤提示
            pass

    def _generate_pie_chart_core(self, filtered_df, index_col, selected_values_col, aggfunc, title_suffix):
        """圓餅圖核心生成邏輯"""
        # 建立簡單的聚合資料
        grouped_data = filtered_df.groupby(index_col)[selected_values_col].agg(aggfunc)
        positive_data = grouped_data[grouped_data > 0]
        
        if positive_data.empty:
            return
        
        plt.close('all')
        fig, ax = plt.subplots(figsize=(9, 7))
        
        colors = self.main_window.selected_colors if self.main_window.selected_colors else self.main_window.default_colors
        while len(colors) < len(positive_data):
            colors = colors + self.main_window.default_colors
        
        show_labels = self.show_index_checkbox.isChecked()
        
        # 永遠顯示標籤和百分比
        wedges, texts, autotexts = ax.pie(
            positive_data,
            labels=positive_data.index,
            autopct='%1.1f%%',
            startangle=20,
            pctdistance=0.85,
            colors=colors[:len(positive_data)],
            textprops={'fontsize': 12}
        )
        
        # 設定百分比文字樣式
        for autotext in autotexts:
            autotext.set_fontsize(11)
            autotext.set_color('white')
            autotext.set_weight('bold')
        
        ax.axis('equal')
        
        # 使用新的標題格式
        if show_labels:
            actual_total = grouped_data.sum()
            title_text = f'圓餅圖 - {index_col} vs {selected_values_col} ({aggfunc}){title_suffix}\n(實際總計: {self.format_value(actual_total)})'
        else:
            title_text = f'圓餅圖 - {index_col} vs {selected_values_col} ({aggfunc}){title_suffix}'
        
        ax.set_title(title_text, fontsize=14, pad=15, weight='bold')
        
        # 永遠顯示圖例
        ax.legend(wedges, positive_data.index, loc="center left", bbox_to_anchor=(1, 0.5), fontsize=9)
        
        plt.tight_layout(pad=1.0)
        
        self.main_window.current_chart_type = 'pie'
        self.main_window.current_figure = fig
        self.display_chart(fig)

