    def __init__(s,mw):
        super().__init__();s.mw=mw;s.data_file=OFFICE_DATA_DIR/"calendar_events.json";s.events=[];OFFICE_DATA_DIR.mkdir(parents=True,exist_ok=True);s.pwa_bridge=PWASyncBridge();s.load_data();s.init_ui()  # v5.29 +pwa_bridge
