        s.tbl=QTableWidget();s.tbl.setColumnCount(6);s.tbl.setHorizontalHeaderLabels(["✓","任務名稱","優先級","到期日","類別","狀態"]);s.tbl.horizontalHeader().setSectionResizeMode(1,QHeaderView.ResizeMode.Stretch);s.tbl.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows);s.tbl.cellDoubleClicked.connect(s.edit_task);s.tbl.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu);s.tbl.customContextMenuRequested.connect(s.show_ctx_menu);lo.addWidget(s.tbl)
