class _FreeCard(QFrame):
    """便條紙自由拖曳卡片 - 可拖曳至畫布任意位置"""
    CARD_W, CARD_H = 280, 200
    def __init__(self, note, panel):
        super().__init__(panel.gw)
        self.note   = note
        self.panel  = panel
        self._drag_offset = None
        self.setCursor(Qt.CursorShape.OpenHandCursor)
    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_offset = event.pos()
            self.setCursor(Qt.CursorShape.ClosedHandCursor)
            self.raise_()
        super().mousePressEvent(event)
    def mouseMoveEvent(self, event):
        if self._drag_offset is not None:
            new_pos = self.mapToParent(event.pos() - self._drag_offset)
            x = max(0, new_pos.x())
            y = max(0, new_pos.y())
            self.move(x, y)
            canvas = self.parent()
            need_w = x + self.CARD_W + 20
            need_h = y + self.CARD_H + 20
            if need_w > canvas.minimumWidth() or need_h > canvas.minimumHeight():
                canvas.setMinimumSize(
                    max(canvas.minimumWidth(), need_w),
                    max(canvas.minimumHeight(), need_h))
        super().mouseMoveEvent(event)
    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._drag_offset is not None:
            self.setCursor(Qt.CursorShape.OpenHandCursor)
            pos = self.pos()
            self.note['x'] = pos.x()
            self.note['y'] = pos.y()
            self.panel.save_data()
            self._drag_offset = None
        super().mouseReleaseEvent(event)

class _FreeCanvas(QWidget):
    """便條紙自由定位畫布"""
    def __init__(self, panel):
        super().__init__()
        self.panel = panel
        self.setMinimumSize(864, 576)

