        self.tabs.addTab(self._build_compound_tab(),     "💰 複利終值")
        self.tabs.addTab(self._build_loan_tab(),         "🏦 貸款攤還")
        self.tabs.addTab(self._build_irr_tab(),          "📈 IRR/NPV")
        layout.addWidget(self.tabs, stretch=5)

        # ── 歷史紀錄 ──
        history_group = QGroupBox("🕐 計算歷史")
        history_group.setStyleSheet("QGroupBox{font-weight:bold;font-size:12px;}")
        hl = QVBoxLayout(history_group)
        self.history_widget = QListWidget()
        self.history_widget.setStyleSheet("font-size:14px;")
        self.history_widget.setMaximumHeight(144)
        hl.addWidget(self.history_widget)

        # 匯出按鈕列
        export_row = QHBoxLayout()
        btn_csv = QPushButton("📋 匯出歷史 (CSV)")
        btn_csv.setStyleSheet(self.STYLE_EXPORT_BTN)
        btn_csv.clicked.connect(self._export_history_csv)
        btn_excel = QPushButton("📊 匯出攤還表 (Excel)")
        btn_excel.setStyleSheet(self.STYLE_EXPORT_BTN)
        btn_excel.clicked.connect(self._export_amortization_excel)
        btn_clear = QPushButton("🗑 清除歷史")
        btn_clear.setStyleSheet(self.STYLE_EXPORT_BTN)
        btn_clear.clicked.connect(self._clear_history)
        export_row.addWidget(btn_csv)
