    # ==================================================================
    #  基礎計算機邏輯
    # ==================================================================
    def _on_calc_button(self, text):
        if text == "AC":
            self._calc_clear()
        elif text == "+/-":
            self._calc_negate()
        elif text == "%":
            self._calc_percent()
        elif text in ("÷", "×", "−", "+"):
            self._calc_operator(text)
        elif text == "=":
            self._calc_equals()
        elif text == ".":
            self._calc_decimal()
        else:
            self._calc_digit(text)

    def _update_display(self):
        try:
            val = float(self.current_display)
            if val == int(val) and "." not in self.current_display:
                formatted = f"{int(val):,}"
            else:
                formatted = self.current_display
        except ValueError:
            formatted = self.current_display
        self._display_updating = True
        self.display.setText(formatted)
        self._display_updating = False

    def _on_display_text_changed(self, text):
        if self._display_updating:
            return
        clean = text.replace(',', '').replace(' ', '').strip()
        if clean in ('', '-'):
            return
        try:
            float(clean)
            self.current_display = clean
            self.waiting_for_operand = False
            self.first_operand = None
            self.pending_operator = None
        except ValueError:
            self._display_updating = True
            self.display.setText(self.current_display)
            self._display_updating = False

    def _calc_clear(self):
        self.current_display = "0"
        self.first_operand = None
        self.pending_operator = None
        self.waiting_for_operand = True
        self._update_display()

    def _calc_digit(self, d):
        if self.waiting_for_operand:
            self.current_display = d
            self.waiting_for_operand = False
        else:
            if self.current_display == "0":
                self.current_display = d
            else:
                self.current_display += d
        self._update_display()

    def _calc_decimal(self):
        if self.waiting_for_operand:
            self.current_display = "0."
            self.waiting_for_operand = False
        elif "." not in self.current_display:
            self.current_display += "."
        self._update_display()

    def _calc_negate(self):
        val = float(self.current_display)
        val = -val
        self.current_display = str(int(val)) if val == int(val) else str(val)
        self._update_display()

    def _calc_percent(self):
        val = float(self.current_display) / 100
        self.current_display = str(val)
        self._update_display()

    def _calc_operator(self, op):
        operand = float(self.current_display)
        if self.first_operand is not None and not self.waiting_for_operand:
            result = self._do_math(self.first_operand, operand, self.pending_operator)
            self.current_display = self._format_result(result)
            self._update_display()
            self.first_operand = result
        else:
            self.first_operand = operand
        self.pending_operator = op
        self.waiting_for_operand = True

    def _calc_equals(self):
        if self.first_operand is None or self.pending_operator is None:
            return
        operand = float(self.current_display)
        result = self._do_math(self.first_operand, operand, self.pending_operator)

        # 歷史紀錄
        op_map = {"÷": "÷", "×": "×", "−": "-", "+": "+"}
        op_symbol = op_map.get(self.pending_operator, self.pending_operator)
        expr = f"{self._fmt_num(self.first_operand)} {op_symbol} {self._fmt_num(operand)} = {self._fmt_num(result)}"
        self._add_history(expr)

        self.current_display = self._format_result(result)
        self._update_display()
        self.first_operand = None
        self.pending_operator = None
        self.waiting_for_operand = True

    @staticmethod
    def _do_math(a, b, op):
        if op == "+":  return a + b
        if op == "−":  return a - b
        if op == "×":  return a * b
        if op == "÷":  return a / b if b != 0 else float("inf")
        return b

    @staticmethod
    def _format_result(val):
        if val == float("inf") or val == float("-inf"):
            return "Error"
        if val == int(val):
            return str(int(val))
        return f"{val:.10g}"

    @staticmethod
    def _fmt_num(val):
        if val == int(val):
            return f"{int(val):,}"
        return f"{val:,.2f}"

    # ==================================================================
    #  預算達成率
    # ==================================================================
    def _calc_budget(self):
        try:
            actual = float(self.budget_actual.text())
            target = float(self.budget_target.text())
            if target == 0:
                self.budget_result.setText("⚠️ 預算值不可為 0")
                return
            rate = (actual / target) * 100
            diff = actual - target
            sign = "+" if diff >= 0 else ""
            color = "#27ae60" if rate >= 100 else "#e67e22" if rate >= 80 else "#e74c3c"
            self.budget_result.setText(
                f'<span style="color:{color}">達成率 {rate:.1f}%（{sign}{diff:,.2f}）</span>'
            )
            self._add_history(f"[預算] 實際{actual:,.0f} / 預算{target:,.0f} = {rate:.1f}%")
        except Exception as e:
            QMessageBox.warning(self, "錯誤", f"請輸入有效數字：{e}")

    # ==================================================================
    #  複利終值
    # ==================================================================
    def _calc_compound(self):
        try:
            P = float(self.compound_principal.text())
            r = float(self.compound_rate.text()) / 100
            n = float(self.compound_years.text())
            fv = P * (1 + r) ** n
            interest = fv - P
            self.compound_result.setText(
                f"💰 終值 {fv:,.2f}\n"
                f"📈 累計利息 {interest:,.2f}\n"
                f"📊 增值倍數 {fv/P:.2f}x"
            )
            self._add_history(f"[複利] 本金{P:,.0f} × {r*100}% × {n:.0f}年 → 終值{fv:,.0f}")
        except Exception as e:
            QMessageBox.warning(self, "錯誤", f"請輸入有效數字：{e}")

    # ==================================================================
    #  貸款攤還（本利均攤）
    # ==================================================================
    def _calc_loan(self):
        try:
            P = float(self.loan_amount.text())
            annual_rate = float(self.loan_rate.text()) / 100
            years = int(self.loan_years.text())
            r = annual_rate / 12
            n = years * 12

            if r == 0:
                monthly = P / n
            else:
                monthly = P * r * (1 + r) ** n / ((1 + r) ** n - 1)
            total = monthly * n
            interest = total - P

            self.loan_result.setText(
                f"📌 每月還款 {monthly:,.0f} 元　　"
                f"📌 總還款 {total:,.0f} 元　　"
                f"📌 總利息 {interest:,.0f} 元"
            )
            self._add_history(
                f"[貸款] {P:,.0f}元, {annual_rate*100}%, {years}年 → 月付{monthly:,.0f}"
            )

            # 建立逐月攤還明細
            self.last_amortization = []
            balance = P
            self.amort_table.setRowCount(n)
            for i in range(n):
                interest_part = balance * r
                principal_part = monthly - interest_part
                balance -= principal_part
                if balance < 0:
                    balance = 0
                row = {
                    "期數": i + 1,
                    "月付金": monthly,
                    "本金": principal_part,
                    "利息": interest_part,
                    "剩餘本金": balance,
                }
                self.last_amortization.append(row)
                self.amort_table.setItem(i, 0, QTableWidgetItem(str(i + 1)))
                self.amort_table.setItem(i, 1, QTableWidgetItem(f"{monthly:,.0f}"))
                self.amort_table.setItem(i, 2, QTableWidgetItem(f"{principal_part:,.0f}"))
                self.amort_table.setItem(i, 3, QTableWidgetItem(f"{interest_part:,.0f}"))
                self.amort_table.setItem(i, 4, QTableWidgetItem(f"{balance:,.0f}"))

        except Exception as e:
            QMessageBox.warning(self, "錯誤", f"請輸入有效數字：{e}")

    # ==================================================================
    #  IRR / NPV
    # ==================================================================
    def _calc_irr(self):
        try:
            inv = float(self.irr_investment.text())
            cfs_text = self.irr_cashflows.text().strip()
            cfs = [float(x.strip()) for x in cfs_text.split(",") if x.strip()]
            all_cfs = [inv] + cfs

            # NPV
            disc_text = self.irr_discount.text().strip()
            disc = float(disc_text) / 100 if disc_text else 0.1
            npv = sum(cf / (1 + disc) ** t for t, cf in enumerate(all_cfs))

            # IRR（牛頓法）
            irr = self._calc_irr_newton(all_cfs)

            irr_str = f"{irr*100:.2f}%" if irr is not None else "無法收斂"
            color_npv = "#27ae60" if npv >= 0 else "#e74c3c"
            self.irr_result.setText(
                f'NPV（折現率 {disc*100:.1f}%）= <span style="color:{color_npv}">{npv:,.2f}</span>\n'
                f"IRR = {irr_str}"
            )
            self._add_history(
                f"[IRR/NPV] 投資{inv:,.0f}, {len(cfs)}期 → NPV={npv:,.0f}, IRR={irr_str}"
            )
        except Exception as e:
            QMessageBox.warning(self, "錯誤", f"請輸入有效數字：{e}")

    @staticmethod
    def _calc_irr_newton(cashflows, guess=0.1, tol=1e-7, max_iter=1000):
        """牛頓法求 IRR"""
        rate = guess
        for _ in range(max_iter):
            npv = sum(cf / (1 + rate) ** t for t, cf in enumerate(cashflows))
            dnpv = sum(-t * cf / (1 + rate) ** (t + 1) for t, cf in enumerate(cashflows))
            if abs(dnpv) < 1e-14:
                return None
            new_rate = rate - npv / dnpv
            if abs(new_rate - rate) < tol:
                return new_rate
            rate = new_rate
        return None

    # ==================================================================
    #  歷史紀錄
    # ==================================================================
    def _add_history(self, text):
        ts = datetime.now().strftime("%H:%M:%S")
        entry = f"[{ts}] {text}"
        self.history_list_data.insert(0, entry)
        self.history_widget.insertItem(0, entry)
        # 限制 500 筆
        if len(self.history_list_data) > 500:
            self.history_list_data = self.history_list_data[:500]
        self._save_history()

    def _clear_history(self):
        self.history_list_data.clear()
        self.history_widget.clear()
        self._save_history()

    def _save_history(self):
        try:
            os.makedirs(HISTORY_DIR, exist_ok=True)
            with open(HISTORY_FILE, "w", encoding="utf-8") as f:
                json.dump(self.history_list_data, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _load_history(self):
        try:
            if os.path.exists(HISTORY_FILE):
                with open(HISTORY_FILE, "r", encoding="utf-8") as f:
                    self.history_list_data = json.load(f)
                for item in self.history_list_data:
                    self.history_widget.addItem(item)
        except Exception:
            pass

    # ==================================================================
    #  匯出功能
    # ==================================================================
    def _export_history_csv(self):
        if not self.history_list_data:
            QMessageBox.information(self, "提示", "尚無歷史紀錄可匯出")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "匯出計算歷史", "計算歷史.csv", "CSV 檔案 (*.csv)"
        )
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8-sig", newline="") as f:
                writer = csv.writer(f)
                writer.writerow(["序號", "計算紀錄"])
                for i, entry in enumerate(self.history_list_data, 1):
                    writer.writerow([i, entry])
            QMessageBox.information(self, "成功", f"已匯出 {len(self.history_list_data)} 筆紀錄\n{path}")
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"匯出失敗：{e}")

    def _export_amortization_excel(self):
        if not self.last_amortization:
            QMessageBox.information(self, "提示", "請先執行貸款攤還計算")
            return
        if not OPENPYXL_AVAILABLE:
            QMessageBox.warning(self, "錯誤", "openpyxl 未安裝，無法匯出 Excel")
            return
        path, _ = QFileDialog.getSaveFileName(
            self, "匯出攤還明細表", "貸款攤還明細.xlsx", "Excel 檔案 (*.xlsx)"
        )
        if not path:
            return
        try:
            wb = openpyxl.Workbook()
            ws = wb.active
            ws.title = "攤還明細"

            # 標題
            headers = ["期數", "月付金", "本金", "利息", "剩餘本金"]
            header_fill = PatternFill(start_color="2980B9", end_color="2980B9", fill_type="solid")
            header_font = XlFont(bold=True, color="FFFFFF", size=11)
            thin_border = Border(
                left=Side(style="thin"), right=Side(style="thin"),
                top=Side(style="thin"), bottom=Side(style="thin"),
            )

            for c, h in enumerate(headers, 1):
                cell = ws.cell(row=1, column=c, value=h)
                cell.fill = header_fill
                cell.font = header_font
                cell.alignment = Alignment(horizontal="center")
                cell.border = thin_border

            # 資料
            num_fmt = '#,##0'
            for r, row in enumerate(self.last_amortization, 2):
                ws.cell(row=r, column=1, value=row["期數"]).border = thin_border
                for c, key in enumerate(["月付金", "本金", "利息", "剩餘本金"], 2):
                    cell = ws.cell(row=r, column=c, value=round(row[key]))
                    cell.number_format = num_fmt
                    cell.border = thin_border

            # 欄寬
            for col in range(1, 6):
                ws.column_dimensions[chr(64 + col)].width = 16

            wb.save(path)
            QMessageBox.information(
                self, "成功",
                f"已匯出 {len(self.last_amortization)} 期攤還明細\n{path}"
            )
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"匯出失敗：{e}")


