    def safe_set_stylesheet(self, widget, stylesheet):
        """安全設定樣式表的方法 - 修正版"""
        try:
            if widget is not None:
                widget.setStyleSheet(stylesheet)
        except Exception as e:
            print(f"設定樣式表時發生錯誤: {e}")
            try:
                if widget is not None:
                    widget.setStyleSheet("""
                        QWidget {
                            background-color: #f8f9fa;
                            font-family: 'Microsoft JhengHei';
                        }
                        QLabel {
                            color: #2c3e50;
                            font-size: 13px;
                        }
                    """)
            except Exception:
                pass

    def save_login_config(self):
        """保存登入設定到配置檔案 - API Token版：不保存Token，保存API位址、機構代號、年度、月份"""
        try:
            if self.remember_login_chk.isChecked():
                config = {
                    'api_url': self.system_name_edit.text(),
                    'org_code': self.offnbr_edit.text(),
                    'offnbr': self.offnbr_edit.text(),
                    'year': self.year_edit.text(),      # *** 新增：保存年度 ***
                    'month': self.month_edit.text(),    # *** 新增：保存月份 ***
                    'remember_login': True
                }

                with open(self.config_file, 'w', encoding='utf-8') as f:
                    json.dump(config, f, indent=2)

                print("[成功] 登入資訊已保存（不含API Token）")
            else:
                if self.config_file.exists():
                    self.config_file.unlink()
                    print("🗑️ 登入資訊已清除")

        except Exception as e:
            print(f"[錯誤] 保存登入設定時發生錯誤：{e}")   

    def load_login_config(self):
        """載入保存的登入設定 - API Token版：載入API位址、機構代號、年度、月份（不載入Token）"""
        try:
            if self.config_file.exists():
                with open(self.config_file, 'r', encoding='utf-8') as f:
                    config = json.load(f)

                if config.get('remember_login', False):
                    self.system_name_edit.setText(config.get('api_url', DEFAULT_API_URL))
                    # API Token 不從設定檔載入，需每次手動輸入
                    # 機構代號：優先從 org_code 載入，其次從 offnbr 載入
                    org_code_val = config.get('org_code', '') or config.get('offnbr', '')
                    self.offnbr_edit.setText(org_code_val)
                    self.year_edit.setText(config.get('year', ''))      # *** 新增：載入年度 ***
                    self.month_edit.setText(config.get('month', ''))     # *** 新增：載入月份 ***
                    self.remember_login_chk.setChecked(True)
                    self.safe_print("✅ 已載入保存的登入資訊")
            else:
                self.offnbr_edit.setText("")
                self.year_edit.setText("")     # *** 新增：預設年度 ***
                self.month_edit.setText("")     # *** 新增：預設月份 ***
                self.safe_print("💡 已自動填入預設密碼")

        except Exception as e:
            self.safe_print(f"❌ 載入登入設定時發生錯誤：{e}")
            if self.config_file.exists():
                try:
                    self.config_file.unlink()
                    print("🗑️ 已刪除損壞的配置檔案")
                except:
                    pass
            self.offnbr_edit.setText("")
            self.year_edit.setText("")     # *** 新增：預設年度 ***
            self.month_edit.setText("")     # *** 新增：預設月份 ***

    def clear_login_config(self):
        """清除保存的登入設定 - 修正版：清除後重新填入預設密碼、年度、月份"""
        try:
            if self.config_file.exists():
                self.config_file.unlink()
                
            self.username_edit.clear()
            self.offnbr_edit.clear()
            self.year_edit.setText("")     # *** 新增：重置年度 ***
            self.month_edit.setText("")     # *** 新增：重置月份 ***
            self.remember_login_chk.setChecked(False)
            
            print("🗑️ 登入設定已清除，密碼重設為預設值")
            QMessageBox.information(self, "清除完成", "保存的登入資訊已清除\n密碼已重設為預設值")
            
        except Exception as e:
            print(f"❌ 清除登入設定時發生錯誤：{e}")
            QMessageBox.critical(self, "錯誤", f"清除登入設定時發生錯誤：{str(e)}")

    def login(self):
        """修改後的登入方法 - API Token 版本"""
        try:
            org_code = self.offnbr_edit.text().strip()
            
            
            # 檢查必填欄位
            api_url = self.system_name_edit.text().strip()
            api_token = self.username_edit.text().strip()
            
            if not api_url:
                raise Exception("請輸入 API 位址")
            if not api_token:
                raise Exception("請輸入服務權杖（API Token）")
            if not org_code:
                raise Exception("請輸入機構代號")
            self.db_manager = DatabaseManager(
                api_url=api_url,
                api_token=api_token,
                org_code=org_code
            )
            
            if not self.db_manager.test_connection():
                _env = _tais_net_probe()
                if _env == "internet":
                    raise Exception(
                        "TAIS API 連線失敗\n\n"
                        "🌐 目前偵測為【外部網路】環境\n"
                        "TAIS API 僅限公司內網使用，無法從外部直接連線。\n\n"
                        "💡 建議：\n"
                        "  • 連接公司 VPN 後再試\n"
                        "  • 如需行動端查詢，請改用「⬆ 推送PWA」\n"
                        "    同步資料至 CAT PWA App"
                    )
                else:
                    raise Exception(
                        "TAIS API 連線失敗\n\n"
                        "🏢 目前偵測為【公司內網】環境\n"
                        "請確認以下項目：\n"
                        "  1. API 位址是否正確\n"
                        "  2. 服務權杖（Token）是否有效\n"
                        "  3. 機構代號是否正確\n"
                        "  4. TAIS 伺服器是否正常運作"
                    )
            
            self.db_connection = self.db_manager.connection
            self.save_login_config()
            
            conn_info = self.db_manager.get_connection_info()
            connection_type = conn_info.get('type', 'api_token')
            
            remember_status = "（已保存API位址和機構代號，Token未保存）" if self.remember_login_chk.isChecked() else ""
            org_code = self.offnbr_edit.text()
            
            QMessageBox.information(
                self, 
                "連線成功", 
                f"已成功連接到資料庫! {remember_status}\n\n"
                f"連線方式: {connection_type.upper()}\n"
                f"API 位址: {conn_info.get('api_url', 'N/A')}\n"
                f"機構代號: {conn_info.get('org_code', 'N/A')}\n"
            )
            
            self.login_success = True
            
            # 先切換頁面，再延遲同步
            self.tab_widget.setCurrentIndex(1)
            
            # 使用 QTimer 延遲執行同步，確保 UI 完全載入
            from PyQt6.QtCore import QTimer
            QTimer.singleShot(100, self.sync_login_params_to_all)  # *** 修改：改用新的同步函數 ***
            QTimer.singleShot(150, self.sync_budget_params)  # 同步到 Budget 系列面板

        except Exception as e:
            error_msg = f"連接失敗: {str(e)}"
            print(error_msg)
            QMessageBox.critical(self, "錯誤", error_msg)

    def sync_login_params_to_all(self):
        """將登入的參數（機構代號、年度、月份）同步到所有查詢頁面"""
        try:
            # 取得登入參數
            offnbr = self.offnbr_edit.text().strip()
            year = self.year_edit.text().strip()
            month = self.month_edit.text().strip()
            
            print(f"\n🔄 開始同步登入參數:")
            print(f"   機構代號: {offnbr}")
            print(f"   年度: {year}")
            print(f"   月份: {month}")
            
            synced_count = 0
            
            # *** 同步機構代號相關欄位 ***
            offnbr_fields = [
                ('param_offnbr', '機構代號'),
                ('param_office', '製票機構'),
                ('param_trnofn', '交易機構'),
                ('param_bkgofn', '列帳機構')
            ]
            
            if offnbr:
                for var_name, display_name in offnbr_fields:
                    if hasattr(self, var_name):
                        getattr(self, var_name).setText(offnbr)
                        synced_count += 1
                        print(f"  ✓ {display_name}: {offnbr}")
            
            # *** 同步年度欄位 ***
            if year:
                if hasattr(self, 'param_year'):
                    self.param_year.setText(year)
                    synced_count += 1
                    print(f"  ✓ 年度: {year}")
            
            # *** 同步月份欄位 ***
            if month:
                if hasattr(self, 'param_month'):
                    # 如果 param_month 是 QComboBox
                    if hasattr(self.param_month, 'setCurrentText'):
                        self.param_month.setCurrentText(month)
                    # 如果 param_month 是 QLineEdit
                    else:
                        self.param_month.setText(month)
                    synced_count += 1
                    print(f"  ✓ 月份: {month}")
            
            # *** 如果有 parameter_inputs 字典，也一併同步 ***
            if hasattr(self, 'parameter_inputs'):
                dict_sync_data = [
                    ('機構代號', offnbr),
                    ('製票機構', offnbr),
                    ('交易機構', offnbr),
                    ('列帳機構', offnbr),
                    ('年度', year),
                    ('月份', month)
                ]
                
                for field_label, value in dict_sync_data:
                    if value and field_label in self.parameter_inputs:
                        widget = self.parameter_inputs[field_label]
                        # 檢查是 QComboBox 還是 QLineEdit
                        if hasattr(widget, 'setCurrentText'):
                            widget.setCurrentText(value)
                        else:
                            widget.setText(value)
                        print(f"  ✓ {field_label}: {value} (透過字典)")
            
            # 輸出同步結果
            if synced_count > 0:
                success_msg = f"✅ 登入參數已同步到 {synced_count} 個欄位"
                print(success_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(success_msg)
            else:
                warning_msg = "⚠️ 未能同步任何參數欄位"
                print(warning_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(warning_msg)
                    
        except Exception as e:
            error_msg = f"❌ 同步登入參數時發生錯誤：{e}"
            print(error_msg)
            import traceback
            traceback.print_exc()
            if hasattr(self, 'safe_print'):
                self.safe_print(error_msg)

    def sync_budget_params(self):
        """將登入資料庫頁的參數同步到 Budget 系列面板"""
        try:
            offnbr = self.offnbr_edit.text().strip()
            year   = self.year_edit.text().strip()
            month  = self.month_edit.text().strip()
            if offnbr:
                self.global_institution_code = offnbr
            if year:
                self.global_year = year
            if month:
                self.global_month = month
            print(f"[Budget同步] 機構:{offnbr} 年:{year} 月:{month}")
            # 同步到 BudgetQueryPanel 的 UI 欄位
            if hasattr(self, 'budget_query_panel'):
                self.budget_query_panel.sync_parameters_from_main()
        except Exception as e:
            print(f"[Budget同步] 失敗: {e}")

    def sync_offnbr_to_params(self):
        """舊函數保留供其他地方使用，但內部改呼叫新函數"""
        self.sync_login_params_to_all()            

    def sync_offnbr_to_params(self):
        """將登入的機構代號同步到參數設定區的所有相關欄位"""
        try:
            offnbr = self.offnbr_edit.text().strip()
            if not offnbr:
                print("⚠️ 機構代號為空，無法同步")
                return
            
            print(f"\n🔄 開始同步機構代號: {offnbr}")
            
            # *** 修正：優先使用 parameter_inputs 字典 ***
            sync_fields = [
                ('機構代號', 'param_offnbr'),
                ('製票機構', 'param_office'),
                ('交易機構', 'param_trnofn'),
                ('列帳機構', 'param_bkgofn')
            ]
            
            synced_count = 0
            failed_fields = []
            
            for field_label, var_name in sync_fields:
                try:
                    # 方法1：從 parameter_inputs 字典取得
                    if hasattr(self, 'parameter_inputs') and field_label in self.parameter_inputs:
                        widget = self.parameter_inputs[field_label]
                        widget.setText(offnbr)
                        synced_count += 1
                        print(f"  ✓ {field_label}: {offnbr} (透過字典)")
                    
                    # 方法2：從物件屬性取得
                    elif hasattr(self, var_name):
                        widget = getattr(self, var_name)
                        widget.setText(offnbr)
                        synced_count += 1
                        print(f"  ✓ {field_label}: {offnbr} (透過屬性)")
                    
                    else:
                        failed_fields.append(field_label)
                        print(f"  ✗ {field_label}: 找不到對應的欄位")
                        
                except Exception as field_error:
                    failed_fields.append(field_label)
                    print(f"  ✗ {field_label}: 設定失敗 - {field_error}")
            
            # 輸出同步結果
            if synced_count > 0:
                success_msg = f"✅ 機構代號 {offnbr} 已同步到 {synced_count} 個參數欄位"
                print(success_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(success_msg)
            
            if failed_fields:
                warning_msg = f"⚠️ 以下欄位同步失敗: {', '.join(failed_fields)}"
                print(warning_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(warning_msg)
            
            if synced_count == 0:
                error_msg = "❌ 未能同步任何參數欄位，請檢查 parameter_inputs 字典是否正確建立"
                print(error_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(error_msg)
                    
        except Exception as e:
            error_msg = f"❌ 同步機構代號時發生錯誤：{e}"
            print(error_msg)
            import traceback
            traceback.print_exc()
            if hasattr(self, 'safe_print'):
                self.safe_print(error_msg)

