    def get_selected_values(self):
        """取得選擇的值欄位 - 修正版：按照值1、值2、值3的順序排列"""
        try:
            selected_values = []
            
            # *** 修正：嚴格按照值1、值2、值3的順序添加 ***
            
            # 檢查值1 (Values)
            if hasattr(self, 'values_combo'):
                value1 = self.values_combo.currentText().strip()
                if value1 and value1 != "":
                    selected_values.append(value1)
                    print(f"   值1: {value1}")
            
            # 檢查值2 (可選)
            if hasattr(self, 'values_combo_2'):
                value2 = self.values_combo_2.currentText().strip()
                if value2 and value2 != "":
                    selected_values.append(value2)
                    print(f"   值2: {value2}")
            
            # 檢查值3 (可選)
            if hasattr(self, 'values_combo_3'):
                value3 = self.values_combo_3.currentText().strip()
                if value3 and value3 != "":
                    selected_values.append(value3)
                    print(f"   值3: {value3}")
            
            print(f"📊 已選擇的值欄位順序: {selected_values}")
            return selected_values
            
        except Exception as e:
            print(f"❌ 取得選擇值時發生錯誤: {e}")
            return []

    def get_selected_values_with_original_names(self):
        """取得選擇的值欄位 - 返回原始欄位名稱"""
        display_values = self.get_selected_values()  # 取得顯示名稱
        
        # 轉換為原始名稱
        original_values = []
        for display_val in display_values:
            original_val = self._get_original_column_name(display_val)
            if original_val:
                original_values.append(original_val)
        
        return original_values

    def update_pivot_fields(self, df):
        """更新樞紐分析欄位"""
        try:
            if df is None or df.empty:
                return
                
            print("正在更新樞紐分析欄位...")
            
            # 檢查控制項是否存在
            controls_to_check = ['index_combo', 'columns_combo', 'values_combo', 
                            'values_combo_2', 'values_combo_3']
            
            for control_name in controls_to_check:
                if not hasattr(self, control_name):
                    print(f"控制項 {control_name} 不存在，跳過更新")
                    return
            
            # 記錄當前選擇
            current_selections = {}
            try:
                current_selections['index'] = self.index_combo.currentText()
                current_selections['columns'] = self.columns_combo.currentText()
                current_selections['values'] = self.values_combo.currentText()
                current_selections['values_2'] = self.values_combo_2.currentText()
                current_selections['values_3'] = self.values_combo_3.currentText()
            except:
                current_selections = {}
            
            # 清除現有項目
            self.index_combo.clear()
            self.columns_combo.clear()
            self.values_combo.clear()
            self.values_combo_2.clear()
            self.values_combo_3.clear()
            
            # 準備欄位清單
            original_columns = list(df.columns)
            display_columns = [self.get_display_column_name(col) for col in original_columns]
            
            # 數值欄位
            numeric_original_cols = df.select_dtypes(include='number').columns.tolist()
            numeric_display_cols = [self.get_display_column_name(col) for col in numeric_original_cols]
            
            # 更新下拉選單
            self.index_combo.addItems(display_columns)
            
            # 欄位下拉選單（可選）
            self.columns_combo.addItem("")  # 空選項表示不分組
            self.columns_combo.addItems(display_columns)
            
            # 值欄位下拉選單 - 只顯示數值欄位
            if numeric_display_cols:
                self.values_combo.addItem("")  # 空選項
                self.values_combo.addItems(numeric_display_cols)
                
                self.values_combo_2.addItem("")  # 空選項
                self.values_combo_2.addItems(numeric_display_cols)
                
                self.values_combo_3.addItem("")  # 空選項
                self.values_combo_3.addItems(numeric_display_cols)
            else:
                self.values_combo.addItem("(無數值欄位)")
                self.values_combo_2.addItem("(無數值欄位)")
                self.values_combo_3.addItem("(無數值欄位)")
            
            # 恢復之前的選擇
            try:
                if current_selections.get('index'):
                    index = self.index_combo.findText(current_selections['index'])
                    if index >= 0:
                        self.index_combo.setCurrentIndex(index)
                
                if current_selections.get('columns'):
                    index = self.columns_combo.findText(current_selections['columns'])
                    if index >= 0:
                        self.columns_combo.setCurrentIndex(index)
                
                if current_selections.get('values'):
                    index = self.values_combo.findText(current_selections['values'])
                    if index >= 0:
                        self.values_combo.setCurrentIndex(index)
                        
                if current_selections.get('values_2'):
                    index = self.values_combo_2.findText(current_selections['values_2'])
                    if index >= 0:
                        self.values_combo_2.setCurrentIndex(index)
                        
                if current_selections.get('values_3'):
                    index = self.values_combo_3.findText(current_selections['values_3'])
                    if index >= 0:
                        self.values_combo_3.setCurrentIndex(index)
            except Exception as e:
                print(f"恢復選擇時發生錯誤：{e}")
            
            print(f"樞紐分析欄位更新完成 - 共 {len(display_columns)} 個欄位，{len(numeric_display_cols)} 個數值欄位")
            
        except Exception as e:
            print(f"更新樞紐分析欄位時發生錯誤：{e}")

    def get_chart_colors(self, count):
        """取得圖表顏色列表"""
        try:
            # 如果使用者有自定義顏色，優先使用
            if hasattr(self, 'chart_colors') and self.chart_colors:
                colors = self.chart_colors.copy()
                
                # 如果自定義顏色不夠用，補充 seaborn 調色盤顏色
                if len(colors) < count:
                    palette_name = self.palette_combo.currentText() if hasattr(self, 'palette_combo') else 'deep'
                    additional_colors = sns.color_palette(palette_name, count - len(colors))
                    # 轉換為十六進制格式
                    additional_hex = [f'#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}' 
                                    for r, g, b in additional_colors]
                    colors.extend(additional_hex)
                
                return colors[:count]
            
            # 如果沒有自定義顏色，使用 seaborn 調色盤
            else:
                palette_name = self.palette_combo.currentText() if hasattr(self, 'palette_combo') else 'deep'
                palette_colors = sns.color_palette(palette_name, count)
                # 轉換為十六進制格式
                hex_colors = [f'#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}' 
                            for r, g, b in palette_colors]
                return hex_colors
                
        except Exception as e:
            print(f"取得圖表顏色時發生錯誤：{e}")
            # 如果發生錯誤，使用預設顏色
            default_colors = ['#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd', 
                            '#8c564b', '#e377c2', '#7f7f7f', '#bcbd22', '#17becf']
            return (default_colors * ((count // len(default_colors)) + 1))[:count]

    def update_selected_colors_display(self):
        """更新已選擇顏色的顯示 - 修正版"""
        try:
            if not hasattr(self, 'selected_colors_label'):
                return
                
            if not hasattr(self, 'chart_colors'):
                self.chart_colors = []
            
            if not self.chart_colors:
                self.selected_colors_label.setText("未選擇顏色 (將使用默認顏色)")
            else:
                colors_text = ", ".join(self.chart_colors)
                if len(colors_text) > 50:  # 如果太長就截斷
                    colors_text = colors_text[:47] + "..."
                self.selected_colors_label.setText(f"已選顏色: {colors_text}")
        except Exception as e:
            print(f"更新顏色顯示時發生錯誤：{e}")

    def add_color(self, color):
        """添加顏色到已選顏色清單 - 修正版"""
        try:
            if not hasattr(self, 'chart_colors'):
                self.chart_colors = []
            
            if color not in self.chart_colors:
                self.chart_colors.append(color)
                self.update_selected_colors_display()
        except Exception as e:
            print(f"添加顏色時發生錯誤：{e}")

    def clear_colors(self):
        """清除所有已選顏色 - 修正版"""
        try:
            if hasattr(self, 'chart_colors'):
                self.chart_colors = []
            else:
                self.chart_colors = []
            self.update_selected_colors_display()
        except Exception as e:
            print(f"清除顏色時發生錯誤：{e}")

    def choose_custom_color(self):
        """選擇自定義顏色 - 修正版"""
        try:
            color = QColorDialog.getColor()
            if color.isValid():
                self.add_color(color.name())
        except Exception as e:
            print(f"選擇自定義顏色時發生錯誤：{e}")
            QMessageBox.warning(self, "錯誤", f"選擇顏色時發生錯誤：{str(e)}")

    # 額外修正：確保圖表顯示相關變數也正確初始化
    def ensure_chart_initialization(self):
        """確保圖表相關變數正確初始化"""
        if not hasattr(self, 'current_figure'):
            self.current_figure = None
        if not hasattr(self, 'chart_colors'):
            self.chart_colors = []
        if not hasattr(self, 'show_labels_chk'):
            # 如果控制項還沒初始化，創建一個臨時的假對象
            class TempCheckBox:
                def isChecked(self):
                    return True
            self.show_labels_chk = TempCheckBox()

    def handle_exception(self, exc_type, exc_value, exc_traceback):
        """全域異常處理，防止程式閃退"""
        try:
            error_msg = ''.join(traceback.format_exception(exc_type, exc_value, exc_traceback))
            print(f"發生未處理的異常:\n{error_msg}")
            
            # 顯示用戶友好的錯誤訊息
            QMessageBox.critical(
                None, 
                "程式錯誤", 
                f"程式發生未預期的錯誤，但已被攔截避免閃退。\n\n"
                f"錯誤類型：{exc_type.__name__}\n"
                f"錯誤訊息：{str(exc_value)}\n\n"
                f"建議操作：\n"
                f"1. 檢查SQL語句是否正確\n"
                f"2. 確認資料庫連接正常\n"
                f"3. 如果查詢大量資料，請添加LIMIT限制\n"
                f"4. 重新啟動程式"
            )
        except:
            # 如果連錯誤處理都失敗，至少印出到控制台
            print(f"嚴重錯誤: {exc_type.__name__}: {exc_value}")

    def determine_query_source(self):
        """智能判斷查詢來源和處理方式"""
        try:
            # 初始化查詢來源資訊
            query_source = {
                'source': 'manual',  # 預設為手動輸入
                'type': None,
                'needs_special_check': True  # 預設需要特殊檢查
            }
            
            # 1. 檢查是否為SQL範本庫查詢
            if hasattr(self, 'is_template_query') and getattr(self, 'is_template_query', False):
                query_source.update({
                    'source': 'sql_template',
                    'type': 'template',
                    'needs_special_check': False  # SQL範本庫查詢跳過特殊檢查
                })
                print("🎯 偵測到SQL範本庫查詢")
                return query_source
            
            # 2. 檢查是否為預設查詢選單查詢
            if hasattr(self, 'current_query_type') and getattr(self, 'current_query_type', None):
                preset_query_type = self.current_query_type
                
                # 根據預設查詢類型決定是否需要特殊檢查
                special_check_types = ['check3', 'check4']  # 需要特殊檢查的查詢類型
                
                query_source.update({
                    'source': 'preset_menu',
                    'type': preset_query_type,
                    'needs_special_check': preset_query_type in special_check_types
                })
                
                if preset_query_type in special_check_types:
                    print(f"🔍 偵測到預設查詢 {preset_query_type}，需要特殊檢查")
                else:
                    print(f"📋 偵測到預設查詢 {preset_query_type}，跳過特殊檢查")
                
                return query_source
            
            # 3. 預設為手動輸入查詢
            print("✏️ 偵測到手動輸入查詢，執行完整檢查")
            return query_source
            
        except Exception as e:
            print(f"判斷查詢來源時發生錯誤: {e}")
            # 錯誤時使用安全的預設值
            return {
                'source': 'manual',
                'type': None,
                'needs_special_check': True
            }

    def on_query_finished(self, result_data):
        """查詢完成的回調方法 - 修正版（優先使用直接顯示）"""
        try:
            print("🔍 查詢執行完成，開始處理結果...")
            
            # 停止超時定時器
            if hasattr(self, 'query_timer') and self.query_timer:
                self.query_timer.stop()
            
            # 重新啟用執行按鈕
            if hasattr(self, 'exec_btn'):
                self.exec_btn.setEnabled(True)
                self.exec_btn.setText("🔍 執行查詢")
            
            # 隱藏進度條
            self._hide_progress_bar()
            
            # === 重要：立即進行欄位名稱對照 ===
            if result_data is not None and isinstance(result_data, pd.DataFrame) and not result_data.empty:
                print("📝 原始欄位名稱:", list(result_data.columns)[:10])
                
                # 確保 field_mapper 存在
                if not hasattr(self, 'field_mapper'):
                    self.field_mapper = FieldNameMapper()
                    print("🔧 臨時建立欄位名稱對照器")
                
                # 執行欄位名稱對照
                print("🔄 開始進行欄位名稱對照...")
                result_data = self.field_mapper.map_dataframe_columns(result_data)
                print("✅ 欄位名稱對照完成")
                print("📝 對照後欄位名稱:", list(result_data.columns)[:10])
            
            # 更新當前資料（使用對照後的資料）
            self.current_data = result_data
            if isinstance(result_data, pd.DataFrame):
                self.original_data = result_data.copy()
            else:
                self.original_data = result_data
            
            # 根據查詢來源決定處理方式 - 修改預設值
            query_source = getattr(self, 'current_query_source', {
                'source': 'manual',
                'type': None,
                'needs_special_check': False  # 👈 改為 False，優先使用直接顯示
            })
            
            # 修改判斷邏輯：只有明確需要特殊檢查時才使用特殊處理
            if query_source.get('needs_special_check', False):
                print("🔧 執行特殊查詢結果檢查...")
                # 執行特殊查詢結果檢查
                sql = self.sql_text.toPlainText().strip()
                query_type = query_source.get('type') or self.determine_query_type(sql)
                self._handle_special_query_result(query_type, result_data)
            else:
                print("📋 使用直接顯示查詢結果...")
                # 預設使用直接顯示結果（跳過特殊檢查）
                self.display_query_results_directly(result_data, query_source)
            
            # 重置查詢來源標記
            self.reset_query_source_flags()
            
            print("✅ 查詢結果處理完成")
            
        except Exception as e:
            self.reset_query_source_flags()
            error_msg = f"處理查詢結果時發生錯誤：{str(e)}"
            print(f"❌ 處理結果錯誤: {error_msg}")
            QMessageBox.critical(self, "錯誤", error_msg)


    def on_query_error(self, error_message):
        """查詢錯誤的回調方法 - 修改版本"""
        try:
            print(f"查詢執行發生錯誤: {error_message}")
            
            # 停止超時定時器
            if hasattr(self, 'query_timer') and self.query_timer:
                self.query_timer.stop()
            
            # 重新啟用執行按鈕
            if hasattr(self, 'exec_btn'):
                self.exec_btn.setEnabled(True)
                self.exec_btn.setText("🔍 執行查詢")
            
            # 隱藏進度條
            self._hide_progress_bar()
            
            # === 新增：錯誤時重置查詢來源標記 ===
            self.reset_query_source_flags()
            
            # 顯示錯誤訊息
            QMessageBox.critical(self, "查詢錯誤", f"執行查詢時發生錯誤：\n{error_message}")
            
        except Exception as e:
            print(f"處理查詢錯誤時發生異常: {e}")


    def display_query_results_directly(self, result_data, query_source=None):
        """直接顯示查詢結果，不進行特殊檢查 - 修正版本（加入欄位名稱對照）"""
        try:
            source_name = self.get_source_display_name(query_source) if query_source else "查詢"
            print(f"📋 直接顯示查詢結果（{source_name}模式）")
            
            # === 新增：確保欄位名稱對照處理 ===
            if result_data is not None and isinstance(result_data, pd.DataFrame) and not result_data.empty:
                print("🔄 確保查詢結果已進行欄位名稱對照...")
                # 建立欄位名稱對照器
                if not hasattr(self, 'field_mapper'):
                    self.field_mapper = FieldNameMapper()
                # 對查詢結果進行欄位名稱對照（如果還沒處理過）
                result_data = self.field_mapper.map_dataframe_columns(result_data)
                print("✅ 查詢結果欄位名稱對照確認完成")
            
            # 更新當前資料
            self.current_data = result_data
            if isinstance(result_data, pd.DataFrame):
                self.original_data = result_data.copy()
            else:
                self.original_data = result_data
            
            # 更新所有控制項（顯示資料到表格）
            if hasattr(self, '_safe_update_all_controls'):
                self._safe_update_all_controls(result_data)
            
            # 切換到結果標籤頁
            if hasattr(self, 'tab_widget'):
                self.tab_widget.setCurrentIndex(2)  # 假設結果頁面是第3個標籤
            
            # 顯示查詢完成訊息
            if isinstance(result_data, pd.DataFrame):
                row_count = len(result_data)
                col_count = len(result_data.columns) if not result_data.empty else 0
                
                if row_count > 0:
                    QMessageBox.information(self, "查詢完成", 
                        f"✅ {source_name}完成！\n\n"
                        f"📊 查詢到 {row_count} 筆資料\n"
                        f"🗃️ 共 {col_count} 個欄位\n\n"
                        f"💡 已套用中文欄位名稱對照")
                else:
                    QMessageBox.information(self, "查詢完成", 
                        f"✅ {source_name}完成！\n\n"
                        f"📋 查無符合條件的資料")
            else:
                QMessageBox.information(self, "查詢完成", 
                    f"✅ {source_name}執行完成！")
            
        except Exception as e:
            print(f"❌ 直接顯示查詢結果時發生錯誤: {e}")
            QMessageBox.critical(self, "錯誤", f"顯示查詢結果時發生錯誤：{str(e)}")


    def get_source_display_name(self, query_source):
        """獲取查詢來源的顯示名稱"""
        if not query_source:
            return "查詢"
        
        source_names = {
            'sql_template': 'SQL範本庫查詢',
            'preset_menu': '預設查詢選單',
            'manual': '手動查詢'
        }
        
        source_name = source_names.get(query_source.get('source', 'manual'), '查詢')
        
        # 如果有具體的查詢類型，加上類型資訊
        if query_source.get('type'):
            query_type = query_source['type']
            if query_source['source'] == 'preset_menu':
                # 對於預設查詢，獲取中文名稱
                type_name = self.get_query_name(query_type) if hasattr(self, 'get_query_name') else query_type
                source_name = f"{source_name}（{type_name}）"
        
        return source_name


    def reset_query_source_flags(self):
        """重置所有查詢來源標記"""
        try:
            # 重置SQL範本庫標記
            if hasattr(self, 'is_template_query'):
                self.is_template_query = False
            
            # 重置預設查詢標記
            if hasattr(self, 'current_query_type'):
                self.current_query_type = None
            
            # 重置當前查詢來源
            if hasattr(self, 'current_query_source'):
                self.current_query_source = None
            
            print("🔄 所有查詢來源標記已重置")
        except Exception as e:
            print(f"❌ 重置查詢來源標記時發生錯誤: {e}")


    def set_direct_query_mode(self):
        """設定為直接查詢模式（確保使用 display_query_results_directly）"""
        try:
            self.current_query_source = {
                'source': 'manual',
                'type': None,
                'needs_special_check': False  # 確保不進行特殊檢查
            }
            print("🎯 已設定為直接查詢模式")
        except Exception as e:
            print(f"❌ 設定直接查詢模式時發生錯誤: {e}")


    def set_special_query_mode(self, query_type=None):
        """設定為特殊查詢模式（使用 _handle_special_query_result）"""
        try:
            self.current_query_source = {
                'source': 'manual',
                'type': query_type,
                'needs_special_check': True  # 確保進行特殊檢查
            }
            print(f"🔧 已設定為特殊查詢模式 (類型: {query_type})")
        except Exception as e:
            print(f"❌ 設定特殊查詢模式時發生錯誤: {e}")

    def insert_sql_template(self, template):
        """插入SQL範本到查詢框 - 修改版本"""
        try:
            # === 新增：設定SQL範本庫查詢標記為True ===
            self.is_template_query = True
            
            # 清除預設查詢標記（避免衝突）
            if hasattr(self, 'current_query_type'):
                self.current_query_type = None
            
            # 將範本SQL插入到查詢框
            if hasattr(self, 'sql_text') and self.sql_text:
                self.sql_text.setPlainText(template)
                print("📝 已插入SQL範本")
                print("🎯 SQL範本庫查詢標記已設定，執行時將跳過特殊檢查")
            else:
                print("❌ SQL編輯器未初始化，無法插入範本")
                QMessageBox.warning(self, "警告", "SQL編輯器未初始化!")
                
        except Exception as e:
            print(f"插入SQL範本時發生錯誤: {e}")
            QMessageBox.critical(self, "錯誤", f"插入SQL範本時發生錯誤：{str(e)}")


    def execute_preset_query(self, query_type):
        """執行預設查詢 - 修改版本（與execute_query兼容）"""
        try:
            print(f"開始執行預設查詢: {query_type}")
            
            # 1. 檢查查詢按鈕是否已初始化
            if not hasattr(self, 'query_buttons') or not self.query_buttons:
                QMessageBox.critical(self, "錯誤", "查詢選單尚未初始化，請重新啟動程式")
                return
            
            # 2. 檢查是否選中了對應的查詢類型
            if query_type not in self.query_buttons:
                QMessageBox.critical(self, "錯誤", f"找不到查詢類型: {query_type}")
                return
            
            # 3. 獲取對應的SQL查詢語句
            sql_query = self.get_preset_sql(query_type)
            
            if not sql_query or sql_query.strip() == "":
                QMessageBox.critical(self, "錯誤", "無法取得SQL查詢內容")
                return
            
            # 4. === 重要修改：設定預設查詢標記 ===
            # 清除SQL範本庫標記（避免衝突）
            if hasattr(self, 'is_template_query'):
                self.is_template_query = False
            
            # 設定預設查詢類型標記
            self.current_query_type = query_type
            print(f"🎯 已設定預設查詢類型: {query_type}")
            
            # 5. 將SQL語句載入到編輯器
            self.sql_text.setPlainText(sql_query)
            
            # 6. 切換到SQL查詢頁面 (假設索引為1)
            self.tab_widget.setCurrentIndex(1)
            
            # 7. 執行查詢
            print("開始執行SQL查詢...")
            
            # 直接調用execute_query方法（它會自動處理預設查詢的特殊邏輯）
            if hasattr(self, 'execute_query'):
                self.execute_query()
            else:
                QMessageBox.warning(self, "提示", 
                    f"✅ SQL查詢已載入到編輯器\n\n查詢名稱：{self.get_query_name(query_type)}\n\n請手動點擊「執行查詢」按鈕來執行查詢")
                return
            
            print("預設查詢執行完成")
            
        except Exception as e:
            print(f"execute_preset_query 發生錯誤: {e}")
            import traceback
            traceback.print_exc()
            QMessageBox.critical(self, "執行錯誤", 
                f"執行查詢時發生錯誤:\n{str(e)}\n\n請檢查：\n1. 資料庫連線是否正常\n2. SQL語法是否正確\n3. 參數設定是否完整")


    def cleanup_query_thread(self):
        """清理查詢執行緒資源 - 修改版本"""
        try:
            # 停止定時器
            if hasattr(self, 'query_timer') and self.query_timer:
                self.query_timer.stop()
                self.query_timer = None
            
            # 清理執行緒
            if hasattr(self, 'query_thread') and self.query_thread:
                if self.query_thread.isRunning():
                    self.query_thread.cancel()
                    self.query_thread.wait(5000)  # 等待最多5秒
                self.query_thread = None
            
            # 重新啟用執行按鈕
            if hasattr(self, 'exec_btn'):
                self.exec_btn.setEnabled(True)
                self.exec_btn.setText("🔍 執行查詢")
            
            # 隱藏進度條
            self._hide_progress_bar()
            
            # === 注意：這裡不重置查詢來源標記 ===
            # 因為在正常完成的情況下，標記應該在結果處理完後才重置
            
            print("🧹 查詢執行緒資源清理完成")
            
        except Exception as e:
            print(f"清理查詢執行緒時發生錯誤: {e}")


