    def _safe_update_result_display(self, df):
        """安全地更新結果顯示"""
        try:
            # 分階段更新，避免一次處理太多資料
            print("開始更新結果表格...")
            self.update_result_table_safe(df)
            
            print("開始更新樞紐分析欄位...")
            self.update_pivot_fields_safe(df)
            
            print("結果顯示更新完成")
            
        except Exception as e:
            print(f"更新結果顯示錯誤: {e}")
            # 即使更新失敗，也要確保基本功能可用
            try:
                # 最簡單的表格更新
                self.simple_update_result_table(df)
            except:
                pass

    def update_result_table_safe(self, df):
        """安全的結果表格更新 - 完全修正版"""
        try:
            if not hasattr(self, 'result_table') or not self.result_table:
                print("❌ 結果表格未初始化")
                return
            
            print("🔄 開始更新結果表格...")
            
            # 確保資料已經過欄位名稱對照
            if df is not None and not df.empty:
                # 再次確認欄位名稱對照（防止遺漏）
                if not hasattr(self, 'field_mapper'):
                    self.field_mapper = FieldNameMapper()
                
                # 檢查是否需要重新對照
                first_column = str(df.columns[0]) if len(df.columns) > 0 else ""
                if first_column and not self._is_chinese_name(first_column):
                    print("⚠️ 發現英文欄位名稱，重新進行對照...")
                    df = self.field_mapper.map_dataframe_columns(df)
                    print("✅ 重新對照完成")
            
            # 限制顯示的資料量
            display_df = df.head(1000) if len(df) > 1000 else df
            
            # 清空並重設表格
            self.result_table.clear()
            self.result_table.setRowCount(len(display_df))
            self.result_table.setColumnCount(len(display_df.columns))
            
            # === 關鍵：直接使用 DataFrame 的欄位名稱（應該已經是中文） ===
            headers = [str(col) for col in display_df.columns]
            self.result_table.setHorizontalHeaderLabels(headers)
            # 每次新查詢都更新完整欄位清單（欄位選擇器套用不呼叫此方法，故不影響灰色顯示）
            self._budgetAllColumns = list(headers)
            
            print(f"📋 表格欄位標題: {headers[:5]}...")
            
            # 分批填入資料
            batch_size = 100
            for start_row in range(0, len(display_df), batch_size):
                end_row = min(start_row + batch_size, len(display_df))
                
                for row in range(start_row, end_row):
                    for col in range(len(display_df.columns)):
                        try:
                            value = display_df.iloc[row, col]
                            display_value = self._safe_format_value(value)
                            item = QTableWidgetItem(str(display_value))
                            self.result_table.setItem(row, col, item)
                        except Exception as e:
                            item = QTableWidgetItem("錯誤")
                            self.result_table.setItem(row, col, item)
                
                QApplication.processEvents()
            
            print("✅ 結果表格更新完成")
            
            # 如果有更多資料未顯示，添加提示
            if len(df) > 1000:
                print(f"📊 注意：共 {len(df)} 筆資料，僅顯示前1000筆")
            
        except Exception as e:
            print(f"❌ 更新結果表格錯誤: {e}")
            raise

    def _safe_format_value(self, value):
        """安全的數值格式化"""
        try:
            if pd.isna(value):
                return ""
            elif isinstance(value, (int, float)):
                if isinstance(value, float) and value.is_integer():
                    return str(int(value))
                elif abs(value) >= 1000:
                    return f"{value:,.0f}"
                else:
                    return f"{value:.2f}".rstrip('0').rstrip('.')
            else:
                # 限制字串長度
                str_val = str(value)
                return str_val[:200] + "..." if len(str_val) > 200 else str_val
        except:
            return str(value)[:50]  # 最後的安全措施

    def simple_update_result_table(self, df):
        """最簡單的表格更新方法，作為備用"""
        try:
            if hasattr(self, 'result_table'):
                # 最多顯示100筆資料
                simple_df = df.head(100)
                self.result_table.clear()
                self.result_table.setRowCount(len(simple_df))
                self.result_table.setColumnCount(len(simple_df.columns))
                self.result_table.setHorizontalHeaderLabels([str(col) for col in simple_df.columns])
                
                for row in range(len(simple_df)):
                    for col in range(len(simple_df.columns)):
                        value = str(simple_df.iloc[row, col])[:50]  # 限制長度
                        item = QTableWidgetItem(value)
                        self.result_table.setItem(row, col, item)
        except:
            pass

    def update_pivot_fields_safe(self, df):
        """安全的樞紐分析欄位更新 - 完全修正版（包含所有下拉選單）"""
        try:
            # 檢查必要的控制項是否存在
            required_combos = ['index_combo', 'columns_combo', 'values_combo', 'values_combo_2', 'values_combo_3']
            missing_combos = [combo for combo in required_combos if not hasattr(self, combo)]
            
            if missing_combos:
                print(f"⚠️ 缺少樞紐分析控制項: {missing_combos}")
                return
            
            print("🔄 更新樞紐分析欄位...")
            
            # 確保使用中文欄位名稱
            if df is not None and not df.empty:
                column_names = list(df.columns)
                non_chinese_count = sum(1 for col in column_names if not self._is_chinese_name(str(col)))
                
                if non_chinese_count > 0:
                    print(f"⚠️ 樞紐分析發現 {non_chinese_count} 個非中文欄位")
                    if not hasattr(self, 'field_mapper'):
                        self.field_mapper = FieldNameMapper()
                    df = self.field_mapper.map_dataframe_columns(df)
                    column_names = list(df.columns)
                    print(f"🔄 重新對照後欄位: {column_names[:3]}...")
                
                # 數值型欄位（用於值選擇）
                numeric_cols = df.select_dtypes(include=['number']).columns.tolist()
                print(f"📊 數值型欄位: {len(numeric_cols)} 個")
                
                # 更新所有下拉選單
                print("1️⃣ 更新 列(Index) 下拉選單...")
                self.index_combo.clear()
                self.index_combo.addItems([""] + column_names)  # 添加空選項
                
                print("2️⃣ 更新 欄(Columns) 下拉選單...")
                self.columns_combo.clear()
                self.columns_combo.addItems([""] + column_names)  # 添加空選項
                
                print("3️⃣ 更新 值(Values) 下拉選單...")
                self.values_combo.clear()
                self.values_combo.addItems([""] + numeric_cols)  # 主要值選擇
                
                print("4️⃣ 更新 值2(可選) 下拉選單...")
                self.values_combo_2.clear()
                self.values_combo_2.addItems([""] + numeric_cols)  # 第二個值選擇
                
                print("5️⃣ 更新 值3(可選) 下拉選單...")
                self.values_combo_3.clear()
                self.values_combo_3.addItems([""] + numeric_cols)  # 第三個值選擇
                
                print(f"✅ 樞紐分析欄位已更新：{len(column_names)} 個總欄位，{len(numeric_cols)} 個數值欄位")
                
                # 更新狀態顯示
                if hasattr(self, 'pivot_status_label'):
                    self.pivot_status_label.setText(f"📊 可用欄位：{len(column_names)} 個（數值型：{len(numeric_cols)} 個）")
                
        except Exception as e:
            print(f"❌ 更新樞紐分析欄位錯誤: {e}")
            import traceback
            traceback.print_exc()

    def on_query_finished(self, df):
        """查詢完成處理"""
        try:
            print(f"查詢完成，收到 {len(df) if df is not None else 0} 筆資料")
            
            # 停止超時定時器
            if hasattr(self, 'query_timer') and self.query_timer:
                self.query_timer.stop()
            
            # 檢查是否為特殊查詢類型
            if hasattr(self, 'current_query_type') and self.current_query_type in ['check3', 'check4']:
                # 處理特殊查詢結果
                self._handle_special_query_result(self.current_query_type, df)
                return
            
            # 一般查詢處理
            if df is not None and not df.empty:
                self.current_data = df
                self.original_data = df.copy()
                self._safe_update_all_controls(df)
                
                if hasattr(self, 'tab_widget'):
                    self.tab_widget.setCurrentIndex(2)
                
                QMessageBox.information(self, "查詢完成", f"成功查詢到 {len(df)} 筆資料！")
            else:
                QMessageBox.information(self, "查詢完成", "查無符合條件的資料")
                
        except Exception as e:
            error_msg = f"處理查詢結果時發生錯誤：{str(e)}"
            print(f"處理結果錯誤: {error_msg}")
            QMessageBox.critical(self, "錯誤", error_msg)
        finally:
            self.cleanup_query_thread()

    def on_query_error(self, error_msg):
        """查詢錯誤處理"""
        try:
            self.cleanup_query_thread()
            
            print(f"查詢錯誤: {error_msg}")
            
            # 根據錯誤類型提供不同的解決建議
            if "timeout" in error_msg.lower():
                error_msg += "\n\n建議：查詢超時，請嘗試縮小查詢範圍或優化SQL語句。"
            elif "connection" in error_msg.lower():
                error_msg += "\n\n建議：連線中斷，請檢查網路連線並重新登入。"
            elif "memory" in error_msg.lower():
                error_msg += "\n\n建議：記憶體不足，請添加LIMIT限制或縮小查詢範圍。"
            elif "syntax" in error_msg.lower():
                error_msg += "\n\n建議：SQL語法錯誤，請檢查SQL語句是否正確。"
            
            QMessageBox.critical(self, "查詢錯誤", error_msg)
            
        except Exception as e:
            print(f"處理查詢錯誤時發生錯誤: {e}")

    def _hide_progress_bar(self):
        """隱藏進度條"""
        try:
            # 隱藏進度條控制項
            if hasattr(self, 'progress_bar'):
                self.progress_bar.setVisible(False)
                self.progress_bar.setValue(0)  # 重置進度條數值
            
            # 隱藏進度標籤
            if hasattr(self, 'progress_label'):
                self.progress_label.setVisible(False)
                self.progress_label.setText("")  # 清空文字內容
                
            print("✅ 進度條已隱藏")
            
        except Exception as e:
            print(f"隱藏進度條時發生錯誤: {e}")

    # 另外，如果你想要更完整的進度條控制，
    # 也可以考慮添加重置進度條的方法：
    def _reset_progress_bar(self):
        """重置進度條到初始狀態"""
        try:
            if hasattr(self, 'progress_bar'):
                self.progress_bar.setValue(0)
                self.progress_bar.setVisible(False)
            
            if hasattr(self, 'progress_label'):
                self.progress_label.setText("準備開始...")
                self.progress_label.setVisible(False)
                
            print("🔄 進度條已重置")
            
        except Exception as e:
            print(f"重置進度條時發生錯誤: {e}")

    def update_dashboards(self):
        """更新儀表板顯示"""
        try:
            # 更新日期圓環
            if hasattr(self, 'date_circle_widget'):
                self.date_circle_widget.update_date()
            
            # 更新年份標籤
            if hasattr(self, 'year_label'):
                current_year = pd.Timestamp.now().year
                self.year_label.setText(str(current_year))
            
            # 更新數字時鐘（即時跳動）
            if hasattr(self, 'digital_clock_label'):
                current_time = pd.Timestamp.now().strftime('%H:%M:%S')
                self.digital_clock_label.setText(current_time)
            
            # 更新天氣資訊 - 使用真實API
            self.update_weather_info()
            
            # 更新空氣品質資訊
            self.update_air_quality_info()
                
        except Exception as e:
            print(f"更新儀表板時發生錯誤：{str(e)}")

    def update_weather_info(self):
        """更新天氣資訊"""
        try:
            # 檢查天氣服務是否已初始化
            if not hasattr(self, 'weather_service') or self.weather_service is None:
                print("天氣服務未初始化，正在重新初始化...")
                self.weather_service = WeatherService()
            
            # 獲取天氣資料
            weather_data = self.weather_service.get_current_weather("彰化市")
            
            if weather_data:
                # 更新溫度顯示
                if hasattr(self, 'temp_label'):
                    self.temp_label.setText(f"{weather_data['temperature']}°C")
                
                # 更新體感溫度
                if hasattr(self, 'feels_like_label'):
                    self.feels_like_label.setText(f"體感溫度: {weather_data['feels_like']}°C")
                
                # 更新天候狀況
                if hasattr(self, 'weather_desc_label'):
                    self.weather_desc_label.setText(f"天候狀況: {weather_data['description']}")
                
                # 更新濕度和氣壓
                if hasattr(self, 'humidity_pressure_label'):
                    self.humidity_pressure_label.setText(
                        f"濕度: {weather_data['humidity']}%  |  氣壓: {weather_data['pressure']} hPa"
                    )
                
                # 更新時間
                if hasattr(self, 'weather_update_label'):
                    update_time = weather_data['update_time'].strftime('%H:%M:%S')
                    self.weather_update_label.setText(f"更新時間: {update_time}")
                    
        except Exception as e:
            print(f"更新天氣資訊時發生錯誤：{str(e)}")
            # 顯示錯誤狀態
            if hasattr(self, 'temp_label'):
                self.temp_label.setText("--°C")
            if hasattr(self, 'weather_desc_label'):
                self.weather_desc_label.setText("天候狀況: 無法取得")

    def update_air_quality_info(self):
        """更新空氣品質資訊"""
        try:
            # 檢查天氣服務是否已初始化
            if not hasattr(self, 'weather_service') or self.weather_service is None:
                print("天氣服務未初始化，正在重新初始化...")
                self.weather_service = WeatherService()
            
            # 獲取空氣品質資料
            aqi_data = self.weather_service.get_air_quality("彰化")
            
            if aqi_data:
                # 更新AQI顯示
                if hasattr(self, 'aqi_label'):
                    aqi_value = aqi_data['aqi']
                    aqi_color = self.weather_service.get_aqi_color(aqi_value)
                    aqi_text_color = self.weather_service.get_aqi_text_color(aqi_color)
                    self.aqi_label.setText(f"AQI: {aqi_value}")
                    self.aqi_label.setStyleSheet(f"""
                        QLabel {{
                            font-size: 22px;
                            font-weight: bold;
                            color: {aqi_text_color};
                            background-color: {aqi_color};
                            border-radius: 7px;
                            padding: 7px;
                            margin: 5px;
                        }}
                    """)
                
                # 更新PM2.5和PM10
                if hasattr(self, 'pm_label'):
                    self.pm_label.setText(f"PM2.5: {aqi_data['pm25']}  |  PM10: {aqi_data['pm10']}")
                    
        except Exception as e:
            print(f"更新空氣品質資訊時發生錯誤：{str(e)}")
            # 顯示錯誤狀態
            if hasattr(self, 'aqi_label'):
                self.aqi_label.setText("AQI: --")
        
    def init_ui(self):
        """初始化主視窗 UI
        頁籤分兩排顯示：
          第1排 (深藍底): Monitor 系列 6個頁籤
          第2排 (深綠底): Budget 系列 7個頁籤
        點任一頁籤，下方內容區全螢幕顯示對應頁面。
        """
        central_widget = QWidget()
        self.setCentralWidget(central_widget)
        main_layout = QVBoxLayout(central_widget)
        main_layout.setContentsMargins(0, 0, 0, 0)
        main_layout.setSpacing(0)

        # ──────────────────────────────────────────
        # 頁籤列容器（兩排 tab bar，無 pane）
        # ──────────────────────────────────────────
        tab_bar_container = QWidget()
        tab_bar_container.setFixedHeight(97)  # 三排各 36px
        tab_bar_layout = QVBoxLayout(tab_bar_container)
