        # ── 相容舊程式碼：tab_widget / budget_tab_widget 包裝 ──
        # 讓 setCurrentIndex 呼叫仍能運作


    def _switch_tab(self, idx, group):
        if group == "monitor": stack_idx = idx
        elif group == "budget": stack_idx = 6 + idx
        elif group == "office": stack_idx = 16 + idx  # v5.34: offset 15→16
        else: stack_idx = idx
        self.content_stack.setCurrentIndex(stack_idx)
        for btn in self._monitor_btns:
            btn.setChecked(group == "monitor" and btn.property("tab_idx") == idx)
        for btn in self._budget_btns:
            btn.setChecked(group == "budget" and btn.property("tab_idx") == idx)
        for btn in getattr(self, '_office_btns', []):
            btn.setChecked(group == "office" and btn.property("tab_idx") == idx)

    def _switch_monitor(self, idx): self._switch_tab(idx, "monitor")
    def _switch_budget(self, idx): self._switch_tab(idx, "budget")
    def _switch_office(self, idx): self._switch_tab(idx, "office")

    def update_clock_only(self):
        """僅更新時鐘顯示"""
        try:
            if hasattr(self, 'digital_clock_label'):
                current_time = pd.Timestamp.now().strftime('%H:%M:%S')
                self.digital_clock_label.setText(current_time)
        except Exception as e:
            print(f"更新時鐘時發生錯誤：{str(e)}")
        
    def create_weather_dashboard(self):
        """創建天氣儀表板（v5_13 緊湊版）"""
        weather_widget = QWidget()
        weather_widget.setFixedSize(360, 280)  # v5_20: 234→280 加高以填滿版面
        weather_widget.setStyleSheet("""
            QWidget {
                background-color: #f8f9fa;
                border: 2px solid #dee2e6;
                border-radius: 9px;
            }
        """)
        
        layout = QVBoxLayout(weather_widget)
        layout.setSpacing(2)
        layout.setContentsMargins(7, 3, 7, 3)
        
        # 標題
        title_label = QLabel("🌡️ 即時天氣資訊")
        title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        title_label.setStyleSheet("""
            QLabel {
                font-size: 13px;
                font-weight: bold;
                color: #2c3e50;
                background-color: transparent;
                border: none;
                padding: 2px;
            }
        """)
        layout.addWidget(title_label)
        
        # 溫度顯示
        self.temp_label = QLabel("--°C")
        self.temp_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.temp_label.setStyleSheet("""
            QLabel {
                font-size: 20px;
                font-weight: bold;
                color: #e74c3c;
                background-color: transparent;
                border: none;
            }
        """)
        layout.addWidget(self.temp_label)
        
        # 體感溫度
        self.feels_like_label = QLabel("體感溫度: --°C")
