    # *** 額外功能：增強套用參數按鈕的樣式 ***
    def enhance_apply_params_button_style(self):
        """
        增強套用參數按鈕的樣式，表明它會執行查詢
        """
        if hasattr(self, 'parameter_inputs'):
            # 找到套用參數按鈕並更新樣式
            for parent in [self]:  # 可以擴展搜索範圍
                apply_buttons = parent.findChildren(QPushButton, "apply_params_btn")
                for btn in apply_buttons:
                    btn.setText("✅ 套用參數並執行查詢")
                    btn.setStyleSheet("""
                        QPushButton {
                            background-color: #27ae60;
                            color: white;
                            border: none;
                            border-radius: 6px;
                            font-size: 14px;
                            font-weight: bold;
                            padding: 6px 11px;
                            min-height: 35px;
                        }
                        QPushButton:hover {
                            background-color: #2ecc71;
                            box-shadow: 0 2px 4px rgba(39, 174, 96, 0.3);
                        }
                        QPushButton:pressed {
                            background-color: #229954;
                        }
                    """)
                    
                    # 設定工具提示
                    btn.setToolTip("點擊後將套用所有參數到SQL查詢並立即執行查詢")
                    break

    def insert_sql_template(self, template):
        """
        插入SQL範本（修改版本，支援參數替換）
        這個函數在用戶點擊SQL範本按鈕時執行
        """
        # 清空目前的SQL內容
        self.sql_text.clear()
        
        # 插入範本（包含參數佔位符）
        self.sql_text.setPlainText(template)
        
        # 將範本加入歷史記錄
        self.add_to_history(template)
        
        # 提示用戶可以設定參數
        QMessageBox.information(self, "範本已載入", 
                            "SQL範本已載入！\n\n" +
                            "您可以：\n" +
                            "1. 在「參數設定」區域調整參數值\n" +
                            "2. 點擊「套用參數」按鈕將參數值代入SQL\n" +
                            "   並自動執行查詢")

    # 繼續原有的其他方法...
    def show_history_context_menu(self, position):
        """顯示歷史記錄右鍵選單"""
        item = self.history_list.itemAt(position)
        if item:
            menu = QMenu()
            
            load_action = menu.addAction("📋 載入查詢")
            delete_action = menu.addAction("🗑️ 刪除此項")
            
            action = menu.exec(self.history_list.mapToGlobal(position))
            
            if action == load_action:
                self.load_history_query(item)
            elif action == delete_action:
                row = self.history_list.row(item)
                self.history_list.takeItem(row)
                if 0 <= row < len(self.query_history):
                    self.query_history.pop(row)

    def format_sql(self):
        """格式化SQL語句"""
        try:
            sql_text = self.sql_text.toPlainText()
            if sql_text.strip():
                # 簡單的SQL格式化
                formatted_sql = sql_text.replace(',', ',\n    ')
                formatted_sql = formatted_sql.replace(' FROM ', '\nFROM ')
                formatted_sql = formatted_sql.replace(' WHERE ', '\nWHERE ')
                formatted_sql = formatted_sql.replace(' GROUP BY ', '\nGROUP BY ')
                formatted_sql = formatted_sql.replace(' ORDER BY ', '\nORDER BY ')
                formatted_sql = formatted_sql.replace(' HAVING ', '\nHAVING ')
                formatted_sql = formatted_sql.replace(' JOIN ', '\nJOIN ')
                formatted_sql = formatted_sql.replace(' LEFT JOIN ', '\nLEFT JOIN ')
                formatted_sql = formatted_sql.replace(' RIGHT JOIN ', '\nRIGHT JOIN ')
                formatted_sql = formatted_sql.replace(' INNER JOIN ', '\nINNER JOIN ')
                
                self.sql_text.setPlainText(formatted_sql)
                QMessageBox.information(self, "格式化完成", "SQL語句已格式化完成！")
            else:
                QMessageBox.warning(self, "警告", "請先輸入SQL語句！")
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"格式化SQL時發生錯誤：{str(e)}")

    def load_history_query(self, item):
        """載入歷史查詢"""
        # 獲取對應的完整SQL（去除時間戳記）
        row = self.history_list.row(item)
        if 0 <= row < len(self.query_history):
            sql = self.query_history[row]
            self.sql_text.setPlainText(sql)

    def clear_query_history(self):
        """清除查詢歷史"""
        self.history_list.clear()
        self.query_history = []
        QMessageBox.information(self, "清除完成", "查詢歷史已清除！")

    def add_to_history(self, sql):
        """添加到查詢歷史"""
        if sql.strip():
            # 添加時間戳記
            timestamp = pd.Timestamp.now().strftime('%H:%M:%S')
            display_text = f"[{timestamp}] {sql[:40]}..." if len(sql) > 40 else f"[{timestamp}] {sql}"
            
            # 避免重複添加相同的查詢
            existing_items = [self.history_list.item(i).text() for i in range(self.history_list.count())]
            if display_text not in existing_items:
                self.query_history.append(sql)  # 保存完整SQL
                self.history_list.addItem(display_text)  # 顯示帶時間戳的版本
                
                # 限制歷史記錄數量
                if len(self.query_history) > 10:
                    self.query_history.pop(0)
                    self.history_list.takeItem(0)

