    def add_color(self, color):
        """添加顏色到已選顏色清單"""
        if not hasattr(self, 'chart_colors'):
            self.chart_colors = []
        
        if color not in self.chart_colors:
            self.chart_colors.append(color)
            self.update_selected_colors_display()

    def choose_custom_color(self):
        """選擇自定義顏色"""
        color = QColorDialog.getColor()
        if color.isValid():
            self.add_color(color.name())

    def clear_colors(self):
        """清除所有已選顏色"""
        if hasattr(self, 'chart_colors'):
            self.chart_colors = []
        self.update_selected_colors_display()

    def update_selected_colors_display(self):
        """更新已選擇顏色的顯示"""
        if not hasattr(self, 'selected_colors_label'):
            return
            
        if not hasattr(self, 'chart_colors') or not self.chart_colors:
            self.selected_colors_label.setText("未選擇顏色 (將使用默認顏色)")
        else:
            colors_text = ", ".join(self.chart_colors)
            if len(colors_text) > 50:  # 如果太長就截斷
                colors_text = colors_text[:47] + "..."
            self.selected_colors_label.setText(f"已選顏色: {colors_text}")

    def apply_seaborn_style(self):
        """應用Seaborn風格"""
        try:
            if not hasattr(self, 'style_combo') or not hasattr(self, 'context_combo') or not hasattr(self, 'palette_combo'):
                QMessageBox.warning(self, "警告", "風格控制項未初始化！")
                return
                
            style = self.style_combo.currentText()
            context = self.context_combo.currentText()
            palette = self.palette_combo.currentText()
            
            import seaborn as sns
            sns.set_style(style)
            sns.set_context(context)
            sns.set_palette(palette)
            
            # 重新設定中文字型
            set_chinese_font()
            
            QMessageBox.information(self, "風格已更新", 
                                f"已應用 Seaborn 風格設定：\n"
                                f"風格: {style}\n"
                                f"上下文: {context}\n"
                                f"調色盤: {palette}")
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"應用 Seaborn 風格時發生錯誤: {str(e)}")

    def display_chart(self, fig):
        """顯示圖表"""
        try:
            # 檢查圖表顯示容器是否存在
            if not hasattr(self, 'chart_layout') or not hasattr(self, 'default_chart_label'):
                print("圖表顯示容器未初始化")
                return
            
            # 隱藏預設提示標籤
            self.default_chart_label.setVisible(False)
            
            # 清除舊的圖表
            for i in reversed(range(self.chart_layout.count())):
                child = self.chart_layout.itemAt(i).widget()
                if child and child != self.default_chart_label:
                    child.setParent(None)
            
            # 添加新的圖表
            from matplotlib.backends.backend_qtagg import FigureCanvasQTAgg as FigureCanvas
            canvas = FigureCanvas(fig)
            self.chart_layout.addWidget(canvas)
            canvas.draw()
            
            # 儲存當前圖表以便匯出
            self.current_figure = fig
            
            print("圖表顯示完成")
            
        except Exception as e:
            print(f"顯示圖表時發生錯誤：{e}")
            QMessageBox.critical(self, "錯誤", f"顯示圖表時發生錯誤：{str(e)}")

    def update_result_table(self, df):
        """更新結果表格 - 標準版本，加入整數格式化"""
        self.result_table.clear()
        self.result_table.setRowCount(len(df))
        self.result_table.setColumnCount(len(df.columns))
        self.result_table.setHorizontalHeaderLabels(df.columns.tolist())
        
        for row in range(len(df)):
            for col in range(len(df.columns)):
                value = df.iloc[row, col]
                
                # 使用統一的格式化方法
                if pd.notna(value):
                    if isinstance(value, (int, float)):
                        display_value = self._format_table_value(value)
                    else:
                        display_value = str(value)
                else:
                    display_value = ""
                
                item = QTableWidgetItem(display_value)
                self.result_table.setItem(row, col, item)

    def setup_filter_widgets(self, df):
        """設定篩選控制元件 - 縮小版"""
        # 清除現有篩選控制元件
        for i in reversed(range(self.filter_container_layout.count())):
            child = self.filter_container_layout.itemAt(i)
            if child and child.widget():
                child.widget().setParent(None)
        
        self.filter_vars = {}
        self.filter_entries = {}
        self.filter_operators = {}
        
        # 改為每行顯示3個欄位以節省空間
        cols_per_row = 6  # 從3改為6
        
        for i, col in enumerate(df.columns):
            row = i // cols_per_row
            col_group = i % cols_per_row
            
            # 每個欄位組佔用3列：標籤、運算子、輸入框
            base_row = row * 4  # 每組之間留一行空隙
            base_col = col_group * 4  # 縮小每組佔用空間從6到4
            
            # 欄位標籤 - 縮小尺寸
            label = QLabel(f"{col}:")
            label.setStyleSheet("""
                QLabel {
                    font-weight: bold; 
                    font-size: 14px;  
                    color: #2c3e50;
                    padding: 3px;    
                    background-color: #ecf0f1;
                    border: 1px solid #bdc3c7;
                    border-radius: 3px;  
                    min-width: 80px;     
                    max-width: 120px;    
                }
            """)
            label.setWordWrap(True)
            self.filter_container_layout.addWidget(label, base_row, base_col, 1, 1)
            
            # 運算子選擇下拉選單 - 縮小
            op_combo = QComboBox()
            op_combo.addItems(['=', '!=', '>', '<', '>=', '<=', 'contains', 'not contains'])
            op_combo.setCurrentText('=')
            op_combo.setStyleSheet("""
                QComboBox {
                    border: 2px solid #3498db;
                    border-radius: 4px;  
                    padding: 4px 6px;    
                    font-size: 14px;    
                    min-width: 20px;   
                    min-height: 25px;    
                    background-color: white;
                }
                QComboBox:hover {
                    border: 2px solid #2980b9;
                    background-color: #f8f9fa;
                }
                QComboBox:focus {
                    border: 2px solid #e74c3c;
                }
            """)
            self.filter_container_layout.addWidget(op_combo, base_row + 1, base_col, 1, 1)
            
            # 篩選值輸入框 - 縮小
            entry = QLineEdit()
            entry.setPlaceholderText(f"篩選 {col[:8]}...")  # 縮短佔位符文字
            entry.setStyleSheet("""
                QLineEdit {
                    border: 2px solid #95a5a6;
                    border-radius: 4px; 
                    padding: 4px 6px;   
                    font-size: 14px;     
                    min-width: 20px;   
                    min-height: 25px;   
                    background-color: white;
                }
                QLineEdit:focus {
                    border: 2px solid #3498db;
                    background-color: #f0f8ff;
                }
                QLineEdit:hover {
                    border: 2px solid #7f8c8d;
                    background-color: #f8f9fa;
                }
            """)
            self.filter_container_layout.addWidget(entry, base_row + 2, base_col, 1, 1)
            
            # 儲存到字典中
            self.filter_vars[col] = entry
            self.filter_entries[col] = entry
            self.filter_operators[col] = op_combo
        
        # 添加底部間距 - 縮小
        spacer = QWidget()
        spacer.setMinimumHeight(14) 
        self.filter_container_layout.addWidget(spacer, (len(df.columns) // cols_per_row + 1) * 4, 0, 1, -1)

