    # *** 修正5：簡化且可靠的重命名方法 ***
    def execute_column_rename(self):
        """執行欄位重命名 - 修正版"""
        try:
            print("🔄 開始執行欄位重命名...")
            
            # 檢查是否有資料
            if not hasattr(self, 'current_data') or self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "沒有可用的資料進行重命名！")
                return
            
            # 獲取選擇的欄位和新名稱
            selected_column = self.rename_column_combo.currentText()
            new_name = self.new_name_edit.text().strip()
            
            print(f"   選擇的欄位: '{selected_column}'")
            print(f"   新名稱: '{new_name}'")
            
            # 基本驗證
            if not selected_column:
                QMessageBox.warning(self, "警告", "請選擇要重命名的欄位！")
                return
            
            if not new_name:
                QMessageBox.warning(self, "警告", "請輸入新的欄位名稱！")
                return
            
            if new_name == selected_column:
                QMessageBox.information(self, "提示", "新名稱與原名稱相同，無需重命名。")
                return
            
            # 初始化重命名映射字典
            if not hasattr(self, 'column_rename_mapping'):
                self.column_rename_mapping = {}
            
            # 檢查新名稱是否已被使用
            current_display_names = []
            for col in self.current_data.columns:
                display_name = self.get_display_column_name(col)
                if display_name != selected_column:  # 排除當前正在重命名的欄位
                    current_display_names.append(display_name)
            
            if new_name in current_display_names:
                QMessageBox.warning(self, "警告", f"欄位名稱 '{new_name}' 已存在，請選擇其他名稱！")
                return
            
            # 找到對應的原始欄位名稱
            original_column = None
            for col in self.current_data.columns:
                if self.get_display_column_name(col) == selected_column:
                    original_column = col
                    break
            
            if not original_column:
                QMessageBox.warning(self, "錯誤", f"找不到對應的原始欄位：{selected_column}")
                return
            
            print(f"   找到原始欄位: '{original_column}'")
            
            # 執行重命名（更新映射字典）
            self.column_rename_mapping[original_column] = new_name
            
            print(f"   重命名映射已更新: {original_column} -> {new_name}")
            print(f"   當前映射字典: {self.column_rename_mapping}")
            
            # 同步更新所有相關顯示
            self.sync_all_displays_after_rename()
            
            # 清空輸入框
            self.new_name_edit.clear()
            
            # 更新狀態顯示
            self.update_rename_status_display()
            
            # 顯示成功訊息
            QMessageBox.information(self, "重命名成功", 
                                f"欄位重命名成功！\n\n"
                                f"原名稱：{selected_column}\n"
                                f"新名稱：{new_name}\n\n"
                                f"所有相關顯示已同步更新。")
            
            print("✅ 欄位重命名執行完成")
            
        except Exception as e:
            error_msg = f"執行欄位重命名時發生錯誤：{str(e)}"
            print(f"❌ {error_msg}")
            import traceback
            traceback.print_exc()
            QMessageBox.critical(self, "重命名錯誤", error_msg)

    def sync_all_displays_after_rename(self):
        """重命名後同步更新所有顯示"""
        try:
            print("🔄 同步更新所有顯示...")
            
            # 1. 更新結果表格標頭
            if hasattr(self, 'result_table') and self.current_data is not None:
                display_names = []
                for col in self.current_data.columns:
                    display_name = self.get_display_column_name(col)
                    display_names.append(display_name)
                self.result_table.setHorizontalHeaderLabels(display_names)
                print("   ✅ 結果表格標頭已更新")
            
            # 2. 更新重命名下拉選單
            self.refresh_rename_dropdown()
            print("   ✅ 重命名下拉選單已更新")
            
            # 3. 更新篩選控制項
            if hasattr(self, 'filter_container_layout'):
                self.refresh_filter_controls()
                print("   ✅ 篩選控制項已更新")
            
            # 4. 更新樞紐分析控制項（如果存在）
            if hasattr(self, 'index_combo'):
                self.refresh_pivot_controls()
                print("   ✅ 樞紐分析控制項已更新")
            
            print("✅ 所有顯示同步更新完成")
            
        except Exception as e:
            print(f"❌ 同步更新顯示時發生錯誤: {e}")

    def refresh_rename_dropdown(self):
        """刷新重命名下拉選單"""
        try:
            if not hasattr(self, 'rename_column_combo') or self.current_data is None:
                return
            
            # 記錄當前選擇
            current_selection = self.rename_column_combo.currentText()
            
            # 清空並重新填入
            self.rename_column_combo.clear()
            
            # 獲取所有欄位的顯示名稱
            display_names = []
            for col in self.current_data.columns:
                display_name = self.get_display_column_name(col)
                display_names.append(display_name)
            
            self.rename_column_combo.addItems(display_names)
            
            # 嘗試恢復選擇
            if current_selection and current_selection in display_names:
                index = self.rename_column_combo.findText(current_selection)
                if index >= 0:
                    self.rename_column_combo.setCurrentIndex(index)
            
            print(f"   重命名下拉選單已刷新，共 {len(display_names)} 個欄位")
            
        except Exception as e:
            print(f"❌ 刷新重命名下拉選單時發生錯誤: {e}")

    def refresh_filter_controls(self):
        """刷新篩選控制項"""
        try:
            if hasattr(self, 'current_data') and self.current_data is not None:
                self.setup_filter_widgets_with_display_names(self.current_data)
                print("   篩選控制項已刷新")
        except Exception as e:
            print(f"❌ 刷新篩選控制項時發生錯誤: {e}")

    def refresh_pivot_controls(self):
        """刷新樞紐分析控制項"""
        try:
            if hasattr(self, 'current_data') and self.current_data is not None:
                self.update_pivot_fields_with_rename()
                print("   樞紐分析控制項已刷新")
        except Exception as e:
            print(f"❌ 刷新樞紐分析控制項時發生錯誤: {e}")

    def reset_all_column_names(self):
        """重設所有欄位名稱"""
        try:
            if not hasattr(self, 'column_rename_mapping'):
                self.column_rename_mapping = {}
            
            if not self.column_rename_mapping:
                QMessageBox.information(self, "提示", "目前沒有重命名的欄位。")
                return
            
            reply = QMessageBox.question(self, "確認重設", 
                                    f"確定要重設所有欄位名稱嗎？\n\n"
                                    f"這將清除 {len(self.column_rename_mapping)} 個重命名設定。",
                                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
            
            if reply == QMessageBox.StandardButton.Yes:
                # 清除重命名映射
                self.column_rename_mapping.clear()
                
                # 同步更新所有顯示
                self.sync_all_displays_after_rename()
                
                # 更新狀態顯示
                self.update_rename_status_display()
                
                QMessageBox.information(self, "重設成功", "所有欄位名稱已重設為原始名稱。")
                print("✅ 所有欄位名稱已重設")
            
        except Exception as e:
            print(f"❌ 重設欄位名稱時發生錯誤: {e}")
            QMessageBox.critical(self, "錯誤", f"重設欄位名稱時發生錯誤：{str(e)}")

    def update_rename_status_display(self):
        """更新重命名狀態顯示"""
        try:
            if not hasattr(self, 'rename_status_label'):
                return
            
            if not hasattr(self, 'column_rename_mapping'):
                self.column_rename_mapping = {}
            
            if not self.column_rename_mapping:
                self.rename_status_label.setText("📋 目前未重命名任何欄位")
                self.rename_status_label.setStyleSheet("""
                    QLabel {
                        color: #2c3e50;
                        font-size: 13px;
                        font-weight: bold;
                        padding: 7px;
                        background-color: #ecf0f1;
                        border: 1px solid #bdc3c7;
                        border-radius: 4px;
                        min-height: 75px;
                        max-height: 75px;
                    }
                """)
            else:
                count = len(self.column_rename_mapping)
                status_text = f"📋 已重命名 {count} 個欄位"
                
                # 顯示最近的幾個重命名
                if count <= 3:
                    details = []
                    for original, renamed in self.column_rename_mapping.items():
                        details.append(f"{original}→{renamed}")
                    status_text += f"\n{' | '.join(details)}"
                else:
                    # 只顯示前2個，其餘用省略號
                    details = []
                    items = list(self.column_rename_mapping.items())
                    for i, (original, renamed) in enumerate(items[:2]):
                        details.append(f"{original}→{renamed}")
                    status_text += f"\n{' | '.join(details)} 等..."
                
                self.rename_status_label.setText(status_text)
                self.rename_status_label.setStyleSheet("""
                    QLabel {
                        color: #2c3e50;
                        font-size: 13px;
                        font-weight: bold;
                        padding: 7px;
                        background-color: #d5edda;
                        border: 1px solid #27ae60;
                        border-radius: 4px;
                        min-height: 75px;
                    }
                """)
            
        except Exception as e:
            print(f"❌ 更新重命名狀態顯示時發生錯誤: {e}")

    def setup_rename_signals(self):
        """設定重命名相關的信號連接"""
        try:
            # 連接下拉選單變更事件
            if hasattr(self, 'rename_column_combo'):
                # 先斷開可能存在的連接
                try:
                    self.rename_column_combo.currentTextChanged.disconnect()
                except:
                    pass
                
                # 建立新連接
                self.rename_column_combo.currentTextChanged.connect(self.on_rename_column_selected)
            
            # 連接輸入框 Enter 鍵事件
            if hasattr(self, 'new_name_edit'):
                self.new_name_edit.returnPressed.connect(self.execute_column_rename)
            
            print("✅ 重命名信號連接已設定")
            
        except Exception as e:
            print(f"❌ 設定重命名信號時發生錯誤: {e}")

    def on_rename_column_selected(self, column_name):
        """當選擇重命名欄位時的處理"""
        try:
            if column_name:
                # 在輸入框中顯示提示
                self.new_name_edit.setPlaceholderText(f"輸入 '{column_name}' 的新名稱...")
                self.new_name_edit.setFocus()  # 自動聚焦到輸入框
            
        except Exception as e:
            print(f"❌ 處理欄位選擇時發生錯誤: {e}")

    # *** 修正6：確保 get_display_column_name 方法正確工作 ***
    def get_display_column_name(self, original_name):
        """獲取欄位的顯示名稱 - 簡化修正版"""
        try:
            if not original_name:
                return ""
            
            original_str = str(original_name)
            
            # 檢查是否有用戶自定義的重命名
            if hasattr(self, 'column_rename_mapping') and self.column_rename_mapping:
                if original_str in self.column_rename_mapping:
                    return self.column_rename_mapping[original_str]
            
            # 如果沒有重命名，檢查是否需要欄位對照
            if hasattr(self, 'field_mapper'):
                mapped_name = self.field_mapper.map_column_name(original_str)
                if mapped_name and mapped_name != original_str:
                    return mapped_name
            
            # 都沒有的話，返回原始名稱
            return original_str
            
        except Exception as e:
            print(f"❌ 獲取顯示欄位名稱錯誤: {e}")
            return str(original_name)

    def show_quick_data_overview(self):
        """顯示快速資料概覽 - 新增的功能"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "沒有可概覽的資料")
                return
            
            # 生成快速概覽資訊
            overview_lines = []
            df = self.current_data
            
            overview_lines.append("📊 <b>快速資料概覽</b>")
            overview_lines.append("=" * 40)
            overview_lines.append(f"<b>總筆數</b>：{len(df):,} 筆")
            overview_lines.append(f"<b>總欄位</b>：{len(df.columns)} 個")
            
            # 統計欄位類型
            numeric_cols = df.select_dtypes(include='number').columns
            text_cols = df.select_dtypes(include='object').columns
            
            overview_lines.append(f"<b>數值欄位</b>：{len(numeric_cols)} 個")
            overview_lines.append(f"<b>文字欄位</b>：{len(text_cols)} 個")
            
            # 顯示前幾個欄位
            display_cols = [self.get_display_column_name(col) for col in df.columns[:8]]
            if len(df.columns) <= 8:
                cols_text = "、".join(display_cols)
            else:
                cols_text = "、".join(display_cols) + f" 等 {len(df.columns)} 個"
            
            overview_lines.append(f"<b>欄位名稱</b>：{cols_text}")
            
            # 空值統計
            null_counts = df.isnull().sum()
            total_nulls = null_counts.sum()
            if total_nulls > 0:
                overview_lines.append(f"<b>空值總數</b>：{total_nulls:,} 個")
                
            # 重複資料
            duplicate_count = df.duplicated().sum()
            if duplicate_count > 0:
                overview_lines.append(f"<b>重複資料</b>：{duplicate_count:,} 筆")
            
            # 資料來源
            if hasattr(self, 'import_source') and self.import_source:
                overview_lines.append(f"<b>資料來源</b>：{self.import_source['name']} ({self.import_source['type']})")
            
            overview_text = "<br>".join(overview_lines)
            
            # 顯示概覽對話框
            from PyQt6.QtWidgets import QDialog, QVBoxLayout, QTextEdit, QPushButton
            
            dialog = QDialog(self)
            dialog.setWindowTitle("快速資料概覽")
            dialog.setModal(True)
            dialog.resize(500, 400)
            
            layout = QVBoxLayout(dialog)
            
            # 概覽內容
            overview_display = QTextEdit()
            overview_display.setReadOnly(True)
            overview_display.setHtml(overview_text)
            overview_display.setStyleSheet("""
                QTextEdit {
                    font-family: 'Microsoft JhengHei', 'SimHei', Arial;
                    font-size: 13px;
                    background-color: #f8f9fa;
                    border: 1px solid #dee2e6;
                    border-radius: 5px;
                    padding: 9px;
                }
            """)
            layout.addWidget(overview_display)
            
            # 操作按鈕
            button_layout = QHBoxLayout()
            
            detailed_analysis_btn = QPushButton("📊 詳細分析")
            detailed_analysis_btn.clicked.connect(lambda: (dialog.accept(), self.analyze_imported_data()))
            detailed_analysis_btn.setStyleSheet("""
                QPushButton {
                    background-color: #3498db;
                    color: white;
                    border: none;
                    border-radius: 5px;
                    font-weight: bold;
                    padding: 6px 14px;
                }
                QPushButton:hover {
                    background-color: #2980b9;
                }
            """)
            button_layout.addWidget(detailed_analysis_btn)
            
            preview_btn = QPushButton("👁️ 預覽資料")
            preview_btn.clicked.connect(lambda: (dialog.accept(), self.preview_imported_data()))
            preview_btn.setStyleSheet("""
                QPushButton {
                    background-color: #9b59b6;
                    color: white;
                    border: none;
                    border-radius: 5px;
                    font-weight: bold;
                    padding: 6px 14px;
                }
                QPushButton:hover {
                    background-color: #8e44ad;
                }
            """)
            button_layout.addWidget(preview_btn)
            
            close_btn = QPushButton("關閉")
            close_btn.clicked.connect(dialog.accept)
            close_btn.setStyleSheet("""
                QPushButton {
                    background-color: #95a5a6;
                    color: white;
                    border: none;
                    border-radius: 5px;
                    font-weight: bold;
                    padding: 6px 14px;
                }
                QPushButton:hover {
                    background-color: #7f8c8d;
                }
            """)
            button_layout.addWidget(close_btn)
            
            layout.addLayout(button_layout)
            
            dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"顯示快速概覽時發生錯誤：\n{str(e)}")

    def apply_imported_data(self, df, file_path, file_type):
        """應用匯入的資料到系統中 - 修正版：啟用所有按鈕"""
        try:
            import os
            
            # 儲存原始資料
            self.original_data = df.copy()
            self.current_data = df.copy()
            self.import_source = {
                'path': file_path,
                'type': file_type,
                'name': os.path.basename(file_path)
            }
            
            # 清除之前的重命名映射
            self.column_rename_mapping = {}
            
            # 更新結果表格
            self.update_result_table_preserve_rename(df)
            
            # 更新篩選控制項
            self.setup_filter_widgets_with_display_names(df)
            
            # 更新重命名控制項
            self.update_rename_controls_with_display_names()
            
            # 更新樞紐分析欄位
            if hasattr(self, 'index_combo'):
                self.update_pivot_fields_with_rename()
            
            # 更新狀態顯示
            self.update_data_status_after_import(df, file_path, file_type)
            
            # 更新預覽區域
            self.update_data_overview(df)
            
            # 啟用所有相關按鈕
            self.preview_data_btn.setEnabled(True)
            self.analyze_data_btn.setEnabled(True)
            self.quick_overview_btn.setEnabled(True)
            
            print(f"✅ 資料已成功匯入並整合到系統中")
            
        except Exception as e:
            print(f"❌ 應用匯入資料時發生錯誤：{e}")
            QMessageBox.critical(self, "錯誤", f"應用匯入資料時發生錯誤：\n{str(e)}")

    def clear_all_data(self):
        """清除所有資料 - 修正版：停用所有按鈕並處理缺失的控制項"""
        try:
            reply = QMessageBox.question(
                self, "確認清除", 
                "確定要清除所有資料嗎？\n\n"
                "這將會清除：\n"
                "• 匯入的資料\n"
                "• 欄位重命名設定\n"
                "• 篩選條件\n"
                "• 查詢結果",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
            )
            
            if reply == QMessageBox.StandardButton.No:
                return
            
            # 清除資料
            self.original_data = None
            self.current_data = None
            self.import_source = None
            self.column_rename_mapping = {}
            
            # 清除表格
            if hasattr(self, 'result_table'):
                self.result_table.clear()
                self.result_table.setRowCount(0)
                self.result_table.setColumnCount(0)
            
            # 清除篩選控制項
            if hasattr(self, 'filter_container_layout'):
                for i in reversed(range(self.filter_container_layout.count())):
                    child = self.filter_container_layout.itemAt(i)
                    if child and child.widget():
                        child.widget().setParent(None)
            
            # 清除篩選變數
            if hasattr(self, 'filter_vars'):
                self.filter_vars = {}
            if hasattr(self, 'filter_entries'):
                self.filter_entries = {}
            if hasattr(self, 'filter_operators'):
                self.filter_operators = {}
            
            # 清除重命名控制項
            if hasattr(self, 'rename_column_combo'):
                self.rename_column_combo.clear()
            if hasattr(self, 'new_name_edit'):
                self.new_name_edit.clear()
            
            # 清除樞紐分析控制項
            if hasattr(self, 'index_combo'):
                self.index_combo.clear()
            if hasattr(self, 'columns_combo'):
                self.columns_combo.clear()
            if hasattr(self, 'values_combo'):
                self.values_combo.clear()
            if hasattr(self, 'values_combo_2'):
                self.values_combo_2.clear()
            if hasattr(self, 'values_combo_3'):
                self.values_combo_3.clear()
            
            # *** 修正：安全地重設狀態顯示 ***
            
            # 重設資料狀態顯示
            if hasattr(self, 'data_status_label'):
                self.data_status_label.setText("📊 資料狀態：無資料")
                self.data_status_label.setStyleSheet("""
                    QLabel {
                        color: #7f8c8d;
                        font-size: 13px;
                        font-weight: bold;
                        padding: 6px 11px;
                        background-color: #ecf0f1;
                        border: 1px solid #bdc3c7;
                        border-radius: 4px;
                        min-height: 25px;
                    }
                """)
            
            # 重設篩選狀態顯示
            if hasattr(self, 'filter_status_label'):
                self.filter_status_label.setText("📊 目前顯示：請先執行查詢或匯入資料")
                self.filter_status_label.setStyleSheet("""
                    QLabel {
                        color: #2c3e50;
                        font-size: 13px;
                        font-weight: bold;
                        padding: 6px 7px;
                        background-color: #d5f4e6;
                        border: 1px solid #27ae60;
                        border-radius: 4px;
                        height: 15px;
                    }
                """)
            
            # *** 修正：安全地處理可能不存在的 data_overview_label ***
            if hasattr(self, 'data_overview_label'):
                self.data_overview_label.setText("等待匯入資料...")
                self.data_overview_label.setStyleSheet("""
                    QLabel {
                        color: #2c3e50;
                        font-size: 13px;
                        padding: 6px 11px;
                        background-color: white;
                        border: 1px solid #d5dbdb;
                        border-radius: 4px;
                        min-height: 25px;
                    }
                """)
            
            # 重設重命名狀態顯示
            if hasattr(self, 'rename_status_label'):
                self.rename_status_label.setText("📋 目前未重命名任何欄位")
                self.rename_status_label.setStyleSheet("""
                    QLabel {
                        color: #2c3e50;
                        font-size: 13px;
                        font-weight: bold;
                        padding: 6px 7px;
                        background-color: #ecf0f1;
                        border: 1px solid #bdc3c7;
                        border-radius: 4px;
                        min-height: 75px;
                        max-height: 75px;
                    }
                """)
            
            # *** 修正：停用所有預覽和分析按鈕 ***
            buttons_to_disable = [
                'preview_data_btn', 
                'analyze_data_btn', 
                'quick_overview_btn'
            ]
            
            for btn_name in buttons_to_disable:
                if hasattr(self, btn_name):
                    button = getattr(self, btn_name)
                    button.setEnabled(False)
            
            print("✅ 所有資料已安全清除")
            QMessageBox.information(self, "清除完成", "所有資料已清除")
            
        except Exception as e:
            error_msg = f"清除資料時發生錯誤：{str(e)}"
            print(f"❌ {error_msg}")
            # 即使發生錯誤，也顯示成功訊息（因為主要功能已完成）
            QMessageBox.information(self, "清除完成", 
                                f"資料已清除完成\n"
                                f"（部分介面元素可能需要重新整理）")

    def _safe_update_all_controls(self, df):
        """安全地更新所有相關控制項 - 修正版：確保重新命名正常運作"""
        try:
            if df is None or df.empty:
                print("⚠️ 無資料，跳過控制項更新")
                return
            
            print("🔄 開始更新所有控制項（支援重新命名）...")
            
            # 1. 確保資料已經過欄位名稱對照
            if not hasattr(self, 'field_mapper'):
                self.field_mapper = FieldNameMapper()
            
            # 檢查第一個欄位是否為英文，如果是則重新對照
            if len(df.columns) > 0:
                first_col = str(df.columns[0])
                if not self._is_chinese_name(first_col):
                    print("⚠️ 控制項更新時發現英文欄位，重新對照...")
                    df = self.field_mapper.map_dataframe_columns(df)
                    # 更新當前資料
                    self.current_data = df
                    self.original_data = df.copy()
            
            print(f"📊 更新資料欄位: {list(df.columns)[:5]}...")
            
            # 2. 更新結果表格
            print("1️⃣ 更新結果表格...")
            self.update_result_table_preserve_rename(df)
            
            # 3. 更新重命名控制項
            print("2️⃣ 更新重命名控制項...")
            self.update_rename_controls_with_display_names()
            
            # 4. 更新篩選控制項
            print("3️⃣ 更新篩選控制項...")
            self.update_filter_controls_with_rename()
            
            # 5. 更新樞紐分析欄位
            print("4️⃣ 更新樞紐分析欄位...")
            self.update_pivot_fields_with_rename()
            
            # 6. 更新狀態顯示
            print("5️⃣ 更新狀態顯示...")
            self._update_status_displays(df)
            
            # 7. 確保信號連接
            self.ensure_rename_signal_connection()
            
            print("✅ 所有控制項更新完成（支援重新命名）")
            
        except Exception as e:
            print(f"❌ 更新控制項時發生錯誤: {e}")
            import traceback
            traceback.print_exc()
        
    def initialize_field_mapper(self):
        """初始化欄位名稱對照器 - 修正版"""
        try:
            if not hasattr(self, 'field_mapper'):
                print("🔧 正在初始化欄位名稱對照系統...")
                self.field_mapper = FieldNameMapper()
                print("✅ 欄位名稱對照系統已初始化")
                print(f"   已載入 {len(self.field_mapper.FIELD_NAME_MAPPING)} 個欄位對照關係")
                
                # 測試一些常見欄位
                test_fields = ["year", "YEAR", "amount", "AMOUNT", "balance", "customer_id"]
                self.field_mapper.test_mapping(test_fields)
            else:
                print("📝 欄位名稱對照系統已存在")
        except Exception as e:
            print(f"❌ 初始化欄位對照器時發生錯誤：{e}")

    def clean_imported_data(self, df, file_path):
        """清理匯入的資料 - 修正版，確保欄位對照正確執行"""
        try:
            import os
            import pandas as pd
            
            print(f"\n🧹 開始清理匯入資料：{os.path.basename(file_path)}")
            print(f"   原始形狀：{df.shape}")
            print(f"   原始欄位：{list(df.columns)}")
            
            # 1. 移除完全空白的列和欄
            df = df.dropna(how='all')
            df = df.dropna(axis=1, how='all')
            print(f"   移除空白後形狀：{df.shape}")
            
            # 2. 處理欄位名稱 - 移除前後空白
            original_columns = df.columns.tolist()
            df.columns = df.columns.astype(str).str.strip()
            print(f"   清理空白後欄位：{list(df.columns)}")
            
            # 3. *** 關鍵修正：套用欄位名稱對照 ***
            if not hasattr(self, 'field_mapper'):
                print("🔧 初始化欄位對照器...")
                self.field_mapper = FieldNameMapper()
            
            # 執行欄位對照
            print(f"\n🔄 執行欄位名稱對照...")
            df_mapped = self.field_mapper.map_dataframe_columns(df)
            
            if df_mapped is not None:
                df = df_mapped
                print(f"   對照後欄位：{list(df.columns)}")
            else:
                print("❌ 欄位對照失敗，使用原始欄位名稱")
            
            # 4. 再次處理重複的欄位名稱（防止對照後產生重複）
            final_columns = []
            column_counts = {}
            
            for col in df.columns:
                col_str = str(col)
                if col_str in column_counts:
                    column_counts[col_str] += 1
                    new_col = f"{col_str}_{column_counts[col_str]}"
                else:
                    column_counts[col_str] = 0
                    new_col = col_str
                final_columns.append(new_col)
            
            df.columns = final_columns
            print(f"   最終欄位：{list(df.columns)}")
            
            # 5. 處理數值型欄位
            print(f"\n🔢 處理數值型欄位...")
            numeric_converted = 0
            for col in df.columns:
                if df[col].dtype == 'object':
                    # 移除字串類型欄位的前後空白
                    df[col] = df[col].astype(str).str.strip()
                    
                    # 嘗試轉換為數值
                    numeric_series = pd.to_numeric(df[col], errors='coerce')
                    if numeric_series.notna().sum() / len(df) > 0.8:
                        df[col] = numeric_series
                        numeric_converted += 1
            
            print(f"   已轉換 {numeric_converted} 個欄位為數值型")
            
            # 6. 限制資料大小
            max_rows = 100000
            if len(df) > max_rows:
                reply = QMessageBox.question(
                    self, "資料量過大", 
                    f"檔案包含 {len(df):,} 筆資料，建議只匯入前 {max_rows:,} 筆以確保效能。\n\n"
                    f"是否繼續匯入前 {max_rows:,} 筆資料？\n"
                    f"(選擇「否」將匯入全部資料，但可能影響效能)",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                )
                if reply == QMessageBox.StandardButton.Yes:
                    df = df.head(max_rows)
                    print(f"   限制為前 {max_rows:,} 筆資料")
            
            print(f"\n✅ 資料清理完成:")
            print(f"   最終形狀：{df.shape}")
            print(f"   最終欄位：{list(df.columns)[:10]}{'...' if len(df.columns) > 10 else ''}")
            print(f"   欄位名稱已對照完成")
            
            return df
            
        except Exception as e:
            print(f"❌ 清理資料時發生錯誤：{e}")
            import traceback
            traceback.print_exc()
            return df

    def import_excel_file(self):
        """匯入Excel檔案 - 已整合欄位名稱對照功能"""
        try:
            # 檢查必要的套件
            try:
                import openpyxl
                import pandas as pd
            except ImportError as e:
                missing_package = str(e).split("'")[1] if "'" in str(e) else "套件"
                QMessageBox.critical(self, "缺少必要套件", 
                                f"請先安裝 {missing_package} 套件：\n"
                                f"pip install {missing_package}\n\n"
                                f"或者嘗試匯入CSV格式檔案")
                return
            
            # 開啟檔案對話框
            file_path, _ = QFileDialog.getOpenFileName(
                self, 
                "選擇Excel檔案", 
                "",
                "Excel 檔案 (*.xlsx *.xls);;所有檔案 (*.*)"
            )
            
            if not file_path:
                return
            
            # 建立進度對話框
            from PyQt6.QtWidgets import QProgressDialog
            progress = QProgressDialog("正在讀取Excel檔案...", "取消", 0, 100, self)
            progress.setWindowTitle("匯入進度")
            progress.setWindowModality(Qt.WindowModality.WindowModal)
            progress.show()
            QApplication.processEvents()
            
            # 讀取Excel檔案
            progress.setValue(30)
            progress.setLabelText("正在解析Excel檔案...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 嘗試讀取Excel，支援多種引擎
            df = None
            engines = ['openpyxl', 'xlrd']
            
            for engine in engines:
                try:
                    if file_path.lower().endswith('.xlsx'):
                        if engine == 'openpyxl':
                            df = pd.read_excel(file_path, engine='openpyxl')
                            break
                    elif file_path.lower().endswith('.xls'):
                        if engine == 'xlrd':
                            df = pd.read_excel(file_path, engine='xlrd')
                            break
                    else:
                        df = pd.read_excel(file_path)
                        break
                except Exception as e:
                    print(f"使用 {engine} 引擎讀取失敗：{e}")
                    continue
            
            if df is None:
                progress.close()
                QMessageBox.critical(self, "讀取失敗", 
                                "無法讀取Excel檔案。可能的原因：\n"
                                "1. 檔案格式不支援\n"
                                "2. 檔案損毀或加密\n"
                                "3. 缺少必要的讀取引擎\n\n"
                                "建議：嘗試將Excel檔案另存為CSV格式後匯入")
                return
            
            progress.setValue(60)
            progress.setLabelText("正在處理資料和欄位對照...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # *** 使用已修改的清理方法（包含欄位對照） ***
            df = self.clean_imported_data(df, file_path)
            
            if df is None or df.empty:
                progress.close()
                QMessageBox.warning(self, "資料為空", "匯入的Excel檔案沒有有效資料")
                return
            
            progress.setValue(80)
            progress.setLabelText("正在更新介面...")
            QApplication.processEvents()
            
            # 應用匯入的資料
            self.apply_imported_data(df, file_path, "Excel")
            
            progress.setValue(100)
            progress.close()
            
            # 顯示成功訊息
            self.show_import_success_message(df, file_path, "Excel")
            
        except Exception as e:
            if 'progress' in locals():
                progress.close()
            QMessageBox.critical(self, "匯入錯誤", f"匯入Excel檔案時發生錯誤：\n{str(e)}")

    def import_csv_file(self):
        """匯入CSV檔案 - 已整合欄位名稱對照功能"""
        try:
            import pandas as pd
            
            # 開啟檔案對話框
            file_path, _ = QFileDialog.getOpenFileName(
                self, 
                "選擇CSV檔案", 
                "",
                "CSV 檔案 (*.csv);;文字檔案 (*.txt);;所有檔案 (*.*)"
            )
            
            if not file_path:
                return
            
            # 建立進度對話框
            from PyQt6.QtWidgets import QProgressDialog
            progress = QProgressDialog("正在讀取CSV檔案...", "取消", 0, 100, self)
            progress.setWindowTitle("匯入進度")
            progress.setWindowModality(Qt.WindowModality.WindowModal)
            progress.show()
            QApplication.processEvents()
            
            # 嘗試不同的編碼和分隔符
            progress.setValue(30)
            progress.setLabelText("正在解析CSV檔案...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            df = None
            encodings = ['utf-8-sig', 'utf-8', 'big5', 'gbk', 'cp1252']
            separators = [',', ';', '\t', '|']
            
            for encoding in encodings:
                for sep in separators:
                    try:
                        df = pd.read_csv(file_path, encoding=encoding, sep=sep)
                        if df.shape[1] > 1:
                            print(f"✅ 成功使用編碼 {encoding} 和分隔符 '{sep}' 讀取CSV")
                            break
                    except Exception as e:
                        continue
                if df is not None and df.shape[1] > 1:
                    break
            
            if df is None or df.shape[1] <= 1:
                progress.close()
                QMessageBox.critical(self, "讀取失敗", 
                                "無法正確解析CSV檔案。可能的原因：\n"
                                "1. 檔案編碼不支援（建議使用UTF-8）\n"
                                "2. 分隔符號不標準\n"
                                "3. 檔案格式錯誤\n\n"
                                "建議：使用Excel開啟檔案後另存為標準CSV格式")
                return
            
            progress.setValue(60)
            progress.setLabelText("正在處理資料和欄位對照...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # *** 使用已修改的清理方法（包含欄位對照） ***
            df = self.clean_imported_data(df, file_path)
            
            if df is None or df.empty:
                progress.close()
                QMessageBox.warning(self, "資料為空", "匯入的CSV檔案沒有有效資料")
                return
            
            progress.setValue(80)
            progress.setLabelText("正在更新介面...")
            QApplication.processEvents()
            
            # 應用匯入的資料
            self.apply_imported_data(df, file_path, "CSV")
            
            progress.setValue(100)
            progress.close()
            
            # 顯示成功訊息
            self.show_import_success_message(df, file_path, "CSV")
            
        except Exception as e:
            if 'progress' in locals():
                progress.close()
            QMessageBox.critical(self, "匯入錯誤", f"匯入CSV檔案時發生錯誤：\n{str(e)}")

