    def preview_imported_data(self):
        """預覽匯入的資料"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "沒有可預覽的資料")
                return
            
            # 創建預覽對話框
            from PyQt6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QTableWidget, QLabel
            
            dialog = QDialog(self)
            dialog.setWindowTitle(f"資料預覽 - {self.import_source['name'] if self.import_source else '未知來源'}")
            dialog.setModal(True)
            dialog.resize(800, 600)
            
            layout = QVBoxLayout(dialog)
            
            # 預覽資訊
            info_label = QLabel(f"顯示前 100 筆資料（共 {len(self.current_data):,} 筆）")
            info_label.setStyleSheet("font-weight: bold; margin: 9px;")
            layout.addWidget(info_label)
            
            # 預覽表格
            preview_table = QTableWidget()
            preview_df = self.current_data.head(100)  # 只顯示前100筆
            
            preview_table.setRowCount(len(preview_df))
            preview_table.setColumnCount(len(preview_df.columns))
            preview_table.setHorizontalHeaderLabels([self.get_display_column_name(col) for col in preview_df.columns])
            
            for row in range(len(preview_df)):
                for col in range(len(preview_df.columns)):
                    value = preview_df.iloc[row, col]
                    display_value = str(value) if pd.notna(value) else ""
                    item = QTableWidgetItem(display_value)
                    preview_table.setItem(row, col, item)
            
            preview_table.resizeColumnsToContents()
            layout.addWidget(preview_table)
            
            # 關閉按鈕
            close_btn = QPushButton("關閉")
            close_btn.clicked.connect(dialog.accept)
            layout.addWidget(close_btn)
            
            dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"預覽資料時發生錯誤：\n{str(e)}")

    def analyze_imported_data(self):
        """分析匯入的資料"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "沒有可分析的資料")
                return
            
            # 創建分析對話框
            from PyQt6.QtWidgets import QDialog, QVBoxLayout, QTextEdit
            
            dialog = QDialog(self)
            dialog.setWindowTitle(f"資料分析 - {self.import_source['name'] if self.import_source else '未知來源'}")
            dialog.setModal(True)
            dialog.resize(600, 500)
            
            layout = QVBoxLayout(dialog)
            
            # 分析結果顯示區域
            analysis_text = QTextEdit()
            analysis_text.setReadOnly(True)
            analysis_text.setStyleSheet("""
                QTextEdit {
                    font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
                    font-size: 14px;
                    background-color: #f8f9fa;
                    border: 1px solid #dee2e6;
                }
            """)
            
            # 執行分析
            analysis_content = self.generate_data_analysis()
            analysis_text.setPlainText(analysis_content)
            
            layout.addWidget(analysis_text)
            
            # 關閉按鈕
            close_btn = QPushButton("關閉")
            close_btn.clicked.connect(dialog.accept)
            layout.addWidget(close_btn)
            
            dialog.exec()
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"分析資料時發生錯誤：\n{str(e)}")

    def generate_data_analysis(self):
        """生成資料分析報告"""
        try:
            df = self.current_data
            analysis_lines = []
            
            analysis_lines.append("=" * 50)
            analysis_lines.append("📊 資料分析報告")
            analysis_lines.append("=" * 50)
            
            # 基本資訊
            analysis_lines.append(f"\n📋 基本資訊：")
            analysis_lines.append(f"• 資料筆數：{len(df):,}")
            analysis_lines.append(f"• 欄位數量：{len(df.columns)}")
            analysis_lines.append(f"• 記憶體使用：{df.memory_usage(deep=True).sum() / 1024 / 1024:.2f} MB")
            
            # 欄位分析
            analysis_lines.append(f"\n🔍 欄位分析：")
            
            numeric_cols = df.select_dtypes(include='number').columns.tolist()
            text_cols = df.select_dtypes(include='object').columns.tolist()
            date_cols = df.select_dtypes(include='datetime').columns.tolist()
            
            analysis_lines.append(f"• 數值型欄位：{len(numeric_cols)} 個")
            if numeric_cols:
                for col in numeric_cols[:5]:  # 只顯示前5個
                    display_name = self.get_display_column_name(col)
                    non_null_count = df[col].notna().sum()
                    analysis_lines.append(f"  - {display_name}: {non_null_count:,} 筆非空值")
            
            analysis_lines.append(f"• 文字型欄位：{len(text_cols)} 個")
            if text_cols:
                for col in text_cols[:5]:  # 只顯示前5個
                    display_name = self.get_display_column_name(col)
                    non_null_count = df[col].notna().sum()
                    unique_count = df[col].nunique()
                    analysis_lines.append(f"  - {display_name}: {non_null_count:,} 筆非空值, {unique_count:,} 個唯一值")
            
            if date_cols:
                analysis_lines.append(f"• 日期型欄位：{len(date_cols)} 個")
            
            # 資料品質分析
            analysis_lines.append(f"\n🎯 資料品質分析：")
            
            # 空值分析
            null_counts = df.isnull().sum()
            null_percentages = (null_counts / len(df)) * 100
            
            analysis_lines.append(f"• 空值情況：")
            for col in df.columns:
                if null_counts[col] > 0:
                    display_name = self.get_display_column_name(col)
                    analysis_lines.append(f"  - {display_name}: {null_counts[col]:,} 個空值 ({null_percentages[col]:.1f}%)")
            
            if null_counts.sum() == 0:
                analysis_lines.append("  - 無空值")
            
            # 重複資料分析
            duplicate_count = df.duplicated().sum()
            analysis_lines.append(f"• 重複資料：{duplicate_count:,} 筆 ({duplicate_count/len(df)*100:.1f}%)")
            
            # 數值統計（只針對數值欄位）
            if numeric_cols:
                analysis_lines.append(f"\n📈 數值統計摘要：")
                for col in numeric_cols[:3]:  # 只顯示前3個數值欄位
                    display_name = self.get_display_column_name(col)
                    series = df[col].dropna()
                    if len(series) > 0:
                        analysis_lines.append(f"• {display_name}:")
                        analysis_lines.append(f"  - 平均值：{series.mean():.2f}")
                        analysis_lines.append(f"  - 中位數：{series.median():.2f}")
                        analysis_lines.append(f"  - 最小值：{series.min():.2f}")
                        analysis_lines.append(f"  - 最大值：{series.max():.2f}")
                        analysis_lines.append(f"  - 標準差：{series.std():.2f}")
            
            # 建議
            analysis_lines.append(f"\n💡 建議：")
            
            if duplicate_count > 0:
                analysis_lines.append("• 考慮移除重複資料以提高資料品質")
            
            if null_counts.sum() > 0:
                analysis_lines.append("• 處理空值：可考慮填補或移除")
            
            if len(text_cols) > 0:
                analysis_lines.append("• 文字欄位可用於分組和篩選")
            
            if len(numeric_cols) > 0:
                analysis_lines.append("• 數值欄位適合用於圖表和統計分析")
            
            analysis_lines.append("• 使用篩選功能探索特定資料範圍")
            analysis_lines.append("• 使用重命名功能讓欄位名稱更易理解")
            analysis_lines.append("• 建立樞紐表進行資料分析")
            
            return "\n".join(analysis_lines)
            
        except Exception as e:
            return f"分析過程中發生錯誤：{str(e)}"

    def update_rename_status(self):
        """更新重命名狀態顯示 - 顯示詳細重命名資訊版本"""
        if not hasattr(self, 'rename_status_label'):
            return
            
        if not hasattr(self, 'column_rename_mapping'):
            self.column_rename_mapping = {}
        
        if not self.column_rename_mapping:
            self.rename_status_label.setText("📋 目前未重命名任何欄位")
            self.rename_status_label.setStyleSheet("""
                QLabel {
                    color: #2c3e50;
                    font-size: 13px;
                    font-weight: bold;
                    padding: 6px 11px;
                    background-color: #ecf0f1;
                    border: 1px solid #bdc3c7;
                    border-radius: 4px;
                    line-height: 1.4;
                    min-height: 75px;
                    max-height: 75px;
                }
            """)
        else:
            renamed_count = len(self.column_rename_mapping)
            
            # 建立詳細的重命名資訊文字
            status_lines = [f"📋 已重命名 {renamed_count} 個欄位："]
            
            # 加入每個重命名的詳細資訊
            for i, (original_name, display_name) in enumerate(self.column_rename_mapping.items(), 1):
                # 限制欄位名稱長度，避免顯示過長
                original_short = original_name[:15] + "..." if len(original_name) > 15 else original_name
                display_short = display_name[:15] + "..." if len(display_name) > 15 else display_name
                
                status_lines.append(f"  {i}. {original_short} → {display_short}")
                
                # 如果重命名項目太多，只顯示前3個，其餘顯示省略
                if i >= 3 and renamed_count > 3:
                    remaining = renamed_count - 3
                    status_lines.append(f"  ... 還有 {remaining} 個重命名項目")
                    break
        
        # 將所有行合併成一個字串
        status_text = "\n".join(status_lines)
        
        self.rename_status_label.setText(status_text)
        self.rename_status_label.setStyleSheet("""
            QLabel {
                color: #2c3e50;
                font-size: 13px;
                font-weight: bold;
                padding: 6px 11px;
                background-color: #d5edda;
                border: 1px solid #27ae60;
                border-radius: 4px;
                line-height: 1.4;
                font-family: "Consolas", "Monaco", "Courier New", monospace;
            }
        """)
        
        # 設定工具提示顯示完整資訊
        if renamed_count > 5:
            tooltip_lines = [f"完整重命名清單 ({renamed_count} 個)："]
            for i, (original_name, display_name) in enumerate(self.column_rename_mapping.items(), 1):
                tooltip_lines.append(f"{i}. {original_name} → {display_name}")
            tooltip_text = "\n".join(tooltip_lines)
            self.rename_status_label.setToolTip(tooltip_text)
        else:
            self.rename_status_label.setToolTip("")

    def get_rename_summary_text(self):
        """取得重命名摘要文字 - 輔助方法"""
        if not hasattr(self, 'column_rename_mapping') or not self.column_rename_mapping:
            return "目前沒有重命名的欄位"
        
        summary_lines = []
        for original, display in self.column_rename_mapping.items():
            summary_lines.append(f"• {original} → {display}")
        
        return "\n".join(summary_lines)

