    def update_rename_controls(self):
        """更新重命名控制項"""
        if self.current_data is None or self.current_data.empty:
            return
        
        # 更新欄位選擇下拉選單
        self.rename_column_combo.clear()
        self.rename_column_combo.addItems(self.current_data.columns.tolist())

    def sync_rename_to_controls(self):
        """同步欄位重命名到篩選和樞紐分析控制項"""
        try:
            if self.current_data is None or self.current_data.empty:
                return
            
            print("正在同步欄位重命名到相關控制項...")
            
            # 1. 更新篩選控制項
            self.update_filter_controls_with_rename()
            
            # 2. 更新樞紐分析控制項
            self.update_pivot_fields_with_rename()
            
            # 3. 更新重命名控制項本身
            self.update_rename_controls_with_display_names()
            
            print("欄位重命名同步完成")
            
        except Exception as e:
            print(f"同步欄位重命名時發生錯誤：{e}")

    # 新增方法：使用顯示名稱建立篩選控制項
    def setup_filter_widgets_with_display_names(self, df):
        """設定篩選控制元件 - 使用顯示名稱版本"""
        if not hasattr(self, 'filter_container_layout'):
            print("篩選容器未初始化")
            return
            
        # 清除現有篩選控制元件
        for i in reversed(range(self.filter_container_layout.count())):
            child = self.filter_container_layout.itemAt(i)
            if child and child.widget():
                child.widget().setParent(None)
        
        if not hasattr(self, 'filter_vars'):
            self.filter_vars = {}
        if not hasattr(self, 'filter_entries'):
            self.filter_entries = {}
        if not hasattr(self, 'filter_operators'):
            self.filter_operators = {}
            
        self.filter_vars.clear()
        self.filter_entries.clear()
        self.filter_operators.clear()
        
        # 改為每行顯示更多欄位以節省空間
        cols_per_row = 4
        
        for i, original_col in enumerate(df.columns):
            # *** 關鍵修改：使用顯示名稱 ***
            display_col = self.get_display_column_name(original_col)
            
            row = i // cols_per_row
            col_group = i % cols_per_row
            
            # 每個欄位組佔用3列：標籤、運算子、輸入框
            base_row = row * 4  # 每組之間留一行空隙
            base_col = col_group * 3  # 每組佔用3列
            
            # 欄位標籤 - 顯示重命名後的名稱
            label = QLabel(f"{display_col}:")
            label.setStyleSheet("""
                QLabel {
                    font-weight: bold; 
                    font-size: 14px;  
                    color: #2c3e50;
                    padding: 2px;    
                    background-color: #ecf0f1;
                    border: 1px solid #bdc3c7;
                    border-radius: 3px;  
                    min-width: 60px;     
                    max-width: 100px;    
                }
            """)
            label.setWordWrap(True)
            label.setToolTip(f"原始欄位：{original_col}")  # 顯示原始名稱作為提示
            self.filter_container_layout.addWidget(label, base_row, base_col, 1, 1)
            
            # 運算子選擇下拉選單
            op_combo = QComboBox()
            op_combo.addItems(['=', '!=', '>', '<', '>=', '<=', 'contains', 'not contains'])
            op_combo.setCurrentText('=')
            op_combo.setStyleSheet("""
                QComboBox {
                    border: 1px solid #bdc3c7;
                    border-radius: 3px;  
                    padding: 2px 4px;    
                    font-size: 13px;    
                    min-width: 40px;   
                    min-height: 20px;    
                    background-color: white;
                }
                QComboBox:hover {
                    border: 2px solid #3498db;
                }
            """)
            self.filter_container_layout.addWidget(op_combo, base_row + 1, base_col, 1, 1)
            
            # 篩選值輸入框
            entry = QLineEdit()
            entry.setPlaceholderText(f"篩選 {display_col[:6]}...")  # 使用顯示名稱
            entry.setStyleSheet("""
                QLineEdit {
                    border: 1px solid #95a5a6;
                    border-radius: 3px; 
                    padding: 2px 4px;   
                    font-size: 13px;     
                    min-width: 50px;   
                    min-height: 20px;   
                    background-color: white;
                }
                QLineEdit:focus {
                    border: 2px solid #3498db;
                }
            """)
            self.filter_container_layout.addWidget(entry, base_row + 2, base_col, 1, 1)
            
            # *** 關鍵修改：使用原始欄位名稱作為key，但顯示重命名後的名稱 ***
            self.filter_vars[original_col] = entry  # 使用原始名稱作為key
            self.filter_entries[original_col] = entry
            self.filter_operators[original_col] = op_combo
        
        # 添加底部間距
        spacer = QWidget()
        spacer.setMinimumHeight(14) 
        self.filter_container_layout.addWidget(spacer, (len(df.columns) // cols_per_row + 1) * 4, 0, 1, -1)
            
    def on_rename_completed(self):
        """重命名操作完成後的回調"""
        try:
            print("🔄 重命名完成，更新所有相關控制項...")
            
            # 獲取當前資料
            if hasattr(self, 'current_data') and self.current_data is not None:
                # 更新所有控制項
                self._safe_update_all_controls(self.current_data)
                
                # 特別確保樞紐分析欄位已更新
                self.update_pivot_fields_with_rename()
                
                print("✅ 重命名後控制項更新完成")
            else:
                print("⚠️ 重命名完成但無當前資料")
                
        except Exception as e:
            print(f"❌ 重命名完成後更新錯誤: {e}")
            
    def on_rename_button_clicked(self):
        """重命名按鈕點擊事件 - 修正版"""
        try:
            if not hasattr(self, 'rename_column_combo') or not hasattr(self, 'new_name_edit'):
                QMessageBox.warning(self, "警告", "重命名控制項未初始化！")
                return
            
            old_name = self.rename_column_combo.currentText()
            new_name = self.new_name_edit.text().strip()
            
            if not old_name:
                QMessageBox.warning(self, "警告", "請選擇要重命名的欄位！")
                return
            
            if not new_name:
                QMessageBox.warning(self, "警告", "請輸入新的欄位名稱！")
                return
            
            if not hasattr(self, 'current_data') or self.current_data is None:
                QMessageBox.warning(self, "警告", "沒有可用的資料進行重命名！")
                return
            
            # 執行重命名
            if old_name in self.current_data.columns:
                # 建立新的 DataFrame 避免修改原始資料
                self.current_data = self.current_data.rename(columns={old_name: new_name})
                
                # 同時更新 original_data
                if hasattr(self, 'original_data') and self.original_data is not None:
                    if isinstance(self.original_data, pd.DataFrame) and old_name in self.original_data.columns:
                        self.original_data = self.original_data.rename(columns={old_name: new_name})
                
                print(f"✅ 欄位重命名成功: '{old_name}' → '{new_name}'")
                
                # 執行重命名後的更新
                self.on_rename_completed()
                
                # 清空輸入框
                self.new_name_edit.clear()
                
                # 顯示成功訊息
                QMessageBox.information(self, "成功", f"欄位 '{old_name}' 已重命名為 '{new_name}'")
                
            else:
                QMessageBox.warning(self, "警告", f"找不到欄位 '{old_name}'！")
                
        except Exception as e:
            error_msg = f"重命名欄位時發生錯誤：{str(e)}"
            print(f"❌ {error_msg}")
            QMessageBox.critical(self, "錯誤", error_msg)

    def get_display_column_names(self):
        """取得所有欄位的顯示名稱列表"""
        if self.current_data is None:
            return []
        return [self.get_display_column_name(col) for col in self.current_data.columns]

    def update_result_table_with_rename(self, df):
        """更新結果表格 - 包含重命名功能，整數格式化版本"""
        if not hasattr(self, 'result_table'):
            print("結果表格未初始化")
            return
            
        self.result_table.clear()
        self.result_table.setRowCount(len(df))
        self.result_table.setColumnCount(len(df.columns))
        
        # 使用顯示名稱設定表頭
        display_names = []
        for original_col in df.columns:
            display_name = self.get_display_column_name(original_col)
            display_names.append(display_name)
        
        self.result_table.setHorizontalHeaderLabels(display_names)
        
        # *** 優化數值格式化 ***
        for row in range(len(df)):
            for col in range(len(df.columns)):
                value = df.iloc[row, col]
                
                # 使用統一的數值格式化方法
                if pd.isna(value):
                    display_value = ""
                elif isinstance(value, (int, float)):
                    display_value = self._format_table_value(value)
                else:
                    display_value = str(value)
                
                item = QTableWidgetItem(display_value)
                self.result_table.setItem(row, col, item)
        
        # 更新重命名控制項
        self.update_rename_controls()

