    def export_to_excel_with_renamed_columns(self):
        """匯出到Excel - 使用重命名後的欄位名稱 (修正版)"""
        if self.current_data is None or self.current_data.empty:
            QMessageBox.warning(self, "警告", "沒有可匯出的資料!")
            return
        
        try:
            import os
            from PyQt6.QtWidgets import QProgressDialog
            
            # 檢查必要套件
            try:
                import openpyxl
            except ImportError:
                try:
                    import xlsxwriter
                except ImportError:
                    reply = QMessageBox.question(
                        self, "缺少Excel套件", 
                        "系統缺少Excel處理套件。\n\n"
                        "請選擇：\n"
                        "- 是：匯出為CSV格式\n"
                        "- 否：取消匯出\n\n"
                        "如需匯出Excel格式，請先安裝套件：\n"
                        "pip install openpyxl",
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                    )
                    if reply == QMessageBox.StandardButton.No:
                        return
                    # 如果選擇是，後續會強制使用CSV格式
            
            # 設定預設儲存路徑為桌面
            desktop_path = os.path.join(os.path.expanduser("~"), "Desktop")
            default_filename = f"查詢結果_{pd.Timestamp.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
            
            # 開啟檔案對話框
            file_path, selected_filter = QFileDialog.getSaveFileName(
                self, 
                "匯出資料", 
                os.path.join(desktop_path, default_filename),
                "Excel 文件 (*.xlsx);;CSV 文件 (*.csv);;所有檔案 (*.*)"
            )
            
            if not file_path:
                return
            
            # 創建進度對話框
            progress = QProgressDialog("正在準備匯出...", "取消", 0, 100, self)
            progress.setWindowTitle("匯出進度")
            progress.setWindowModality(Qt.WindowModality.WindowModal)
            progress.setAutoClose(True)
            progress.setAutoReset(True)
            progress.show()
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            progress.setValue(20)
            progress.setLabelText("正在檢查檔案...")
            QApplication.processEvents()
            
            # 檢查檔案是否被其他程式開啟
            if os.path.exists(file_path):
                try:
                    # 更安全的檔案檢查方式
                    with open(file_path, 'a') as f:
                        pass
                except (OSError, PermissionError):
                    progress.close()
                    QMessageBox.critical(self, "檔案被佔用", 
                                    f"檔案 {os.path.basename(file_path)} 正被其他程式開啟，請關閉後重試")
                    return
            
            progress.setValue(40)
            progress.setLabelText("正在準備資料...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 創建包含重命名欄位的DataFrame副本（套用結果表格當前可見欄位）
            export_df = self.current_data.copy()
            try:
                if hasattr(self, 'result_table') and self.result_table.columnCount() > 0:
                    _tbl = self.result_table
                    _vis = [_tbl.horizontalHeaderItem(c).text()
                            for c in range(_tbl.columnCount())
                            if _tbl.horizontalHeaderItem(c)]
                    _avail = [c for c in _vis if c in export_df.columns]
                    if _avail:
                        export_df = export_df[_avail]
            except Exception:
                pass
            
            # 初始化欄位重命名映射（如果不存在）
            if not hasattr(self, 'column_rename_mapping'):
                self.column_rename_mapping = {}
            
            # 應用欄位重命名
            if self.column_rename_mapping:
                export_df = export_df.rename(columns=self.column_rename_mapping)
                progress.setLabelText(f"已應用 {len(self.column_rename_mapping)} 個欄位重命名...")
            
            progress.setValue(60)
            progress.setLabelText("正在寫入檔案...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 根據副檔名或套件可用性選擇匯出方式
            file_type = ""
            
            # 強制CSV格式（如果沒有Excel套件）
            force_csv = False
            try:
                import openpyxl
            except ImportError:
                try:
                    import xlsxwriter
                except ImportError:
                    force_csv = True
            
            if file_path.lower().endswith('.csv') or force_csv:
                # 匯出為CSV
                if force_csv and not file_path.lower().endswith('.csv'):
                    file_path = os.path.splitext(file_path)[0] + '.csv'
                
                export_df.to_csv(file_path, index=False, encoding='utf-8-sig')
                file_type = "CSV"
                
            else:
                # 確保副檔名為xlsx
                if not file_path.lower().endswith('.xlsx'):
                    file_path += '.xlsx'
                
                # 匯出為Excel
                excel_exported = False
                
                # 嘗試使用openpyxl
                if not excel_exported:
                    try:
                        export_df.to_excel(file_path, index=False, engine='openpyxl')
                        file_type = "Excel (openpyxl)"
                        excel_exported = True
                    except ImportError:
                        pass
                    except Exception as e:
                        print(f"openpyxl匯出失敗：{e}")
                
                # 如果openpyxl失敗，嘗試使用xlsxwriter
                if not excel_exported:
                    try:
                        export_df.to_excel(file_path, index=False, engine='xlsxwriter')
                        file_type = "Excel (xlsxwriter)"
                        excel_exported = True
                    except ImportError:
                        pass
                    except Exception as e:
                        print(f"xlsxwriter匯出失敗：{e}")
                
                # 如果都失敗，回退到CSV
                if not excel_exported:
                    csv_path = os.path.splitext(file_path)[0] + '.csv'
                    export_df.to_csv(csv_path, index=False, encoding='utf-8-sig')
                    file_path = csv_path
                    file_type = "CSV (Excel套件不可用)"
            
            progress.setValue(90)
            progress.setLabelText("完成匯出...")
            QApplication.processEvents()
            
            progress.setValue(100)
            progress.close()
            QApplication.processEvents()
            
            # 顯示成功訊息
            renamed_info = ""
            if self.column_rename_mapping:
                renamed_info = f"\n\n已套用 {len(self.column_rename_mapping)} 個欄位重命名"
            
            QMessageBox.information(self, "匯出成功", 
                                f"資料已成功匯出為{file_type}檔案:\n{os.path.basename(file_path)}\n\n"
                                f"儲存位置: {os.path.dirname(file_path)}\n"
                                f"共 {len(export_df)} 筆資料、{len(export_df.columns)} 個欄位{renamed_info}")
            
        except PermissionError as e:
            if 'progress' in locals():
                progress.close()
            QMessageBox.critical(self, "權限錯誤", 
                            f"無法寫入檔案，請檢查:\n"
                            f"1. 檔案路徑是否有寫入權限\n"
                            f"2. 檔案是否正被其他程式開啟\n"
                            f"3. 磁碟空間是否足夠\n\n錯誤詳情：{str(e)}")
        except FileNotFoundError as e:
            if 'progress' in locals():
                progress.close()
            QMessageBox.critical(self, "路徑錯誤", 
                            f"指定的檔案路徑不存在，請選擇有效的儲存位置\n\n錯誤詳情：{str(e)}")
        except Exception as e:
            if 'progress' in locals():
                progress.close()
            error_details = str(e)
            QMessageBox.critical(self, "匯出錯誤", 
                            f"匯出時發生未預期的錯誤:\n{error_details}\n\n"
                            f"請檢查:\n"
                            f"1. 資料格式是否正確\n"
                            f"2. 系統是否有足夠權限\n"
                            f"3. 檔案路徑是否有效")
            
            # 記錄詳細錯誤到控制台（便於除錯）
            import traceback
            print("匯出錯誤的詳細資訊：")
            print(traceback.format_exc())

    def export_chart_to_svg(self):
        """匯出圖表為SVG - 增強版"""
        if not hasattr(self, 'current_figure') or self.current_figure is None:
            QMessageBox.critical(self, "錯誤", "請先生成圖表!")
            return
        
        try:
            import os
            
            # 設定預設儲存路徑為桌面
            desktop_path = os.path.join(os.path.expanduser("~"), "Desktop")
            default_filename = f"圖表_{pd.Timestamp.now().strftime('%Y%m%d_%H%M%S')}.svg"
            
            file_path, _ = QFileDialog.getSaveFileName(
                self, 
                "匯出圖表為SVG", 
                os.path.join(desktop_path, default_filename),
                "SVG 檔案 (*.svg);;PDF 檔案 (*.pdf);;PNG 檔案 (*.png);;所有檔案 (*.*)"
            )
            
            if not file_path:
                return
            
            # 根據選擇的格式設定副檔名和參數
            if file_path.lower().endswith('.pdf'):
                format_type = 'pdf'
                if not file_path.lower().endswith('.pdf'):
                    file_path += '.pdf'
            elif file_path.lower().endswith('.png'):
                format_type = 'png'
                if not file_path.lower().endswith('.png'):
                    file_path += '.png'
            else:
                format_type = 'svg'
                if not file_path.lower().endswith('.svg'):
                    file_path += '.svg'
            
            # 儲存圖表
            save_params = {
                'format': format_type,
                'bbox_inches': 'tight',
                'dpi': 300 if format_type == 'png' else None,
                'facecolor': 'white',
                'edgecolor': 'none'
            }
            
            # 移除None值參數
            save_params = {k: v for k, v in save_params.items() if v is not None}
            
            self.current_figure.savefig(file_path, **save_params)
            
            QMessageBox.information(self, "匯出成功", 
                                f"圖表已成功匯出為 {format_type.upper()} 檔案:\n"
                                f"{os.path.basename(file_path)}\n\n"
                                f"儲存位置: {os.path.dirname(file_path)}")
            
        except Exception as e:
            QMessageBox.critical(self, "匯出錯誤", f"匯出圖表時發生錯誤:\n{str(e)}")

    def export_pivot_to_excel(self):
        """匯出樞紐表到Excel - 修正重命名問題版本"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.critical(self, "錯誤", "沒有資料可匯出!")
                return
            
            # 獲取顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            
            if not index_display:
                QMessageBox.critical(self, "錯誤", "請選擇列(Index)欄位!")
                return
            
            if not values_display:
                QMessageBox.critical(self, "錯誤", "請至少選擇一個值(Values)欄位!")
                return
            
            # *** 修正關鍵：轉換為原始名稱 ***
            index = self._get_original_column_name(index_display)
            columns = self._get_original_column_name(columns_display) if columns_display else None
            values = [self._get_original_column_name(val) for val in values_display if val]
            
            print(f"匯出樞紐表 - 顯示名稱: index={index_display}, columns={columns_display}, values={values_display}")
            print(f"匯出樞紐表 - 原始名稱: index={index}, columns={columns}, values={values}")
            
            # 創建進度對話框
            from PyQt6.QtWidgets import QProgressDialog
            progress = QProgressDialog("正在生成樞紐表...", "取消", 0, 100, self)
            progress.setWindowTitle("匯出樞紐表")
            progress.setWindowModality(Qt.WindowModality.WindowModal)
            progress.show()
            QApplication.processEvents()
            
            # 確保數值型（使用原始名稱）
            df_copy = self.current_data.copy()
            for val in values:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            progress.setValue(30)
            progress.setLabelText("正在計算樞紐表...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 生成樞紐表（使用原始名稱）
            pivot_params = {
                'values': values,
                'index': index,
                'aggfunc': aggfunc,
                'fill_value': 0
            }
            
            if columns:
                pivot_params['columns'] = columns
            
            pivot_table = pd.pivot_table(df_copy, **pivot_params)
            
            # *** 重要修正：將樞紐表的欄位名稱改為顯示名稱 ***
            # 1. 處理索引名稱
            if pivot_table.index.name:
                pivot_table.index.name = index_display
            
            # 2. 處理欄位名稱
            if isinstance(pivot_table.columns, pd.MultiIndex):
                # 多層索引情況
                new_columns = []
                for col in pivot_table.columns:
                    if len(col) >= 2:
                        # 找到對應的顯示名稱
                        val_display = self.get_display_column_name(col[0])
                        new_columns.append((val_display, col[1]))
                    else:
                        new_columns.append(col)
                pivot_table.columns = pd.MultiIndex.from_tuples(new_columns)
                
                # 設定欄位名稱
                if columns_display:
                    pivot_table.columns.names = [None, columns_display]
            else:
                # 單層索引情況
                new_column_names = []
                for col in pivot_table.columns:
                    display_name = self.get_display_column_name(col)
                    new_column_names.append(display_name)
                pivot_table.columns = new_column_names
            
            progress.setValue(60)
            progress.setLabelText("正在準備匯出...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 設定檔案路徑
            import os
            desktop_path = os.path.join(os.path.expanduser("~"), "Desktop")
            default_filename = f"樞紐表_{pd.Timestamp.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
            
            file_path, _ = QFileDialog.getSaveFileName(
                self, 
                "匯出樞紐表到Excel", 
                os.path.join(desktop_path, default_filename),
                "Excel 檔案 (*.xlsx);;CSV 檔案 (*.csv);;所有檔案 (*.*)"
            )
            
            if not file_path:
                progress.close()
                return
            
            progress.setValue(80)
            progress.setLabelText("正在寫入檔案...")
            QApplication.processEvents()
            
            if progress.wasCanceled():
                return
            
            # 匯出檔案
            if file_path.lower().endswith('.csv'):
                pivot_table.to_csv(file_path, encoding='utf-8-sig')
                file_type = "CSV"
            else:
                if not file_path.lower().endswith('.xlsx'):
                    file_path += '.xlsx'
                pivot_table.to_excel(file_path, engine='openpyxl')
                file_type = "Excel"
            
            progress.setValue(100)
            progress.close()
            QApplication.processEvents()
            
            # 準備摘要資訊（使用顯示名稱）
            summary_info = f"樞紐表設定:\n"
            summary_info += f"• 列(Index): {index_display}\n"
            if columns_display:
                summary_info += f"• 欄(Columns): {columns_display}\n"
            summary_info += f"• 值(Values): {', '.join(values_display)}\n"
            summary_info += f"• 聚合函數: {aggfunc}\n"
            summary_info += f"• 資料維度: {pivot_table.shape[0]} 列 x {pivot_table.shape[1]} 欄"
            
            QMessageBox.information(self, "匯出成功", 
                                f"樞紐表已成功匯出為{file_type}檔案:\n"
                                f"{os.path.basename(file_path)}\n\n"
                                f"儲存位置: {os.path.dirname(file_path)}\n\n{summary_info}")
            
        except Exception as e:
            if 'progress' in locals():
                progress.close()
            QMessageBox.critical(self, "匯出錯誤", f"匯出樞紐表時發生錯誤:\n{str(e)}")

    # 7. 新增輔助方法
    def get_selected_values_with_display_names(self):
        """取得選擇的值欄位 - 返回顯示名稱和原始名稱的配對"""
        display_values = self.get_selected_values()
        return {
            'display': display_values,
            'original': [self._get_original_column_name(val) for val in display_values if val]
        }

