    def add_color(self, color):
        """添加顏色"""
        if color not in self.chart_colors:
            self.chart_colors.append(color)
            self.update_selected_colors_display()

    def choose_custom_color(self):
        """選擇自定義顏色"""
        color = QColorDialog.getColor()
        if color.isValid():
            self.add_color(color.name())

    def clear_colors(self):
        """清除顏色"""
        self.chart_colors = []
        self.update_selected_colors_display()

    def update_selected_colors_display(self):
        """更新已選擇顏色顯示"""
        if not self.chart_colors:
            self.selected_colors_label.setText("未選擇顏色 (將使用默認顏色)")
        else:
            self.selected_colors_label.setText(", ".join(self.chart_colors))

    def apply_seaborn_style(self):
        """應用Seaborn風格"""
        try:
            style = self.style_combo.currentText()
            context = self.context_combo.currentText()
            palette = self.palette_combo.currentText()
            
            sns.set_style(style)
            sns.set_context(context)
            sns.set_palette(palette)
            
            set_chinese_font()
            
            if self.current_figure:
                self.display_chart(self.current_figure)
                QMessageBox.information(self, "已更新", f"已應用 Seaborn {style} 風格、{context} 上下文和 {palette} 調色盤")
            else:
                QMessageBox.information(self, "已設定", f"已設定 Seaborn {style} 風格、{context} 上下文和 {palette} 調色盤，將應用於下一個圖表")
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"應用 Seaborn 風格時發生錯誤: {str(e)}")

    def _convert_pivot_table_to_display_names(self, pivot_table, index_display, columns_display, values_display):
        """將樞紐表的欄位名稱轉換為顯示名稱 - 修正版：保持值欄位順序"""
        try:
            print("🔄 開始轉換樞紐表欄位名稱為顯示名稱（保持順序）...")
            
            # 複製樞紐表
            display_pivot_table = pivot_table.copy()
            
            # 1. 處理索引名稱
            if display_pivot_table.index.name:
                display_pivot_table.index.name = index_display
                print(f"   ✅ 索引名稱: {pivot_table.index.name} -> {index_display}")
            
            # 2. 處理欄位名稱
            if isinstance(display_pivot_table.columns, pd.MultiIndex):
                # 多層索引情況（有 columns 分組）
                print("   🔢 處理多層索引欄位（保持值1、值2、值3順序）...")
                
                # *** 關鍵修正：按照values_display的順序重新排列 ***
                new_columns = []
                
                # 按照values_display的順序處理每個值欄位
                for i, val_display in enumerate(values_display):
                    original_val = self._get_original_column_name(val_display)
                    
                    # 找到所有包含此值欄位的欄位組合
                    for col in display_pivot_table.columns:
                        if len(col) >= 2:
                            col_value_name = col[0]
                            group_value = col[1]
                            
                            # 檢查是否匹配當前的值欄位
                            if (col_value_name == original_val or 
                                col_value_name == val_display):
                                
                                new_columns.append((val_display, group_value))
                                print(f"   ✅ 排序欄位 {i+1}: {col} -> {(val_display, group_value)}")
                
                # 處理任何遺漏的欄位
                for col in display_pivot_table.columns:
                    if col not in [(new_col[0], new_col[1]) for new_col in new_columns]:
                        # 嘗試找到對應的顯示名稱
                        if len(col) >= 2:
                            original_value_name = col[0]
                            group_value = col[1]
                            
                            # 找到對應的顯示名稱
                            value_display_name = None
                            for val_display in values_display:
                                original_val = self._get_original_column_name(val_display)
                                if original_val == original_value_name:
                                    value_display_name = val_display
                                    break
                            
                            if value_display_name:
                                new_columns.append((value_display_name, group_value))
                            else:
                                new_columns.append(col)
                            print(f"   ⚠️ 補充遺漏欄位: {col}")
                
                # 設定新的多層索引（保持順序）
                display_pivot_table.columns = pd.MultiIndex.from_tuples(new_columns)
                
                # 設定欄位名稱
                if columns_display:
                    display_pivot_table.columns.names = [None, columns_display]
                    print(f"   ✅ 多層欄位名稱設定: [None, {columns_display}]")
                        
            else:
                # 單層索引情況
                print("   📝 處理單層索引欄位（保持值1、值2、值3順序）...")
                
                # *** 關鍵修正：按照values_display的順序重新排列欄位 ***
                new_column_names = []
                
                # 首先按照values_display的順序添加欄位
                for val_display in values_display:
                    original_val = self._get_original_column_name(val_display)
                    
                    # 檢查原始欄位名或顯示欄位名是否在樞紐表中
                    if original_val in display_pivot_table.columns:
                        new_column_names.append(val_display)
                        print(f"   ✅ 順序欄位: {original_val} -> {val_display}")
                    elif val_display in display_pivot_table.columns:
                        new_column_names.append(val_display)
                        print(f"   ✅ 順序欄位: {val_display} (已是顯示名稱)")
                
                # 處理任何遺漏的欄位
                for col in display_pivot_table.columns:
                    # 找到對應的顯示名稱
                    display_name = None
                    for val_display in values_display:
                        original_val = self._get_original_column_name(val_display)
                        if original_val == col:
                            display_name = val_display
                            break
                    
                    if display_name and display_name not in new_column_names:
                        new_column_names.append(display_name)
                        print(f"   ✅ 補充欄位: {col} -> {display_name}")
                    elif not display_name and col not in new_column_names:
                        new_column_names.append(col)
                        print(f"   ⚠️ 保持原名: {col}")
                
                # 重新排序樞紐表欄位
                if new_column_names:
                    # 建立新舊欄位名稱的對應關係
                    column_mapping = {}
                    for old_col in display_pivot_table.columns:
                        for val_display in values_display:
                            original_val = self._get_original_column_name(val_display)
                            if old_col == original_val or old_col == val_display:
                                column_mapping[old_col] = val_display
                                break
                        if old_col not in column_mapping:
                            column_mapping[old_col] = old_col
                    
                    # 重新命名欄位
                    display_pivot_table = display_pivot_table.rename(columns=column_mapping)
                    
                    # 按照新順序重新排列欄位
                    final_columns = []
                    for new_col in new_column_names:
                        if new_col in display_pivot_table.columns:
                            final_columns.append(new_col)
                    
                    if final_columns:
                        display_pivot_table = display_pivot_table[final_columns]
                        print(f"   ✅ 欄位已按值1、值2、值3順序重新排列: {final_columns}")
            
            print("🎉 樞紐表欄位名稱轉換完成（順序已修正）")
            print(f"   最終欄位順序: {list(display_pivot_table.columns)}")
            return display_pivot_table
            
        except Exception as e:
            print(f"❌ 轉換樞紐表欄位名稱時發生錯誤: {e}")
            import traceback
            traceback.print_exc()
            return pivot_table  # 返回原始樞紐表

