    def generate_pivot_table(self):
        """修正版：生成並顯示樞紐表 - 確保合計計算正確"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "請先執行 SQL 查詢以取得資料！")
                return None
            
            # 取得顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            
            print(f"🔍 生成樞紐表 - 顯示名稱:")
            print(f"   Index: {index_display}")
            print(f"   Columns: {columns_display}")
            print(f"   Values: {values_display}")
            print(f"   聚合函數: {aggfunc}")
            
            # 基本驗證
            if not index_display or not values_display:
                QMessageBox.critical(self, "錯誤", "請選擇列(Index)欄位和至少一個值(Values)欄位！")
                return None
            
            # 創建基礎樞紐表（不含合計）
            pivot_table = self.create_pivot_table_without_total()
            if pivot_table is None:
                return None
            
            print(f"✅ 基礎樞紐表創建完成: {pivot_table.shape}")
            
            # 計算正確的合計行
            pivot_table_with_total = self._add_correct_total_row(pivot_table, aggfunc)
            
            # 轉換欄位名稱並顯示
            display_pivot_table = self._convert_pivot_table_to_display_names(
                pivot_table_with_total, index_display, columns_display, values_display
            )
            
            format_type = self.format_combo.currentText()
            self._display_pivot_table_in_chart_area_final(display_pivot_table, 
                                                index_display, columns_display, 
                                                values_display, aggfunc, format_type)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
            print(f"🎉 樞紐表生成並顯示完成")
            return display_pivot_table
            
        except Exception as e:
            error_msg = f"生成樞紐表時發生錯誤: {str(e)}"
            print(f"❌ {error_msg}")
            import traceback
            print("詳細錯誤追蹤:")
            print(traceback.format_exc())
            QMessageBox.critical(self, "樞紐表生成錯誤", error_msg)
            return None

    def create_pivot_table_without_total(self):
        """創建不含合計行的基礎樞紐表 - 修正版：確保值欄位順序正確"""
        try:
            # 轉換為原始欄位名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()  # 這裡會按照值1、值2、值3順序返回
            aggfunc = self.aggfunc_combo.currentText()
            
            index_col = self._get_original_column_name(index_display)
            columns_col = self._get_original_column_name(columns_display) if columns_display else None
            values_cols = [self._get_original_column_name(val) for val in values_display if val]
            
            print(f"🔄 樞紐表欄位順序確認:")
            print(f"   Index: {index_display} -> {index_col}")
            print(f"   Columns: {columns_display} -> {columns_col}")
            print(f"   Values (按順序): {values_display} -> {values_cols}")
            
            # 驗證欄位存在
            missing_fields = []
            if index_col not in self.current_data.columns:
                missing_fields.append(f"Index欄位 '{index_col}' (顯示: {index_display})")
            if columns_col and columns_col not in self.current_data.columns:
                missing_fields.append(f"Columns欄位 '{columns_col}' (顯示: {columns_display})")
            for i, val in enumerate(values_cols):
                if val not in self.current_data.columns:
                    missing_fields.append(f"Values欄位 '{val}' (顯示: {values_display[i]})")
            
            if missing_fields:
                error_msg = "以下欄位在資料中不存在:\n" + "\n".join(missing_fields)
                print(f"❌ {error_msg}")
                return None
            
            # 處理資料
            df_copy = self.current_data.copy()
            
            # 轉換數值欄位，保留原始 NaN 結構
            for val in values_cols:
                print(f"處理數值欄位 {val}...")
                original_dtype = df_copy[val].dtype
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
                non_null_count = df_copy[val].notna().sum()
                print(f"   轉換: {original_dtype} -> 數值型，有效值: {non_null_count}")
            
            # 只移除所有值欄位都是 NaN 的行
            all_values_null = True
            for val in values_cols:
                all_values_null = all_values_null & df_copy[val].isna()
            
            df_filtered = df_copy[~all_values_null]
            
            print(f"📊 數據處理結果:")
            print(f"   原始筆數: {len(df_copy)}")
            print(f"   過濾後筆數: {len(df_filtered)}")
            
            if df_filtered.empty:
                print("❌ 過濾後沒有有效資料")
                return None
            
            # *** 關鍵修正：確保values參數按照正確順序傳遞 ***
            pivot_params = {
                'values': values_cols,  # 這裡values_cols已經按照值1、值2、值3的順序
                'index': index_col,
                'aggfunc': aggfunc,
                'fill_value': 0,  # 使用0而非None，便於計算
                'margins': False,  # 明確禁用自動合計
                'margins_name': 'Total'
            }
            
            if columns_col:
                pivot_params['columns'] = columns_col
            
            print(f"📋 樞紐表參數 (按順序): {pivot_params}")
            
            # 創建樞紐表
            pivot_table = pd.pivot_table(df_filtered, **pivot_params)
            
            # *** 額外確保：如果是多層索引，重新排序欄位 ***
            if isinstance(pivot_table.columns, pd.MultiIndex):
                print("🔧 檢查多層索引欄位順序...")
                
                # 獲取所有層級
                level_0_values = pivot_table.columns.levels[0].tolist()  # 值欄位名稱
                level_1_values = pivot_table.columns.levels[1].tolist()  # 分組值
                
                # 根據values_cols的順序重新排序level_0
                ordered_level_0 = []
                for original_val in values_cols:
                    # 找到對應的顯示名稱
                    for display_val in values_display:
                        if self._get_original_column_name(display_val) == original_val:
                            if display_val in level_0_values:
                                ordered_level_0.append(display_val)
                            elif original_val in level_0_values:
                                ordered_level_0.append(original_val)
                            break
                
                # 添加任何遺漏的欄位
                for val in level_0_values:
                    if val not in ordered_level_0:
                        ordered_level_0.append(val)
                
                print(f"   原始欄位順序: {level_0_values}")
                print(f"   重新排序後: {ordered_level_0}")
                
                # 重新建構欄位順序
                new_columns = []
                for val in ordered_level_0:
                    for group in level_1_values:
                        if (val, group) in pivot_table.columns:
                            new_columns.append((val, group))
                
                # 重新排序樞紐表欄位
                if new_columns:
                    pivot_table = pivot_table[new_columns]
                    print(f"   ✅ 樞紐表欄位已重新排序")
            
            # 移除任何可能的自動合計行
            auto_total_names = ['All', '合計', '總計', 'Total', 'total']
            for total_name in auto_total_names:
                if total_name in pivot_table.index:
                    print(f"   移除自動生成的合計行: {total_name}")
                    pivot_table = pivot_table.drop(total_name, axis=0)
            
            print(f"✅ 基礎樞紐表創建成功 - 維度: {pivot_table.shape}")
            print(f"   最終欄位順序: {list(pivot_table.columns)}")
            return pivot_table
            
        except Exception as e:
            error_msg = f"創建基礎樞紐表時發生錯誤: {str(e)}"
            print(f"❌ {error_msg}")
            return None

    def _add_correct_total_row(self, pivot_table, aggfunc):
        """正確計算並添加合計行"""
        try:
            print("🧮 正在計算正確的合計行...")
            
            # 檢查是否已存在合計行
            if "合計" in pivot_table.index:
                print("   發現現有合計行，移除後重新計算")
                pivot_table = pivot_table.drop("合計", axis=0)
            
            # 獲取原始資料進行合計計算
            index_col = self._get_original_column_name(self.index_combo.currentText())
            columns_col = self._get_original_column_name(self.columns_combo.currentText()) if self.columns_combo.currentText() else None
            values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
            
            # 準備原始資料
            df_copy = self.current_data.copy()
            for val in values_cols:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            # 移除所有值欄位都是 NaN 的行
            all_values_null = True
            for val in values_cols:
                all_values_null = all_values_null & df_copy[val].isna()
            df_filtered = df_copy[~all_values_null]
            
            # 根據聚合函數類型計算正確的合計
            if isinstance(pivot_table.columns, pd.MultiIndex):
                # 多層索引情況（有 columns 分組）
                print("   處理多層索引合計計算...")
                total_row = pd.Series(index=pivot_table.columns, dtype=float)
                
                for col in pivot_table.columns:
                    value_name = col[0]  # 值欄位名稱
                    group_value = col[1]  # 分組值
                    
                    # 找到對應的原始值欄位
                    original_value_col = None
                    for val in values_cols:
                        # 檢查顯示名稱是否匹配
                        for display_val in self.get_selected_values():
                            if self._get_original_column_name(display_val) == val and display_val == value_name:
                                original_value_col = val
                                break
                        if original_value_col:
                            break
                    
                    if not original_value_col:
                        # 如果沒找到對應，嘗試直接匹配
                        original_value_col = value_name
                    
                    if original_value_col and original_value_col in df_filtered.columns:
                        if columns_col:
                            # 篩選特定分組的資料
                            group_data = df_filtered[df_filtered[columns_col] == group_value]
                        else:
                            group_data = df_filtered
                        
                        if not group_data.empty:
                            if aggfunc == 'sum':
                                total_row[col] = group_data[original_value_col].sum(skipna=True)
                            elif aggfunc == 'mean':
                                total_row[col] = group_data[original_value_col].mean(skipna=True)
                            elif aggfunc == 'count':
                                total_row[col] = group_data[original_value_col].count()
                            elif aggfunc == 'max':
                                total_row[col] = group_data[original_value_col].max(skipna=True)
                            elif aggfunc == 'min':
                                total_row[col] = group_data[original_value_col].min(skipna=True)
                            else:
                                total_row[col] = group_data[original_value_col].sum(skipna=True)
                        else:
                            total_row[col] = 0
                    else:
                        total_row[col] = 0
                        
                    print(f"     {col}: {total_row[col]:.2f}")
            
            else:
                # 單層索引情況
                print("   處理單層索引合計計算...")
                total_row = pd.Series(index=pivot_table.columns, dtype=float)
                
                for col in pivot_table.columns:
                    # 找到對應的原始欄位
                    original_col = None
                    for val in values_cols:
                        # 檢查顯示名稱是否匹配
                        for display_val in self.get_selected_values():
                            if self._get_original_column_name(display_val) == val and display_val == col:
                                original_col = val
                                break
                        if original_col:
                            break
                    
                    if not original_col:
                        # 如果沒找到對應，嘗試直接匹配
                        original_col = col
                    
                    if original_col and original_col in df_filtered.columns:
                        if aggfunc == 'sum':
                            total_row[col] = df_filtered[original_col].sum(skipna=True)
                        elif aggfunc == 'mean':
                            total_row[col] = df_filtered[original_col].mean(skipna=True)
                        elif aggfunc == 'count':
                            total_row[col] = df_filtered[original_col].count()
                        elif aggfunc == 'max':
                            total_row[col] = df_filtered[original_col].max(skipna=True)
                        elif aggfunc == 'min':
                            total_row[col] = df_filtered[original_col].min(skipna=True)
                        else:
                            total_row[col] = df_filtered[original_col].sum(skipna=True)
                    else:
                        total_row[col] = 0
                        
                    print(f"     {col}: {total_row[col]:.2f}")
            
            # 設定合計行名稱
            total_row.name = "合計"
            
            # *** 重要：在應用格式轉換之前先添加合計行 ***
            pivot_with_total = pd.concat([pivot_table, total_row.to_frame().T])
            
            # 現在應用格式轉換（如千位格式）
            format_type = self.format_combo.currentText()
            if format_type == "thousands":
                print(f"🔢 應用千位格式轉換...")
                pivot_with_total = pivot_with_total / 1000
                pivot_with_total = pivot_with_total.round(0)
            
            print(f"✅ 合計行計算完成")
            print(f"   最終維度: {pivot_with_total.shape}")
            print(f"   合計行數量: {(pivot_with_total.index == '合計').sum()}")
            
            return pivot_with_total
            
        except Exception as e:
            print(f"❌ 計算合計行時發生錯誤: {e}")
            # 如果計算失敗，返回原始樞紐表
            return pivot_table

    # ================================
    # 🛠️ 除錯和驗證工具
    # ================================

    def debug_total_calculation(self, pivot_table, aggfunc):
        """除錯合計計算過程"""
        try:
            print("\n=== 合計計算除錯 ===")
            
            # 獲取原始資料
            values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
            df_copy = self.current_data.copy()
            
            for val in values_cols:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            # 移除全 NaN 行
            all_values_null = True
            for val in values_cols:
                all_values_null = all_values_null & df_copy[val].isna()
            df_filtered = df_copy[~all_values_null]
            
            print(f"原始資料筆數: {len(self.current_data)}")
            print(f"過濾後筆數: {len(df_filtered)}")
            
            for val in values_cols:
                if val in df_filtered.columns:
                    total_in_data = df_filtered[val].sum(skipna=True)
                    count_in_data = df_filtered[val].count()
                    mean_in_data = df_filtered[val].mean(skipna=True)
                    
                    print(f"\n欄位 {val}:")
                    print(f"  原始資料總和: {total_in_data:,.2f}")
                    print(f"  原始資料計數: {count_in_data}")
                    print(f"  原始資料平均: {mean_in_data:.2f}")
                    
                    # 檢查樞紐表中的計算
                    if isinstance(pivot_table.columns, pd.MultiIndex):
                        pivot_total = 0
                        for col in pivot_table.columns:
                            if col[0] == val or any(display_val for display_val in self.get_selected_values() 
                                                if self._get_original_column_name(display_val) == val and display_val == col[0]):
                                pivot_total += pivot_table[col].sum(skipna=True)
                        print(f"  樞紐表計算: {pivot_total:,.2f}")
                    else:
                        if val in pivot_table.columns:
                            pivot_total = pivot_table[val].sum(skipna=True)
                            print(f"  樞紐表計算: {pivot_total:,.2f}")
                    
                    print(f"  聚合函數: {aggfunc}")
            
            print("====================")
            
        except Exception as e:
            print(f"除錯時發生錯誤: {e}")

    def validate_total_accuracy(self, original_data, pivot_table_with_total, aggfunc):
        """驗證合計行的準確性"""
        try:
            print("\n🔍 驗證合計行準確性...")
            
            if "合計" not in pivot_table_with_total.index:
                print("❌ 沒有找到合計行")
                return False
            
            # 獲取合計行
            total_row = pivot_table_with_total.loc["合計"]
            
            # 獲取原始資料進行驗證
            values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
            df_copy = original_data.copy()
            
            for val in values_cols:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            # 驗證每個值欄位
            accuracy_results = []
            
            for i, val in enumerate(values_cols):
                if val in df_copy.columns:
                    if aggfunc == 'sum':
                        expected_total = df_copy[val].sum(skipna=True)
                    elif aggfunc == 'mean':
                        expected_total = df_copy[val].mean(skipna=True)
                    elif aggfunc == 'count':
                        expected_total = df_copy[val].count()
                    elif aggfunc == 'max':
                        expected_total = df_copy[val].max(skipna=True)
                    elif aggfunc == 'min':
                        expected_total = df_copy[val].min(skipna=True)
                    else:
                        expected_total = df_copy[val].sum(skipna=True)
                    
                    # 獲取樞紐表中的合計值
                    if isinstance(total_row, pd.Series):
                        if len(total_row) > i:
                            actual_total = total_row.iloc[i]
                        else:
                            actual_total = total_row.iloc[0]  # 如果只有一個值
                    else:
                        actual_total = total_row
                    
                    # 處理千位格式
                    format_type = self.format_combo.currentText()
                    if format_type == "thousands":
                        expected_total = expected_total / 1000
                    
                    difference = abs(expected_total - actual_total)
                    is_accurate = difference < 0.01
                    
                    accuracy_results.append(is_accurate)
                    
                    print(f"欄位 {val}:")
                    print(f"  預期合計: {expected_total:,.2f}")
                    print(f"  實際合計: {actual_total:,.2f}")
                    print(f"  差異: {difference:,.2f}")
                    print(f"  準確性: {'✅ 正確' if is_accurate else '❌ 有誤'}")
            
            overall_accuracy = all(accuracy_results)
            print(f"\n總體準確性: {'✅ 合計計算正確' if overall_accuracy else '❌ 合計計算有誤'}")
            
            return overall_accuracy
            
        except Exception as e:
            print(f"❌ 驗證合計準確性時發生錯誤: {e}")
            return False

    def _display_pivot_table_in_chart_area_no_total(self, pivot_table, index_display, columns_display, values_display, aggfunc, format_type):
        """在圖表區域顯示樞紐表 - 修正版：不重複添加合計行"""
        try:
            print("📊 開始在圖表區域顯示樞紐表...")
            print(f"樞紐表形狀: {pivot_table.shape}")
            print(f"樞紐表類型: {type(pivot_table)}")
            
            # 檢查輸入的樞紐表
            if pivot_table is None:
                print("❌ 樞紐表為None")
                return
            
            if pivot_table.empty:
                print("❌ 樞紐表為空")
                empty_label = QLabel("⚠️ 樞紐表無資料\n請檢查選擇的欄位和聚合函數設定")
                empty_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
                empty_label.setStyleSheet("""
                    QLabel {
                        font-size: 14px;
                        color: #e74c3c;
                        background-color: #fdf2f2;
                        border: 2px solid #e74c3c;
                        border-radius: 7px;
                        padding: 27px;
                        margin: 18px;
                    }
                """)
                # 清除舊顯示
                self.clear_chart_display()
                self.chart_layout.addWidget(empty_label)
                return
            
            # 清除舊的圖表顯示
            self.clear_chart_display()
            
            # *** 修正3：檢查是否已有合計行，如果沒有才添加 ***
            has_total_row = (pivot_table.index == "合計").any()
            
            if not has_total_row:
                print("⚠️ 樞紐表沒有合計行，進行添加...")
                pivot_table_with_total = self._add_total_row_to_pivot(pivot_table, aggfunc)
            else:
                print("✅ 樞紐表已包含合計行，直接使用")
                pivot_table_with_total = pivot_table
            
            # 確保只有一個合計行
            total_count = (pivot_table_with_total.index == "合計").sum()
            if total_count > 1:
                print(f"⚠️ 發現 {total_count} 個合計行，進行清理...")
                # 移除多餘的合計行
                data_rows = pivot_table_with_total[pivot_table_with_total.index != "合計"]
                total_rows = pivot_table_with_total[pivot_table_with_total.index == "合計"]
                
                if not total_rows.empty:
                    final_total = total_rows.iloc[-1:].copy()  # 只保留最後一個合計行
                    pivot_table_with_total = pd.concat([data_rows, final_total])
                    print(f"✅ 合計行清理完成，剩餘 {(pivot_table_with_total.index == '合計').sum()} 個")
            
            print(f"樞紐表（最終）形狀: {pivot_table_with_total.shape}")
            print(f"樞紐表內容預覽:")
            print(pivot_table_with_total.to_string())
            
            # 創建樞紐表顯示的 Widget
            from PyQt6.QtWidgets import QTableWidget, QTableWidgetItem, QVBoxLayout, QLabel, QWidget, QScrollArea
            from PyQt6.QtCore import Qt
            from PyQt6.QtGui import QColor, QFont
            
            # 創建滾動區域容器
            scroll_area = QScrollArea()
            scroll_area.setWidgetResizable(True)
            scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            scroll_area.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            
            # 創建主容器 Widget
            main_widget = QWidget()
            main_layout = QVBoxLayout(main_widget)
            main_layout.setContentsMargins(9, 4, 9, 4)
            main_layout.setSpacing(4)
            
            # 創建標題
            title_parts = [f"📊 樞紐表分析"]
            if columns_display:
                title_parts.append(f"【{index_display} × {columns_display}】")
            else:
                title_parts.append(f"【{index_display}】")
            title_parts.append(f"vs {', '.join(values_display)}")
            title_parts.append(f"({aggfunc})")
            
            if format_type == "thousands":
                title_parts.append("(千)")
            elif format_type == "currency":
                currency_symbol = getattr(self, 'currency_edit', None)
                currency_text = currency_symbol.text() if currency_symbol else "NT$"
                title_parts.append(f"({currency_text})")
            
            title_text = " ".join(title_parts)
            
            title_label = QLabel(title_text)
            title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            title_label.setFixedHeight(54)
            title_label.setStyleSheet("""
                QLabel {
                    font-size: 16px;
                    font-weight: bold;
                    color: #2c3e50;
                    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                                            stop:0 #3498db, stop:1 #2980b9);
                    color: white;
                    border-radius: 7px;
                    padding: 9px;
                    margin: 3px;
                }
            """)
            main_layout.addWidget(title_label)
            
            # 創建樞紐表表格
            pivot_table_widget = QTableWidget()
            
            # 設定表格大小
            num_rows = len(pivot_table_with_total.index)
            num_cols = len(pivot_table_with_total.columns)
            
            print(f"設定表格大小: {num_rows} 列 x {num_cols} 欄")
            
            pivot_table_widget.setRowCount(num_rows)
            pivot_table_widget.setColumnCount(num_cols)
            
            # 設定欄位標題
            if isinstance(pivot_table_with_total.columns, pd.MultiIndex):
                col_labels = []
                for col in pivot_table_with_total.columns:
                    if len(col) >= 2:
                        col_labels.append(f"{col[0]}\n({col[1]})")
                    else:
                        col_labels.append(str(col))
                pivot_table_widget.setHorizontalHeaderLabels(col_labels)
            else:
                pivot_table_widget.setHorizontalHeaderLabels([str(col) for col in pivot_table_with_total.columns])
            
            # 設定列標題（索引）
            row_labels = []
            for idx in pivot_table_with_total.index:
                if len(str(idx)) > 25:
                    row_labels.append(str(idx)[:22] + "...")
                else:
                    row_labels.append(str(idx))
            pivot_table_widget.setVerticalHeaderLabels(row_labels)
            
            # 統計資訊
            total_sum = 0
            max_value = float('-inf')
            min_value = float('inf')
            valid_count = 0
            
            # 填入資料
            print(f"📊 開始填入表格資料...")
            for row in range(num_rows):
                for col in range(num_cols):
                    try:
                        # 獲取原始值
                        if isinstance(pivot_table_with_total.columns, pd.MultiIndex):
                            value = pivot_table_with_total.iloc[row, col]
                        else:
                            value = pivot_table_with_total.iloc[row, col]
                        
                        # 處理統計
                        if pd.notna(value) and isinstance(value, (int, float)):
                            total_sum += value
                            max_value = max(max_value, value)
                            min_value = min(min_value, value)
                            valid_count += 1
                        
                        # 格式化數值顯示
                        if pd.isna(value):
                            display_value = "-"
                        elif value == 0:
                            display_value = "0"
                        elif isinstance(value, (int, float)):
                            if format_type == "thousands":
                                display_value = f"{value:,.0f}K"
                            elif format_type == "currency":
                                currency_symbol = getattr(self, 'currency_edit', None)
                                currency_text = currency_symbol.text() if currency_symbol else "NT$"
                                display_value = f"{currency_text}{value:,.0f}"
                            else:
                                # 使用統一的格式化方法
                                if isinstance(value, float) and value.is_integer():
                                    display_value = f"{int(value):,}"
                                elif abs(value) >= 1000:
                                    display_value = f"{value:,.0f}"
                                else:
                                    display_value = f"{value:.1f}"
                        else:
                            display_value = str(value)
                        
                        # 創建表格項目
                        item = QTableWidgetItem(display_value)
                        item.setTextAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
                        
                        # *** 修正4：合計行特殊格式 - 只檢查最後一行 ***
                        is_total_row = (row == num_rows - 1 and 
                                    str(pivot_table_with_total.index[row]) == "合計")
                        
                        if isinstance(value, (int, float)) and not pd.isna(value):
                            font = QFont()
                            font.setBold(True)
                            font.setPointSize(11)
                            item.setFont(font)
                            
                            if is_total_row:
                                # 合計行使用特殊顏色
                                item.setBackground(QColor(52, 152, 219, 50))
                                item.setForeground(QColor(44, 62, 80))
                                font.setPointSize(11)
                                item.setFont(font)
                            elif value < 0:
                                item.setForeground(QColor(231, 76, 60))
                            elif value > 0:
                                item.setForeground(QColor(52, 73, 94))
                            else:
                                item.setForeground(QColor(149, 165, 166))
                        else:
                            if is_total_row:
                                item.setBackground(QColor(52, 152, 219, 50))
                                item.setForeground(QColor(44, 62, 80))
                            else:
                                item.setForeground(QColor(127, 140, 141))
                        
                        pivot_table_widget.setItem(row, col, item)
                        
                    except Exception as e:
                        print(f"❌ 設定表格項目 ({row}, {col}) 時發生錯誤: {e}")
                        # 設定錯誤項目
                        item = QTableWidgetItem("錯誤")
                        item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                        item.setForeground(QColor(231, 76, 60))
                        pivot_table_widget.setItem(row, col, item)
            
            print(f"✅ 表格資料填入完成")
            print(f"   有效數值: {valid_count} 個")
            print(f"   數值範圍: {min_value:.2f} ~ {max_value:.2f}")
            print(f"   總和: {total_sum:.2f}")
            
            # 設定表格樣式
            pivot_table_widget.setStyleSheet("""
                QTableWidget {
                    gridline-color: #bdc3c7;
                    background-color: white;
                    alternate-background-color: #f8f9fa;
                    selection-background-color: #3498db;
                    selection-color: white;
                    font-size: 13px;
                    border: 1px solid #dee2e6;
                    border-radius: 6px;
                }
                QTableWidget::item {
                    padding: 7px;
                    border-bottom: 1px solid #ecf0f1;
                    border-right: 1px solid #ecf0f1;
                }
                QTableWidget::item:selected {
                    background-color: #3498db;
                    color: white;
                }
                QTableWidget::item:hover {
                    background-color: #e8f4f8;
                }
                QHeaderView::section {
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                                            stop:0 #34495e, stop:1 #2c3e50);
                    color: white;
                    padding: 9px;
                    border: 1px solid #2c3e50;
                    font-weight: bold;
                    font-size: 14px;
                }
                QHeaderView::section:horizontal {
                    border-bottom: 2px solid #2c3e50;
                }
                QHeaderView::section:vertical {
                    border-right: 2px solid #2c3e50;
                }
            """)
            
            # 設定表格屬性
            pivot_table_widget.setAlternatingRowColors(True)
            pivot_table_widget.setSortingEnabled(True)
            pivot_table_widget.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            
            # 自動調整欄寬
            pivot_table_widget.resizeColumnsToContents()
            for col in range(num_cols):
                current_width = pivot_table_widget.columnWidth(col)
                if current_width > 180:
                    pivot_table_widget.setColumnWidth(col, 180)
                elif current_width < 80:
                    pivot_table_widget.setColumnWidth(col, 80)
            
            # 自動調整表格高度
            pivot_table_widget.resizeRowsToContents()
            
            # 計算表格實際需要的高度
            header_height = pivot_table_widget.horizontalHeader().height()
            total_row_height = 0
            for row in range(num_rows):
                total_row_height += pivot_table_widget.rowHeight(row)
            
            extra_margin = 30
            actual_table_height = header_height + total_row_height + extra_margin
            
            print(f"表格高度計算: 表頭={header_height}, 內容行={total_row_height}, 總計={actual_table_height}")
            
            if actual_table_height <= 800:
                pivot_table_widget.setFixedHeight(actual_table_height)
            else:
                pivot_table_widget.setMaximumHeight(720)
                pivot_table_widget.setMinimumHeight(540)
            
            main_layout.addWidget(pivot_table_widget, stretch=1)
            
            # 創建摘要資訊
            summary_info = self._create_detailed_pivot_summary_info_with_total(
                pivot_table_with_total, values_display, aggfunc, format_type, 
                total_sum, max_value, min_value, valid_count
            )
            
            summary_label = QLabel(summary_info)
            summary_label.setAlignment(Qt.AlignmentFlag.AlignLeft)
            summary_label.setWordWrap(True)
            summary_label.setFixedHeight(108)
            summary_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #2c3e50;
                    background-color: #f8f9fa;
                    border: 1px solid #dee2e6;
                    border-radius: 6px;
                    padding: 9px;
                    margin: 3px;
                    line-height: 1.4;
                }
            """)
            main_layout.addWidget(summary_label, stretch=0)
            
            # 設定滾動區域
            scroll_area.setWidget(main_widget)
            
            total_content_height = (
                60 +
                actual_table_height +
                120 +
                40
            )
            
            available_height = self.height() - 200
            scroll_area_height = min(total_content_height, available_height)
            scroll_area_height = max(scroll_area_height, 400)
            
            scroll_area.setMinimumHeight(scroll_area_height)
            scroll_area.setMaximumHeight(available_height)
            
            print(f"滾動區域高度設定: {scroll_area_height} (內容高度: {total_content_height})")
            
            if hasattr(self, 'chart_layout'):
                self.chart_layout.addWidget(scroll_area)
            
            print("✅ 樞紐表顯示完成 - 合計行已正確處理，只出現在最後一行")
            
        except Exception as e:
            print(f"❌ 顯示樞紐表時發生錯誤: {e}")
            import traceback
            print("詳細錯誤資訊:")
            print(traceback.format_exc())
            QMessageBox.critical(self, "顯示錯誤", f"顯示樞紐表時發生錯誤：{str(e)}")

    def _add_total_row_to_pivot(self, pivot_table, aggfunc):
        """修正版：為樞紐表添加合計行 - 確保只添加一次且位置正確"""
        try:
            print("🧮 正在為樞紐表添加合計行...")
            
            # *** 修正1：檢查是否已存在合計行 ***
            if "合計" in pivot_table.index:
                print("   發現現有合計行，直接返回原表格")
                return pivot_table
            
            # 檢查其他可能的合計行名稱
            total_names = ["總計", "Total", "總和", "小計", "All"]
            for total_name in total_names:
                if total_name in pivot_table.index:
                    print(f"   發現現有合計行 '{total_name}'，重命名為'合計'")
                    # 重命名為標準的'合計'
                    pivot_table = pivot_table.rename(index={total_name: "合計"})
                    return pivot_table
            
            # 保存原始樞紐表以供計算使用
            original_table = pivot_table.copy()
            format_type = self.format_combo.currentText()
            
            # 根據聚合函數計算合計
            if aggfunc in ['sum', 'count']:
                # 加總或計數：對所有行進行加總
                original_total = original_table.sum(axis=0, skipna=True)
            elif aggfunc == 'mean':
                # 平均值：重新計算總平均值
                index_col = self._get_original_column_name(self.index_combo.currentText())
                values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
                columns_col = self._get_original_column_name(self.columns_combo.currentText()) if self.columns_combo.currentText() else None
                
                df_copy = self.current_data.copy()
                for val in values_cols:
                    df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
                
                # 計算總平均值
                if isinstance(original_table.columns, pd.MultiIndex):
                    original_total = pd.Series(index=original_table.columns, dtype=float)
                    for col in original_table.columns:
                        if len(col) >= 2:
                            value_col = col[0]
                            group_col = col[1]
                            if columns_col:
                                subset = df_copy[df_copy[columns_col] == group_col]
                            else:
                                subset = df_copy
                            
                            if not subset.empty and value_col in subset.columns:
                                original_total[col] = subset[value_col].mean(skipna=True)
                            else:
                                original_total[col] = 0
                else:
                    original_total = pd.Series(index=original_table.columns, dtype=float)
                    for col in original_table.columns:
                        found = False
                        for val in values_cols:
                            if val in df_copy.columns:
                                original_total[col] = df_copy[val].mean(skipna=True)
                                found = True
                                break
                        if not found:
                            original_total[col] = 0
                            
            elif aggfunc == 'max':
                original_total = original_table.max(axis=0, skipna=True)
            elif aggfunc == 'min':
                original_total = original_table.min(axis=0, skipna=True)
            else:
                original_total = original_table.sum(axis=0, skipna=True)
            
            # 設定合計行名稱
            original_total.name = "合計"
            
            # 根據格式類型轉換合計值
            if format_type == "thousands":
                display_total = original_total / 1000
                display_total = display_total.round(0)
            else:
                display_total = original_total.copy()
            
            display_total.name = "合計"
            
            # *** 修正2：確保合計行添加到最後 ***
            pivot_with_total = pd.concat([pivot_table, display_total.to_frame().T])
            
            print(f"✅ 合計行添加完成")
            print(f"   最終合計行數量: {(pivot_with_total.index == '合計').sum()}")
            
            if format_type == "thousands":
                print(f"   顯示合計: {display_total.sum():.2f}K")
            else:
                print(f"   顯示合計: {display_total.sum():.2f}")
            
            return pivot_with_total
            
        except Exception as e:
            print(f"❌ 添加合計行時發生錯誤: {e}")
            # 如果添加合計失敗，返回原始樞紐表
            return pivot_table

    def create_pivot_table(self):
        """修正版：創建樞紐表 - 確保不產生重複合計行"""
        try:
            if self.current_data is None or self.current_data.empty:
                print("❌ 沒有可用的資料")
                return None
            
            # 取得顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            
            print(f"🔍 創建樞紐表 - 顯示名稱:")
            print(f"   Index: {index_display}")
            print(f"   Columns: {columns_display}")
            print(f"   Values: {values_display}")
            print(f"   聚合函數: {aggfunc}")
            
            # 基本驗證
            if not index_display or not values_display:
                print("❌ 缺少必要的欄位選擇")
                return None
            
            # 轉換為原始欄位名稱
            index_col = self._get_original_column_name(index_display)
            columns_col = self._get_original_column_name(columns_display) if columns_display else None
            values_cols = [self._get_original_column_name(val) for val in values_display if val]
            
            print(f"🔄 欄位名稱轉換:")
            print(f"   Index: {index_display} -> {index_col}")
            print(f"   Columns: {columns_display} -> {columns_col}")
            print(f"   Values: {values_display} -> {values_cols}")
            
            # 驗證欄位存在
            missing_fields = []
            if index_col not in self.current_data.columns:
                missing_fields.append(f"Index欄位 '{index_col}' (顯示: {index_display})")
            if columns_col and columns_col not in self.current_data.columns:
                missing_fields.append(f"Columns欄位 '{columns_col}' (顯示: {columns_display})")
            for i, val in enumerate(values_cols):
                if val not in self.current_data.columns:
                    missing_fields.append(f"Values欄位 '{val}' (顯示: {values_display[i]})")
            
            if missing_fields:
                error_msg = "以下欄位在資料中不存在:\n" + "\n".join(missing_fields)
                print(f"❌ {error_msg}")
                return None
            
            # 改善數據處理邏輯
            df_copy = self.current_data.copy()
            
            # 只轉換值欄位為數值型，但保留原始NaN結構
            for val in values_cols:
                print(f"處理數值欄位 {val}...")
                original_dtype = df_copy[val].dtype
                
                # 轉換為數值型，但保留NaN（不強制填0）
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
                
                non_null_count = df_copy[val].notna().sum()
                print(f"   轉換: {original_dtype} -> 數值型，有效值: {non_null_count}")
            
            # 不過度過濾數據，保持原始數據結構
            # 只移除所有值欄位都是NaN的行，但保留部分有值的行
            all_values_null = True
            for val in values_cols:
                all_values_null = all_values_null & df_copy[val].isna()
            
            df_filtered = df_copy[~all_values_null]  # 只移除所有值都是NaN的行
            
            print(f"📊 數據過濾結果:")
            print(f"   原始筆數: {len(df_copy)}")
            print(f"   過濾後筆數: {len(df_filtered)}")
            
            if df_filtered.empty:
                print("❌ 過濾後沒有有效資料")
                return None
            
            # *** 修正：確保 pandas.pivot_table 不自動添加合計行 ***
            pivot_params = {
                'values': values_cols,
                'index': index_col,
                'aggfunc': aggfunc,
                'fill_value': None,  # 使用None而非0，保持數據真實性
                'margins': False,    # *** 關鍵：明確設定 margins=False，避免自動添加合計 ***
                'margins_name': 'All'  # 即使不使用margins，也明確設定名稱
            }
            
            if columns_col:
                pivot_params['columns'] = columns_col
            
            print(f"📋 樞紐表參數: {pivot_params}")
            
            # 創建樞紐表
            pivot_table = pd.pivot_table(df_filtered, **pivot_params)
            
            print(f"✅ 樞紐表創建成功")
            print(f"   維度: {pivot_table.shape}")
            print(f"   檢查是否有自動合計行: {'合計' in pivot_table.index}")
            
            # *** 如果 pandas 自動添加了合計行，移除它 ***
            auto_total_names = ['All', '合計', '總計', 'Total']
            for total_name in auto_total_names:
                if total_name in pivot_table.index:
                    print(f"   移除自動生成的合計行: {total_name}")
                    pivot_table = pivot_table.drop(total_name, axis=0)
            
            # 處理數值格式但不影響計算
            format_type = self.format_combo.currentText()
            if format_type == "thousands":
                print(f"🔢 應用千位格式轉換...")
                # 保存原始樞紐表用於合計計算
                self._original_pivot_table = pivot_table.copy()
                pivot_table = pivot_table / 1000
                pivot_table = pivot_table.round(0)
            else:
                # 即使不是千位格式，也保存原始表
                self._original_pivot_table = pivot_table.copy()
            
            print(f"🎉 樞紐表創建完成 - 最終維度: {pivot_table.shape}")
            return pivot_table
            
        except Exception as e:
            error_msg = f"創建樞紐表時發生未預期的錯誤: {str(e)}"
            print(f"❌ {error_msg}")
            return None


    def _validate_pivot_calculations(self, aggfunc):
        """驗證樞紐表計算的正確性"""
        try:
            if not hasattr(self, '_original_pivot_table'):
                return True
            
            original_table = self._original_pivot_table
            
            # 獲取原始數據進行驗證
            index_col = self._get_original_column_name(self.index_combo.currentText())
            values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
            
            df_copy = self.current_data.copy()
            for val in values_cols:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            print(f"\n🔍 驗證樞紐表計算正確性:")
            
            # 驗證總計
            if aggfunc == 'sum':
                for val in values_cols:
                    original_sum = df_copy[val].sum(skipna=True)
                    
                    if isinstance(original_table.columns, pd.MultiIndex):
                        # 多層索引情況
                        pivot_sum = 0
                        for col in original_table.columns:
                            if col[0] == val:
                                pivot_sum += original_table[col].sum(skipna=True)
                    else:
                        # 單層索引情況
                        if val in original_table.columns:
                            pivot_sum = original_table[val].sum(skipna=True)
                        else:
                            # 嘗試找到匹配的欄位
                            pivot_sum = 0
                            for col in original_table.columns:
                                if val in str(col):
                                    pivot_sum += original_table[col].sum(skipna=True)
                    
                    print(f"   {val}:")
                    print(f"     原始數據總和: {original_sum:,.2f}")
                    print(f"     樞紐表總和: {pivot_sum:,.2f}")
                    print(f"     差異: {abs(original_sum - pivot_sum):,.2f}")
                    
                    if abs(original_sum - pivot_sum) > 0.01:
                        print(f"     ⚠️ 警告：發現計算差異！")
                        return False
                    else:
                        print(f"     ✅ 計算正確")
            
            return True
            
        except Exception as e:
            print(f"❌ 驗證樞紐表時發生錯誤: {e}")
            return False
        
    def validate_pivot_calculations(self, pivot_info, aggfunc):
        """驗證樞紐表計算的正確性"""
        try:
            if not pivot_info:
                return False
            
            original_table = pivot_info['original_table']
            
            # 獲取原始數據進行驗證
            index_col = self._get_original_column_name(self.index_combo.currentText())
            values_cols = [self._get_original_column_name(val) for val in self.get_selected_values()]
            columns_col = self._get_original_column_name(self.columns_combo.currentText()) if self.columns_combo.currentText() else None
            
            df_copy = self.current_data.copy()
            for val in values_cols:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            print(f"\n🔍 驗證樞紐表計算正確性:")
            
            # 驗證總計
            if aggfunc == 'sum':
                for val in values_cols:
                    original_sum = df_copy[val].sum(skipna=True)
                    
                    if isinstance(original_table.columns, pd.MultiIndex):
                        # 多層索引情況
                        pivot_sum = 0
                        for col in original_table.columns:
                            if col[0] == val:
                                pivot_sum += original_table[col].sum(skipna=True)
                    else:
                        # 單層索引情況
                        if val in original_table.columns:
                            pivot_sum = original_table[val].sum(skipna=True)
                        else:
                            pivot_sum = 0
                    
                    print(f"   {val}:")
                    print(f"     原始數據總和: {original_sum:,.2f}")
                    print(f"     樞紐表總和: {pivot_sum:,.2f}")
                    print(f"     差異: {abs(original_sum - pivot_sum):,.2f}")
                    
                    if abs(original_sum - pivot_sum) > 0.01:
                        print(f"     ⚠️ 警告：發現計算差異！")
                        return False
                    else:
                        print(f"     ✅ 計算正確")
            
            return True
            
        except Exception as e:
            print(f"❌ 驗證樞紐表時發生錯誤: {e}")
            return False

    def _create_detailed_pivot_summary_info_with_total(self, pivot_table, values_display, aggfunc, format_type, 
                                                total_sum, max_value, min_value, valid_count):
        """創建包含合計資訊的樞紐表摘要"""
        try:
            info_lines = []
            
            # 基本維度資訊（扣除合計行）
            data_rows = len(pivot_table.index) - 1 if pivot_table.index[-1] == "合計" else len(pivot_table.index)
            info_lines.append(f"📊 <b>資料維度</b>：{data_rows} 列 × {len(pivot_table.columns)} 欄 + 合計行")
            
            # 聚合函數和欄位資訊
            info_lines.append(f"📈 <b>聚合方式</b>：{aggfunc}({', '.join(values_display)})")
            
            # 統計摘要 - 包含合計資訊
            if valid_count > 0:
                avg_value = total_sum / valid_count
                
                # 取得合計行數值
                if pivot_table.index[-1] == "合計":
                    total_row = pivot_table.iloc[-1]
                    if isinstance(total_row, pd.Series):
                        total_values = total_row.tolist()
                        total_display = ", ".join([f"{val:,.0f}" for val in total_values if pd.notna(val)])
                    else:
                        total_display = f"{total_row:,.0f}"
                else:
                    total_display = "無合計資料"
                
                if format_type == "thousands":
                    info_lines.append(f"📊 <b>數值範圍</b>：{min_value:,.0f}K ~ {max_value:,.0f}K (平均: {avg_value:,.0f}K)")
                    info_lines.append(f"🧮 <b>合計</b>：{total_display}K")
                elif format_type == "currency":
                    currency_symbol = getattr(self, 'currency_edit', None)
                    currency_text = currency_symbol.text() if currency_symbol else "NT$"
                    info_lines.append(f"📊 <b>數值範圍</b>：{currency_text}{min_value:,.0f} ~ {currency_text}{max_value:,.0f} (平均: {currency_text}{avg_value:,.0f})")
                    info_lines.append(f"🧮 <b>合計</b>：{currency_text}{total_display}")
                else:
                    info_lines.append(f"📊 <b>數值範圍</b>：{min_value:,.1f} ~ {max_value:,.1f} (平均: {avg_value:,.1f})")
                    info_lines.append(f"🧮 <b>合計</b>：{total_display}")
                
                info_lines.append(f"🔢 <b>有效數值</b>：{valid_count} 個")
            else:
                info_lines.append(f"⚠️ <b>警告</b>：無有效數值資料")
            
            # 顏色說明
            info_lines.append(f"🎨 <b>顏色</b>：<span style='color: #e74c3c;'>紅=負值</span> | <span style='color: #34495e;'>藍=正值</span> | <span style='color: #3498db; background-color: #ecf0f1;'>淺藍=合計</span>")
            
            return "<br>".join(info_lines)
            
        except Exception as e:
            print(f"創建摘要資訊時發生錯誤: {e}")
            return f"📊 樞紐表摘要 - 維度：{len(pivot_table.index)} × {len(pivot_table.columns)} | 聚合：{aggfunc} | 已添加合計行"

    # 額外的輔助函數修正：確保摘要資訊簡潔
    def _create_detailed_pivot_summary_info(self, pivot_table, values_display, aggfunc, format_type, 
                                        total_sum, max_value, min_value, valid_count):
        """創建簡潔的樞紐表摘要資訊 - 優化版"""
        try:
            info_lines = []
            
            # 基本維度資訊
            info_lines.append(f"📊 <b>資料維度</b>：{pivot_table.shape[0]} 列 × {pivot_table.shape[1]} 欄")
            
            # 聚合函數和欄位資訊
            info_lines.append(f"📈 <b>聚合方式</b>：{aggfunc}({', '.join(values_display)})")
            
            # 統計摘要 - 簡化版
            if valid_count > 0:
                avg_value = total_sum / valid_count
                
                if format_type == "thousands":
                    info_lines.append(f"📊 <b>數值範圍</b>：{min_value:,.0f}K ~ {max_value:,.0f}K (平均: {avg_value:,.0f}K, 總計: {total_sum:,.0f}K)")
                elif format_type == "currency":
                    currency_symbol = getattr(self, 'currency_edit', None)
                    currency_text = currency_symbol.text() if currency_symbol else "NT$"
                    info_lines.append(f"📊 <b>數值範圍</b>：{currency_text}{min_value:,.0f} ~ {currency_text}{max_value:,.0f} (平均: {currency_text}{avg_value:,.0f})")
                else:
                    info_lines.append(f"📊 <b>數值範圍</b>：{min_value:,.1f} ~ {max_value:,.1f} (平均: {avg_value:,.1f}, 總計: {total_sum:,.1f})")
                
                info_lines.append(f"🔢 <b>有效數值</b>：{valid_count} 個")
            else:
                info_lines.append(f"⚠️ <b>警告</b>：無有效數值資料")
            
            # 顏色說明 - 簡化
            info_lines.append(f"🎨 <b>顏色</b>：<span style='color: #e74c3c;'>紅=負值</span> | <span style='color: #34495e;'>藍=正值</span> | <span style='color: #95a5a6;'>灰=零值</span>")
            
            return "<br>".join(info_lines)
            
        except Exception as e:
            print(f"創建摘要資訊時發生錯誤: {e}")
            return f"📊 樞紐表摘要 - 維度：{pivot_table.shape[0]} × {pivot_table.shape[1]} | 聚合：{aggfunc}"

    def debug_pivot_table_data(self, pivot_table):
        """除錯樞紐表資料"""
        try:
            print("=== 樞紐表除錯資訊 ===")
            print(f"樞紐表類型: {type(pivot_table)}")
            print(f"樞紐表形狀: {pivot_table.shape}")
            print(f"樞紐表索引: {pivot_table.index.tolist()}")
            print(f"樞紐表欄位: {pivot_table.columns.tolist()}")
            print(f"樞紐表 dtypes:")
            print(pivot_table.dtypes)
            print(f"樞紐表內容:")
            print(pivot_table)
            print("========================")
        except Exception as e:
            print(f"除錯樞紐表時發生錯誤: {e}")

    # 修正 generate_pivot_table 方法，加入除錯資訊
    def generate_pivot_table_with_debug(self):
        """生成並顯示樞紐表 - 加強除錯版本"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.warning(self, "警告", "請先執行 SQL 查詢以取得資料！")
                return None
            
            # 取得顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            
            print(f"🔍 生成樞紐表 - 顯示名稱:")
            print(f"   Index: {index_display}")
            print(f"   Columns: {columns_display}")
            print(f"   Values: {values_display}")
            print(f"   聚合函數: {aggfunc}")
            
            # 基本驗證
            if not index_display or not values_display:
                QMessageBox.critical(self, "錯誤", "請選擇列(Index)欄位和至少一個值(Values)欄位！")
                return None
            
            # 轉換為原始欄位名稱
            index_col = self._get_original_column_name(index_display)
            columns_col = self._get_original_column_name(columns_display) if columns_display else None
            values_cols = [self._get_original_column_name(val) for val in values_display if val]
            
            print(f"🔄 欄位名稱轉換:")
            print(f"   Index: {index_display} -> {index_col}")
            print(f"   Columns: {columns_display} -> {columns_col}")
            print(f"   Values: {values_display} -> {values_cols}")
            
            # 驗證欄位存在
            missing_fields = []
            if index_col not in self.current_data.columns:
                missing_fields.append(f"Index欄位 '{index_col}' (顯示: {index_display})")
            if columns_col and columns_col not in self.current_data.columns:
                missing_fields.append(f"Columns欄位 '{columns_col}' (顯示: {columns_display})")
            for i, val in enumerate(values_cols):
                if val not in self.current_data.columns:
                    missing_fields.append(f"Values欄位 '{val}' (顯示: {values_display[i]})")
            
            if missing_fields:
                error_msg = "以下欄位在資料中不存在:\n" + "\n".join(missing_fields)
                QMessageBox.critical(self, "欄位錯誤", error_msg)
                return None
            
            # 複製資料並處理
            df_copy = self.current_data.copy()
            
            # 處理數值欄位
            for val in values_cols:
                print(f"處理數值欄位 {val}...")
                original_dtype = df_copy[val].dtype
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
                non_null_count = df_copy[val].notna().sum()
                print(f"   轉換: {original_dtype} -> 數值型，有效值: {non_null_count}")
            
            # 生成樞紐表
            pivot_params = {
                'values': values_cols,
                'index': index_col,
                'aggfunc': aggfunc,
                'fill_value': 0
            }
            
            if columns_col:
                pivot_params['columns'] = columns_col
            
            print(f"📋 樞紐表參數: {pivot_params}")
            
            pivot_table = pd.pivot_table(df_copy, **pivot_params)
            
            # 除錯資訊
            self.debug_pivot_table_data(pivot_table)
            
            # 處理數值格式
            format_type = self.format_combo.currentText()
            if format_type == "thousands":
                pivot_table = pivot_table / 1000
                pivot_table = pivot_table.round(0)
            
            # 轉換欄位名稱並顯示
            display_pivot_table = self._convert_pivot_table_to_display_names(
                pivot_table, index_display, columns_display, values_display
            )
            
            self._display_pivot_table_in_chart_area(display_pivot_table, 
                                                index_display, columns_display, 
                                                values_display, aggfunc, format_type)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
            print(f"🎉 樞紐表生成並顯示完成")
            return display_pivot_table
            
        except Exception as e:
            error_msg = f"生成樞紐表時發生錯誤: {str(e)}"
            print(f"❌ {error_msg}")
            import traceback
            print("詳細錯誤追蹤:")
            print(traceback.format_exc())
            QMessageBox.critical(self, "樞紐表生成錯誤", error_msg)
            return None

    def get_selected_values_with_display_names(self):
        """取得選擇的值欄位 - 返回顯示名稱和原始名稱的配對"""
        display_values = self.get_selected_values()
        return {
            'display': display_values,
            'original': [self._get_original_column_name(val) for val in display_values if val]
        }

    def debug_field_mapping(self):
        """除錯用：顯示欄位映射狀況"""
        if not hasattr(self, 'column_rename_mapping'):
            print("沒有欄位重命名映射")
            return
        
        print("=== 欄位重命名映射 ===")
        for original, display in self.column_rename_mapping.items():
            print(f"原始: {original} -> 顯示: {display}")
        
        print("=== 當前選擇狀況 ===")
        print(f"Index 顯示: {self.index_combo.currentText()}")
        print(f"Index 原始: {self._get_original_column_name(self.index_combo.currentText())}")
        
        values_display = self.get_selected_values()
        values_original = [self._get_original_column_name(val) for val in values_display]
        print(f"Values 顯示: {values_display}")
        print(f"Values 原始: {values_original}")

    def format_number(self, value):
        """格式化數值顯示"""
        format_type = self.format_combo.currentText()
        
        if format_type == "thousands":
            # 將數值除以1000並四捨五入，然後加上千位分隔符號
            thousands_value = round(value)
            return '{:,}'.format(thousands_value)
        elif format_type == "currency":
            return f"{self.currency_edit.text()}{value:,.0f}"
        elif format_type == "normal":
            return '{:,.2f}'.format(value)
        else:
            return str(round(value, 2))

    def generate_bar_chart(self):
        """生成長條圖 - 修正版：支援欄(Columns)分組並提供年度選擇"""
        if self.current_data is None or self.current_data.empty:
            QMessageBox.warning(self, "警告", "請先執行 SQL 查詢以取得資料！")
            return
        
        try:
            # 檢查必要欄位 - 使用顯示名稱檢查
            index_col_display = self.index_combo.currentText()
            columns_col_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_cols_display = self.get_selected_values()
            chart_type = self.bar_chart_type_combo.currentText()
            
            if not index_col_display:
                QMessageBox.warning(self, "警告", "請選擇列(Index)欄位！")
                return
            
            if not values_cols_display:
                QMessageBox.warning(self, "警告", "請至少選擇一個值(Values)欄位！")
                return
            
            # 轉換為原始欄位名稱
            index_col = self._get_original_column_name(index_col_display)
            columns_col = self._get_original_column_name(columns_col_display) if columns_col_display else None
            values_cols = [self._get_original_column_name(val) for val in values_cols_display if val]
            
            print(f"長條圖設定:")
            print(f"  列(Index): {index_col_display} -> {index_col}")
            print(f"  欄(Columns): {columns_col_display} -> {columns_col}")
            print(f"  值(Values): {values_cols_display} -> {values_cols}")
            print(f"  圖表類型: {chart_type}")
            
            # 生成樞紐表（使用原始名稱）
            pivot_data = self.create_pivot_table()
            if pivot_data is None:
                return
            
            print(f"樞紐表生成成功，形狀: {pivot_data.shape}")
            print(f"樞紐表欄位: {list(pivot_data.columns)}")
            print(f"樞紐表欄位類型: {type(pivot_data.columns)}")
            
            # 清除舊圖表
            self.clear_chart_display()
            
            # 創建新圖表
            fig, ax = plt.subplots(figsize=(14, 8))
            
            # 應用風格
            sns.set_style(self.style_combo.currentText())
            sns.set_context(self.context_combo.currentText())
            sns.set_palette(self.palette_combo.currentText())
            set_chinese_font()
            
            # 檢查是否有欄分組
            has_columns = columns_col is not None and columns_col_display is not None
            
            # *** 修正：特定圖表類型的年度選擇功能 ***
            special_chart_types = ["Bar-in-bar Charts", "Overlapping Bar Chart", "組合圖 (長條圖+折線圖)"]
            
            # 修正條件：確保特殊圖表類型優先處理
            if chart_type in special_chart_types and has_columns and isinstance(pivot_data.columns, pd.MultiIndex):
                print(f"🎯 檢測到特殊圖表類型且有欄分組：{chart_type}")
                
                # 分析可用的分組值（如不同年度）
                available_groups = list(pivot_data.columns.levels[1])
                print(f"可用的{columns_col_display}值: {available_groups}")
                
                # 提供年度選擇
                if len(available_groups) > 1:
                    selected_group = self._show_group_selection_dialog_for_bar_chart(
                        available_groups, columns_col_display, chart_type
                    )
                    if selected_group is not None:
                        # 根據選擇的年度繪製特殊圖表
                        colors = self.get_chart_colors(20)
                        self._draw_special_bar_chart_with_selected_group(
                            ax, pivot_data, selected_group, values_cols, values_cols_display,
                            index_col_display, columns_col_display, chart_type, colors
                        )
                        # 已完成特殊圖表繪製，直接返回
                        plt.tight_layout()
                        self.display_chart(fig)
                        self.tab_widget.setCurrentIndex(3)
                        return
                    else:
                        # 用戶取消，使用預設處理
                        colors = self.get_chart_colors(20)
                        self._draw_grouped_bar_chart_with_columns(ax, pivot_data, values_cols, values_cols_display, 
                                                                index_col_display, columns_col_display, colors)
                else:
                    # 只有一個分組，直接使用
                    selected_group = available_groups[0]
                    colors = self.get_chart_colors(20)
                    self._draw_special_bar_chart_with_selected_group(
                        ax, pivot_data, selected_group, values_cols, values_cols_display,
                        index_col_display, columns_col_display, chart_type, colors
                    )
                    # 已完成特殊圖表繪製，直接返回
                    plt.tight_layout()
                    self.display_chart(fig)
                    self.tab_widget.setCurrentIndex(3)
                    return
            
            elif has_columns and isinstance(pivot_data.columns, pd.MultiIndex):
                print("檢測到欄分組，使用多維分組長條圖")
                colors = self.get_chart_colors(20)
                
                if chart_type == "群組長條圖":
                    self._draw_grouped_bar_chart_with_columns(ax, pivot_data, values_cols, values_cols_display, 
                                                            index_col_display, columns_col_display, colors)
                elif chart_type == "堆疊長條圖":
                    self._draw_stacked_bar_chart_with_columns(ax, pivot_data, values_cols, values_cols_display,
                                                            index_col_display, columns_col_display, colors)
                else:
                    # 其他圖表類型使用群組長條圖
                    self._draw_grouped_bar_chart_with_columns(ax, pivot_data, values_cols, values_cols_display,
                                                            index_col_display, columns_col_display, colors)
            else:
                print("使用一般長條圖（無欄分組）")
                colors = self.get_chart_colors(max(len(values_cols), len(pivot_data.columns)))
                
                # 原有的邏輯（無欄分組）
                if chart_type == "群組長條圖":
                    self._draw_grouped_bar_chart(ax, pivot_data, values_cols, colors)
                elif chart_type == "堆疊長條圖":
                    self._draw_stacked_bar_chart(ax, pivot_data, values_cols, colors)
                elif chart_type == "Bar-in-bar Charts":
                    self._draw_bar_in_bar_chart(ax, pivot_data, values_cols, colors)
                elif chart_type == "Overlapping Bar Chart":
                    self._draw_overlapping_bar_chart(ax, pivot_data, values_cols, colors)
                elif chart_type == "組合圖 (長條圖+折線圖)":
                    aggfunc = self.aggfunc_combo.currentText()
                    format_type = self.format_combo.currentText()
                    ylabel_suffix = "(千)" if format_type == "thousands" else ""
                    self._draw_combo_chart(ax, pivot_data, values_cols, colors, aggfunc, 
                                        index_col, columns_col, ylabel_suffix)
            
            # 設定圖表樣式（除了組合圖和已完成的特殊圖表）
            # 檢查是否已經在特殊圖表處理中設定過標題
            current_title = ax.get_title()
            if not current_title and chart_type != "組合圖 (長條圖+折線圖)":
                format_type = self.format_combo.currentText()
                ylabel_suffix = "(千)" if format_type == "thousands" else ""
                
                # 建構標題
                if has_columns:
                    title = f'{chart_type} - {", ".join(values_cols_display)} 按 {index_col_display} × {columns_col_display} 分組{ylabel_suffix}'
                else:
                    title = f'{chart_type} - {", ".join(values_cols_display)} 按 {index_col_display} 分組{ylabel_suffix}'
                
                ax.set_title(title, fontsize=self.title_fontsize)
                ax.set_xlabel(index_col_display, fontsize=self.label_fontsize)
                ax.set_ylabel(f'{", ".join(values_cols_display)}{ylabel_suffix}', fontsize=self.label_fontsize)
                
                # 顯示圖例
                if ax.get_legend_handles_labels()[0]:
                    ax.legend(fontsize=self.label_fontsize-2, loc='best')
            
            # 套用數值格式
            self._apply_chart_formatting(ax, pivot_data)
            
            plt.tight_layout()
            
            # 顯示圖表
            self.display_chart(fig)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
                    
        except Exception as e:
            error_msg = f"生成長條圖時發生錯誤：{str(e)}"
            print(error_msg)
            import traceback
            print("詳細錯誤資訊:")
            print(traceback.format_exc())
            QMessageBox.critical(self, "錯誤", error_msg)

    def _draw_special_bar_chart_with_selected_group(self, ax, pivot_table, selected_group, values_cols, 
                                                values_cols_display, index_display, columns_display, 
                                                chart_type, colors):
        """根據選擇的分組繪製特殊長條圖 - 修正版：標題明確顯示選擇的欄分組"""
        try:
            print(f"繪製特殊長條圖：{chart_type}，選擇的{columns_display}: {selected_group}")
            
            # 提取選定分組的資料
            plot_data = pd.DataFrame(index=pivot_table.index)
            
            for i, value_display in enumerate(values_cols_display):
                value_original = self._get_original_column_name(value_display)
                
                # 尋找對應的欄位
                if (value_original, selected_group) in pivot_table.columns:
                    plot_data[value_display] = pivot_table[(value_original, selected_group)]
                elif (selected_group, value_original) in pivot_table.columns:
                    plot_data[value_display] = pivot_table[(selected_group, value_original)]
                else:
                    print(f"找不到欄位組合: {value_original} x {selected_group}")
                    continue
            
            if plot_data.empty or len(plot_data.columns) == 0:
                raise Exception(f"無法找到{selected_group}的資料")
            
            # 準備繪圖資料
            x_pos = np.arange(len(plot_data.index))
            available_values = list(plot_data.columns)
            
            # 根據圖表類型繪製
            if chart_type == "Bar-in-bar Charts":
                self._draw_bar_in_bar_chart_single_group(ax, plot_data, available_values, colors, x_pos)
            elif chart_type == "Overlapping Bar Chart":
                self._draw_overlapping_bar_chart_single_group(ax, plot_data, available_values, colors, x_pos)
            elif chart_type == "組合圖 (長條圖+折線圖)":
                self._draw_combo_chart_single_group(ax, plot_data, available_values, colors, x_pos)
            
            # 設定X軸標籤
            ax.set_xticks(x_pos)
            ax.set_xticklabels(plot_data.index, rotation=45, ha='right')
            
            # *** 修正：明確標題格式，顯示選擇的欄分組 ***
            format_type = self.format_combo.currentText()
            ylabel_suffix = "(千)" if format_type == "thousands" else ""
            
            # 新標題格式：圖表類型 - 值欄位 按 索引欄位【欄分組: 分組值】
            if len(available_values) == 1:
                title = f'{chart_type} - {available_values[0]} 按 {index_display}\n【{columns_display}: {selected_group}】{ylabel_suffix}'
            else:
                values_text = ", ".join(available_values)
                title = f'{chart_type} - {values_text} 按 {index_display}\n【{columns_display}: {selected_group}】{ylabel_suffix}'
            
            ax.set_title(title, fontsize=self.title_fontsize, pad=20)
            ax.set_xlabel(index_display, fontsize=self.label_fontsize)
            ax.set_ylabel(f'{", ".join(available_values)}{ylabel_suffix}', fontsize=self.label_fontsize)
            
            # 顯示圖例
            if ax.get_legend_handles_labels()[0]:
                ax.legend(fontsize=self.label_fontsize-2, loc='best')
            
            print(f"✅ 特殊長條圖繪製完成 - {chart_type} with {columns_display}: {selected_group}")
            
        except Exception as e:
            raise Exception(f"繪製特殊長條圖時發生錯誤: {str(e)}")


    def _show_group_selection_dialog_for_bar_chart(self, available_groups, columns_display, chart_type):
        """顯示長條圖的分組選擇對話框 - 改善版：明確說明選擇結果"""
        try:
            from PyQt6.QtWidgets import QDialog, QVBoxLayout, QLabel, QComboBox, QPushButton, QHBoxLayout
            
            dialog = QDialog(self)
            dialog.setWindowTitle(f"選擇{columns_display} - {chart_type}")
            dialog.setFixedSize(432, 252)
            
            layout = QVBoxLayout(dialog)
            layout.setSpacing(14)
            layout.setContentsMargins(18, 18, 18, 18)
            
            # 說明標籤
            info_label = QLabel(
                f"檢測到多個{columns_display}值：{', '.join(map(str, available_groups))}\n\n"
                f"請選擇要在{chart_type}中顯示的{columns_display}：\n"
                f"圖表標題將顯示為「{chart_type} - 值欄位 按 索引欄位【{columns_display}: 選擇值】」"
            )
            info_label.setWordWrap(True)
            info_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #2c3e50;
                    padding: 11px;
                    background-color: #f8f9fa;
                    border: 1px solid #dee2e6;
                    border-radius: 7px;
                    margin: 5px;
                    line-height: 1.4;
                }
            """)
            layout.addWidget(info_label)
            
            # 下拉選單
            combo = QComboBox()
            combo.addItems([str(group) for group in available_groups])
            combo.setStyleSheet("""
                QComboBox {
                    font-size: 14px;
                    padding: 9px;
                    border: 2px solid #3498db;
                    border-radius: 6px;
                    background-color: white;
                    min-height: 30px;
                }
                QComboBox:focus {
                    border: 2px solid #2980b9;
                }
            """)
            layout.addWidget(combo)
            
            # 說明文字
            note_label = QLabel(f"💡 提示：{chart_type}將只顯示選擇的{columns_display}資料")
            note_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #7f8c8d;
                    font-style: italic;
                    padding: 7px;
                    background-color: #ecf0f1;
                    border-radius: 4px;
                    margin: 3px;
                }
            """)
            layout.addWidget(note_label)
            
            # 按鈕
            button_layout = QHBoxLayout()
            button_layout.setSpacing(11)
            
            ok_button = QPushButton("✓ 確定選擇")
            ok_button.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 10px 18px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #2ecc71;
                }
            """)
            ok_button.clicked.connect(dialog.accept)
            button_layout.addWidget(ok_button)
            
            cancel_button = QPushButton("✗ 使用預設")
            cancel_button.setStyleSheet("""
                QPushButton {
                    background-color: #95a5a6;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 10px 18px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #7f8c8d;
                }
            """)
            cancel_button.clicked.connect(dialog.reject)
            button_layout.addWidget(cancel_button)
            
            layout.addLayout(button_layout)
            
            # 顯示對話框
            result = dialog.exec()
            
            if result == QDialog.DialogCode.Accepted:
                selected_index = combo.currentIndex()
                selected_group = available_groups[selected_index]
                print(f"用戶選擇了{columns_display}: {selected_group}")
                return selected_group
            else:
                print("用戶選擇使用預設處理")
                return None
                    
        except Exception as e:
            print(f"顯示長條圖選擇對話框時發生錯誤: {e}")
            return available_groups[0] if available_groups else None

    def _draw_bar_in_bar_chart_single_group(self, ax, plot_data, available_values, colors, x_pos):
        """繪製單一分組的Bar-in-bar圖表"""
        try:
            if len(available_values) < 2:
                QMessageBox.warning(self, "警告", "Bar-in-bar 圖表需要至少2個數值欄位!")
                return
            
            # 外層和內層資料
            outer_data = plot_data[available_values[0]].fillna(0)
            inner_data = plot_data[available_values[1]].fillna(0)
            
            # 計算長條寬度
            outer_width = 0.8
            inner_width = 0.6
            
            # 繪製外層長條
            outer_color = colors[0] if colors else '#3498db'
            outer_bars = ax.bar(x_pos, outer_data, width=outer_width, 
                            color=outer_color, alpha=0.7, label=available_values[0])
            
            # 繪製內層長條
            inner_color = colors[1] if colors and len(colors) > 1 else '#e74c3c'
            inner_bars = ax.bar(x_pos, inner_data, width=inner_width, 
                            color=inner_color, alpha=0.9, label=available_values[1])
            
            # 添加數值標籤
            if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                for i, (outer_val, inner_val) in enumerate(zip(outer_data, inner_data)):
                    if not pd.isna(outer_val) and outer_val != 0:
                        formatted_outer = self._format_label_value(outer_val)
                        ax.text(i, outer_val + max(outer_data) * 0.01, 
                            formatted_outer, ha='center', va='bottom',
                            fontsize=self.label_fontsize-2)
                    
                    if not pd.isna(inner_val) and inner_val != 0:
                        formatted_inner = self._format_label_value(inner_val)
                        ax.text(i, inner_val + max(inner_data) * 0.01, 
                            formatted_inner, ha='center', va='bottom',
                            fontsize=self.label_fontsize-2, color='white', weight='bold')
            
        except Exception as e:
            raise Exception(f"繪製單一分組Bar-in-bar圖表時發生錯誤: {str(e)}")

    def _draw_overlapping_bar_chart_single_group(self, ax, plot_data, available_values, colors, x_pos):
        """繪製單一分組的重疊長條圖"""
        try:
            for i, val in enumerate(available_values):
                # 取得資料
                data_values = plot_data[val].fillna(0)
                
                # 計算透明度
                alpha = 0.7 - (i * 0.1)
                alpha = max(alpha, 0.3)
                
                # 取得顏色
                color = colors[i] if colors and i < len(colors) else None
                
                # 繪製重疊長條圖
                bars = ax.bar(x_pos, data_values, color=color, label=val, alpha=alpha, width=0.8)
                
                # 添加數值標籤
                if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                    for j, bar in enumerate(bars):
                        height = bar.get_height()
                        if not pd.isna(height) and height != 0:
                            formatted_value = self._format_label_value(height)
                            ax.text(bar.get_x() + bar.get_width()/2., height,
                                formatted_value, ha='center', va='bottom',
                                fontsize=self.label_fontsize-2)
            
        except Exception as e:
            raise Exception(f"繪製單一分組重疊長條圖時發生錯誤: {str(e)}")

    def _draw_combo_chart_single_group(self, ax, plot_data, available_values, colors, x_pos):
        """繪製單一分組的組合圖"""
        try:
            if len(available_values) < 2:
                QMessageBox.warning(self, "警告", "組合圖需要至少2個數值欄位!")
                return
            
            # 長條圖和折線圖資料
            bar_data = plot_data[available_values[0]].fillna(0)
            line_data = plot_data[available_values[1]].fillna(0)
            
            # 繪製長條圖
            bar_color = colors[0] if colors else '#1f77b4'
            bars = ax.bar(x_pos, bar_data.values, color=bar_color, alpha=0.7, 
                        width=0.6, label=available_values[0])
            
            # 創建右側Y軸用於折線圖
            ax2 = ax.twinx()
            
            # 繪製折線圖
            line_color = colors[1] if colors and len(colors) > 1 else '#ff7f0e'
            line = ax2.plot(x_pos, line_data.values, color=line_color, marker='o', 
                        linewidth=2, markersize=8, label=available_values[1])
            
            # 設定Y軸標籤和顏色
            aggfunc = self.aggfunc_combo.currentText()
            format_type = self.format_combo.currentText()
            ylabel_suffix = "(千)" if format_type == "thousands" else ""
            
            ax.set_ylabel(f"{aggfunc}({available_values[0]}){ylabel_suffix}", 
                        fontsize=self.label_fontsize, color=bar_color, fontweight='bold')
            ax2.set_ylabel(f"{aggfunc}({available_values[1]}){ylabel_suffix}", 
                        fontsize=self.label_fontsize, color=line_color, fontweight='bold')
            
            # 統一圖例管理
            handles = [bars]
            labels = [available_values[0]]
            
            if isinstance(line, list):
                handles.append(line[0])
            else:
                handles.append(line)
            labels.append(available_values[1])
            
            legend = ax.legend(handles, labels, loc='upper right', bbox_to_anchor=(0.98, 0.98),
                            fontsize=self.label_fontsize-1, frameon=True, fancybox=True,
                            shadow=True, title='圖例', title_fontsize=self.label_fontsize,
                            facecolor='white', edgecolor='gray', framealpha=0.9)
            
            legend.get_title().set_fontweight('bold')
            
            # 設定Y軸刻度顏色
            ax.tick_params(axis='y', labelcolor=bar_color, labelsize=self.label_fontsize-2)
            ax2.tick_params(axis='y', labelcolor=line_color, labelsize=self.label_fontsize-2)
            ax.tick_params(axis='x', labelsize=self.label_fontsize-2)
            
            # 添加數值標籤
            if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                # 長條圖標籤
                for i, (x, y) in enumerate(zip(x_pos, bar_data.values)):
                    if not pd.isna(y) and y != 0:
                        formatted_value = self._format_label_value(y)
                        ax.annotate(formatted_value, (x, y), textcoords="offset points", 
                                xytext=(0, 5), ha='center', fontsize=self.label_fontsize-3,
                                color=bar_color, fontweight='bold')
                
                # 折線圖標籤
                for i, (x, y) in enumerate(zip(x_pos, line_data.values)):
                    if not pd.isna(y) and y != 0:
                        formatted_value = self._format_label_value(y)
                        ax2.annotate(formatted_value, (x, y), textcoords="offset points", 
                                    xytext=(0, 10), ha='center', fontsize=self.label_fontsize-3,
                                    color=line_color, fontweight='bold')
            
            # 添加網格
            ax.grid(True, alpha=0.3, axis='both')
            ax2.grid(False)
            
            # 套用數值格式
            self._apply_chart_formatting(ax, bar_data)
            self._apply_chart_formatting(ax2, line_data)
            
        except Exception as e:
            raise Exception(f"繪製單一分組組合圖時發生錯誤: {str(e)}")

    def _draw_grouped_bar_chart_with_columns(self, ax, pivot_table, values_cols, values_cols_display, 
                                        index_display, columns_display, colors):
        """繪製帶欄分組的群組長條圖"""
        try:
            print(f"開始繪製帶欄分組的群組長條圖")
            print(f"樞紐表形狀: {pivot_table.shape}")
            print(f"樞紐表欄位結構: {pivot_table.columns}")
            
            # 處理MultiIndex columns
            if isinstance(pivot_table.columns, pd.MultiIndex):
                # 重新組織資料結構
                organized_data = self._organize_multiindex_data(pivot_table, values_cols, values_cols_display)
            else:
                # 如果不是MultiIndex，按原有邏輯處理
                organized_data = self._organize_simple_data(pivot_table, values_cols, values_cols_display)
            
            if not organized_data:
                raise Exception("無法組織資料結構")
            
            # 準備繪圖
            index_labels = pivot_table.index.tolist()
            x_pos = np.arange(len(index_labels))
            
            # 計算分組資訊
            n_groups = len(organized_data)  # 有多少個欄分組（如年度數量）
            n_values = len(values_cols_display)  # 有多少個值欄位（如動支數、預算數）
            total_bars = n_groups * n_values  # 總長條數
            
            bar_width = 0.8 / total_bars  # 每根長條的寬度
            group_width = bar_width * n_values  # 每個欄分組的總寬度
            
            print(f"繪圖參數: n_groups={n_groups}, n_values={n_values}, total_bars={total_bars}")
            
            # 繪製長條圖
            legend_handles = []
            legend_labels = []
            
            for group_idx, (group_name, group_data) in enumerate(organized_data.items()):
                for value_idx, value_name in enumerate(values_cols_display):
                    if value_name in group_data:
                        # 計算位置偏移
                        bar_idx = group_idx * n_values + value_idx
                        offset = (bar_idx - total_bars/2 + 0.5) * bar_width
                        
                        # 取得資料
                        data_values = group_data[value_name].fillna(0)
                        
                        # 取得顏色
                        color_idx = value_idx * n_groups + group_idx
                        color = colors[color_idx % len(colors)] if colors else None
                        
                        # 繪製長條
                        bars = ax.bar(x_pos + offset, data_values, bar_width, 
                                    color=color, alpha=0.8,
                                    label=f"{value_name} ({group_name})")
                        
                        # 記錄圖例
                        legend_handles.append(bars[0])
                        legend_labels.append(f"{value_name} ({group_name})")
                        
                        # 添加數值標籤
                        if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                            for i, bar in enumerate(bars):
                                height = bar.get_height()
                                if not pd.isna(height) and height != 0:
                                    formatted_value = self._format_label_value(height)
                                    ax.text(bar.get_x() + bar.get_width()/2., height,
                                        formatted_value, ha='center', va='bottom',
                                        fontsize=self.label_fontsize-4, rotation=45)
            
            # 設定X軸
            ax.set_xticks(x_pos)
            ax.set_xticklabels(index_labels, rotation=45, ha='right')
            
            # 設定圖例
            if legend_handles:
                ax.legend(legend_handles, legend_labels, 
                        fontsize=self.label_fontsize-3, 
                        loc='upper left', 
                        bbox_to_anchor=(1.02, 1))
            
            print("✅ 帶欄分組的群組長條圖繪製完成")
            
        except Exception as e:
            raise Exception(f"繪製帶欄分組的群組長條圖時發生錯誤: {str(e)}")

    def _draw_stacked_bar_chart_with_columns(self, ax, pivot_table, values_cols, values_cols_display,
                                        index_display, columns_display, colors):
        """繪製帶欄分組的堆疊長條圖"""
        try:
            print(f"開始繪製帶欄分組的堆疊長條圖")
            
            # 處理MultiIndex columns
            if isinstance(pivot_table.columns, pd.MultiIndex):
                organized_data = self._organize_multiindex_data(pivot_table, values_cols, values_cols_display)
            else:
                organized_data = self._organize_simple_data(pivot_table, values_cols, values_cols_display)
            
            if not organized_data:
                raise Exception("無法組織資料結構")
            
            # 準備繪圖
            index_labels = pivot_table.index.tolist()
            x_pos = np.arange(len(index_labels))
            
            n_groups = len(organized_data)
            group_width = 0.8 / n_groups
            
            # 為每個欄分組繪製堆疊長條圖
            legend_handles = []
            legend_labels = []
            
            for group_idx, (group_name, group_data) in enumerate(organized_data.items()):
                # 計算位置偏移
                offset = (group_idx - n_groups/2 + 0.5) * group_width
                
                # 初始化底部位置
                bottom = np.zeros(len(index_labels))
                
                for value_idx, value_name in enumerate(values_cols_display):
                    if value_name in group_data:
                        # 取得資料
                        data_values = group_data[value_name].fillna(0)
                        
                        # 取得顏色
                        color_idx = value_idx * n_groups + group_idx
                        color = colors[color_idx % len(colors)] if colors else None
                        
                        # 繪製堆疊長條
                        bars = ax.bar(x_pos + offset, data_values, group_width,
                                    bottom=bottom, color=color, alpha=0.8,
                                    label=f"{value_name} ({group_name})")
                        
                        # 記錄圖例
                        legend_handles.append(bars[0])
                        legend_labels.append(f"{value_name} ({group_name})")
                        
                        # 添加數值標籤
                        if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                            for i, bar in enumerate(bars):
                                height = bar.get_height()
                                if not pd.isna(height) and height != 0:
                                    formatted_value = self._format_label_value(height)
                                    ax.text(bar.get_x() + bar.get_width()/2.,
                                        bottom[i] + height/2,
                                        formatted_value, ha='center', va='center',
                                        fontsize=self.label_fontsize-4)
                        
                        # 更新底部位置
                        bottom += data_values
            
            # 設定X軸
            ax.set_xticks(x_pos)
            ax.set_xticklabels(index_labels, rotation=45, ha='right')
            
            # 設定圖例
            if legend_handles:
                ax.legend(legend_handles, legend_labels,
                        fontsize=self.label_fontsize-3,
                        loc='upper left',
                        bbox_to_anchor=(1.02, 1))
            
            print("✅ 帶欄分組的堆疊長條圖繪製完成")
            
        except Exception as e:
            raise Exception(f"繪製帶欄分組的堆疊長條圖時發生錯誤: {str(e)}")

    def _organize_multiindex_data(self, pivot_table, values_cols, values_cols_display):
        """組織MultiIndex欄位的資料結構"""
        try:
            print("開始組織MultiIndex資料結構")
            organized_data = {}
            
            # 分析MultiIndex結構
            if len(pivot_table.columns.levels) >= 2:
                # 第一層：值欄位，第二層：分組欄位（如年度）
                for value_col in values_cols_display:
                    for group_col in pivot_table.columns.levels[1]:
                        group_name = str(group_col)
                        if group_name not in organized_data:
                            organized_data[group_name] = {}
                        
                        # 找對應的原始欄位名稱
                        original_value_col = self._get_original_column_name(value_col)
                        
                        # 檢查該欄位組合是否存在
                        if (original_value_col, group_col) in pivot_table.columns:
                            organized_data[group_name][value_col] = pivot_table[(original_value_col, group_col)]
                        elif (group_col, original_value_col) in pivot_table.columns:
                            organized_data[group_name][value_col] = pivot_table[(group_col, original_value_col)]
            
            print(f"組織完成，分組數: {len(organized_data)}")
            for group_name, group_data in organized_data.items():
                print(f"  分組 {group_name}: {list(group_data.keys())}")
            
            return organized_data
            
        except Exception as e:
            print(f"組織MultiIndex資料時發生錯誤: {e}")
            return {}

    def _organize_simple_data(self, pivot_table, values_cols, values_cols_display):
        """組織簡單資料結構（無欄分組）"""
        try:
            print("組織簡單資料結構（無欄分組）")
            organized_data = {"全部": {}}
            
            for value_display, value_original in zip(values_cols_display, values_cols):
                if value_original in pivot_table.columns:
                    organized_data["全部"][value_display] = pivot_table[value_original]
            
            return organized_data
            
        except Exception as e:
            print(f"組織簡單資料時發生錯誤: {e}")
            return {}

    def get_selected_values_with_original_names(self):
        """取得選擇的值欄位 - 返回原始欄位名稱"""
        display_values = self.get_selected_values()  # 取得顯示名稱
        
        # 轉換為原始名稱
        original_values = []
        for display_val in display_values:
            original_val = self._get_original_column_name(display_val)
            if original_val:
                original_values.append(original_val)
        
        return original_values

    def clear_chart_display(self):
        """清除圖表顯示"""
        try:
            if hasattr(self, 'chart_layout'):
                # 移除除了預設標籤以外的所有widget
                for i in reversed(range(self.chart_layout.count())):
                    child = self.chart_layout.itemAt(i).widget()
                    if child and child != getattr(self, 'default_chart_label', None):
                        child.setParent(None)
            
            # 顯示預設標籤
            if hasattr(self, 'default_chart_label'):
                self.default_chart_label.setVisible(True)
                
        except Exception as e:
            print(f"清除圖表顯示時發生錯誤：{e}")

    def update_filter_controls(self):
        """更新篩選控制項 - 重新導向到支援重命名的版本"""
        self.update_filter_controls_with_rename()

