    def _draw_grouped_bar_chart(self, ax, pivot_table, values, colors):
        """繪製群組長條圖 - 修正版"""
        try:
            print(f"開始繪製群組長條圖，pivot_table形狀: {pivot_table.shape}")
            print(f"pivot_table欄位: {list(pivot_table.columns)}")
            print(f"要求的values: {values}")
            
            x_pos = np.arange(len(pivot_table.index))
            print(f"x_pos長度: {len(x_pos)}")
            
            # 找出實際可用的欄位
            available_columns = list(pivot_table.columns)
            available_values = []
            
            # 匹配可用的欄位
            for val in values:
                # 直接匹配
                if val in available_columns:
                    available_values.append(val)
                else:
                    # 模糊匹配（包含該值的欄位名稱）
                    matching_cols = [col for col in available_columns if val in str(col)]
                    if matching_cols:
                        available_values.extend(matching_cols[:1])  # 只取第一個匹配的
            
            if not available_values:
                raise Exception(f"找不到匹配的欄位。可用欄位: {available_columns}")
            
            print(f"實際使用的欄位: {available_values}")
            
            # 計算長條寬度
            width = 0.8 / len(available_values)
            
            for i, val in enumerate(available_values):
                try:
                    # 取得資料
                    data_values = pivot_table[val].fillna(0)
                    print(f"欄位 {val} 的資料長度: {len(data_values)}")
                    
                    # 檢查資料長度
                    if len(data_values) != len(x_pos):
                        print(f"警告：資料長度不匹配 - x_pos: {len(x_pos)}, data: {len(data_values)}")
                        continue
                    
                    # 計算位置偏移
                    offset = (i - len(available_values)/2 + 0.5) * width
                    
                    # 取得顏色
                    color = colors[i] if colors and i < len(colors) else None
                    
                    # 繪製長條圖
                    bars = ax.bar(x_pos + offset, data_values, width, 
                                color=color, label=val, alpha=0.8)
                    
                    # 添加數值標籤
                    if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                        for j, bar in enumerate(bars):
                            height = bar.get_height()
                            if not pd.isna(height) and height != 0:
                                formatted_value = self._format_label_value(height)
                                ax.text(bar.get_x() + bar.get_width()/2., height,
                                    formatted_value, ha='center', va='bottom',
                                    fontsize=self.label_fontsize-2)
                    
                except Exception as e:
                    print(f"處理欄位 {val} 時發生錯誤: {e}")
                    continue
            
            # 設定X軸標籤
            ax.set_xticks(x_pos)
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
        except Exception as e:
            raise Exception(f"繪製群組長條圖時發生錯誤: {str(e)}")

    def _draw_stacked_bar_chart(self, ax, pivot_table, values, colors):
        """繪製堆疊長條圖 - 修正版"""
        try:
            print(f"開始繪製堆疊長條圖，pivot_table形狀: {pivot_table.shape}")
            
            x_pos = np.arange(len(pivot_table.index))
            bottom = np.zeros(len(pivot_table.index))
            
            # 找出實際可用的欄位
            available_columns = list(pivot_table.columns)
            available_values = []
            
            for val in values:
                if val in available_columns:
                    available_values.append(val)
                else:
                    matching_cols = [col for col in available_columns if val in str(col)]
                    if matching_cols:
                        available_values.extend(matching_cols[:1])
            
            if not available_values:
                raise Exception(f"找不到匹配的欄位。可用欄位: {available_columns}")
            
            for i, val in enumerate(available_values):
                try:
                    # 取得資料
                    data_values = pivot_table[val].fillna(0)
                    
                    # 檢查資料長度
                    if len(data_values) != len(x_pos):
                        print(f"警告：資料長度不匹配 - x_pos: {len(x_pos)}, data: {len(data_values)}")
                        continue
                    
                    # 取得顏色
                    color = colors[i] if colors and i < len(colors) else None
                    
                    # 繪製堆疊長條圖
                    bars = ax.bar(x_pos, data_values, bottom=bottom, 
                                color=color, label=val, alpha=0.8)
                    
                    # 添加數值標籤
                    if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                        for j, bar in enumerate(bars):
                            height = bar.get_height()
                            if not pd.isna(height) and height != 0:
                                formatted_value = self._format_label_value(height)
                                ax.text(bar.get_x() + bar.get_width()/2., 
                                    bottom[j] + height/2,
                                    formatted_value, ha='center', va='center',
                                    fontsize=self.label_fontsize-2)
                    
                    # 更新底部位置
                    bottom += data_values
                    
                except Exception as e:
                    print(f"處理欄位 {val} 時發生錯誤: {e}")
                    continue
            
            # 設定X軸標籤
            ax.set_xticks(x_pos)
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
        except Exception as e:
            raise Exception(f"繪製堆疊長條圖時發生錯誤: {str(e)}")

    def _draw_bar_in_bar_chart(self, ax, pivot_table, values, colors):
        """繪製 Bar-in-bar 圖表 - 修正版"""
        try:
            print(f"開始繪製 Bar-in-bar 圖表，pivot_table形狀: {pivot_table.shape}")
            
            # 找出實際可用的欄位
            available_columns = list(pivot_table.columns)
            available_values = []
            
            for val in values:
                if val in available_columns:
                    available_values.append(val)
                else:
                    matching_cols = [col for col in available_columns if val in str(col)]
                    if matching_cols:
                        available_values.extend(matching_cols[:1])
            
            if len(available_values) < 2:
                QMessageBox.warning(self, "警告", "Bar-in-bar 圖表需要至少2個數值欄位!")
                return
            
            x_pos = np.arange(len(pivot_table.index))
            
            # 計算長條寬度
            outer_width = 0.8
            inner_width = 0.6
            
            # 確保資料是數值型且處理 NaN 值
            outer_data = pivot_table[available_values[0]].fillna(0)
            inner_data = pivot_table[available_values[1]].fillna(0)
            
            # 檢查資料長度
            if len(outer_data) != len(x_pos) or len(inner_data) != len(x_pos):
                raise Exception("資料長度不匹配")
            
            # 繪製外層長條（第一個數值）
            outer_color = colors[0] if colors else '#3498db'
            outer_bars = ax.bar(x_pos, outer_data, 
                            width=outer_width, 
                            color=outer_color, 
                            alpha=0.7,
                            label=available_values[0])
            
            # 繪製內層長條（第二個數值）
            inner_color = colors[1] if colors and len(colors) > 1 else '#e74c3c'
            inner_bars = ax.bar(x_pos, inner_data, 
                            width=inner_width, 
                            color=inner_color, 
                            alpha=0.9,
                            label=available_values[1])
            
            # 添加數值標籤
            if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                for i, (outer_val, inner_val) in enumerate(zip(outer_data, inner_data)):
                    if not pd.isna(outer_val) and outer_val != 0:
                        formatted_outer = self._format_label_value(outer_val)
                        ax.text(i, outer_val + max(outer_data) * 0.01, 
                            formatted_outer, ha='center', va='bottom',
                            fontsize=self.label_fontsize-2)
                    
                    if not pd.isna(inner_val) and inner_val != 0:
                        formatted_inner = self._format_label_value(inner_val)
                        ax.text(i, inner_val + max(inner_data) * 0.01, 
                            formatted_inner, ha='center', va='bottom',
                            fontsize=self.label_fontsize-2, color='white', weight='bold')
            
            # 設定X軸標籤
            ax.set_xticks(x_pos)
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
        except Exception as e:
            raise Exception(f"繪製 Bar-in-bar 圖表時發生錯誤: {str(e)}")

    def _draw_overlapping_bar_chart(self, ax, pivot_table, values, colors):
        """繪製重疊長條圖 - 修正版"""
        try:
            print(f"開始繪製重疊長條圖，pivot_table形狀: {pivot_table.shape}")
            
            x_pos = np.arange(len(pivot_table.index))
            
            # 找出實際可用的欄位
            available_columns = list(pivot_table.columns)
            available_values = []
            
            for val in values:
                if val in available_columns:
                    available_values.append(val)
                else:
                    matching_cols = [col for col in available_columns if val in str(col)]
                    if matching_cols:
                        available_values.extend(matching_cols[:1])
            
            if not available_values:
                raise Exception(f"找不到匹配的欄位。可用欄位: {available_columns}")
            
            for i, val in enumerate(available_values):
                try:
                    # 取得資料
                    data_values = pivot_table[val].fillna(0)
                    
                    # 檢查資料長度
                    if len(data_values) != len(x_pos):
                        print(f"警告：資料長度不匹配 - x_pos: {len(x_pos)}, data: {len(data_values)}")
                        continue
                    
                    # 計算透明度
                    alpha = 0.7 - (i * 0.1)
                    alpha = max(alpha, 0.3)
                    
                    # 取得顏色
                    color = colors[i] if colors and i < len(colors) else None
                    
                    # 繪製重疊長條圖
                    bars = ax.bar(x_pos, data_values, 
                                color=color, label=val, alpha=alpha, width=0.8)
                    
                    # 添加數值標籤
                    if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                        for j, bar in enumerate(bars):
                            height = bar.get_height()
                            if not pd.isna(height) and height != 0:
                                formatted_value = self._format_label_value(height)
                                ax.text(bar.get_x() + bar.get_width()/2., height,
                                    formatted_value, ha='center', va='bottom',
                                    fontsize=self.label_fontsize-2)
                    
                except Exception as e:
                    print(f"處理欄位 {val} 時發生錯誤: {e}")
                    continue
            
            # 設定X軸標籤
            ax.set_xticks(x_pos)
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
        except Exception as e:
            raise Exception(f"繪製重疊長條圖時發生錯誤: {str(e)}")
    def generate_line_chart(self):
        """生成折線圖 - 修正版：支援欄分組並明確標示年度"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.critical(self, "錯誤", "沒有資料可生成圖表!")
                return
            
            # 獲取顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            
            if not index_display:
                QMessageBox.critical(self, "錯誤", "請選擇列(Index)欄位!")
                return
            
            if not values_display:
                QMessageBox.critical(self, "錯誤", "請至少選擇一個值(Values)欄位!")
                return
            
            # *** 修正關鍵：轉換為原始名稱 ***
            index = self._get_original_column_name(index_display)
            columns = self._get_original_column_name(columns_display) if columns_display else None
            values = [self._get_original_column_name(val) for val in values_display if val]
            
            print(f"折線圖設定:")
            print(f"  列(Index): {index_display} -> {index}")
            print(f"  欄(Columns): {columns_display} -> {columns}")
            print(f"  值(Values): {values_display} -> {values}")
            
            # 確保數值型
            df_copy = self.current_data.copy()
            for val in values:
                df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
            
            # 應用風格
            sns.set_style(self.style_combo.currentText())
            sns.set_context(self.context_combo.currentText())
            sns.set_palette(self.palette_combo.currentText())
            set_chinese_font()
            
            # 生成樞紐表 - 使用原始名稱
            pivot_params = {
                'values': values,
                'index': index,
                'aggfunc': aggfunc,
                'fill_value': 0,
                'margins': False
            }
            
            if columns:
                pivot_params['columns'] = columns
            
            pivot_table = pd.pivot_table(df_copy, **pivot_params)
            
            # 檢查是否需要千位格式轉換
            format_type = self.format_combo.currentText()
            if format_type == "thousands":
                pivot_table = pivot_table / 1000
                pivot_table = pivot_table.round(0)
            
            ylabel_suffix = "(千)" if format_type == "thousands" else ""
            
            # *** 關鍵修正：處理欄分組情況 ***
            if columns and isinstance(pivot_table.columns, pd.MultiIndex):
                # 有欄分組的情況 - 讓用戶選擇處理方式
                self._handle_line_chart_with_columns(pivot_table, index_display, columns_display, 
                                                values_display, aggfunc, ylabel_suffix)
            else:
                # 無欄分組的情況 - 使用原有邏輯
                self._draw_simple_line_chart(pivot_table, index_display, values_display, 
                                        aggfunc, ylabel_suffix)
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"生成折線圖錯誤: {str(e)}")

    def _handle_line_chart_with_columns(self, pivot_table, index_display, columns_display, 
                                    values_display, aggfunc, ylabel_suffix):
        """處理有欄分組的折線圖"""
        try:
            print("處理有欄分組的折線圖")
            print(f"樞紐表欄位結構: {pivot_table.columns}")
            
            # 分析可用的欄分組值（如不同年度）
            if isinstance(pivot_table.columns, pd.MultiIndex):
                # 取得所有分組值
                available_groups = list(pivot_table.columns.levels[1])
                print(f"可用的{columns_display}值: {available_groups}")
                
                # 如果只有一個分組，直接使用
                if len(available_groups) == 1:
                    selected_group = available_groups[0]
                    self._draw_single_group_line_chart(pivot_table, selected_group, index_display, 
                                                    columns_display, values_display, aggfunc, ylabel_suffix)
                else:
                    # 多個分組 - 提供選擇對話框
                    selected_group = self._show_group_selection_dialog(available_groups, columns_display)
                    if selected_group is not None:
                        self._draw_single_group_line_chart(pivot_table, selected_group, index_display, 
                                                        columns_display, values_display, aggfunc, ylabel_suffix)
                    else:
                        # 用戶取消選擇，繪製多線圖
                        self._draw_multi_group_line_chart(pivot_table, available_groups, index_display, 
                                                        columns_display, values_display, aggfunc, ylabel_suffix)
            else:
                # 不是MultiIndex，按原有邏輯處理
                self._draw_simple_line_chart(pivot_table, index_display, values_display, aggfunc, ylabel_suffix)
                
        except Exception as e:
            raise Exception(f"處理有欄分組的折線圖時發生錯誤: {str(e)}")

    # 修正1: 優化折線圖對話框，參考長條圖樣式
    def _show_group_selection_dialog(self, available_groups, columns_display):
        """顯示折線圖分組選擇對話框 - 優化版：參考長條圖樣式"""
        try:
            from PyQt6.QtWidgets import QDialog, QVBoxLayout, QLabel, QComboBox, QPushButton, QHBoxLayout
            
            dialog = QDialog(self)
            dialog.setWindowTitle(f"選擇{columns_display} - 折線圖")
            dialog.setFixedSize(405, 225)
            
            # 設定對話框樣式
            dialog.setStyleSheet("""
                QDialog {
                    background-color: #f8f9fa;
                    border: 2px solid #3498db;
                    border-radius: 9px;
                }
            """)
            
            layout = QVBoxLayout(dialog)
            layout.setSpacing(14)
            layout.setContentsMargins(18, 18, 18, 18)
            
            # 說明標籤 - 與長條圖樣式一致
            info_label = QLabel(f"檢測到多個{columns_display}值，請選擇要在折線圖中顯示的{columns_display}：")
            info_label.setWordWrap(True)
            info_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #2c3e50;
                    padding: 9px;
                    background-color: #f8f9fa;
                    border: 1px solid #dee2e6;
                    border-radius: 5px;
                    margin: 5px;
                }
            """)
            layout.addWidget(info_label)
            
            # 下拉選單 - 與長條圖樣式一致
            combo = QComboBox()
            combo.addItems([str(group) for group in available_groups])
            combo.addItem("顯示所有（多條線）")
            combo.setStyleSheet("""
                QComboBox {
                    font-size: 14px;
                    padding: 7px;
                    border: 2px solid #3498db;
                    border-radius: 5px;
                    background-color: white;
                    min-height: 30px;
                }
                QComboBox:focus {
                    border: 2px solid #2980b9;
                }
                QComboBox::drop-down {
                    border: none;
                    width: 30px;
                }
                QComboBox::down-arrow {
                    image: none;
                    border-left: 5px solid transparent;
                    border-right: 5px solid transparent;
                    border-top: 5px solid #3498db;
                    margin-right: 5px;
                }
            """)
            layout.addWidget(combo)
            
            # 說明文字 - 添加圖表類型特定說明
            note_label = QLabel(f"💡 提示：折線圖支援單一{columns_display}清楚顯示趨勢，或選擇多條線比較不同{columns_display}")
            note_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #7f8c8d;
                    font-style: italic;
                    padding: 5px;
                    background-color: #ecf0f1;
                    border-radius: 3px;
                    margin: 3px;
                }
            """)
            layout.addWidget(note_label)
            
            # 按鈕區域 - 與長條圖樣式一致
            button_layout = QHBoxLayout()
            button_layout.setSpacing(9)
            
            ok_button = QPushButton("✓ 確定選擇")
            ok_button.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 8px 18px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #2ecc71;
                }
                QPushButton:pressed {
                    background-color: #229954;
                }
            """)
            ok_button.clicked.connect(dialog.accept)
            button_layout.addWidget(ok_button)
            
            cancel_button = QPushButton("✗ 顯示所有")
            cancel_button.setStyleSheet("""
                QPushButton {
                    background-color: #95a5a6;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 8px 18px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #7f8c8d;
                }
                QPushButton:pressed {
                    background-color: #6c7b7d;
                }
            """)
            cancel_button.clicked.connect(dialog.reject)
            button_layout.addWidget(cancel_button)
            
            layout.addLayout(button_layout)
            
            # 顯示對話框
            result = dialog.exec()
            
            if result == QDialog.DialogCode.Accepted:
                selected_index = combo.currentIndex()
                if selected_index < len(available_groups):
                    selected_group = available_groups[selected_index]
                    print(f"折線圖用戶選擇了{columns_display}: {selected_group}")
                    return selected_group
                else:
                    print("折線圖用戶選擇顯示所有")
                    return None  # 選擇顯示所有
            else:
                print("折線圖用戶選擇顯示所有")
                return None  # 預設顯示所有
                
        except Exception as e:
            print(f"顯示折線圖選擇對話框時發生錯誤: {e}")
            return None  # 出錯時顯示所有

    def _draw_single_group_line_chart(self, pivot_table, selected_group, index_display, 
                                    columns_display, values_display, aggfunc, ylabel_suffix):
        """繪製單一分組的折線圖"""
        try:
            print(f"繪製單一分組折線圖，選擇的{columns_display}: {selected_group}")
            
            # 生成圖表
            fig, ax = plt.subplots(figsize=(12, 8))
            
            colors = self.chart_colors if self.chart_colors else None
            lines = []
            
            # 處理選定分組的資料
            plot_data = pd.DataFrame(index=pivot_table.index)
            
            for i, value_display in enumerate(values_display):
                value_original = self._get_original_column_name(value_display)
                
                # 尋找對應的欄位
                if (value_original, selected_group) in pivot_table.columns:
                    plot_data[value_display] = pivot_table[(value_original, selected_group)]
                elif (selected_group, value_original) in pivot_table.columns:
                    plot_data[value_display] = pivot_table[(selected_group, value_original)]
                else:
                    print(f"找不到欄位組合: {value_original} x {selected_group}")
                    continue
                
                # 繪製線條
                color = colors[i] if colors and i < len(colors) else None
                data_values = plot_data[value_display].fillna(0)
                
                line = ax.plot(range(len(pivot_table.index)), data_values, 
                            marker='o', linewidth=2, markersize=6, 
                            color=color, label=value_display)
                lines.append(line[0])
                
                # 添加數值標籤
                if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                    for j, (x, y) in enumerate(zip(range(len(pivot_table.index)), data_values)):
                        if not pd.isna(y) and y != 0:
                            formatted_value = self._format_label_value(y)
                            offset_y = 5 + (i * 15)
                            ax.annotate(formatted_value, 
                                    (j, y),
                                    textcoords="offset points", 
                                    xytext=(0, offset_y), 
                                    ha='center',
                                    va='bottom',
                                    fontsize=self.label_fontsize-3,
                                    color=color if color else 'black',
                                    fontweight='bold',
                                    bbox=dict(boxstyle="round,pad=0.3", 
                                            facecolor='white', 
                                            edgecolor=color if color else 'black',
                                            alpha=0.8))
            
            # 設定X軸刻度
            ax.set_xticks(range(len(pivot_table.index)))
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
            # 設定標題和標籤 - 明確標示選擇的分組
            title = f"折線圖 - {index_display} vs {', '.join(values_display)} ({aggfunc})\n【{columns_display}: {selected_group}】{ylabel_suffix}"
            plt.title(title, fontsize=self.title_fontsize, pad=20)
            plt.xlabel(index_display, fontsize=self.label_fontsize)
            plt.ylabel(f"{aggfunc}({', '.join(values_display)}){ylabel_suffix}", fontsize=self.label_fontsize)
            plt.xticks(fontsize=self.label_fontsize)
            plt.yticks(fontsize=self.label_fontsize)
            
            # 套用數值格式
            self._apply_chart_formatting(ax, plot_data)
            
            # 顯示圖例和網格
            if len(values_display) > 1:
                plt.legend(values_display, fontsize=self.label_fontsize-2, loc='best')
            plt.grid(True, alpha=0.3)
            
            plt.tight_layout()
            
            self.current_figure = fig
            self.display_chart(fig)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
            print(f"✅ 單一分組折線圖繪製完成 - {columns_display}: {selected_group}")
            
        except Exception as e:
            raise Exception(f"繪製單一分組折線圖時發生錯誤: {str(e)}")

    def _draw_multi_group_line_chart(self, pivot_table, available_groups, index_display, 
                                    columns_display, values_display, aggfunc, ylabel_suffix):
        """繪製多分組的折線圖（每個分組一條線）"""
        try:
            print(f"繪製多分組折線圖，分組數: {len(available_groups)}")
            
            # 生成圖表
            fig, ax = plt.subplots(figsize=(14, 8))
            
            # 為每個分組和每個值欄位分配顏色
            total_lines = len(available_groups) * len(values_display)
            colors = self.get_chart_colors(total_lines)
            
            lines = []
            legend_labels = []
            line_idx = 0
            
            for group_idx, group in enumerate(available_groups):
                for value_idx, value_display in enumerate(values_display):
                    value_original = self._get_original_column_name(value_display)
                    
                    # 尋找對應的欄位
                    if (value_original, group) in pivot_table.columns:
                        data_values = pivot_table[(value_original, group)].fillna(0)
                    elif (group, value_original) in pivot_table.columns:
                        data_values = pivot_table[(group, value_original)].fillna(0)
                    else:
                        print(f"找不到欄位組合: {value_original} x {group}")
                        continue
                    
                    # 設定線條樣式
                    color = colors[line_idx % len(colors)] if colors else None
                    linestyle = '-' if value_idx == 0 else '--'  # 第一個值用實線，其他用虛線
                    marker = 'o' if value_idx == 0 else 's'      # 第一個值用圓點，其他用方點
                    
                    # 繪製線條
                    line = ax.plot(range(len(pivot_table.index)), data_values, 
                                marker=marker, linewidth=2, markersize=6, 
                                color=color, linestyle=linestyle,
                                label=f"{value_display} ({group})")
                    lines.append(line[0])
                    legend_labels.append(f"{value_display} ({group})")
                    
                    line_idx += 1
            
            # 設定X軸刻度
            ax.set_xticks(range(len(pivot_table.index)))
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
            # 設定標題和標籤 - 標示包含所有分組
            groups_text = ", ".join([str(g) for g in available_groups])
            title = f"折線圖 - {index_display} vs {', '.join(values_display)} ({aggfunc})\n【{columns_display}: {groups_text}】{ylabel_suffix}"
            plt.title(title, fontsize=self.title_fontsize, pad=20)
            plt.xlabel(index_display, fontsize=self.label_fontsize)
            plt.ylabel(f"{aggfunc}({', '.join(values_display)}){ylabel_suffix}", fontsize=self.label_fontsize)
            plt.xticks(fontsize=self.label_fontsize)
            plt.yticks(fontsize=self.label_fontsize)
            
            # 套用數值格式
            self._apply_chart_formatting(ax, pivot_table)
            
            # 顯示圖例和網格
            plt.legend(legend_labels, fontsize=self.label_fontsize-3, 
                    loc='center left', bbox_to_anchor=(1, 0.5))
            plt.grid(True, alpha=0.3)
            
            plt.tight_layout()
            
            self.current_figure = fig
            self.display_chart(fig)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
            print(f"✅ 多分組折線圖繪製完成 - 包含{len(available_groups)}個{columns_display}")
            
        except Exception as e:
            raise Exception(f"繪製多分組折線圖時發生錯誤: {str(e)}")

    def _draw_simple_line_chart(self, pivot_table, index_display, values_display, aggfunc, ylabel_suffix):
        """繪製簡單折線圖（無欄分組）"""
        try:
            print("繪製簡單折線圖（無欄分組）")
            
            # 處理樞紐表結構
            if isinstance(pivot_table.columns, pd.MultiIndex):
                plot_data = pd.DataFrame()
                for val_display in values_display:
                    val_original = self._get_original_column_name(val_display)
                    if val_original in [col[0] for col in pivot_table.columns]:
                        val_data = pivot_table[val_original]
                        if isinstance(val_data, pd.DataFrame):
                            plot_data[val_display] = val_data.iloc[:, 0] if val_data.shape[1] > 0 else val_data
                        else:
                            plot_data[val_display] = val_data
                pivot_table = plot_data
            else:
                if len(values_display) == 1 and pivot_table.ndim == 1:
                    pivot_table = pd.DataFrame({values_display[0]: pivot_table})
                elif len(values_display) > 1:
                    # 重命名欄位為顯示名稱
                    rename_mapping = {}
                    for val_display in values_display:
                        val_original = self._get_original_column_name(val_display)
                        if val_original in pivot_table.columns:
                            rename_mapping[val_original] = val_display
                    
                    if rename_mapping:
                        pivot_table = pivot_table.rename(columns=rename_mapping)
                        pivot_table = pivot_table[[col for col in values_display if col in pivot_table.columns]]
            
            if pivot_table.empty:
                QMessageBox.critical(self, "錯誤", "樞紐表生成失敗，請檢查資料和設定!")
                return
            
            # 生成圖表
            fig, ax = plt.subplots(figsize=(12, 8))
            
            colors = self.chart_colors if self.chart_colors else None
            lines = []
            
            available_values = [val for val in values_display if val in pivot_table.columns]
            
            if not available_values:
                QMessageBox.critical(self, "錯誤", "選擇的值欄位在樞紐表中不存在")
                return
            
            for i, val in enumerate(available_values):
                color = colors[i] if colors and i < len(colors) else None
                data_values = pivot_table[val].fillna(0)
                
                line = ax.plot(range(len(pivot_table.index)), data_values, 
                            marker='o', linewidth=2, markersize=6, 
                            color=color, label=val)
                lines.append(line[0])
                
                # 添加數值標籤
                if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                    for j, (x, y) in enumerate(zip(range(len(pivot_table.index)), data_values)):
                        if not pd.isna(y) and y != 0:
                            formatted_value = self._format_label_value(y)
                            offset_y = 5 + (i * 15)
                            ax.annotate(formatted_value, 
                                    (j, y),
                                    textcoords="offset points", 
                                    xytext=(0, offset_y), 
                                    ha='center',
                                    va='bottom',
                                    fontsize=self.label_fontsize-3,
                                    color=color if color else 'black',
                                    fontweight='bold',
                                    bbox=dict(boxstyle="round,pad=0.3", 
                                            facecolor='white', 
                                            edgecolor=color if color else 'black',
                                            alpha=0.8))
            
            # 設定X軸刻度
            ax.set_xticks(range(len(pivot_table.index)))
            ax.set_xticklabels(pivot_table.index, rotation=45, ha='right')
            
            # 設定標題和標籤
            plt.title(f"折線圖 - {index_display} vs {', '.join(available_values)} ({aggfunc}){ylabel_suffix}", 
                    fontsize=self.title_fontsize, pad=20)
            plt.xlabel(index_display, fontsize=self.label_fontsize)
            plt.ylabel(f"{aggfunc}({', '.join(available_values)}){ylabel_suffix}", fontsize=self.label_fontsize)
            plt.xticks(fontsize=self.label_fontsize)
            plt.yticks(fontsize=self.label_fontsize)
            
            # 套用數值格式
            self._apply_chart_formatting(ax, pivot_table)
            
            # 顯示圖例和網格
            if len(available_values) > 1:
                plt.legend(available_values, fontsize=self.label_fontsize-2, loc='best')
            plt.grid(True, alpha=0.3)
            
            plt.tight_layout()
            
            self.current_figure = fig
            self.display_chart(fig)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
            print("✅ 簡單折線圖繪製完成")
            
        except Exception as e:
            raise Exception(f"繪製簡單折線圖時發生錯誤: {str(e)}")

    def _draw_combo_chart(self, ax, pivot_table, values, colors, aggfunc, index, columns, ylabel_suffix=""):
        """繪製組合圖（長條圖+折線圖）- 修正重命名問題版本"""
        try:
            if len(values) < 2:
                QMessageBox.warning(self, "警告", "組合圖需要至少2個數值欄位！")
                return
            
            # *** 修正關鍵：values 參數已經是原始名稱，但需要取得對應的顯示名稱用於標題 ***
            # 獲取對應的顯示名稱
            values_display = []
            for val in values:
                display_name = self.get_display_column_name(val)
                values_display.append(display_name)
            
            # 獲取 index 的顯示名稱
            index_display = self.get_display_column_name(index)
            columns_display = self.get_display_column_name(columns) if columns else None
            
            print(f"組合圖 - 原始名稱: values={values}, index={index}, columns={columns}")
            print(f"組合圖 - 顯示名稱: values={values_display}, index={index_display}, columns={columns_display}")
            
            # 準備X軸數據
            x_data = range(len(pivot_table.index))
            x_labels = pivot_table.index
            
            # 確保 values 中的每個欄位都存在於 pivot_table 中
            available_values = [val for val in values if val in pivot_table.columns]
            
            if len(available_values) < 2:
                QMessageBox.warning(self, "警告", "組合圖需要至少2個有效的數值欄位！")
                return
            
            # 長條圖數據（使用第一個數值欄位）
            if not columns:
                # 無分組情況
                bar_data = pivot_table[available_values[0]]
                line_data = pivot_table[available_values[1]]
            else:
                # 有分組情況
                if isinstance(pivot_table.columns, pd.MultiIndex):
                    # 多層索引，取第一個分組的數據
                    first_col = pivot_table.columns.levels[1][0] if len(pivot_table.columns.levels) > 1 else pivot_table.columns[0][1]
                    bar_data = pivot_table[(available_values[0], first_col)]
                    line_data = pivot_table[(available_values[1], first_col)]
                else:
                    # 單層索引
                    bar_data = pivot_table.iloc[:, 0]
                    line_data = pivot_table.iloc[:, 1] if pivot_table.shape[1] > 1 else pivot_table.iloc[:, 0]
            
            # 確保資料是數值型且處理 NaN 值
            bar_data = bar_data.fillna(0)
            line_data = line_data.fillna(0)
            
            # 繪製長條圖
            bar_color = colors[0] if colors else '#1f77b4'
            bars = ax.bar(x_data, bar_data.values, 
                        color=bar_color,
                        alpha=0.7, 
                        width=0.6, 
                        label=values_display[0])  # 使用顯示名稱
            
            # 創建右側Y軸用於折線圖
            ax2 = ax.twinx()
            
            # 繪製折線圖
            line_color = colors[1] if colors and len(colors) > 1 else '#ff7f0e'
            line = ax2.plot(x_data, line_data.values, 
                            color=line_color,
                            marker='o', 
                            linewidth=2, 
                            markersize=8, 
                            label=values_display[1])  # 使用顯示名稱
            
            # 設定X軸
            ax.set_xticks(x_data)
            ax.set_xticklabels(x_labels, rotation=45, ha='right')
            
            # 設定Y軸標籤和顏色（使用顯示名稱）
            ax.set_ylabel(f"{aggfunc}({values_display[0]}){ylabel_suffix}", 
                        fontsize=self.label_fontsize, 
                        color=bar_color, 
                        fontweight='bold')
            ax2.set_ylabel(f"{aggfunc}({values_display[1]}){ylabel_suffix}", 
                        fontsize=self.label_fontsize, 
                        color=line_color, 
                        fontweight='bold')
            
            # 統一圖例管理 - 位置改為圖表內右上方
            if ax.get_legend():
                ax.get_legend().set_visible(False)
            if ax2.get_legend():
                ax2.get_legend().set_visible(False)
            
            # 手動創建統一圖例（使用顯示名稱）
            handles = [bars]
            labels = [values_display[0]]
            
            # 添加折線圖到圖例
            if isinstance(line, list):
                handles.append(line[0])
            else:
                handles.append(line)
            labels.append(values_display[1])
            
            # 設定統一圖例位置在圖表內右上方
            legend = ax.legend(handles, labels, 
                            loc='upper right',                   
                            bbox_to_anchor=(0.98, 0.98),         
                            fontsize=self.label_fontsize-1,
                            frameon=True,
                            fancybox=True,
                            shadow=True,
                            title='圖例',
                            title_fontsize=self.label_fontsize,
                            facecolor='white',                    
                            edgecolor='gray',                     
                            framealpha=0.9)                       
            
            # 設定圖例標題樣式
            legend.get_title().set_fontweight('bold')
            
            # 設定Y軸刻度顏色
            ax.tick_params(axis='y', labelcolor=bar_color, labelsize=self.label_fontsize-2)
            ax2.tick_params(axis='y', labelcolor=line_color, labelsize=self.label_fontsize-2)
            ax.tick_params(axis='x', labelsize=self.label_fontsize-2)
            
            # 添加數值標籤（如果勾選）
            if hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                # 長條圖標籤
                for i, (x, y) in enumerate(zip(x_data, bar_data.values)):
                    if not pd.isna(y) and y != 0:
                        formatted_value = self._format_label_value(y)
                        ax.annotate(formatted_value, (x, y), 
                                textcoords="offset points", 
                                xytext=(0, 5), ha='center',
                                fontsize=self.label_fontsize-3,
                                color=bar_color,
                                fontweight='bold')
                
                # 折線圖標籤
                for i, (x, y) in enumerate(zip(x_data, line_data.values)):
                    if not pd.isna(y) and y != 0:
                        formatted_value = self._format_label_value(y)
                        ax2.annotate(formatted_value, (x, y), 
                                    textcoords="offset points", 
                                    xytext=(0, 10), ha='center',
                                    fontsize=self.label_fontsize-3,
                                    color=line_color,
                                    fontweight='bold')
            
            # 設定標題（使用顯示名稱）
            plt.title(f"組合圖 (長條圖+折線圖) - {index_display} vs {values_display[0]}, {values_display[1]} ({aggfunc}){ylabel_suffix}", 
                    fontsize=self.title_fontsize, pad=20)
            
            # 設定X軸標籤（使用顯示名稱）
            ax.set_xlabel(index_display, fontsize=self.label_fontsize)
            
            # 添加網格（僅左側軸）
            ax.grid(True, alpha=0.3, axis='both')
            ax2.grid(False)  # 右側軸不顯示網格避免重疊
            
            # 套用數值格式
            self._apply_chart_formatting(ax, bar_data)
            self._apply_chart_formatting(ax2, line_data)
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"繪製組合圖時發生錯誤: {str(e)}")

    def _format_label_value(self, value):
        """格式化標籤數值 - 修正版：normal格式也使用千位分隔符號"""
        format_type = self.format_combo.currentText()
        
        if format_type == "thousands":
            # 千位格式：已經除以1000，顯示千分位格式並加上K後綴
            return f"{value:,.0f}K"
        elif format_type == "currency":
            # 貨幣格式：加上貨幣符號和千位分隔符號
            currency_symbol = self.currency_edit.text()
            return f"{currency_symbol}{value:,.0f}"
        else:  # format_type == "normal"
            # 修正：normal格式也使用千位分隔符號
            if isinstance(value, (int, float)):
                # 判斷是否為整數或接近整數
                if isinstance(value, int) or (isinstance(value, float) and value.is_integer()):
                    # 整數使用千位分隔符號，不顯示小數點
                    return f"{int(value):,}"
                else:
                    # 浮點數使用千位分隔符號，顯示1位小數
                    return f"{value:,.1f}"
            else:
                # 非數值型態直接轉換為字串
                return str(value)

    def _apply_chart_formatting(self, ax, pivot_table):
        """套用圖表格式化 - 修正版：normal格式也使用千位分隔符號"""
        format_type = self.format_combo.currentText()
        
        if format_type == "thousands":
            # 千位格式：Y軸顯示千分位格式
            ax.yaxis.set_major_formatter(FuncFormatter(lambda x, p: f"{x:,.0f}"))
        elif format_type == "currency":
            # 貨幣格式：Y軸顯示貨幣符號和千位分隔符號
            currency_symbol = self.currency_edit.text()
            ax.yaxis.set_major_formatter(FuncFormatter(lambda x, p: f"{currency_symbol}{x:,.0f}"))
        else:  # format_type == "normal"
            # 修正：normal格式的Y軸也使用千位分隔符號
            ax.yaxis.set_major_formatter(FuncFormatter(lambda x, p: f"{x:,.0f}" if x == int(x) else f"{x:,.1f}"))

    def generate_pie_chart(self):
        """生成圓餅圖或環圈圖 - 修正版：支援多值選擇和欄分組選擇，總計數值支援格式化"""
        try:
            if self.current_data is None or self.current_data.empty:
                QMessageBox.critical(self, "錯誤", "沒有資料可生成圖表!")
                return
            
            # 獲取顯示名稱
            index_display = self.index_combo.currentText()
            columns_display = self.columns_combo.currentText() if self.columns_combo.currentText() else None
            values_display = self.get_selected_values()
            aggfunc = self.aggfunc_combo.currentText()
            chart_type = self.pie_chart_type_combo.currentText()
            
            if not index_display:
                QMessageBox.critical(self, "錯誤", "請選擇列(Index)欄位!")
                return
            if not values_display:
                QMessageBox.critical(self, "錯誤", "請至少選擇一個值(Values)欄位!")
                return
            
            # *** 新增：當有多個值欄位或有欄分組時，提供選擇對話框 ***
            selected_value_display = None
            selected_group = None
            
            # 檢查是否需要選擇
            need_value_selection = len(values_display) > 1
            need_group_selection = columns_display is not None
            
            if need_value_selection or need_group_selection:
                # 獲取可用的分組值（如果有欄分組）
                available_groups = []
                if need_group_selection:
                    # 轉換為原始名稱進行查詢
                    index_original = self._get_original_column_name(index_display)
                    columns_original = self._get_original_column_name(columns_display)
                    values_original = [self._get_original_column_name(val) for val in values_display]
                    
                    # 創建測試樞紐表來獲取分組值
                    df_copy = self.current_data.copy()
                    for val in values_original:
                        df_copy[val] = pd.to_numeric(df_copy[val], errors='coerce')
                    df_copy = df_copy.dropna(subset=values_original)
                    
                    if not df_copy.empty:
                        available_groups = sorted(df_copy[columns_original].dropna().unique().tolist())
                
                # 顯示整合選擇對話框
                selection_result = self._show_pie_chart_selection_dialog(
                    values_display, available_groups, columns_display
                )
                
                if selection_result is None:
                    return  # 用戶取消
                
                selected_value_display, selected_group = selection_result
            else:
                # 不需要選擇，使用第一個值
                selected_value_display = values_display[0]
                selected_group = None
            
            # *** 轉換為原始名稱 ***
            index = self._get_original_column_name(index_display)
            columns = self._get_original_column_name(columns_display) if columns_display else None
            selected_value = self._get_original_column_name(selected_value_display)
            
            print(f"圓餅圖選擇結果:")
            print(f"  選擇的值: {selected_value_display} -> {selected_value}")
            print(f"  選擇的分組: {selected_group}")
            
            # 處理資料
            df_copy = self.current_data.copy()
            df_copy[selected_value] = pd.to_numeric(df_copy[selected_value], errors='coerce')
            df_copy = df_copy.dropna(subset=[selected_value])
            df_copy = df_copy[df_copy[selected_value] != 0]
            
            if df_copy.empty:
                QMessageBox.critical(self, "錯誤", "選擇的數值資料全為0或NaN，無法繪製圓餅圖!")
                return
            
            # 如果有選擇特定分組，先篩選資料
            if selected_group is not None and columns:
                df_copy = df_copy[df_copy[columns] == selected_group]
                if df_copy.empty:
                    QMessageBox.critical(self, "錯誤", f"選擇的{columns_display} '{selected_group}' 沒有資料!")
                    return
            
            # 應用Seaborn風格設定
            sns.set_style(self.style_combo.currentText())
            sns.set_context(self.context_combo.currentText())
            sns.set_palette(self.palette_combo.currentText())
            set_chinese_font()
            
            # 創建樞紐表
            pie_data = pd.pivot_table(
                df_copy,
                values=selected_value,
                index=index,
                aggfunc=aggfunc,
                fill_value=0
            )
            
            # 移除0值
            pie_data = pie_data[pie_data[selected_value] != 0]
            if pie_data.empty:
                QMessageBox.critical(self, "錯誤", "彙總後資料全為0，無法繪製圓餅圖!")
                return
            
            # *** 處理標題資訊 ***
            title_parts = []
            if selected_group is not None:
                title_parts.append(f"{columns_display}: {selected_group}")
            
            title_suffix = f" - {', '.join(title_parts)}" if title_parts else ""
            
            # 其餘邏輯保持相同...
            total_sum = pie_data[selected_value].sum()
            
            # *** 新增：獲取數值格式設定 ***
            format_type = self.format_combo.currentText()
            
            # *** 新增：處理總計值的格式轉換（用於顯示和計算） ***
            display_total = total_sum  # 用於計算百分比的原始總計
            formatted_total_for_chart = total_sum  # 用於圖表顯示的總計
            
            # 根據格式類型調整顯示總計
            if format_type == "thousands":
                formatted_total_for_chart = total_sum / 1000
                display_suffix = " (千)"
            else:
                display_suffix = ""
            
            if len(pie_data) > 5:
                top5 = pie_data.reindex(pie_data[selected_value].abs().nlargest(5).index)
                others_sum = total_sum - top5[selected_value].sum()
                
                if abs(others_sum) > 0.01:
                    others_row = pd.DataFrame({selected_value: [others_sum]}, index=['其他'])
                    pie_table = pd.concat([top5, others_row])
                    display_suffix += " (前5大項+其他)"
                else:
                    pie_table = top5
                    display_suffix += " (前5大項)"
            else:
                pie_table = pie_data
            
            total = display_total  # 使用原始總計計算百分比
            if abs(total) < 0.01:
                QMessageBox.critical(self, "錯誤", "所有數值加總接近0，無法繪製圓餅圖!")
                return
            
            percents = (pie_table[selected_value] / total * 100).round(1)
            
            labels = []
            for idx, pct in zip(pie_table.index, percents):
                labels.append(f"{idx} ({pct:.1f}%)")
            
            pie_values = pie_table[selected_value].abs()
            
            # 顏色處理
            color_count = len(pie_table)
            if self.chart_colors:
                colors = self.chart_colors[:color_count]
                if len(colors) < color_count:
                    seaborn_colors = sns.color_palette(self.palette_combo.currentText(), color_count)
                    colors.extend(seaborn_colors[len(colors):])
            else:
                colors = sns.color_palette(self.palette_combo.currentText(), color_count)
            
            adjusted_colors = []
            for i, val in enumerate(pie_table[selected_value]):
                if val < 0:
                    color = colors[i % len(colors)]
                    if isinstance(color, str):
                        import matplotlib.colors as mcolors
                        rgb = mcolors.hex2color(color)
                        lighter_rgb = tuple(min(1.0, c + 0.3) for c in rgb)
                        adjusted_colors.append(lighter_rgb)
                    else:
                        adjusted_colors.append(tuple(min(1.0, c + 0.3) for c in color))
                else:
                    adjusted_colors.append(colors[i % len(colors)])
            
            # 繪製圖表
            fig, ax = plt.subplots(figsize=(10, 8))
            
            fig.patch.set_facecolor('white')
            if self.style_combo.currentText() in ['dark', 'darkgrid']:
                fig.patch.set_facecolor('#2e2e2e')
                ax.set_facecolor('#2e2e2e')
            
            if chart_type == "環圈圖":
                wedgeprops = {'width': 0.4, 'edgecolor': 'white', 'linewidth': 2} # 環的寬度占半徑的40%，內圓較大
                chart_title = f"環圈圖 - {index_display} vs {selected_value_display} ({aggfunc}){title_suffix}{display_suffix}"
            else:
                wedgeprops = {'edgecolor': 'white', 'linewidth': 1}
                chart_title = f"圓餅圖 - {index_display} vs {selected_value_display} ({aggfunc}){title_suffix}{display_suffix}"
            
            wedges, texts = ax.pie(
                pie_values,
                labels=labels,
                autopct=None,
                startangle=45,
                colors=adjusted_colors,
                wedgeprops=wedgeprops,
                textprops={'fontsize': self.label_fontsize}
            )
            
            # *** 修正關鍵：環圈圖中間總計數值支援格式化 ***
            if chart_type == "環圈圖" and hasattr(self, 'show_labels_chk') and self.show_labels_chk.isChecked():
                # 根據數值格式設定來格式化總計顯示
                formatted_total_text = self._format_center_total_value(formatted_total_for_chart, format_type)
                
                ax.text(0, 0, f'總計\n{formatted_total_text}', 
                    horizontalalignment='center',
                    verticalalignment='center',
                    fontsize=self.label_fontsize + 2,
                    fontweight='bold',
                    color='black' if self.style_combo.currentText() not in ['dark', 'darkgrid'] else 'white')
            
            text_color = 'white' if self.style_combo.currentText() in ['dark', 'darkgrid'] else 'black'
            for text in texts:
                text.set_fontsize(self.label_fontsize)
                text.set_color(text_color)
            
            if any(pie_table[selected_value] < 0):
                note_text = "註：負數值以較淺顏色顯示，百分比基於總和計算"
                plt.figtext(0.02, 0.02, note_text, fontsize=10, 
                        color=text_color, style='italic')
            
            title_color = text_color
            plt.title(chart_title, 
                    fontsize=self.title_fontsize, 
                    pad=30,
                    y=0.98,
                    color=title_color)
            plt.axis('equal')
            
            self.current_figure = fig
            self.display_chart(fig)
            
            # 切換到圖表標籤頁
            self.tab_widget.setCurrentIndex(3)
            
        except Exception as e:
            QMessageBox.critical(self, "錯誤", f"生成圓餅圖錯誤: {str(e)}")

    def _format_center_total_value(self, value, format_type):
        """專門用於環圈圖中間總計數值的格式化方法"""
        try:
            if pd.isna(value):
                return "0"
            
            if format_type == "thousands":
                # 千位格式：數值已經除以1000，顯示千分位格式並加上K後綴
                if value == 0:
                    return "0K"
                elif abs(value) >= 1000:
                    return f"{value:,.0f}K"
                else:
                    return f"{value:,.1f}K"
            elif format_type == "currency":
                # 貨幣格式：加上貨幣符號和千位分隔符號
                currency_symbol = getattr(self, 'currency_edit', None)
                currency_text = currency_symbol.text() if currency_symbol and currency_symbol.text() else "NT$"
                
                if value == 0:
                    return f"{currency_text}0"
                elif isinstance(value, (int, float)) and abs(value) >= 1:
                    if value == int(value):
                        return f"{currency_text}{int(value):,}"
                    else:
                        return f"{currency_text}{value:,.0f}"
                else:
                    return f"{currency_text}{value:,.2f}"
            else:  # format_type == "normal"
                # 一般格式：使用千位分隔符號
                if value == 0:
                    return "0"
                elif isinstance(value, (int, float)):
                    if value == int(value):
                        # 整數顯示
                        return f"{int(value):,}"
                    else:
                        # 小數顯示（通常圓餅圖總計是整數，但以防萬一）
                        if abs(value) >= 1000:
                            return f"{value:,.0f}"
                        else:
                            return f"{value:,.1f}"
                else:
                    return str(value)
        except Exception as e:
            print(f"格式化中間總計數值時發生錯誤: {e}")
            # 發生錯誤時回退到基本格式
            try:
                return f"{value:,.0f}"
            except:
                return str(value)

    def _show_pie_chart_selection_dialog(self, values_display, available_groups, columns_display):
        """顯示圓餅圖整合選擇對話框（值欄位 + 欄分組）"""
        try:
            from PyQt6.QtWidgets import (
                QDialog, QVBoxLayout, QHBoxLayout, QLabel, QComboBox, QPushButton,
                QGroupBox, QGridLayout
            )
            
            dialog = QDialog(self)
            dialog.setWindowTitle("圓餅圖選擇設定")
            dialog.setFixedSize(450, 360)
            
            # 設定對話框樣式
            dialog.setStyleSheet("""
                QDialog {
                    background-color: #f8f9fa;
                    border: 2px solid #e74c3c;
                    border-radius: 9px;
                }
            """)
            
            layout = QVBoxLayout(dialog)
            layout.setSpacing(14)
            layout.setContentsMargins(18, 18, 18, 18)
            
            # 標題說明
            title_label = QLabel("🥧 圓餅圖設定選擇")
            title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            title_label.setStyleSheet("""
                QLabel {
                    font-size: 16px;
                    font-weight: bold;
                    color: #2c3e50;
                    padding: 9px;
                    background-color: #fdf2f2;
                    border: 2px solid #e74c3c;
                    border-radius: 7px;
                    margin: 5px;
                }
            """)
            layout.addWidget(title_label)
            
            # 選擇區域
            selection_group = QGroupBox("請選擇要顯示的內容")
            selection_group.setStyleSheet("""
                QGroupBox {
                    font-size: 14px;
                    font-weight: bold;
                    color: #2c3e50;
                    border: 1px solid #dee2e6;
                    border-radius: 5px;
                    margin: 5px;
                    padding-top: 14px;
                }
                QGroupBox::title {
                    subcontrol-origin: margin;
                    left: 10px;
                    padding: 0 8px 0 8px;
                }
            """)
            selection_layout = QGridLayout(selection_group)
            selection_layout.setSpacing(9)
            
            # 值欄位選擇
            values_label = QLabel("選擇值欄位:")
            values_label.setStyleSheet("""
                QLabel {
                    font-size: 14px;
                    font-weight: bold;
                    color: #2c3e50;
                    padding: 5px;
                }
            """)
            selection_layout.addWidget(values_label, 0, 0)
            
            self.value_combo = QComboBox()
            self.value_combo.addItems(values_display)
            self.value_combo.setStyleSheet("""
                QComboBox {
                    font-size: 14px;
                    padding: 7px;
                    border: 2px solid #3498db;
                    border-radius: 5px;
                    background-color: white;
                    min-height: 25px;
                }
                QComboBox:focus {
                    border: 2px solid #2980b9;
                }
            """)
            selection_layout.addWidget(self.value_combo, 0, 1)
            
            # 欄分組選擇（如果有）
            self.group_combo = None
            if available_groups:
                group_label = QLabel(f"選擇{columns_display}:")
                group_label.setStyleSheet("""
                    QLabel {
                        font-size: 14px;
                        font-weight: bold;
                        color: #2c3e50;
                        padding: 5px;
                    }
                """)
                selection_layout.addWidget(group_label, 1, 0)
                
                self.group_combo = QComboBox()
                self.group_combo.addItems([str(group) for group in available_groups])
                self.group_combo.setStyleSheet("""
                    QComboBox {
                        font-size: 14px;
                        padding: 7px;
                        border: 2px solid #e74c3c;
                        border-radius: 5px;
                        background-color: white;
                        min-height: 25px;
                    }
                    QComboBox:focus {
                        border: 2px solid #c0392b;
                    }
                """)
                selection_layout.addWidget(self.group_combo, 1, 1)
            
            layout.addWidget(selection_group)
            
            # 說明文字
            if len(values_display) > 1 and available_groups:
                info_text = f"圓餅圖只能顯示一個值欄位和一個{columns_display}分組。"
            elif len(values_display) > 1:
                info_text = "圓餅圖只能顯示一個值欄位。"
            elif available_groups:
                info_text = f"請選擇要顯示的{columns_display}分組。"
            else:
                info_text = "確認圓餅圖設定。"
            
            info_label = QLabel(f"💡 {info_text}")
            info_label.setStyleSheet("""
                QLabel {
                    font-size: 13px;
                    color: #7f8c8d;
                    font-style: italic;
                    padding: 7px;
                    background-color: #ecf0f1;
                    border-radius: 5px;
                    margin: 3px;
                }
            """)
            layout.addWidget(info_label)
            
            # 按鈕區域
            button_layout = QHBoxLayout()
            button_layout.setSpacing(9)
            
            ok_button = QPushButton("✓ 確定")
            ok_button.setStyleSheet("""
                QPushButton {
                    background-color: #27ae60;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 10px 22px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #2ecc71;
                }
            """)
            ok_button.clicked.connect(dialog.accept)
            button_layout.addWidget(ok_button)
            
            cancel_button = QPushButton("✗ 取消")
            cancel_button.setStyleSheet("""
                QPushButton {
                    background-color: #95a5a6;
                    color: white;
                    border: none;
                    border-radius: 6px;
                    font-weight: bold;
                    font-size: 14px;
                    padding: 10px 22px;
                    min-height: 35px;
                }
                QPushButton:hover {
                    background-color: #7f8c8d;
                }
            """)
            cancel_button.clicked.connect(dialog.reject)
            button_layout.addWidget(cancel_button)
            
            layout.addLayout(button_layout)
            
            # 顯示對話框
            result = dialog.exec()
            
            if result == QDialog.DialogCode.Accepted:
                selected_value = self.value_combo.currentText()
                selected_group = None
                
                if self.group_combo is not None:
                    selected_index = self.group_combo.currentIndex()
                    selected_group = available_groups[selected_index]
                
                print(f"圓餅圖用戶選擇: 值={selected_value}, 分組={selected_group}")
                return selected_value, selected_group
            else:
                print("圓餅圖用戶取消選擇")
                return None
                
        except Exception as e:
            print(f"顯示圓餅圖選擇對話框時發生錯誤: {e}")
            return None

