    def check_database_connection(self):
        """
        檢查資料庫連線狀態
        
        返回:
            bool: True表示已連線，False表示未連線
        """
        try:
            # 檢查是否有連線物件且連線正常
            # 這裡假設您有一個 self.connection 或類似的連線物件
            if hasattr(self, 'connection') and self.connection:
                # 如果您使用的是不同的連線檢查方式，請修改這部分
                return True
            return False
        except:
            return False

