    def sync_offnbr_to_params(self):
        """將登入的機構代號同步到參數設定區的所有相關欄位（支援多個頁面）"""
        try:
            offnbr = self.offnbr_edit.text().strip()
            if not offnbr:
                print("⚠️ 機構代號為空，無法同步")
                return
            
            print(f"\n🔄 開始同步機構代號: {offnbr}")
            
            # *** 定義需要同步的欄位（所有頁面共用這些屬性名稱）***
            sync_field_names = [
                'param_offnbr',    # 機構代號
                'param_office',    # 製票機構
                'param_trnofn',    # 交易機構
                'param_bkgofn'     # 列帳機構
            ]
            
            synced_count = 0
            failed_fields = []
            
            # *** 方法1：直接透過物件屬性同步（適用於兩個頁面）***
            for var_name in sync_field_names:
                try:
                    if hasattr(self, var_name):
                        widget = getattr(self, var_name)
                        widget.setText(offnbr)
                        synced_count += 1
                        
                        # 根據變數名稱顯示友善的欄位名稱
                        field_display_name = {
                            'param_offnbr': '機構代號',
                            'param_office': '製票機構',
                            'param_trnofn': '交易機構',
                            'param_bkgofn': '列帳機構'
                        }.get(var_name, var_name)
                        
                        print(f"  ✓ {field_display_name}: {offnbr}")
                    else:
                        failed_fields.append(var_name)
                        print(f"  ✗ {var_name}: 找不到對應的欄位")
                        
                except Exception as field_error:
                    failed_fields.append(var_name)
                    print(f"  ✗ {var_name}: 設定失敗 - {field_error}")
            
            # *** 方法2：如果有 parameter_inputs 字典，也一併同步 ***
            if hasattr(self, 'parameter_inputs'):
                dict_sync_fields = [
                    '機構代號',
                    '製票機構',
                    '交易機構',
                    '列帳機構'
                ]
                
                for field_label in dict_sync_fields:
                    try:
                        if field_label in self.parameter_inputs:
                            widget = self.parameter_inputs[field_label]
                            widget.setText(offnbr)
                            print(f"  ✓ {field_label}: {offnbr} (透過字典)")
                    except Exception as e:
                        print(f"  ✗ {field_label}: 字典同步失敗 - {e}")
            
            # 輸出同步結果
            if synced_count > 0:
                success_msg = f"✅ 機構代號 {offnbr} 已同步到 {synced_count} 個參數欄位"
                print(success_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(success_msg)
            
            if failed_fields:
                warning_msg = f"⚠️ 以下欄位同步失敗: {', '.join(failed_fields)}"
                print(warning_msg)
            
            if synced_count == 0:
                error_msg = "❌ 未能同步任何參數欄位"
                print(error_msg)
                if hasattr(self, 'safe_print'):
                    self.safe_print(error_msg)
                    
        except Exception as e:
            error_msg = f"❌ 同步機構代號時發生錯誤：{e}"
            print(error_msg)
            import traceback
            traceback.print_exc()
            if hasattr(self, 'safe_print'):
                self.safe_print(error_msg)

