    def get_darker_color(self, hex_color, factor=0.2):
        """
        產生較深的顏色 - 用於按鈕hover效果
        """
        try:
            hex_color = hex_color.lstrip('#')
            r = int(hex_color[0:2], 16)
            g = int(hex_color[2:4], 16)
            b = int(hex_color[4:6], 16)
            
            r = max(0, int(r * (1 - factor)))
            g = max(0, int(g * (1 - factor)))
            b = max(0, int(b * (1 - factor)))
            
            return f"#{r:02x}{g:02x}{b:02x}"
        except:
            return "#333333"

    # 其餘方法保持不變，包括：
    # load_selected_query, get_connection_string, test_connection, 
    # connect_database, disconnect_database, execute_query, 等等...
    
    def load_selected_query(self):
        """
        載入被選擇的查詢到SQL編輯器
        """
        try:
            print("開始執行 load_selected_query...")
            
            if not hasattr(self, 'query_buttons') or not self.query_buttons:
                QMessageBox.critical(self, "錯誤", "查詢選單尚未初始化，請重新啟動程式")
                return
            
            selected_query_type = None
            for query_type, radio_button in self.query_buttons.items():
                if radio_button.isChecked():
                    selected_query_type = query_type
                    break
            
            if not selected_query_type:
                QMessageBox.warning(self, "警告", "請先選擇一個查詢項目\n\n請在右側查詢清單中選擇要載入的項目")
                return
            
            print(f"載入項目: {selected_query_type}")
            
            sql_query = self.get_preset_sql(selected_query_type)
            
            if not sql_query or sql_query.strip() == "":
                QMessageBox.critical(self, "錯誤", "無法取得SQL查詢內容")
                return
            
            self.sql_text.setPlainText(sql_query)
            self.current_query_type = selected_query_type
            
            query_name = self.get_query_name(selected_query_type)
            QMessageBox.information(self, "載入成功", 
                                f"✅ 已成功載入查詢到SQL編輯器\n\n查詢名稱：{query_name}\n\n請切換到「SQL查詢」分頁查看")
            
            self.tab_widget.setCurrentIndex(1)
            self.query_buttons[selected_query_type].setChecked(False)
            
            print("載入查詢完成")
            
        except Exception as e:
            print(f"load_selected_query 發生錯誤: {e}")
            import traceback
            traceback.print_exc()
            QMessageBox.critical(self, "載入錯誤", f"載入查詢時發生錯誤:\n{str(e)}\n\n請檢查程式狀態或重新啟動程式")
          
    def get_preset_sql(self, query_type):
        """
        根據查詢類型返回對應的SQL語句模板
        """
        offnbr = self.param_offnbr.text() or "3047"        
        year = self.param_year.text() or "114"
        month = self.param_month.text() or "09"
        genacc = self.param_genacc.text() or "4609"
        subacc = self.param_subacc.text() or "4106"
        office = self.param_office.text() or "3047"
        trnofn = self.param_trnofn.text() or "3047"        
        bkgofn = self.param_bkgofn.text() or "3047"
        history = self.param_history.text() or "0000"
        projectno = self.param_projectno.text() or ""       
        sql_templates = {
            "deposit": f"""with tempA as( --- 18xx存出保證金或保證品>50萬，若大於50萬應通知企客以定存單更換(押標金應退回或轉至履保金) ---
        select (CASE WHEN SUBSTR(vencod,1,2) IN ('3C','WP','BR','3D','1B','4D','5E','7G')
        THEN vencod  ELSE auxacc   END) AS newvencod ,' 懸記帳 ' vsusp
        ,M.genacc||'-'||M.subacc||accnam accnam, amtnet,auxacc,vencod,
        (case when TRNAT3='B'  then '** 屬性 '||tRNAT3||'-'||auxac3
        else auxac3 end ) auxac3, RTRIM(auxac4) auxac4,RTRIM(trndsc)  trndsc,
        substr(digits(BKGDAT),2,3)||'/'||substr(digits(BKGDAT),5,2)||'/'
        ||substr(digits(BKGDAT),7,2)
        ||'---'|| VOUID||'-'||substr(digits(reGNBR),3,4)||'  列帳'||VOUID||'-'||substr(digits(BKGNBR),3,4) bkgdata
            ,BKGOFN, M.OFFNBR,m.trnofn,M.ACTEM1
        from vsusp{offnbr}  m
        left join acpacctn d
        on d.genacc=m.genacc and d.subacc=m.subacc  and
        M.bkgofn=d.offnbr   and
        ((substr(m.bkgdat,1,3)<=106 and d.year =107 ) or
        (substr(m.bkgdat,1,3)=d.year and substr(m.bkgdat,1,3)>106))
        where  (  substr(auxacc,1,2) in ('WP','3C','BR','3D','1B','4D','5E','7G')    or
        substr(vencod,1,2) in ('WP','3C','BR','3D','1B','4D','5E','7G'))
        and renctl<>'*' 
        union all
        select (CASE WHEN SUBSTR(vencod,1,2) IN ('3C','WP','BR','3D','1B','4D','5E','7G')  
            THEN  vencod  ELSE auxacc   END) AS newvencod                   
        ,'傳票未過帳',M.genacc||'-'||M.subacc|| IFNULL(accnam, '') accnam
        ,amtnet,auxacc,vencod,auxac3,auxac4,trndsc,                                
        substr(digits(reGYY),2,3)||'/'||digits(reGMM)||'/'||digits(regDD)               
        ||'---'|| VOUID||'-'||substr(digits(reGNBR),3,4) bkgdata,BKGOFN, M.OFFNBR, m.trnofn,ACTEM1    
        from voud{offnbr} m
        left join acpacctn d                                                
        ON m.regyy = d.year AND M.bkgofn = d.offnbr AND d.genacc = m.genacc AND d.subacc = m.subacc
        where  delctl<>'D' and bkgctl<>'B'  
        and (( substr(M.auxacc,1,2) in ('WP','3C','BR','3D','1B','4D','5E','7G')) or       
        ( substr(M.vencod,1,2) in ('WP','3C','BR','3D','1B','4D','5E','7G')) )             
        and  substr(M.genacc,1,1) not in ('4','5') 
        ), tempB as (
        select *
        from tempA 
        where (amtnet >500000 or amtnet*-1>500000) and  (accnam like '1817%' ) and bkgofn<>'{bkgofn}'
        )
        select distinct *
        from tempA a
        left join tempB b
        on a.vencod=b.vencod and a.amtnet=b.amtnet
        where  (a.accnam like '1811%' or a.accnam like '1816-09%' ) and a.bkgofn='{bkgofn}' and  (a.amtnet >500000 or a.amtnet*-1>500000) 
        order by 3,1,10
        limit 5000""",

                    "k2_internal": f"""WITH base_data AS (--- 專標案K2碼誤植(內部)；BCRMID應等於VOUDID(統編應一致)若只有PBX設備編號為正常 ---
        SELECT 
            m.auxac3 AS VOUDID,
            CASE WHEN SUBSTR(m.auxacc, 1, 2) IN ('3C', 'WP', 'BR', '3D', '1B', '4D', '5E', '7G') 
                THEN m.auxacc ELSE m.vencod END AS newvencod,
            '收入費用明細帳 ' AS bookname,
            m.genacc, m.subacc, m.AMTNET, m.auxacc, m.vencod, m.auxac3, m.auxac4, m.trndsc,
            m.reGYY, m.reGMM, m.regDD, m.VOUID, m.reGNBR, m.BKGYY, m.BKGMM, m.BKgDD, m.BKGNBR,
            m.BKGCTL, m.BKGOFN, m.OFFNBR, m.trnofn, m.ACTEM1
        FROM (
            SELECT * FROM voud{offnbr} WHERE delctl <> 'D'
            UNION ALL
            SELECT * FROM voudH0000 WHERE delctl <> 'D' AND bkgyy BETWEEN 108 AND 113
        ) m
        WHERE SUBSTR(m.genacc, 1, 1) IN ('4', '5')
        AND (
            SUBSTR(m.vencod, 1, 2) IN ('3C', 'WP', 'BR', '3D', '1B', '4D', '5E', '7G') OR 
            SUBSTR(m.auxacc, 1, 2) IN ('3C', 'WP', 'BR', '3D', '1B', '4D', '5E', '7G')
        )
        AND m.reGYY = 115 AND m.reGMM = 1
    ),
    temp AS (
        SELECT 
            b.VOUDID, b.newvencod, b.bookname,
            b.genacc || '-' || b.subacc || '-' || IFNULL(d.accnam, '') AS newgenacc,
            b.AMTNET, b.auxacc, b.vencod, b.auxac3, b.auxac4, b.trndsc,
            DIGITS(b.reGYY) || '/' || DIGITS(b.reGMM) || '/' || DIGITS(b.regDD) || '---' || b.VOUID || '-' || substr(DIGITS(b.reGNBR),3,4) ||
            '  帳列' || DIGITS(b.BKGYY) || '/' || DIGITS(b.BKGMM) || '/' || DIGITS(b.BKgDD) || '---' || b.VOUID || '-' ||
            substr(DIGITS(b.BKGNBR),3,4) AS bkgdata,
            b.BKGCTL, b.BKGOFN, b.OFFNBR, b.trnofn, b.ACTEM1
        FROM base_data b
        LEFT JOIN acpacctn d ON b.regyy = d.year AND b.bkgofn = d.offnbr AND d.genacc = b.genacc AND d.subacc = b.subacc
    )
    SELECT e.bck2no, e.BCCUST, e.BCRMID, p.*
    FROM (SELECT bck2no, BCCUST, vencod AS BCRMID FROM vbcname WHERE BCDEPT = '3047CE4 ') e
    INNER JOIN temp p ON e.bck2no = p.newvencod  -- 既然下方有 p.auxac3 is not null，這裡用 Inner Join 效能更好
    WHERE p.auxac3 <> '' AND p.VOUDID <> e.BCRMID
    ORDER BY 1, 10
    LIMIT 5000""",

                    "analysis": f"""select  --- TAIS2461_異常或指定科目分析說明 ---
         '係'||substr(digits(reGYY),2,3)||'/'||digits(reGMM)||'/'||digits(regDD)
        ||RTRIM(trndsc)||' '||''||decimal(round(amtnet,0),10,0) ||'所致' reason
        ,  VOUID, REGNBR, BKGNBR, substr(digits(BKGYY),2,3)||digits(BKGMM)||digits(BKGDD) bkgdat,genacc,subacc,
        aUXACC, vencod,auxac3,trnamt,DRCRID,amtnet
        , BKGOFN, OFFNBR, ACTEM1
        from voud{offnbr}
        where trnOFN='{trnofn}' and  bkgYY='{year}'  and
        genacc='{genacc}' and subacc like '{subacc}%'
        and  delctl<>'D'  and  voucs  <> 'Y'
        order by 5
        limit 5000""",

                    "analysis1": f"""SELECT --- 異常或差異分析說明(YoYMoM) ---     
        distinct a.bkgofn,a.TRNOFN, a.YEAR,a.MONTH, a.GENACC, a.SUBACC, a.fulnam, 
        a.AMTLM,a.DAMTTM, a.CAMTTM,                                       
        case when substr(a.genacc,1,1) in ('1','5')                        
            then a.damttm-a.camttm                                        
            else a.camttm-a.damttm  end  netttm                                 
            , a.amttm ,a.bgtty,case when a.amttm=0 and a.bgtty<> 0 then 0 
        when a.amttm=0 and a.bgtty=  0 then 0                             
        when a.amttm<>0 and a.bgtty=  0 then -100  else  decimal(round   
        (decimal(a.amttm,14,2)/decimal(a.bgtty,14,2)*100,2),8,2) end ||'%'  BGTypct
        ,b.amttm amttmly,a.AMTLY,                                                 
        case when b.amttm<>0 and a.amtly<>0 then   decimal(round (decimal
        (b.amttm,14,2)/decimal(a.amtly,14,2)*100,2),8,2) else 0 end ||'%'  LYpct,
        ((a.amttm-a.amtlm)-(c.amttm-c.amtlm)) DIFMon,   decimal((((a.amttm-a.amtlm)-(c.amttm-c.amtlm))/(c.amttm-c.amtlm) ) *100,8,2)||'%' MON,                     
        ((a.amttm-a.amtlm)-(b.amttm-b.amtlm)) DIFMOM, case when (a.amttm-a.amtlm)=0 and (b.amttm-b.amtlm)<> 0 then 0   when (a.amttm-a.amtlm)=0 and (b.amttm-b.amtlm)=  0 then 0   when (a.amttm-a.amtlm)<>0 and (b.amttm-b.amtlm)=  0 then -100  else decimal(((a.amttm-a.amtlm)/b.amttm)*100,8,2) end ||'%'  MOM,              
        a.amttm-b.amttm  DIFYoY , decimal(((a.amttm-b.amttm)/b.amttm)*100,8,2)||'%' YOY                
        FROM VQRY2{offnbr} A  
        LEFT JOIN VQRY2{offnbr} B  
        ON A.YEAR=(B.YEAR+1)  AND  A.MONTH=B.MONTH AND A.bkgOFN=B.bkgOFN  
        AND A.GENACC=B.GENACC AND  A.SUBACC=B.SUBACC                       
        LEFT JOIN VQRY2{offnbr} C  
        ON A.YEAR=C.YEAR  AND   A.MONTH=(C.MONTH + 1) AND                  
        A.bkgOFN=C.bkgOFN AND A.GENACC=C.GENACC AND   A.SUBACC=C.SUBACC    
        WHERE a.bkgofn='0000' and  a.ACCLEN=9  and                              
        a.YEAR={year} and a.month={month}
        and a.genacc like '{genacc}%'  and a.subacc like '{subacc}%'
        order by genacc, subacc                                            
        limit 5000""",

                    "negative": f"""With temp as (--- 企客專標案損益負數(毛損) ---
        select bkgyy,vencod,TRNOFN,
        case when substr(genacc,1,2)='46' then amtnet else 0 end as am1,
        case when substr(genacc,1,2)='56' then amtnet else 0 end as am2,
        case when substr(genacc,1,2)='44' then amtnet else 0 end as am3,
        case when (substr(genacc,1,1)='5' and
        substr(genacc,1,2)<>'56' ) then amtnet else 0 end as am4
        from voud{offnbr}
        where TRNOFN='{trnofn}' 
        and substr(vencod,1,3)in ('3CI','4DC') and ((substr(genacc,1,1) in ('4','5'))
        and (substr(genacc,1,2) not in ('47','57')) ) 
        union all
        select bkgyy,vencod,TRNOFN,
        case when substr(genacc,1,2)='46' then amtnet else 0 end as am1,
        case when substr(genacc,1,2)='56' then amtnet else 0 end as am2,
        case when substr(genacc,1,2)='44' then amtnet else 0 end as am3,
        case when (substr(genacc,1,1)='5' and
        substr(genacc,1,2)<>'56' ) then amtnet else 0 end as am4
        from voudH0000
        where TRNOFN='{trnofn}' 
        and substr(vencod,1,3)in ('3CI','4DC') and ((substr(genacc,1,1) in ('4','5'))
        and (substr(genacc,1,2) not in ('47','57')) ) )
        select m.vencod,BCNAM,sum(am1) as revenue46,sum(am2) as expense56
        ,sum(am1)-sum(am2)  as grossprofit,sum(am3)  as revenue44XX
        ,sum(am4)  as expense5XXX,sum(am1+am3-am2-am4) as NETincome
        from temp m
        left join VBCNAME a  
        on  m.vencod=BCK2NO
        where TRNOFN='{trnofn}' and bkgyy={year}
        group by m.vencod ,BCNAM
        having sum(am1)-sum(am2)<0 and bcnam<>''
        limit 5000""",

                    "gross_profit": f"""with B as ( --- 企客專標案當年度已結算毛利率 ---
        select distinct (CASE WHEN SUBSTR(auxacc,1,2) IN ('3C',  '4D',     
         'WP','BR','3D')  THEN auxacc  ELSE vencod   END) AS vencod        
        from voud{offnbr} 
        where  BKGOFN='{bkgofn}' and (genacc='1211' or (
        substr(vencod,1,2) IN ('3D','3C','WP','BR','4D')               
        and  (trndsc like '%結算%' or trndsc like '%預收轉%'))  )      
        and  delctl<>'D'  and  voucs  <> 'Y'                             
        union                                                              
         select distinct (CASE WHEN SUBSTR(auxacc,1,2) IN ('3C',  '4D',    
          'WP','BR','3D')  THEN auxacc  ELSE vencod   END) AS vencod       
        from voudh0000 
        where  BKGOFN='{bkgofn}' and (genacc='1211' or (
        substr(vencod,1,2) IN ('3D','3C','WP','BR','4D')               
        and  (trndsc like '%結算%' or trndsc like '%預收轉%'))  )      
        and  delctl<>'D'  and  voucs  <> 'Y' ) ,           
        C as(
        select distinct vencod,a.bkgofn,a.trnofn,ITMCOD, ITMDSC,           
        sum(case when a.genacc like '4%'  then amtnet else 0 end ) as amt1,
        sum(case when a.genacc like '5%'  then amtnet else 0 end ) as amt2,
        sum(case when a.genacc like '4%'  then amtnet else 0 end )  - 
        sum(case when a.genacc like '5%'  then amtnet else 0 end ) as amt3  
        from voud{offnbr} a 
            LEFT JOIN VQRY6{offnbr} e
                ON a.genacc = e.genacc 
                AND a.subacc = e.subacc
                AND YEAR = {year}
                AND MONTH = {month}
                AND e.trnofn = '{trnofn}'
                AND e.bkgofn = '0000'
            WHERE a.trnofn = '{trnofn}' 
                AND bkgyy = {year}
                AND bkgmm <= {month}
                AND (substr(a.genacc,1,1) IN ('4','5') 
                AND substr(a.genacc,1,2) NOT IN ('57','47'))
                AND (ITMCOD IN ('D.1','D.2') OR substr(ITMCOD,1,1) = 'I')
        group by bkgyy,a.bkgofn,a.trnofn,vencod,a.genacc,ITMCOD, ITMDSC 
        union 
        select distinct vencod,a.bkgofn,a.trnofn,ITMCOD, ITMDSC,           
        sum(case when a.genacc like '4%'  then amtnet else 0 end ) as amt1,
        sum(case when a.genacc like '5%'  then amtnet else 0 end ) as amt2,
        sum(case when a.genacc like '4%'  then amtnet else 0 end )  - 
        sum(case when a.genacc like '5%'  then amtnet else 0 end ) as amt3  
        from voudh0000 a 
            LEFT JOIN VQRY6{offnbr} e
                ON a.genacc = e.genacc 
                AND a.subacc = e.subacc
                AND YEAR = {year}
                AND MONTH = {month}
                AND e.trnofn = '{trnofn}'
                AND e.bkgofn = '0000'
            WHERE a.trnofn = '{trnofn}' 
                AND bkgyy = {year}
                AND bkgmm <= {month}
                AND (substr(a.genacc,1,1) IN ('4','5') 
                AND substr(a.genacc,1,2) NOT IN ('57','47'))
                AND (ITMCOD IN ('D.1','D.2') OR substr(ITMCOD,1,1) = 'I')
        group by bkgyy,a.bkgofn,a.trnofn,vencod,a.genacc,ITMCOD, ITMDSC ) 
        SELECT  
            CASE 
                WHEN GROUPING(b.vencod) = 1 THEN ''
                ELSE bcnam 
            END AS bcnam,
            CASE 
                WHEN GROUPING(b.vencod) = 1 THEN '合計'
            WHEN b.vencod isnull  THEN  '其他'
                ELSE b.vencod 
            END AS vencod, 
        sum(amt1) as revenue46,sum(amt2) as expense56 ,sum(amt3) as grossprofit,
        case when sum(amt1)=0 and sum(amt2)>0 then -1     
        when sum(amt1)=0 and sum(amt2)<=0 then 0                            
        else  (decimal(round(decimal(sum(amt1)-sum(amt2),20,4)/               
        decimal(sum(amt1),20,4),4),10,4))*100 end  as PERCENT
        from C c
         left join B b                                               
        on  c.vencod=b.vencod                      
        left join vbcname  d
        on  b.vencod=BCK2NO
        group by rollup ((b.vencod,bcnam))
        HAVING GROUPING(b.vencod) = 0 OR GROUPING(bcnam) = 1
        ORDER BY  GROUPING(b.vencod),b.vencod
        limit 5000""",

                    "k2_external": f"""WITH temp_vencod AS (--- 上陳前檢查-120A在製品專標案K2碼誤植(他機構)；若只出現1817存出保證品為正常 ---
            SELECT DISTINCT vencod                               
            FROM (
                SELECT vencod FROM voud{offnbr}
                WHERE trnofn = '{trnofn}' AND bkgofn = '{bkgofn}' AND delctl <> 'D' AND voucs <> 'Y'
                AND SUBSTR(vencod, 1, 2) IN ('3D','1B','3C','WP','BR','4D','7G','5E')
                UNION ALL
                SELECT vencod FROM voudH0000
                WHERE trnofn = '{trnofn}' AND bkgofn = '{bkgofn}' AND delctl <> 'D' AND voucs <> 'Y' AND bkgyy >= '108'
                AND SUBSTR(vencod, 1, 2) IN ('3D','1B','3C','WP','BR','4D','7G','5E')
            )
        ),
        vsusp_details AS (
            SELECT 
                CASE WHEN SUBSTR(m.vencod, 1, 2) IN ('3C','WP','BR','3D','1B','4D','5E','7G') THEN m.vencod ELSE m.auxacc END AS newvencod,
                ' 懸記帳 ' AS bookname,
                m.genacc || '-' || m.subacc || d.accnam AS accnam,
                m.amtnet, m.auxacc, m.vencod,
                CASE WHEN m.TRNAT3 = 'B' THEN '** 屬性 ' || m.tRNAT3 || '-' || m.auxac3 ELSE m.auxac3 END AS auxac3,
                RTRIM(m.auxac4) AS auxac4, RTRIM(m.trndsc) AS trndsc,
                SUBSTR(DIGITS(m.BKGDAT), 2, 3) || '/' || SUBSTR(DIGITS(m.BKGDAT), 5, 2) || '/' || SUBSTR(DIGITS(m.BKGDAT), 7, 2) ||
                '---' || m.VOUID || '-' || SUBSTR(DIGITS(m.reGNBR), 3, 4) || '  列帳' || m.VOUID || '-' || SUBSTR(DIGITS(m.BKGNBR), 3, 4) AS bkgdata,
                m.BKGOFN, m.OFFNBR, m.trnofn, m.ACTEM1
            FROM vsusp{offnbr} m
            LEFT JOIN acpacctn d ON d.genacc = m.genacc AND d.subacc = m.subacc AND m.bkgofn = d.offnbr
                AND ((SUBSTR(m.bkgdat, 1, 3) <= 106 AND d.year = 107) OR (SUBSTR(m.bkgdat, 1, 3) = d.year AND SUBSTR(m.bkgdat, 1, 3) > 106))
            WHERE m.renctl <> '*' 
            AND (SUBSTR(m.auxacc, 1, 2) IN ('WP','3C','BR','3D','1B','4D','5E','7G') OR SUBSTR(m.vencod, 1, 2) IN ('WP','3C','BR','3D','1B','4D','5E','7G'))
            AND m.OFFNBR <> '{office}' AND m.bkgofn <> '{bkgofn}'
            AND (m.genacc LIKE '1817%' OR m.genacc LIKE '120A%')
            UNION ALL
            SELECT 
                CASE WHEN SUBSTR(m.vencod, 1, 2) IN ('3C','WP','BR','3D','1B','4D','5E','7G') THEN m.vencod ELSE m.auxacc END AS newvencod,
                '未過帳明細帳' AS bookname,
                m.genacc || '-' || m.subacc || IFNULL(d.accnam, '') AS accnam,
                m.AMTNET, m.auxacc, m.vencod, m.auxac3, m.auxac4, m.trndsc,
                SUBSTR(DIGITS(m.reGYY), 2, 3) || '/' || DIGITS(m.reGMM) || '/' || DIGITS(m.regDD) || '---' || m.VOUID || '-' || SUBSTR(DIGITS(m.reGNBR), 3, 4) AS bkgdata,
                m.BKGOFN, m.OFFNBR, m.trnofn, m.ACTEM1
            FROM voud{offnbr} m
            LEFT JOIN acpacctn d ON m.regyy = d.year AND m.bkgofn = d.offnbr AND d.genacc = m.genacc AND d.subacc = m.subacc
            WHERE m.delctl <> 'D' AND m.bkgctl <> 'B'
            AND (SUBSTR(m.auxacc, 1, 2) IN ('WP','3C','BR','3D','1B','4D','5E','7G') OR SUBSTR(m.vencod, 1, 2) IN ('WP','3C','BR','3D','1B','4D','5E','7G'))
            AND SUBSTR(m.genacc, 1, 1) NOT IN ('4', '5')
            AND m.OFFNBR <> '{office}' AND m.bkgofn <> '{bkgofn}'
            AND (m.genacc LIKE '1817%' OR m.genacc LIKE '120A%')
        )
        SELECT e.bck2no, e.BCCUST, q.*
        FROM (SELECT bck2no, BCCUST FROM vbcname WHERE BCDEPT = '{office}CE4') e
        INNER JOIN temp_vencod p ON e.bck2no = p.vencod
        INNER JOIN vsusp_details q ON p.vencod = q.newvencod
        ORDER BY 1, 6
        LIMIT 5000""",

                    "unfinished": f"""select --- 上陳前檢查-未完工程157x已列帳未過帳明細(留意結帳當月) ---                                           
        '未過帳' bkgctl , bkgyy||digits(bkgmm)||digits(bkgdd) bkgdat,
        m.vouid||'-'||m.regnbr REGNBR               
        ,m.vouid||'-'||m.bkgnbr bkgnbr,m.genacc,M.subacc,accnam,auxacc,vencod,    
        auxac3,AUXAC4,amtnet,trndsc,m.OFFNBR,BKGOFN,M.TRNOFN,ACTEM1
        from voud{offnbr} m  
        LEFT JOIN  ACPACCTN N                                     
        ON M.regyy = N.YEAR      AND                                        
        M.BKGOFN = N.OFFNBR  AND                                            
        M.GENACC = N.GENACC  AND                                            
        M.SUBACC = N.SUBACC                                                 
        where    bkgctl<>'B' and delctl<>'D'   and m.offnbr='{office}' 
        and M.BKGOFN='{bkgofn}' and (M.GENACC='1571'  or M.GENACC='1572')   and bkgnbr <> '0'  
        order by 6,7,4,5
        limit 5000""",

                    "unfinished1": f"""with tempA  as ( --- 查詢工程已決算1571仍有餘額 ---
        select distinct auxacc                    
        from voud{offnbr}
        where offnbr='{office}'   and   delctl<>'D'  and  voucs  <> 'Y'  and 
        genacc in ('1501','1511','1521','1531','1541','1551','1561')
        ),
        tempB as ( select distinct bkgofn,genacc ,subacc ,a.auxacc,sum(amtnet) as  amtnet
        from voud{offnbr} A
        join tempA b
        on a.auxacc=b.auxacc
        where a.genacc in ('1571','1572')  and bkgofn='{bkgofn}' 
        group by bkgofn, genacc,subacc,a.auxacc
        union all
        select distinct bkgofn,genacc ,subacc ,D.auxacc,sum(amtnet) as amtnet
        from voudh0000  D   
        join tempA b
        on D.auxacc=b.auxacc
        where D.genacc in ('1571','1572') and bkgofn='{bkgofn}' 
        group by bkgofn, genacc,subacc,D.auxacc
        ),
        tempC as (
        select c.bkgofn,genacc ,subacc ,auxacc,e.pjnam,sum(amtnet) as amtnet, 7
        from tempB c
        left join  vproj2{offnbr} e
        on c.bkgofn=e.offnbr and c.auxacc=e.pjnbr 
        group by c.bkgofn, genacc,subacc,auxacc,e.pjnam
        having sum(amtnet) <>0
        ),
        tempD as (
        select auxacc,sum(amtnet) amtnet1
        from tempC F
        group by auxacc
        having sum(amtnet) >0
        order by 1)
        select  BKGOFN,GENACC,SUBACC,G.AUXACC,PJNAM,AMTNET,7 as Item7
        from tempC F
        join tempD G
        on F.auxacc=G.auxacc
        union all
        select '','','',f.auxacc,'小計', sum(f.amtnet),7.1
        from tempC F
        group by f.auxacc
        having sum(f.amtnet)>0
        union all
        select '','' ,'','7.1合計','', sum(amtnet1),7.2
        from tempD G
        group by 6
        having sum(amtnet1)>0
        order by 4,7,3
        limit 5000""",

                    "check1": f"""select  --- 上陳前檢查-4922-0501&4609-1002科目列帳機構非7050 ---
        substr(digits(reGYY),2,3)||'/'||digits(reGMM)||'/'||digits(regDD)
        ||RTRIM(trndsc)||'/'||''||amtnet as DATETRNDSC
        ,  VOUID, REGNBR, BKGNBR, BKGYY, BKGMM, BKGDD,genacc,subacc,
        aUXACC, vencod,auxac3,trnamt,DRCRID,amtnet
        , BKGOFN, OFFNBR, ACTEM1
        from voud{offnbr}
        where TRNOFN='{trnofn}' and  BKGYY={year}  and
        ((genacc = '4922' and subacc = '0501') or (genacc = '4609'  and subacc = '1002')or (genacc = '4921'  and subacc = '01')or (genacc = '4922'  and subacc = '04'))
        and  delctl<>'D'  and  voucs  <> 'Y' and bkgofn<>'7050'
        order by 8,9,1
        limit 5000""",

                    "check2": f"""select --- 查詢企客2253-04科目他機構劃入未沖轉明細 ---
        substr(digits(bkgdat),2,7) bkgdat,vouid,bkgnbr, genacc,subacc,auxacc,vencod,auxac3
        , amtnet,drcrid,trndsc ,RENCTL
        from vsusp{offnbr}
        where genacc='2253' and subacc like '04%'   and     renctl<>'*'
        and OFFNBR<>'{office}' and bkgofn='{bkgofn}'
        limit 5000""",

                    "check3": f"""select * --- 檢查營業稅代號:33銷退營業人未輸入統編 ---                                                           
        from  VTAx{offnbr}
        where tvoun1||tvouno  in (                                         
                    SELECT tvoun1||tvouno                                   
                    from  VTAx{offnbr}
                    where tvoun1||'-'||tvouno  in (                         
                        SELECT tvoun1||'-'||tvouno                          
                        from  VTAx{offnbr}
                        where   taxcod in ('33') and TSALNO='' and tserno>0 
        and  regyy={year} and regmm={month}  and  STROFN='{office}' )
                and  taxcod in ('31') and tserno>0     and  STROFN='{office}' ) 
            and tserno>0 and  STROFN='{office}' 
        order by  tvoun1||tvouno        
        limit 5000""",

                    "check4": f"""select * --- 檢查營業稅代號:33銷退「非」營業人但輸入統編 ---                                                           
        from  VTAx{offnbr}
        where tvoun1||tvouno  in (                                         
                    SELECT tvoun1||tvouno                                   
                    from  VTAx{offnbr}
                    where tvoun1||'-'||tvouno  in (                         
                        SELECT tvoun1||'-'||tvouno                          
                        from  VTAx{offnbr}
                        where   taxcod in ('33') and TSALNO<>'' and tserno>0 
        and  regyy={year} and regmm={month}  and  STROFN='{office}' )
                and  taxcod in ('37') and tserno>0     and  STROFN='{office}' ) 
            and tserno>0 and  STROFN='{office}' 
        order by  tvoun1||tvouno        
        limit 5000""",

                    "check7": f"""select --- 查詢營業稅代號:3F免稅金額 ---
        taxcod,decimal(sum(tnoamt),15,0) tnoamt,
        decimal(sum(taxamt),15,0) taxamt,decimal(sum(tnoamt+taxamt),15,0) totamt
        from  VTAx{offnbr}
        where  bkgyy= {year} and  
        tserno<>0  and  taxcod in ('3F','5F','6F','36','6A') 
        And STROFN='{office}'
        GROUP BY TAXCOD         
        limit 5000""",

                    "check8": f"""SELECT --- 查詢營業稅代號稅額合計數 ---
            CASE 
                WHEN taxcod IS NULL AND tvoun1 IS NULL AND TCONBR IS NULL THEN '總計'
                WHEN taxcod = '33' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '33小計'
                WHEN taxcod = '35' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '35小計'
                WHEN taxcod = '37' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '37小計'
                WHEN taxcod = '32' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '32小計'
                WHEN taxcod = '36' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '36小計'
                WHEN taxcod = '5E' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '5E小計'
                WHEN taxcod = '3F' AND tvoun1 IS NULL AND TCONBR IS NULL THEN '3F小計'
                ELSE TCONBR
            END AS TCONBR,
            COALESCE(tvoun1, '') AS tvoun1,
            COALESCE(taxcod, '') AS taxcod,
            DECIMAL(SUM(tnoamt), 15, 0) AS tnoamt,
            DECIMAL(SUM(CASE WHEN taxcod = '33' THEN taxamt * -1 ELSE taxamt END), 15, 0) AS taxamt,
            DECIMAL(SUM(tnoamt + taxamt), 15, 0) AS totamt
        FROM VTAx{offnbr}
        WHERE regyy = {year}
            AND (regmm BETWEEN {month}-1 AND {month})
            AND tserno <> 0
            AND taxcod IN ('33', '35', '37', '32', '36', '5E', '3F')
            AND STROFN = '{office}'
        GROUP BY 
            CUBE(TCONBR, tvoun1, taxcod)
        HAVING 
            (taxcod IS NOT NULL AND tvoun1 IS NOT NULL AND TCONBR IS NOT NULL) OR
            (taxcod IN ('33', '35', '37', '32', '36', '5E', '3F') AND tvoun1 IS NULL AND TCONBR IS NULL) OR
            (taxcod IS NULL AND tvoun1 IS NULL AND TCONBR IS NULL)
        ORDER BY 1        
        limit 5000""",

                    "check9": f"""SELECT --- 查詢營所稅代號:41T合計數是否為0, 若異常請在TAIS_7221更正 ---
        TAIYY||'-'||TAIMM YYMM,vouid,regnbr,taicod,SUM(PAYAMA  ) AMTNET,OFFNBR
        FROM  VTAI{offnbr}
        WHERE TAIYY={year}  and TAIMM={month}  and taicod='41T' and strofn='{office}'
        GROUP BY TAIYY||'-'||TAIMM,vouid,regnbr,taicod ,OFFNBR        
        limit 5000""",
        
                            "check10": f"""with table1 as (--- 查詢懸記帳未沖銷與主檔不符, 若異常可能為取消懸記帳追蹤所致 ---     
        select genacc,subacc,sum(amtnet) as amtnet
        from vsusp{offnbr}
        where  BKGOFN='{bkgofn}'  and renctl<>'*'                          
        group by genacc,subacc  )                                      
        select m.genacc,n.subacc,FULNAM,amttm,amtnet                   
        FROM VQRY2{offnbr}  m 
        LEFT JOIN  table1       n                                    
        on  m.GENACC=n.genacc and m.subacc=n.subacc
        where  year={year}   and month={month}
        and   amttm<>amtnet
        and m.Genacc||M.subacc in (select genacc||subacc             
        from table1  )                                     
        limit 5000""",

                            "check11": f"""select --- 一般保證品明細科目是否相對應(1872/2872) ---
        a.*
        from voud{offnbr} a
        join (
            select vouid, regnbr, offnbr, subacc
            from voud{offnbr}
            where genacc in ('1872','2872') and regyy = {year}
            group by vouid, regnbr, offnbr, subacc
            having sum(case drcrid when ' ' then trnamt when '-' then trnamt*-1 end) <> 0
        ) b on a.vouid = b.vouid and a.regnbr = b.regnbr
            and a.offnbr = b.offnbr and a.subacc = b.subacc
        where a.regyy = {year}
        and a.genacc in ('1872','2872')
        limit 5000""",

                            "check12": f"""select --- 五年連續未使用會計項目 ---
        n.genacc, n.subacc, n.accnam
        from acpacctn n
        where n.offnbr = '{office}' and n.year = {year}
        and not exists (
            select 1 from voud{offnbr} m
            where m.bkgofn = '{office}' and m.genacc = n.genacc and m.subacc = n.subacc
            and m.regyy in ({year},{year}-1,{year}-2))
        and not exists (
            select 1 from voudh0000 m
            where m.bkgofn = '{office}' and m.genacc = n.genacc and m.subacc = n.subacc
            and m.regyy in ({year}-3,{year}-4))
        order by n.genacc, n.subacc
        limit 5000""",
        
                            "check14": f"""select --- 當年度預收預付及保留科目未沖銷懸記帳 ---
        upper(bkgdat) bkgdat, substr(bkgdat,1,3)||'-'||m.vouid||'-'||m.regnbr regnbr,                            
        m.vouid||'-'||m.bkgnbr bkgnbr,m.genacc,M.subacc,accnam,auxacc,vencod,auxac3,
        AUXAC4,amtnet,trndsc,m.OFFNBR,BKGOFN,M.TRNOFN,ACTEM1,
        RENCTL,M.AUXAC5,M.AUXAC6,M.AUXAC7,M.AUXAC8,M.AUXAC9,M.AUXAC10,M.ACTEM2,M.RCVOFN,M.BKGGRP,M.STRGRP
        from vsusp{offnbr} m
        left join acpacctn n
        on m.genacc=n.genacc and m.subacc=n.subacc and
        m.offnbr=n.offnbr and n.year=SUBSTR((BKGDAT),1,3)
        where M.BKGOFN='{bkgofn}'
        and (m.GENACC like '12%' or m.GENACC like '2144%' or m.GENACC like '22%')
        and m.subacc like '%'
        and ( m.auxacc like '%{year}%'
        or m.vencod like '%{year}%'
        or m.auxac3 like '%{year}%' )
        and n.fulnam like '%%'
        and renctl<>'*'                                          
        limit 5000""",        

                    "check13": f"""select  --- 專標案結算後120A及2253-04仍有餘額 ---
        t.GENACC,t.SUBACC,accnam,auxacc,t.VENCOD,AUXAC3,sum(amtnet) amtnet, trndsc,b.bcnam
        from vsusp{offnbr} t
        left join vbcname b                                    
        on  t.vencod=b.BCK2NO
        LEFT JOIN  ACPACCTN N
        ON t.regyy = N.YEAR      AND                                        
        t.BKGOFN = N.OFFNBR  AND                                            
        t.GENACC = N.GENACC  AND                                            
        t.SUBACC = N.SUBACC                                                 
        where (t.vencod in (
        select distinct vencod
        from voud{offnbr}
        where  BKGOFN='{bkgofn}' and
        genacc in ('2253','120A' )  and (trndsc like '%結算%' or trndsc like '%預收轉%')
        and substr(vencod,1,2) in ('WP','3C','4D')
        and  delctl<>'D'  and  voucs  <> 'Y' )
        or t.vencod in (
        select distinct vencod
        from voudh0000
        where  BKGOFN='{bkgofn}'
        and (trndsc like '%結算%' or trndsc like '%預收轉%')
        and substr(vencod,1,2) in ('WP','3C','4D')
        and  delctl<>'D'  and  voucs  <> 'Y' ))
        and (t.genacc='120A' or (t.genacc='2253' and t.subacc like '04%') )
        and   renctl<>'*' and trnofn='{trnofn}'
        group by t.genacc,t.subacc,auxacc,t.VENCOD,AUXAC3, trndsc,accnam,bcnam
        having sum(amtnet)<>0
        union all
        select '未過帳_'|| m.GENACC GENACC,m.SUBACC,n.accnam accnam ,m.auxacc ,m.vencod,m.auxac3,sum(amtnet) AMTNET
         ,m.trndsc,b.BCNAM           
        from voud{offnbr} m 
        left join vbcname b                                    
        on  m.vencod=b.BCK2NO
        LEFT JOIN  ACPACCTN N                                     
        ON M.regyy = N.YEAR      AND                                        
        M.BKGOFN = N.OFFNBR  AND                                            
        M.GENACC = N.GENACC  AND                                            
        M.SUBACC = N.SUBACC                                                 
        where    bkgctl<>'B' and delctl<>'D'  
        and (m.vencod in (
        select distinct vencod
        from voud{offnbr}
        where  BKGOFN='{bkgofn}' and
        genacc in ('2253','120A' )  and (trndsc like '%結算%' or trndsc like '%預收轉%')
        and substr(vencod,1,2) in ('WP','3C','4D')
        and  delctl<>'D'  and  voucs  <> 'Y' ))
        and M.BKGOFN='{bkgofn}'  and 
        (m.genacc in ('120A') or (m.genacc in ('2253') and m.subacc in ('04'))  )                          
        group by m.genacc,m.subacc,m.auxacc,m.VENCOD,BCNAM,m.auxac3,n.accnam ,m.trndsc
        having sum(amtnet)<>0                 
        order by 5,2                      
        limit 5000""",
        
                    "check5": f"""with temp as ( --- 專標案結算後科目仍有餘額(含歷史檔) ---                                                    
        select distinct (CASE WHEN SUBSTR(auxacc,1,2) IN ('3C',  '4D',     
        'WP','BR','3D')  THEN auxacc  ELSE vencod   END) AS vencod        
        from voud{offnbr}
        where  BKGOFN='{bkgofn}' and (genacc='1211' or (
        substr(vencod,1,2) IN ('3D','3C','WP','BR','4D')               
        and  (trndsc like '%結算%' or trndsc like '%預收轉%'))  )      
        and  delctl<>'D'  and  voucs  <> 'Y'                                
        union                                                              
        select distinct (CASE WHEN SUBSTR(auxacc,1,2) IN ('3C',  '4D',    
        'WP','BR','3D')  THEN auxacc  ELSE vencod   END) AS vencod       
        from voudh0000
        where  BKGOFN='{bkgofn}' and (genacc='1211' or ( 
        substr(vencod,1,2) IN ('3D','3C','WP','BR','4D')               
        and  (trndsc like '%結算%' or trndsc like '%預收轉%'))  )      
        and  delctl<>'D'  and  voucs  <> 'Y'                )               
        select  a.GENACC,a.SUBACC,accnam ,a.auxacc ,a.VENCOD,sum(amtnet) AMTNET
        ,BCNAM,BCKTNO,BCWNDW,BCCHRG ,BCACDT    , digits(CNENDDAT) CNENDDAT                 
        from vsusp{offnbr} a   
        left join temp t                                                  
        on ( a.vencod=t.vencod or a.auxacc=t.vencod)                       
        left join vbcname b                                    
        on  a.vencod=BCK2NO                                                
        left join acpacctn d                                                
        on d.genacc=a.genacc and d.subacc=a.subacc  and                    
        a.bkgofn=d.offnbr   and                                            
        ((substr(a.bkgdat,1,3)<=106 and d.year =107 ) or                   
        (substr(a.bkgdat,1,3)=d.year and substr(a.bkgdat,1,3)>106))        
        where  (a.genacc in ('120A','2253',                                 
        '2144','1253','1261','1816','2147')  or a.genacc='1144' and a.subacc like '98U%') and   renctl<>'*'              
        and BKGOFN='{bkgofn}' and  ( a.vencod=t.vencod or a.auxacc=t.vencod)  
        group by a.genacc,a.subacc,a.auxacc,a.VENCOD,AUXAC3,BCNAM,BCKTNO   
        ,BCWNDW,BCCHRG ,accnam ,BCACDT , digits(CNENDDAT)                                       
        union   all                                                           
        select '未過帳_'|| m.GENACC,m.SUBACC,n.accnam ,m.auxacc ,m.vencod,sum(amtnet) AMTNET
        ,BCNAM,BCKTNO,BCWNDW,trim(BCCHRG), BCACDT    , digits(CNENDDAT) CNENDDAT                 
        from voud{offnbr} m 
        left join temp t                                                  
        on ( m.vencod=t.vencod or m.auxacc=t.vencod)                       
        left join vbcname b                                    
        on  m.vencod=BCK2NO                                                
        LEFT JOIN  ACPACCTN N                                     
        ON M.regyy = N.YEAR      AND                                        
        M.BKGOFN = N.OFFNBR  AND                                            
        M.GENACC = N.GENACC  AND                                            
        M.SUBACC = N.SUBACC                                                 
        where    bkgctl<>'B' and delctl<>'D'   
        and M.BKGOFN='{bkgofn}' and ( m.vencod=t.vencod or m.auxacc=t.vencod) and 
        (m.genacc in ('120A','2253',                                 
        '2144','1253','1261','1816','2147')  or m.genacc='1144' and m.subacc like '98U%')             
        group by m.genacc,m.subacc,m.auxacc,m.VENCOD,AUXAC3,BCNAM,BCKTNO   
        ,BCWNDW,BCCHRG ,accnam ,BCACDT , digits(CNENDDAT)                                    
        having sum(amtnet)<>0                 
        order by 5,1                      
        limit 5000""",

                    "check6": f"""With tempA as( --- 上陳前檢查相關科目餘額(2825等)(含未過帳) ---
        select distinct m.genacc||'-'||m.subacc ACCNUM, m.fulnam,                        
        m.year||'-'||m.month BKGYM, m.damttm , m.camttm, m.AMTTM                    
        from  VQRY2{offnbr} m
        where  YEAR={year}  and  MONTH={month} and
        (genacc in ('1162','1822','1823','1813','1261','1178'
        ,'1257','1261','2825','1816', '1257' ,'5913','2147')   and                               
        subacc in ('22CI','5602','9999','57','01A','02','2402A'
        ,'04A','09CI'))                                   
        ) , tempB as(
        select distinct m.genacc||'-'||m.subacc ACCNUM, '',m.bkgyy,m.offnbr,
        m.bkgyy||'-'||m.bkgmm BKGYM, '' , '', sum(m.amtnet) sum01
        from voud{offnbr} m
        where  bkgyy={year}  and  bkgmm={month} and
        (offnbr='{offnbr}' and m.genacc in ('2825') and
        m.subacc in ('44S','45')) and delctl<>'D' and bkgctl='B'
        group by m.genacc||'-'||m.subacc, m.bkgyy||'-'||m.bkgmm,m.bkgyy,m.offnbr
        ),
        tempC as(
        select  distinct c.genacc||'-'||c.subacc ACCNUM,sum(COALESCE(c.amtnet,0)) sum03
        from voud{offnbr} c
        where   delctl<>'D' and bkgctl<>'B'  and regyy={year} and regmm={month} and 
        ( bkgofn='{bkgofn}'  and c.genacc in ('1162','1822','1823','1813','1261','1178'
        ,'1257','1261','2825','1816', '1257' ,'5913','2147')   and                               
        c.subacc in ('22CI','5602','9999','57','01A','02','2402A'
        ,'04A','09CI') )                                  
        group by c.genacc||'-'||c.subacc
        ),
        tempD as(
        select distinct d.genacc||'-'||d.subacc ACCNUM,sum(COALESCE(d.amtnet,0)) sum02
        from voud{offnbr} d
        where delctl<>'D' and bkgctl<>'B' and
        (offnbr='{offnbr}' and d.genacc in ('2825') and
        d.subacc in ('44S','45'))
        group by d.genacc||'-'||d.subacc
        )
        select distinct a.ACCNUM,a.fulnam,                         
        a.BKGYM,a.damttm,a.camttm, a.AMTTM ,COALESCE(c.sum03,0) UNPOSTED, COALESCE(a.AMTTM, 0) + COALESCE(c.sum03, 0) as SUM, case when a.ACCNUM='2825-5602' then '1816.2A or 2825.2A' when a.accnum  in ('2825-0201') then '後二碼是月份須調整' else '' end NOTEs      
        from tempA a
        left join tempC c
        on a.ACCNUM=c.ACCNUM
        union all
        select distinct b.accnum ,n.fulnam,b.bkgym,'','',COALESCE(b.sum01, 0),COALESCE(d.sum02,0) UNPOSTED ,COALESCE(b.sum01, 0) + COALESCE(d.sum02, 0) as SUM, case when b.accnum  in ('2825-44S','2825-45') then 'BKGOFN=2040' else '' end NOTEs
        from tempB b
        LEFT JOIN ACPACCTN N
        on b.bkgyy=n.year and b.offnbr=n.offnbr and
        b.accnum = n.genacc||'-'||n.subacc
        left join tempD d
        on b.accnum=d.accnum
        order by 1        
        limit 5000""",

                    "projectsheet": f"""with AAA as ( --- 工程編號結算表 ---
        select cpnbr||Pjcode as pname ,
        subacc,
        n.pjnam,
        0 as amt1,
        (EXPTM+TAMTTM) as amt2,
        (TAMTTM) as amt3,
        (AEXPLM+EXPTM+TAMTTY) as amt4,
        (TAMTTY) as amt5,
        (TAMTPY)
        as amt6,
        (EXPPY+AEXPLM+EXPTM) as amt7,
        0 as amt8
        from acpprojm a join acpmdata b
        on a.year=b.year and a.month=b.month and b.bkgofn='0000'
        left join VPROJ2{offnbr} n
        on n.pjnbr=a.cpnbr||a.pjcode and n.offnbr=a.bkgofn
        where a.BKGOFN='{bkgofn}' and cpnbr||Pjcode='{projectno}'
        union all
        select CPNBR||PJCODE||BUSTYP as pname,
        subacc,
        n.pjnam,
        (accbamt+incbgt-decbgt) as amt1 ,
        0 as amt2 ,
        0 as amt3
        ,
        0 as amt4 ,
        0 as amt5 ,
        0 as amt6 ,
        0 as amt7 ,
        0 as amt8
        from VPJBGA{offnbr} c
        left join VPROJ2{offnbr} n
        on n.pjnbr=c.cpnbr||c.pjcode||c.BUSTYP and n.offnbr=c.offnbr
        where c.offnbr='{office}' and CPNBR||PJCODE||BUSTYP='{projectno}' and CPYEAR> 0
        union all
        select auxacc as pname,
        subacc,
        pjnam,
        0 as amt1,
        0 as amt2 ,
        0 as amt3
        ,
        0 as amt4,
        0 as amt5 ,
        0 as amt6 ,
        0 as amt7 ,
        amtnet as amt8
        from voud{offnbr} d
        left join VPROJ2{offnbr} n
        on n.pjnbr=d.auxacc and n.offnbr=d.bkgofn
        where delctl<>'D' and bkgctl<>'B' and ( genacc like '1571%' or genacc like '1572%') and
        auxacc='{projectno}' )
        select    pname,subacc,pjnam,sum(amt1) BUDGET,sum (amt2) EXPTM,sum(amt3) TRNSTM, sum(amt4) EXPTY,        
        sum(amt5) TRNSTY,sum(amt6) TRNSLY,sum(amt7) UNBALNCE,sum(amt8) UNPOSTED,sum(amt7+amt8) UNPSTBALNCE    
        from aaa  a   
        group by pname,
        subacc,pjnam 
        having not (sum(amt1)=0 and sum(amt2)=0
        and sum(amt4)=0 and sum(amt5)=0
        and sum(amt7)=0 and sum(amt8)=0 )
        union all                                                           
        select pname,'9-1材料小計 ','',sum(amt1),sum (amt2),sum(amt3),sum(amt4),
        sum(amt5),sum(amt6),sum(amt7),sum(amt8) ,sum(amt7+amt8) as amt9
        from aaa
        where subacc like '1%'
        group by  pname
        union all                                                           
        select pname,'9-2人工小計 ','',sum(amt1),sum (amt2),sum(amt3),sum(amt4),
        sum(amt5),sum(amt6),sum(amt7),sum(amt8) ,sum(amt7+amt8) as amt9
        from aaa
        where subacc like '2%'
        group by  pname
        union all                                                           
        select pname,'9-3其他小計 ','',sum(amt1),sum (amt2),sum(amt3),sum(amt4),
        sum(amt5),sum(amt6),sum(amt7),sum(amt8) ,sum(amt7+amt8) as amt9
        from aaa
        where subacc like '3%'
        group by  pname
        union all                                                           
        select pname,'9-4間接小計 ','',sum(amt1),sum (amt2),sum(amt3),sum(amt4),
        sum(amt5),sum(amt6),sum(amt7),sum(amt8) ,sum(amt7+amt8) as amt9
        from aaa
        where   substr(subacc,1,1) not in ('1','2','3')
        group by  pname
        union all                                                           
        select pname,'9 合計 ','',sum(amt1),sum (amt2),sum(amt3),sum(amt4), 
        sum(amt5),sum(amt6),sum(amt7),sum(amt8) ,sum(amt7+amt8) as amt9    
        from aaa                                                            
        group by  pname                                                     
        order by 2,3                                          
        limit 5000"""
        }
        
        return sql_templates.get(query_type, "-- 未找到對應的查詢模板")
    
