    def setup_result_table_context_menu(self):
        """設定查詢結果表格的右鍵選單功能"""
        try:
            if hasattr(self, 'result_table'):
                # 設定右鍵選單政策
                self.result_table.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
                self.result_table.customContextMenuRequested.connect(self.show_result_table_context_menu)
                print("✅ 查詢結果表格右鍵選單已設定")
        except Exception as e:
            print(f"❌ 設定查詢結果表格右鍵選單時發生錯誤: {e}")

    def show_result_table_context_menu(self, position):
        """顯示查詢結果表格的右鍵選單"""
        try:
            # 獲取點擊位置的項目
            item = self.result_table.itemAt(position)
            if not item:
                return
            
            # 獲取選中的行
            row = item.row()
            if row < 0:
                return
            
            # 提取該行的參數
            row_params = self.extract_row_parameters(row)
            if not row_params:
                QMessageBox.warning(self, "警告", "無法從該行提取有效參數")
                return
            
            # 創建右鍵選單
            context_menu = QMenu(self)
            
            # 添加標題
            title_action = context_menu.addAction(f"📊 使用第 {row + 1} 行資料執行查詢")
            title_action.setEnabled(False)
            
            context_menu.addSeparator()
            
            # 添加SQL基本查詢選項
            sql_queries = [
                ("📊 傳票查詢", "voucher_query", "查詢傳票基本資料"),
                ("📊 歷史檔傳票查詢", "voucher_queryH", "查詢傳票基本資料"),                
                ("🔗 傳票明細查詢", "voucher_detail_query", "查詢傳票詳細內容"),
                ("🔗 歷史檔傳票明細查詢", "voucher_detail_queryH", "查詢傳票詳細內容"),                
                ("📈 懸記帳查詢", "suspense_query", "查詢懸記帳資料"),
                ("🔍 主檔查詢", "master_query", "查詢主檔科目資料"),
                ("📅 營業稅查詢", "tax_query", "查詢營業稅發票資料"),
                ("🎯 專標案查詢", "project_query", "查詢專案相關的收入費用明細"),
            ]
            
            for query_name, query_type, description in sql_queries:
                action = context_menu.addAction(query_name)
                action.setToolTip(description)
                # 使用lambda捕獲當前的query_type和row_params
                action.triggered.connect(
                    lambda checked, qt=query_type, rp=row_params.copy(): 
                    self.execute_sql_query_with_params(qt, rp)
                )
            
            context_menu.addSeparator()
            
            # 添加參數預覽
            params_action = context_menu.addAction("👁️ 預覽提取的參數")
            params_action.triggered.connect(lambda: self.preview_extracted_params(row_params))
            
            # 顯示選單
            context_menu.exec(self.result_table.mapToGlobal(position))
            
        except Exception as e:
            print(f"❌ 顯示右鍵選單時發生錯誤: {e}")
            QMessageBox.critical(self, "錯誤", f"顯示右鍵選單時發生錯誤：{str(e)}")

    def extract_row_parameters(self, row):
        """從指定行提取查詢參數 - 修正版"""
        try:
            if not hasattr(self, 'current_data') or self.current_data is None:
                print("❌ 無當前資料可提取參數")
                return None
            
            if row >= len(self.current_data):
                print(f"❌ 行索引 {row} 超出資料範圍")
                return None
            
            # 獲取該行的資料
            row_data = self.current_data.iloc[row]
            params = {}
            
            print(f"🔍 開始提取第 {row + 1} 行的參數...")
            
            # 定義參數提取映射 - 修正參數名稱一致性
            param_mappings = {
                # 年度相關
                'year': ['YEAR', 'year', '年度', 'regyy', 'REGYY'],
                'month': ['MONTH', 'month', '月份', 'regmm', 'REGMM'],
                
                # 機構相關 - 統一使用offnbr
                'offnbr': ['OFFNBR', 'offnbr', '製票機構', '機構代號'],
                'bkgofn': ['BKGOFN', 'bkgofn', '列帳機構'],
                'trnofn': ['TRNOFN', 'trnofn', '交易機構'],
                
                # 科目相關
                'genacc': ['GENACC', 'genacc', '總帳', '總帳科目'],
                'subacc': ['SUBACC', 'subacc', '明細帳', '明細科目'],
                
                # 專案和發票相關
                'vencod': ['VENCOD', 'vencod', 'bck2no', 'NEWVENCOD', 'newvencod', '專案編號/廠商統編', '專案編號'],
                'auxacc': ['AUXACC', 'auxacc', '輔助帳號', '輔助帳號1'],
                'auxac3': ['AUXAC3', 'auxac3', '輔助帳號三', '輔助帳號3'], 
                'auxac4': ['AUXAC4', 'auxac4', '輔助帳號四', '輔助帳號4'],                                
                'tvouno': ['TVOUNO', 'tvouno', '發票號碼'],
                
                # 傳票相關
                'vouid': ['VOUID', 'vouid', '傳票種類'],
                'regnbr': ['REGNBR', 'regnbr', '製票編號'],
                'bkgnbr': ['BKGNBR', 'bkgnbr', '列帳編號'],
                
                # 特殊處理：製票及列帳編號
                'bkgdata': ['BKGDATA', 'bkgdata', '製票及列帳編號']
            }
            
            # 遍歷所有欄位，嘗試匹配和提取參數
            for original_col in self.current_data.columns:
                display_col = self.get_display_column_name(original_col)
                cell_value = row_data[original_col]
                
                # 跳過空值
                if pd.isna(cell_value) or str(cell_value).strip() == "":
                    continue
                
                cell_value_str = str(cell_value).strip()
                
                # 遍歷參數映射，查找匹配的欄位
                for param_key, field_names in param_mappings.items():
                    if original_col in field_names or display_col in field_names:
                        # 特殊處理BKGDATA（製票及列帳編號）
                        if param_key == 'bkgdata' and cell_value_str:
                            extracted_params = self.parse_bkgdata_string(cell_value_str)
                            params.update(extracted_params)
                            print(f"   📋 {display_col}: {cell_value_str} -> 解析出: {extracted_params}")
                        
                        # 特殊處理REGNBR（製票編號）格式如 "114-3-1157"
                        elif param_key == 'regnbr' and cell_value_str and '-' in cell_value_str:
                            extracted_params = self.parse_regnbr_string(cell_value_str)
                            params.update(extracted_params)
                            print(f"   📋 {display_col}: {cell_value_str} -> 解析出: {extracted_params}")
                        
                        # 一般參數直接存儲
                        else:
                            params[param_key] = cell_value_str
                            print(f"   📋 {display_col}: {cell_value_str}")
                        
                        break
            
            # 補充預設值和驗證
            params = self.supplement_default_params(params)
            
            print(f"✅ 參數提取完成，共提取 {len(params)} 個參數")
            return params
            
        except Exception as e:
            print(f"❌ 提取行參數時發生錯誤: {e}")
            return None

    def supplement_default_params(self, params):
        """補充預設參數和驗證 - 修正版"""
        try:
            # 設定預設值 - 確保所有必要參數都有預設值
            defaults = {
                'year': '114',
                'month': '9', 
                'auxacc': '',      # 輔助帳號                
                'vencod': '',      # 專案編號/廠商統編
                'auxac3': '',      # 輔助帳號三 
                'auxac4': '',      # 輔助帳號四                                 
                'genacc': '',      # 總帳科目
                'subacc': '',      # 明細科目
                'vouid': '3',      # 傳票種類
                'regnbr': '',      # 製票編號
                'bkgnbr': '',      # 列帳編號
                'offnbr': '3047',  # 製票機構
                'bkgofn': '',  # 列帳機構
                'trnofn': '3047',  # 交易機構
                'tvouno': '97192325'       # 發票號碼
            }
            
            # 補充缺失的參數
            for key, default_value in defaults.items():
                if key not in params or not params[key]:
                    params[key] = default_value
                    print(f"   🔧 補充預設參數 {key}: {default_value}")
            
            # 參數驗證和修正
            if params.get('year') and len(params['year']) > 3:
                # 如果年度是完整西元年，轉為民國年
                try:
                    year_int = int(params['year'])
                    if year_int > 1911:
                        params['year'] = str(year_int - 1911)
                        print(f"   🔧 轉換年度格式: {year_int} -> {params['year']}")
                except:
                    pass
            
            # 確保數字參數是字串格式
            numeric_params = ['year', 'month', 'vouid', 'regnbr', 'bkgnbr']
            for param in numeric_params:
                if param in params and params[param]:
                    params[param] = str(params[param]).strip()
            
            print(f"🔧 最終參數: {params}")
            return params
            
        except Exception as e:
            print(f"❌ 補充預設參數時發生錯誤: {e}")
            return params

    def parse_bkgdata_string(self, bkgdata_str):
        """解析製票及列帳編號字串，提取年度、傳票種類、製票編號等"""
        try:
            params = {}
            
            # BKGDATA格式範例: "114/6/19---3-1157  列帳3-1080"
            # 另一種格式: "114-3-1157"
            
            if '---' in bkgdata_str:
                # 分割製票和列帳部分
                parts = bkgdata_str.split('---')
                if len(parts) >= 2:
                    # 製票部分：如 "114/6/19"
                    make_part = parts[0].strip()
                    if '/' in make_part:
                        date_parts = make_part.split('/')
                        if len(date_parts) >= 3:
                            params['year'] = date_parts[0]  # 年度
                            params['month'] = date_parts[1]  # 月份
                    
                    # 列帳部分：如 "3-1157  列帳3-1080"
                    book_part = parts[1].strip()
                    if '-' in book_part:
                        # 提取第一個出現的傳票種類-編號
                        voucher_match = book_part.split()[0]  # 取第一個空格前的部分
                        if '-' in voucher_match:
                            voucher_parts = voucher_match.split('-')
                            if len(voucher_parts) >= 2:
                                params['vouid'] = voucher_parts[0]  # 傳票種類
                                params['regnbr'] = voucher_parts[1]  # 製票編號
            
            elif '-' in bkgdata_str:
                # 簡單格式："114-3-1157"
                parts = bkgdata_str.split('-')
                if len(parts) >= 3:
                    params['year'] = parts[0]  # 年度
                    params['vouid'] = parts[1]  # 傳票種類
                    params['regnbr'] = parts[2]  # 製票編號
            
            return params
            
        except Exception as e:
            print(f"❌ 解析BKGDATA字串時發生錯誤: {e}")
            return {}

    def parse_regnbr_string(self, regnbr_str):
        """解析製票編號字串，提取年度、傳票種類、製票編號"""
        try:
            params = {}
            
            # REGNBR格式範例: "114-3-1157"
            if '-' in regnbr_str:
                parts = regnbr_str.split('-')
                if len(parts) >= 3:
                    params['year'] = parts[0]  # 年度
                    params['vouid'] = parts[1]  # 傳票種類  
                    params['regnbr'] = parts[2]  # 製票編號
                elif len(parts) == 2:
                    params['vouid'] = parts[0]  # 傳票種類
                    params['regnbr'] = parts[1]  # 製票編號
            
            return params
            
        except Exception as e:
            print(f"❌ 解析REGNBR字串時發生錯誤: {e}")
            return {}

