    def update_parameter_inputs_with_extracted_params(self, params):
        """使用提取的參數更新參數設定界面"""
        try:
            if not hasattr(self, 'parameter_inputs'):
                print("⚠️ 參數輸入控制項未初始化")
                return
            
            # 參數名稱映射（從提取的參數名稱到界面參數名稱）
            param_mapping = {
                'year': '年度',
                'month': '月份',
                'auxacc': '輔助帳號',                
                'vencod': '專案編號',
                'auxac3': '輔助帳號三', 
                'auxac4': '輔助帳號四',                                  
                'genacc': '總帳科目',
                'subacc': '明細科目',
                'vouid': '傳票種類',
                'regnbr': '製票編號',
                'bkgnbr': '列帳編號',
                'offnbr': '製票機構', 
                'bkgofn': '列帳機構',
                'trnofn': '交易機構',
                'tvouno': '發票號碼'
            }
            
            updated_count = 0
            for param_key, param_value in params.items():
                if param_key in param_mapping and param_value:
                    ui_param_name = param_mapping[param_key]
                    
                    if ui_param_name in self.parameter_inputs:
                        widget = self.parameter_inputs[ui_param_name]
                        
                        if hasattr(widget, 'setText'):
                            # QLineEdit
                            widget.setText(str(param_value))
                            updated_count += 1
                            print(f"   ✅ 更新 {ui_param_name}: {param_value}")
                        elif hasattr(widget, 'setCurrentText'):
                            # QComboBox
                            widget.setCurrentText(str(param_value))
                            updated_count += 1
                            print(f"   ✅ 更新 {ui_param_name}: {param_value}")
            
            print(f"🔄 參數界面更新完成，共更新 {updated_count} 個參數")
            
        except Exception as e:
            print(f"❌ 更新參數界面時發生錯誤: {e}")
            
