    def setup_dashboard_tab(self):
        """設定監控儀表板標籤頁"""
        # 初始化儀表板狀態儲存
        # status: 'unrun' | 'running' | 'normal' | 'warning' | 'error'
        self.dashboard_results = {}
        self.dashboard_thread = None
        self.dashboard_cards = {}   # query_type -> dict of label widgets
        self._build_dashboard_ui()

    def _build_dashboard_ui(self):
        """建立監控儀表板 UI"""
        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)

        scroll_widget = QWidget()
        scroll.setWidget(scroll_widget)

        tab_layout = QVBoxLayout(self.dashboard_tab)
        tab_layout.setContentsMargins(0, 0, 0, 0)
        tab_layout.addWidget(scroll)

        main_layout = QVBoxLayout(scroll_widget)
        main_layout.setSpacing(5)  # v5_14: 9 → 5
        main_layout.setContentsMargins(7, 5, 7, 5)  # v5_14: (14,9,14,9)→(7,5,7,5)

        # 頂部工具列
        self._build_dashboard_toolbar(main_layout)

        # 摘要統計列
        self._build_dashboard_summary(main_layout)

        # 分組查詢卡片
        self._build_dashboard_groups(main_layout)

        # 執行日誌區
        self._build_dashboard_log(main_layout)

        main_layout.addStretch()

