# v5.17 新增：Email 寄送功能（Outlook / SMTP 雙模式）
# ============================================================


def _auto_col_width(ws, max_width=55):
    """自動調整 openpyxl 工作表欄位寬度（依內容最長文字計算）"""
    try:
        from openpyxl.utils import get_column_letter
        for col in ws.columns:
            max_len = max(
                (len(str(c.value)) if c.value is not None else 0 for c in col),
                default=8
            )
            ws.column_dimensions[get_column_letter(col[0].column)].width = min(max_len + 2, max_width)
    except Exception:
        pass

def _build_email_send_dialog(parent, title_text, df_getter, default_subject=""):
    """
    通用 Email 寄送對話框工廠。
    df_getter()：呼叫時回傳要附加的 DataFrame；
                 若為 None 或空則提示警告後關閉。
    """
    from PyQt6.QtWidgets import (
        QDialog, QVBoxLayout, QHBoxLayout, QLabel,
        QLineEdit, QPushButton, QRadioButton,
        QButtonGroup, QWidget, QGroupBox, QMessageBox
    )

    dlg = QDialog(parent)
    dlg.setWindowTitle(title_text)
    dlg.setMinimumWidth(480)
    dlg.setStyleSheet("""
        QDialog { background: #f8f9fa; }
        QLabel  { font-size: 12px; font-family: 'Microsoft JhengHei'; }
        QLineEdit {
            font-size: 12px; font-family: 'Microsoft JhengHei';
            border: 1px solid #ced4da; border-radius: 4px;
            padding: 5px 8px; background: white;
        }
        QPushButton {
            font-size: 12px; font-family: 'Microsoft JhengHei';
            font-weight: bold; color: white; border: none;
            border-radius: 5px; padding: 7px 18px;
        }
        QGroupBox {
            font-size: 12px; font-family: 'Microsoft JhengHei';
            font-weight: bold; border: 1px solid #dee2e6;
            border-radius: 6px; margin-top: 6px; padding-top: 10px;
        }
        QGroupBox::title { subcontrol-origin: margin; left: 10px; padding: 0 4px; }
    """)

    main_layout = QVBoxLayout(dlg)
    main_layout.setSpacing(10)
    main_layout.setContentsMargins(18, 18, 18, 14)

    # ── 模式選擇 ──
    mode_grp = QGroupBox("寄送模式")
    mode_lay  = QHBoxLayout(mode_grp)
    rb_outlook = QRadioButton("📨 Outlook（本機）")
    rb_smtp    = QRadioButton("📡 SMTP（自訂）")
    rb_outlook.setChecked(True)
    rb_outlook.setStyleSheet("font-size:12px;font-family:'Microsoft JhengHei';")
    rb_smtp.setStyleSheet("font-size:12px;font-family:'Microsoft JhengHei';")
    bg = QButtonGroup(dlg)
    bg.addButton(rb_outlook, 0)
    bg.addButton(rb_smtp, 1)
    mode_lay.addWidget(rb_outlook)
    mode_lay.addWidget(rb_smtp)
    mode_lay.addStretch()
    main_layout.addWidget(mode_grp)

    # ── 收件人 ──
    to_layout = QHBoxLayout()
    to_layout.addWidget(QLabel("收件人 *："))
    to_edit = QLineEdit()
    to_edit.setPlaceholderText("recipient@cht.com.tw（多位用分號 ; 分隔）")
    to_layout.addWidget(to_edit)
    main_layout.addLayout(to_layout)

    # ── 主旨 ──
    subj_layout = QHBoxLayout()
    subj_layout.addWidget(QLabel("郵件主旨："))
    subj_edit = QLineEdit()
    subj_edit.setPlaceholderText("（選填，預設帶入系統名稱與時間）")
    if default_subject:
        subj_edit.setText(default_subject)
    subj_layout.addWidget(subj_edit)
    main_layout.addLayout(subj_layout)

    # ── SMTP 設定區（預設隱藏）──
    smtp_grp = QGroupBox("⚙️ SMTP 伺服器設定")
    smtp_grp.setVisible(False)
    smtp_form = QVBoxLayout(smtp_grp)

    def _smtp_row(label_text, placeholder, pw=False):
        row = QHBoxLayout()
        lbl = QLabel(label_text)
        lbl.setFixedWidth(90)
        inp = QLineEdit()
        inp.setPlaceholderText(placeholder)
        if pw:
            inp.setEchoMode(QLineEdit.EchoMode.Password)
        row.addWidget(lbl)
        row.addWidget(inp)
        smtp_form.addLayout(row)
        return inp

    host_edit = _smtp_row("SMTP 主機 *：", "smtp.example.com")
    port_edit = _smtp_row("SMTP Port *：", "587")
    port_edit.setText("587")
    user_edit = _smtp_row("帳號 *：", "sender@example.com")
    pass_edit = _smtp_row("密碼 *：", "SMTP 密碼或應用程式密碼", pw=True)
    main_layout.addWidget(smtp_grp)

    def _on_mode_change(_):
        smtp_grp.setVisible(rb_smtp.isChecked())
        dlg.adjustSize()

    rb_outlook.toggled.connect(_on_mode_change)
    rb_smtp.toggled.connect(_on_mode_change)

    # ── 按鈕列 ──
    btn_row = QHBoxLayout()
    btn_row.addStretch()
    send_btn = QPushButton("📤 寄送")
    send_btn.setStyleSheet("QPushButton{background:#20c997;}QPushButton:hover{background:#17a589;}")
    cancel_btn = QPushButton("取消")
    cancel_btn.setStyleSheet("QPushButton{background:#6c757d;}QPushButton:hover{background:#5a6268;}")
    btn_row.addWidget(send_btn)
    btn_row.addWidget(cancel_btn)
    main_layout.addLayout(btn_row)
    cancel_btn.clicked.connect(dlg.reject)

    def _do_send():
        to_val = to_edit.text().strip()
        if not to_val:
            QMessageBox.warning(dlg, "警告", "請填寫收件人 Email！")
            return

        df = df_getter()
        if df is None or (hasattr(df, 'empty') and df.empty):
            QMessageBox.warning(dlg, "警告", "目前無可寄送的資料！")
            return

        subj = subj_edit.text().strip() or (
            f"[TAIS查詢] 查詢結果 {__import__('datetime').datetime.now().strftime('%Y/%m/%d %H:%M')}"
        )
        body = (
            f"您好，\n\n附件為 TAIS 綜合管理系統匯出的資料，共 {len(df)} 筆記錄。\n"
            f"匯出時間：{__import__('datetime').datetime.now().strftime('%Y/%m/%d %H:%M:%S')}\n\n"
            "此郵件由系統自動寄送。\n"
        )

        import tempfile, os
        now_str = __import__('datetime').datetime.now().strftime('%Y%m%d_%H%M%S')
        tmp_path = os.path.join(tempfile.gettempdir(), f"TAIS_query_{now_str}.xlsx")

        try:
            with pd.ExcelWriter(tmp_path, engine='openpyxl') as writer:
                df.to_excel(writer, index=False, sheet_name="查詢結果")
                _auto_col_width(writer.sheets["查詢結果"])

            if rb_outlook.isChecked():
                import win32com.client as win32
                outlook = win32.Dispatch('outlook.application')
                mail = outlook.CreateItem(0)
                mail.To      = to_val.replace(';', '; ')
                mail.Subject = subj
                mail.Body    = body
                mail.Attachments.Add(tmp_path)
                mail.Send()
                _cfm_dlg = QDialog(dlg)
                _cfm_dlg.setWindowTitle("完成")
                _cfm_dlg.setMinimumWidth(380)
                _cfm_vlay = QVBoxLayout(_cfm_dlg)
                _cfm_vlay.setContentsMargins(20, 16, 20, 14)
                _cfm_lbl = QLabel(f"✅ 已透過 Outlook 寄送至：{to_val}")
                _cfm_lbl.setWordWrap(True)
                _cfm_lbl.setStyleSheet("font-family:'Microsoft JhengHei';font-size:12px;")
                _cfm_vlay.addWidget(_cfm_lbl)
                _cfm_blay = QHBoxLayout()
                _cfm_blay.addStretch()
                _cfm_btn = QPushButton("確定")
                _cfm_btn.setFixedWidth(80)
                _cfm_btn.setStyleSheet("QPushButton{background:#1a73e8;color:white;border-radius:4px;padding:5px 12px;font-family:'Microsoft JhengHei';}")
                _cfm_btn.clicked.connect(_cfm_dlg.accept)
                _cfm_blay.addWidget(_cfm_btn)
                _cfm_vlay.addLayout(_cfm_blay)
                _cfm_dlg.exec()
            else:
                import smtplib, ssl
                from email.mime.multipart import MIMEMultipart
                from email.mime.base import MIMEBase
                from email.mime.text import MIMEText
                from email import encoders

                host = host_edit.text().strip()
                port = int(port_edit.text().strip() or 587)
                user = user_edit.text().strip()
                pw   = pass_edit.text()
                if not host or not user or not pw:
                    QMessageBox.warning(dlg, "警告", "SMTP 模式請填寫完整伺服器設定！")
                    return

                with open(tmp_path, 'rb') as f:
                    excel_bytes = f.read()

                msg = MIMEMultipart()
                msg['From']    = user
                msg['To']      = to_val
                msg['Subject'] = subj
                msg.attach(MIMEText(body, 'plain', 'utf-8'))
                part = MIMEBase('application',
                                'vnd.openxmlformats-officedocument.spreadsheetml.sheet')
                part.set_payload(excel_bytes)
                encoders.encode_base64(part)
                part.add_header('Content-Disposition',
                                f'attachment; filename="TAIS_query_{now_str}.xlsx"')
                msg.attach(part)

                ctx = ssl.create_default_context()
                with smtplib.SMTP(host, port, timeout=30) as srv:
                    srv.ehlo(); srv.starttls(context=ctx); srv.ehlo()
                    srv.login(user, pw)
                    srv.sendmail(user, to_val, msg.as_string())
                _cfm_dlg2 = QDialog(dlg)
                _cfm_dlg2.setWindowTitle("完成")
                _cfm_dlg2.setMinimumWidth(380)
                _cfm_vlay2 = QVBoxLayout(_cfm_dlg2)
                _cfm_vlay2.setContentsMargins(20, 16, 20, 14)
                _cfm_lbl2 = QLabel(f"✅ 已透過 SMTP 寄送至：{to_val}")
                _cfm_lbl2.setWordWrap(True)
                _cfm_lbl2.setStyleSheet("font-family:'Microsoft JhengHei';font-size:12px;")
                _cfm_vlay2.addWidget(_cfm_lbl2)
                _cfm_blay2 = QHBoxLayout()
                _cfm_blay2.addStretch()
                _cfm_btn2 = QPushButton("確定")
                _cfm_btn2.setFixedWidth(80)
                _cfm_btn2.setStyleSheet("QPushButton{background:#1a73e8;color:white;border-radius:4px;padding:5px 12px;font-family:'Microsoft JhengHei';}")
                _cfm_btn2.clicked.connect(_cfm_dlg2.accept)
                _cfm_blay2.addWidget(_cfm_btn2)
                _cfm_vlay2.addLayout(_cfm_blay2)
                _cfm_dlg2.exec()

            dlg.accept()

        except ImportError:
            QMessageBox.critical(
                dlg, "錯誤",
                "找不到 win32com 模組。\n請先安裝：pip install pywin32"
            )
        except Exception as e:
            QMessageBox.critical(dlg, "寄送失敗", f"❌ 寄送失敗：{str(e)}")
        finally:
            try:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except Exception:
                pass

    send_btn.clicked.connect(_do_send)
    return dlg


# ── ResultPanel.send_email_result_dialog（預算結果 Email）──
def _result_panel_send_email_result_dialog(self):
    """預算結果分頁－寄送Email（取得 main_window.filtered_data 可見欄位）"""
    def _get_df():
        df = getattr(self.main_window, 'filtered_data', None)
        if df is None or (hasattr(df, 'empty') and df.empty):
            df = getattr(self.main_window, 'current_data', None)
        if df is None or (hasattr(df, 'empty') and df.empty):
            return None
        try:
            cc = self.table.columnCount()
            if cc > 0:
                vis = [self.table.horizontalHeaderItem(c).text()
                       for c in range(cc) if self.table.horizontalHeaderItem(c)]
                avail = [col for col in vis if col in df.columns]
                if avail:
                    df = df[avail]
        except Exception:
            pass
        return df

    import datetime as _dt_e
    _mw   = self.main_window
    _year = getattr(_mw, 'global_year',  str(_dt_e.datetime.now().year - 1911))
    _mon  = getattr(_mw, 'global_month', str(_dt_e.datetime.now().month))
    _def_subj = f"預算動支資料 {_year}/{_mon}"
    dlg = _build_email_send_dialog(
        self, "寄送 Email－預算查詢結果", _get_df,
        default_subject=_def_subj
    )
    dlg.exec()


ResultPanel.send_email_result_dialog = _result_panel_send_email_result_dialog


# ── ResultPanel.send_budget_managers_dialog（寄送預算主管浮動視窗）──
def _result_panel_send_budget_managers_dialog(self):
    """
    預算結果分頁－寄送預算主管。
    從 email_list.xlsx 載入收件人名單，浮動視窗勾選（含全選），
    逐一用 Outlook 寄送含附件的 Email。
    """
    from PyQt6.QtWidgets import (
        QDialog, QVBoxLayout, QHBoxLayout, QLabel,
        QLineEdit, QPushButton, QCheckBox, QScrollArea,
        QWidget, QGroupBox, QFrame, QMessageBox
    )

    # ── 取得可附加的 DataFrame ──
    df_send = getattr(self.main_window, 'filtered_data', None)
    if df_send is None or (hasattr(df_send, 'empty') and df_send.empty):
        df_send = getattr(self.main_window, 'current_data', None)
    if df_send is None or (hasattr(df_send, 'empty') and df_send.empty):
        QMessageBox.warning(self, "警告", "目前無可寄送的資料，請先執行預算查詢！")
        return

    # 取可見欄位
    try:
        cc = self.table.columnCount()
        if cc > 0:
            vis   = [self.table.horizontalHeaderItem(c).text()
                     for c in range(cc) if self.table.horizontalHeaderItem(c)]
            avail = [col for col in vis if col in df_send.columns]
            if avail:
                df_send = df_send[avail]
    except Exception:
        pass

    # ── 載入 email_list.xlsx ──
    import os
    email_xlsx = r"C:\budget_data\email_list.xlsx"
    recipients = []
    if os.path.exists(email_xlsx):
        try:
            import openpyxl
            wb = openpyxl.load_workbook(email_xlsx, data_only=True)
            ws = wb.active
            for row in ws.iter_rows(min_row=2, values_only=True):
                unit    = str(row[0]).strip() if len(row) > 0 and row[0] else ""
                name    = str(row[1]).strip() if len(row) > 1 and row[1] else ""
                title   = str(row[2]).strip() if len(row) > 2 and row[2] else ""
                email   = str(row[3]).strip() if len(row) > 3 and row[3] else ""
                to_str  = str(row[4]).strip() if len(row) > 4 and row[4] else ""
                cc_str  = str(row[5]).strip() if len(row) > 5 and row[5] else ""
                subj    = str(row[6]).strip() if len(row) > 6 and row[6] else ""
                body    = str(row[7]).strip() if len(row) > 7 and row[7] else ""
                if "@" in email and email != "電子郵件信箱":
                    recipients.append({
                        "unit":    unit,
                        "name":    name,
                        "title":   title,
                        "email":   email.strip().rstrip('"'),
                        "to":      to_str.rstrip('"'),
                        "cc":      cc_str.rstrip('"'),
                        "subject": subj,
                        "body":    body,
                    })
        except Exception as ex:
            QMessageBox.warning(self, "警告",
                                f"無法讀取 email_list.xlsx：{ex}\n請手動輸入收件人。")
    else:
        QMessageBox.warning(self, "警告",
                            f"找不到 email_list.xlsx（路徑：{email_xlsx}）\n請手動輸入收件人。")

    # ── 建立浮動視窗 ──
    dlg = QDialog(self)
    dlg.setWindowTitle("👥 寄送預算主管 Email")
    dlg.setMinimumWidth(560)
    dlg.setMinimumHeight(460)
    dlg.setStyleSheet("""
        QDialog  { background:#f8f9fa; }
        QLabel   { font-size:12px; font-family:'Microsoft JhengHei'; }
        QLineEdit{
            font-size:12px; font-family:'Microsoft JhengHei';
            border:1px solid #ced4da; border-radius:4px; padding:5px 8px; background:white;
        }
        QPushButton{
            font-size:12px; font-family:'Microsoft JhengHei';
            font-weight:bold; color:white; border:none; border-radius:5px; padding:7px 18px;
        }
        QCheckBox{ font-size:12px; font-family:'Microsoft JhengHei'; }
        QGroupBox{
            font-size:12px; font-family:'Microsoft JhengHei'; font-weight:bold;
            border:1px solid #dee2e6; border-radius:6px; margin-top:6px; padding-top:10px;
        }
        QGroupBox::title{ subcontrol-origin:margin; left:10px; padding:0 4px; }
    """)

    main_lay = QVBoxLayout(dlg)
    main_lay.setSpacing(10)
    main_lay.setContentsMargins(18, 16, 18, 14)

    # 標題提示
    hint = QLabel(f"共找到 <b>{len(recipients)}</b> 位主管，請勾選收件人後寄送（附件：預算查詢結果 Excel）")
    hint.setWordWrap(True)
    hint.setStyleSheet("color:#495057;font-size:12px;font-family:'Microsoft JhengHei';")
    main_lay.addWidget(hint)

    # ── 名單群組（可捲動）──
    list_grp = QGroupBox("收件人名單")
    list_vlay = QVBoxLayout(list_grp)
    list_vlay.setSpacing(4)

    # 全選
    chk_all = QCheckBox("✅ 全選 / 全不選")
    chk_all.setStyleSheet(
        "font-weight:bold;color:#007bff;font-size:13px;font-family:'Microsoft JhengHei';"
    )
    chk_all.setChecked(True)
    list_vlay.addWidget(chk_all)

    sep = QFrame()
    sep.setFrameShape(QFrame.Shape.HLine)
    sep.setStyleSheet("color:#dee2e6;")
    list_vlay.addWidget(sep)

    scroll_area = QScrollArea()
    scroll_area.setWidgetResizable(True)
    scroll_area.setMinimumHeight(200)
    scroll_area.setMaximumHeight(300)
    scroll_area.setStyleSheet("QScrollArea{border:none;}")

    scroll_widget = QWidget()
    scroll_lay    = QVBoxLayout(scroll_widget)
    scroll_lay.setSpacing(3)
    scroll_lay.setContentsMargins(4, 4, 4, 4)

    checkboxes = []
    for rec in recipients:
        row_chk = QCheckBox(
            f"【{rec['unit']}】{rec['name']}　{rec['title']}　<{rec['email']}>"
        )
        row_chk.setChecked(True)
        row_chk.setProperty("email_data", rec)
        scroll_lay.addWidget(row_chk)
        checkboxes.append(row_chk)

    if not recipients:
        scroll_lay.addWidget(QLabel("（無可用收件人，請確認 email_list.xlsx 內容）"))

    scroll_lay.addStretch()
    scroll_area.setWidget(scroll_widget)
    list_vlay.addWidget(scroll_area)
    main_lay.addWidget(list_grp)

    def _on_all_toggled(state):
        for cb in checkboxes:
            cb.setChecked(state == 2)  # Qt.CheckState.Checked = 2

    def _on_single_toggled(_):
        all_checked = all(cb.isChecked() for cb in checkboxes)
        chk_all.blockSignals(True)
        chk_all.setChecked(all_checked)
        chk_all.blockSignals(False)

    chk_all.stateChanged.connect(_on_all_toggled)
    for cb in checkboxes:
        cb.stateChanged.connect(_on_single_toggled)

    # ── 主旨後綴（各單位前綴 [單位] 自動加入）──
    import datetime as _dt_mgr
    _mw_mgr  = self.main_window
    _year_m  = getattr(_mw_mgr, 'global_year',  str(_dt_mgr.datetime.now().year - 1911))
    _mon_m   = getattr(_mw_mgr, 'global_month', str(_dt_mgr.datetime.now().month))
    _suffix_default = f"預算動支資料 {_year_m}/{_mon_m}"

    subj_row = QHBoxLayout()
    subj_lbl = QLabel("主旨後綴：")
    subj_lbl.setFixedWidth(80)
    subj_edit = QLineEdit()
    subj_edit.setText(_suffix_default)
    subj_edit.setPlaceholderText("各郵件主旨將自動加入 [單位] 前綴")
    hint_lbl = QLabel("（實際主旨：[單位] + 後綴，例如：[9A0 會計駐點] 預算動支資料 115/4）")
    hint_lbl.setStyleSheet("color:#888;font-size:10px;font-family:'Microsoft JhengHei';")
    subj_row.addWidget(subj_lbl)
    subj_row.addWidget(subj_edit)
    main_lay.addLayout(subj_row)
    main_lay.addWidget(hint_lbl)

    # ── 按鈕列 ──
    btn_row = QHBoxLayout()
    btn_row.addStretch()
    send_btn = QPushButton("📤 寄送勾選名單")
    send_btn.setStyleSheet(
        "QPushButton{background:#e83e8c;}QPushButton:hover{background:#c2185b;}"
    )
    cancel_btn = QPushButton("取消")
    cancel_btn.setStyleSheet(
        "QPushButton{background:#6c757d;}QPushButton:hover{background:#5a6268;}"
    )
    btn_row.addWidget(send_btn)
    btn_row.addWidget(cancel_btn)
    main_lay.addLayout(btn_row)
    cancel_btn.clicked.connect(dlg.reject)

    def _do_send_managers():
        selected_recs = [
            cb.property("email_data")
            for cb in checkboxes
            if cb.isChecked() and cb.property("email_data")
        ]
        if not selected_recs:
            QMessageBox.warning(dlg, "警告", "請至少勾選一位收件人！")
            return

        _suffix = subj_edit.text().strip() or _suffix_default

        import tempfile, os
        now_tag = __import__('datetime').datetime.now().strftime('%Y%m%d_%H%M%S')

        # 識別預算主管欄位（依優先順序尋找）
        _dept_cols = ['預算主管', '預算單位', 'DEPT', '預算主管單位']
        _dept_col = next((c for c in _dept_cols if c in df_send.columns), None)

        # 確認 Outlook 可用（提前檢查，避免逐筆失敗）
        try:
            import win32com.client as win32
            outlook = win32.Dispatch('outlook.application')
        except ImportError:
            QMessageBox.critical(
                dlg, "錯誤",
                "找不到 win32com 模組。\n請先安裝：pip install pywin32"
            )
            return

        ok_list, fail_list = [], []
        tmp_files = []
        try:
            for rec in selected_recs:
                # 依目標預算主管篩選資料列，僅保留與該主管相關的資料
                if _dept_col:
                    df_filtered = df_send[
                        df_send[_dept_col].astype(str).str.strip() == rec['unit'].strip()
                    ].copy()
                    if df_filtered.empty:
                        df_filtered = df_send  # 無符合資料則附上完整資料
                else:
                    df_filtered = df_send

                # 為每位收件人建立獨立的暫存 Excel
                safe_unit = rec['unit'][:10].replace('/', '_').replace('\\', '_')
                tmp_path = os.path.join(tempfile.gettempdir(),
                                        f"TAIS_budget_{now_tag}_{safe_unit}.xlsx")
                tmp_files.append(tmp_path)
                try:
                    with pd.ExcelWriter(tmp_path, engine='openpyxl') as writer:
                        df_filtered.to_excel(writer, index=False, sheet_name="預算動支資料")
                        _auto_col_width(writer.sheets["預算動支資料"])

                    now_str_body = __import__('datetime').datetime.now().strftime('%Y/%m/%d %H:%M:%S')

                    # 優先使用 email_list.xlsx 的欄位，若空白則自動補足
                    mail_to      = (rec.get('to') or
                                    f"{rec['name']} {rec['title']} <{rec['email']}>")
                    mail_cc      = rec.get('cc') or ""
                    mail_subject = (rec.get('subject') or
                                    f"[{rec['unit']}] {_suffix}")
                    mail_body    = (rec.get('body') or
                                    f"{rec['name']} {rec['title']} 您好：\n\n"
                                    f"會計駐點傳送預算動支資料（共 {len(df_filtered)} 筆），\n"
                                    f"匯出時間：{now_str_body}\n\n"
                                    "  列帳局「0000」代表為各分公司合計數，"
                                    "可篩選「0000」查看預算動支再看各分公司。\n\n"
                                    " 會計駐點  敬上")

                    mail = outlook.CreateItem(0)
                    mail.To      = mail_to
                    if mail_cc:
                        mail.CC  = mail_cc
                    mail.Subject = mail_subject
                    mail.Body    = mail_body
                    mail.Attachments.Add(tmp_path)
                    ok_list.append(f"{rec['name']}（{rec['email']}）")
                except Exception as ex:
                    fail_list.append(f"{rec['name']}（{rec['email']}）：{ex}")

            msg_parts = []
            if ok_list:
                msg_parts.append("✅ 寄送成功：\n" + "\n".join(f"  • {x}" for x in ok_list))
            if fail_list:
                msg_parts.append("❌ 寄送失敗：\n" + "\n".join(f"  • {x}" for x in fail_list))

            _res_dlg = QDialog(dlg)
            _res_dlg.setWindowTitle("寄送結果")
            _res_dlg.setMinimumWidth(400)
            _res_vlay = QVBoxLayout(_res_dlg)
            _res_vlay.setContentsMargins(20, 16, 20, 14)
            _res_lbl = QLabel("\n\n".join(msg_parts))
            _res_lbl.setWordWrap(True)
            _res_lbl.setStyleSheet("font-family:'Microsoft JhengHei';font-size:12px;")
            _res_vlay.addWidget(_res_lbl)
            _res_blay = QHBoxLayout()
            _res_blay.addStretch()
            _res_cfm = QPushButton("確定")
            _res_cfm.setFixedWidth(80)
            _res_cfm.setStyleSheet("QPushButton{background:#1a73e8;color:white;border-radius:4px;padding:5px 12px;font-family:'Microsoft JhengHei';}")
            _res_cfm.clicked.connect(_res_dlg.accept)
            _res_blay.addWidget(_res_cfm)
            _res_vlay.addLayout(_res_blay)
            _res_dlg.exec()
            if ok_list:
                dlg.accept()

        except Exception as e:
            QMessageBox.critical(dlg, "寄送失敗", f"❌ 寄送過程發生錯誤：{str(e)}")
        finally:
            for tmp_path in tmp_files:
                try:
                    if os.path.exists(tmp_path):
                        os.remove(tmp_path)
                except Exception:
                    pass

    send_btn.clicked.connect(_do_send_managers)
    dlg.exec()


ResultPanel.send_budget_managers_dialog = _result_panel_send_budget_managers_dialog


# ── CombinedApp.send_email_result_tab3（查詢結果 Tab 寄送 Email）──
def _combined_app_send_email_result_tab3(self):
    """
    查詢結果 Tab（Tab 03）－寄送 Email。
    取 result_table 當前可見欄位資料，帶入 _build_email_send_dialog 寄送。
    """
    def _get_df():
        tbl = getattr(self, 'result_table', None)
        if tbl is None or tbl.rowCount() == 0:
            return None
        cols = [
            tbl.horizontalHeaderItem(c).text()
            if tbl.horizontalHeaderItem(c) else f"欄位{c+1}"
            for c in range(tbl.columnCount())
        ]
        rows = []
        for r in range(tbl.rowCount()):
            row = {}
            for c, col in enumerate(cols):
                item = tbl.item(r, c)
                row[col] = item.text() if item else ""
            rows.append(row)
        if not rows:
            return None
        return pd.DataFrame(rows, columns=cols)

    dlg = _build_email_send_dialog(self, "寄送 Email－查詢結果", _get_df)
    dlg.exec()


CombinedApp.send_email_result_tab3 = _combined_app_send_email_result_tab3


if __name__ == "__main__":
    safe_main()
    